function pfMentionsMe(m){let t=''+((m&&m.body)||(m&&m.text)||'');const pl=pfMsgPayload(m);if(pl&&pl.type==='text')t=pl.text||'';const nm=(S.me&&S.me.name)||'我';return !!(t&&nm&&t.indexOf('@'+nm)>=0);}
