  if(isStoredImgRef(v)){const key=v.slice(4),src=_imgCache[key];return src?`<div class="${cls}"><img src="${src}"></div>`:`<div class="${cls}" data-idb-avatar="${esc(key)}">${_avIc('user')}</div>`;}
