function roleTimeParts(t,zone){const when=+t||Date.now(),requested=String(zone||'').trim(),configured=String(S&&S.settings&&S.settings.timeZone||'').trim(),localZone=deviceTimeZone();let tz='';if(requested&&(requested===localZone||timeZoneValid(requested)))tz=requested;else if(!requested&&configured&&(configured===localZone||timeZoneValid(configured)))tz=configured;if(!tz||tz===localZone)return localRoleTimeParts(when,localZone);if(privateNativeShellOn()){const offset=nativeTimeZoneOffset(tz);if(offset!==null){const d=new Date(when+offset*60000);return{year:d.getUTCFullYear(),month:d.getUTCMonth()+1,day:d.getUTCDate(),hour:d.getUTCHours(),minute:d.getUTCMinutes(),second:d.getUTCSeconds(),weekday:d.getUTCDay(),zone:tz};}return localRoleTimeParts(when,localZone);}const parts={};try{roleTimeFormatter(tz).formatToParts(new Date(when)).forEach(x=>{if(x.type!=='literal')parts[x.type]=x.value;});const y=+parts.year,m=+parts.month,d=+parts.day,h=(+parts.hour||0)%24,minute=+parts.minute||0,second=+parts.second||0;return{year:y,month:m,day:d,hour:h,minute,second,weekday:new Date(Date.UTC(y,m-1,d)).getUTCDay(),zone:tz};}catch(_){return localRoleTimeParts(when,localZone);}}
