function timeZoneName(zone){const names={'Asia/Shanghai':'北京时间','Asia/Tokyo':'日本时间','Asia/Seoul':'韩国时间','Asia/Singapore':'新加坡时间','Asia/Bangkok':'泰国时间','Asia/Dubai':'阿联酋时间','Asia/Kolkata':'印度时间','Europe/London':'英国时间','Europe/Paris':'法国时间','Europe/Berlin':'德国时间','Europe/Moscow':'俄罗斯时间','America/New_York':'美国纽约时间','America/Chicago':'美国芝加哥时间','America/Denver':'美国丹佛时间','America/Los_Angeles':'美国洛杉矶时间','America/Toronto':'加拿大多伦多时间','America/Vancouver':'加拿大温哥华时间','America/Sao_Paulo':'巴西圣保罗时间','Australia/Sydney':'澳大利亚悉尼时间','Pacific/Auckland':'新西兰奥克兰时间'};return names[zone]||String(zone||'').replace(/_/g,' ').replace(/\//g,' / ');}
function timeZoneOptions(selected){selected=String(selected||'local');const local=deviceTimeZone(),featured=['Asia/Shanghai','Asia/Tokyo','Asia/Seoul','Asia/Singapore','Asia/Bangkok','Asia/Dubai','Asia/Kolkata','Europe/London','Europe/Paris','Europe/Berlin','Europe/Moscow','America/New_York','America/Chicago','America/Denver','America/Los_Angeles','America/Toronto','America/Vancouver','America/Sao_Paulo','Australia/Sydney','Pacific/Auckland'];let all=[];if(privateNativeShellOn()){all=Object.keys(nativeTimeZoneOffsets()||{});}else{try{all=Intl.supportedValuesOf('timeZone');}catch(_){}}const seen=new Set(featured),rest=all.filter(z=>!seen.has(z));const option=(z,label)=>`<option value="${esc(z)}" ${selected===z?'selected':''}>${esc(label)} · ${timeZoneOffsetText(z==='local'?local:z)}</option>`;return option('local','跟随本机（'+timeZoneName(local)+'）')+'<optgroup label="常用时区">'+featured.map(z=>option(z,timeZoneName(z))).join('')+'</optgroup>'+(rest.length?'<optgroup label="全球其他时区">'+rest.map(z=>option(z,timeZoneName(z))).join('')+'</optgroup>':'');}
function northLocaleNumber(value,locale){const n=Number(value);if(!privateNativeShellOn())return n.toLocaleString(locale||undefined);if(!Number.isFinite(n))return String(value==null?'':value);const sign=n<0?'-':'',raw=String(Math.abs(n)),parts=raw.split('.'),whole=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,','),fraction=parts.length>1?'.'+parts.slice(1).join('.'):'';return sign+whole+fraction;}
function northLocaleDate(value,options){const d=value instanceof Date?value:new Date(value);if(Number.isNaN(d.getTime()))return'';if(!privateNativeShellOn())return d.toLocaleString('zh-CN',options||undefined);const opt=options||{},two=n=>String(n).padStart(2,'0'),year=opt.year==='2-digit'?two(d.getFullYear()%100):String(d.getFullYear()),month=opt.month==='2-digit'?two(d.getMonth()+1):String(d.getMonth()+1),day=opt.day==='2-digit'?two(d.getDate()):String(d.getDate()),fields=!!(opt.year||opt.month||opt.day||opt.hour||opt.minute||opt.second),dateWanted=!options||!fields||opt.year||opt.month||opt.day,timeWanted=!options||!fields||opt.hour||opt.minute||opt.second;let date='';if(dateWanted){if(opt.year)date=year+'/'+month+'/'+day;else if(opt.month||opt.day)date=month+'/'+day;else date=year+'/'+month+'/'+day;}let time='';if(timeWanted){time=two(d.getHours())+':'+two(d.getMinutes());if(!options||!fields||opt.second)time+=':'+two(d.getSeconds());}return(date+(date&&time?' ':'')+time).trim();}
function setTimeZone(zone){zone=String(zone||'local');if(zone!=='local'&&!timeZoneValid(zone)){toast('这个时区无法使用');render();return;}S.settings.timeZone=zone==='local'?'':zone;save();render();(S.contacts||[]).filter(c=>c&&c.proactive&&c.proactive.serverPush).forEach(c=>roleServerPushSync(c,true));const active=roleTimeZone();toast('角色时区已设为'+(zone==='local'?'跟随本机：':'：')+timeZoneName(active)+'，现在 '+hm(Date.now()));}
function hm(t){const p=t instanceof Date?{hour:t.getHours(),minute:t.getMinutes()}:roleTimeParts(t||Date.now());return String(p.hour).padStart(2,'0')+':'+String(p.minute).padStart(2,'0');}
function weekdayCN(t){const day=t instanceof Date?t.getDay():roleTimeParts(t||Date.now()).weekday;return ['周日','周一','周二','周三','周四','周五','周六'][day];}
function timeAwarenessPrompt(who,kind){
  if(!S.settings.timeAware)return '时间感知已关闭。你不知道当前日期、几点、星期、早中晚、距离上一件事过了多久，也不能从消息时间戳、作息表、系统时钟或其他隐藏数据推测；除非'+(who||'对方')+'在当前对话里直接告诉你，否则不要主动提及。';
  const now=Date.now(),clock=hm(now),part=dayPartNow(),today=roleClockDate(now),tomorrow=new Date(today),yesterday=new Date(today);tomorrow.setDate(tomorrow.getDate()+1);yesterday.setDate(yesterday.getDate()-1);
  const subject=who||'对方',scene=kind==='call'?'通话里':kind==='cohab'?'共同生活里':'微信里';
  return '角色采用的时区是【'+timeZoneName(roleTimeZone())+'，'+roleTimeZone()+'，'+timeZoneOffsetText(roleTimeZone(),now)+'】；当前真实时间是【'+ymdFull(now)+' '+weekdayCN(now)+' '+clock+'】；当前时段是【'+part+'】。你不用'+subject+'问也知道现在几点。\n'+
    '日期关系必须按日历计算：今天是'+weekdayCN(now)+'，昨天是'+weekdayCN(yesterday)+'，明天是'+weekdayCN(tomorrow)+'。绝不能把今天或明天说成别的星期。\n'+
    '时间相关表达必须严格按这个精确时间说，不能凭感觉四舍五入、提前跳到下一个整点或下一天：现在是 '+clock+' 就只能说 '+clock+'、'+clock.replace(':','点')+'分、或贴近的口语时间；23:20到23:49 应说十一点二十到十一点五十之间，绝对不要说十二点了；只有真实日期/小时已经变了，才说凌晨、明天、昨天。\n'+
    '凡是打招呼、催睡觉、问吃饭、说早中晚、提今天/明天/昨天、判断隔了多久，都必须先按这个时间校准，再用符合你人设的方式自然说出来。'+(scene?'这是当前'+scene+'最高优先级事实。':'');
}
function roleReplyClockPin(now){if(!S.settings.timeAware)return'';now=+now||Date.now();return '\n【本轮发送前时间核对（只供你内部知道，不要机械复述）】设备当前准确时间是【'+ymdFull(now)+' '+weekdayCN(now)+' '+hm(now)+'】。每次回复都先以这个值校准当前几点、早晚和日期；不能提前跳到下一个整点。除非当前话题确实涉及时间、作息、吃饭或日期，否则不要主动报时，也不要为了展示你看过时间而提时间。';}
function clockCNNumber(n){n=Math.max(0,Math.floor(+n||0));const d=['零','一','二','三','四','五','六','七','八','九'];if(n<10)return d[n];if(n<20)return n===10?'十':'十'+d[n-10];return d[Math.floor(n/10)]+'十'+(n%10?d[n%10]:'');}
function currentClockSpoken(t){const d=roleTimeParts(t||Date.now()),h=d.hour,m=d.minute,part=h<5?'凌晨':h<9?'早上':h<12?'上午':h<14?'中午':h<18?'下午':h<23?'晚上':'深夜',hour=h%12||12;return part+clockCNNumber(hour)+'点'+(m===0?'整':m===30?'半':clockCNNumber(m)+'分');}
function directClockQuestion(text){return /(?:现在|当前|这会儿|此刻).{0,8}(?:几点|时间)|(?:几点|时间).{0,8}(?:现在|当前|这会儿|此刻)|几点了|看(?:看|一下)?.{0,5}几点/.test(String(text||''));}
function refreshDirectClockReply(content,userText,now){content=String(content||'');if(!S.settings.timeAware||!directClockQuestion(userText))return content;const exact=currentClockSpoken(now||Date.now()),re=/(?:凌晨|早上|上午|中午|下午|傍晚|晚上|夜里|深夜)?\s*(?:(?:[01]?\d|2[0-3]):[0-5]\d|[零〇一二三四五六七八九十两\d]{1,3}\s*(?:点|时)(?:\s*(?:[零〇一二三四五六七八九十两\d]{1,3}\s*分?|半|一刻|三刻|整))?)/;return re.test(content)?content.replace(re,exact):content;}
function conversationGapExact(gap){gap=Math.max(0,Math.floor(+gap||0));if(gap<60000)return Math.floor(gap/1000)+'秒';if(gap<3600000)return Math.floor(gap/60000)+'分'+String(Math.floor(gap%60000/1000)).padStart(2,'0')+'秒';const h=Math.floor(gap/3600000),m=Math.floor(gap%3600000/60000);return h+'小时'+m+'分钟';}
function clockNumberValue(token){token=String(token||'').trim();if(/^\d+$/.test(token))return+token;const map={零:0,'〇':0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};if(token==='十')return 10;const at=token.indexOf('十');if(at>=0){const a=at===0?1:(map[token[at-1]]==null?0:map[token[at-1]]),b=at===token.length-1?0:(map[token[at+1]]==null?0:map[token[at+1]]);return a*10+b;}return token.length===1&&map[token]!=null?map[token]:NaN;}
const ROLE_TIME_TOLERANCE_MINUTES=2;
function clockMinuteDistance(a,b){a=((+a%1440)+1440)%1440;b=((+b%1440)+1440)%1440;const d=Math.abs(a-b);return Math.min(d,1440-d);}
function roleClockClaimDistance(hourToken,minuteToken,qualifier,period,p){const h=clockNumberValue(hourToken);let minute=minuteToken==null||minuteToken===''?0:clockNumberValue(minuteToken);if(qualifier==='半')minute=30;else if(qualifier==='一刻')minute=15;else if(qualifier==='三刻')minute=45;else if(qualifier==='整')minute=0;if(!Number.isFinite(h)||!Number.isFinite(minute)||h<0||h>24||minute<0||minute>59)return NaN;const actual=(+p.hour||0)*60+(+p.minute||0);let hours=[];if(h===24)hours=[0];else if(h>12)hours=[h];else if(h===12)hours=[0,12];else hours=[h,h+12];period=String(period||'');if(/凌晨/.test(period))hours=hours.filter(x=>x<6);else if(/早上|上午/.test(period))hours=hours.filter(x=>x<12);else if(/中午/.test(period))hours=hours.filter(x=>x>=11&&x<=13);else if(/下午|傍晚|晚上|夜里|深夜/.test(period))hours=hours.filter(x=>x>=12);if(!hours.length)return NaN;return Math.min(...hours.map(x=>clockMinuteDistance(x*60+minute,actual)));}
function conversationVisibleRows(c,limit){try{return(msgs(c.id)||[]).filter(m=>m&&m.time&&!m._silent&&!m._call&&m.type!=='sys'&&(m.role==='user'||m.role==='assistant')).slice(-Math.max(2,+limit||40));}catch(_){return[];}}
function conversationGapFact(c){try{const arr=conversationVisibleRows(c,80);let ui=-1;for(let i=arr.length-1;i>=0;i--){if(arr[i].role==='user'){ui=i;break;}}if(ui<=0)return null;const curm=arr[ui];let start=ui;for(let i=ui-1;i>=0;i--){const m=arr[i];if(m.role==='user'&&curm.time-m.time<3*60000){start=i;continue;}break;}const prev=arr[start-1];if(!prev)return null;return{current:curm,previous:prev,gap:Math.max(0,curm.time-prev.time)};}catch(_){return null;}}
function conversationGapQuestion(text){return/(?:隔了|隔多久|隔多长|多久才|多长时间|什么时候.{0,8}(?:回|找)|没回.{0,8}多久|离开.{0,8}多久|时间感|过了多久)/.test(String(text||''));}
function conversationHistoricalGapQuestion(text){return/(?:刚才|刚刚|之前|前面|那次).{0,12}(?:隔|多久|没回|回来)|(?:没回|离开).{0,12}(?:什么时候|多久|回来)|(?:隔了多久|多久才).{0,8}(?:回|回来)/.test(String(text||''));}
function conversationReferencedGapFact(c){try{const rows=conversationVisibleRows(c,40),latest=conversationGapFact(c),question=latest&&msgToText(latest.current);if(!latest||!conversationGapQuestion(question)||!conversationHistoricalGapQuestion(question))return null;let at=-1,fallback=null;for(let i=rows.length-1;i>=0;i--){if(rows[i]===latest.current||rows[i].id&&latest.current.id&&rows[i].id===latest.current.id){at=i;break;}}for(let i=at-1;i>0;i--){const m=rows[i],prev=rows[i-1],gap=m&&prev?m.time-prev.time:0;if(!m||m.role!=='user')continue;const fact={current:m,previous:prev,gap:Math.max(0,gap),referenced:true};if(!fallback)fallback=fact;if(gap>=5*60000)return fact;}return fallback;}catch(_){return null;}}
function conversationClaimGapFact(c){return conversationReferencedGapFact(c)||conversationGapFact(c);}
function conversationComplaintGapFact(c,now){const rows=conversationVisibleRows(c,40),last=rows[rows.length-1],lastUser=[...rows].reverse().find(m=>m.role==='user');if(last&&last.role==='assistant'&&lastUser)return{gap:Math.max(0,(+now||Date.now())-lastUser.time),proactive:true,current:lastUser};return conversationGapFact(c);}
function roleReplyTimelineRows(c,limit){const unified=typeof roleCrossChannelOn==='function'?roleCrossChannelOn(c):typeof offlineWechatLiveOn==='function'&&offlineWechatLiveOn();if(unified&&typeof roleInteractionRows==='function')return roleInteractionRows(c).filter(x=>x&&x.at).slice(-Math.max(2,+limit||40));return conversationVisibleRows(c,limit).map(m=>({at:+m.time||0,channel:m._call?'call':'online',role:m.role==='user'?'user':'assistant',text:String(msgToText(m)||previewOf(m)||'').replace(/\s+/g,' ').trim()}));}
function roleReplyGapFact(c,now){const rows=roleReplyTimelineRows(c,80),last=rows[rows.length-1],lastUser=[...rows].reverse().find(x=>x.role==='user');if(!lastUser)return null;if(last&&last.role==='assistant')return{gap:Math.max(0,(+now||Date.now())-lastUser.at),proactive:true,current:lastUser,unified:lastUser.channel!=='online'||rows.some(x=>x.channel!=='online')};let at=rows.lastIndexOf(lastUser);if(at<=0)return null;let start=at;for(let i=at-1;i>=0;i--){const x=rows[i];if(x.role==='user'&&lastUser.at-x.at<3*60000){start=i;continue;}break;}const previous=rows[start-1];if(!previous)return null;return{gap:Math.max(0,lastUser.at-previous.at),current:lastUser,previous,unified:lastUser.channel!=='online'||previous.channel!=='online'};}
function roleReplyTimelinePin(c){if(!S.settings.timeAware)return'';const rows=roleReplyTimelineRows(c,10);if(!rows.length)return'';const unified=typeof roleCrossChannelOn==='function'?roleCrossChannelOn(c):typeof offlineWechatLiveOn==='function'&&offlineWechatLiveOn(),silence=roleReplyGapFact(c,Date.now()),silenceLine=silence&&silence.proactive?'\n对方距最近一次真实发言已经【'+conversationGapExact(silence.gap)+'】；这是主动联系时判断是否久未回复的唯一时长。':'',crossLine=unified?'\n微信、电话和共同生活已经按真实时间合并。微信气泡之间即使隔了很多小时，只要中间在线下或电话里有互动，就绝不能说对方失联、消失或很久没理你；必须记得并承接最近那个渠道真实发生的内容。':'';return '\n【最近跨渠道真实时间线（只供内部判断，不要逐条复述）】\n'+rows.map((m,i)=>'['+fmtDT(m.at)+']['+(m.channel==='cohab'?'共同生活':m.channel==='call'?'电话':'微信')+']['+(m.role==='user'?S.me.name:(c.remark||c.name||'角色'))+']'+(i?'[距上一条'+conversationGapExact(Math.max(0,m.at-rows[i-1].at))+']':'')+' '+String(m.text||'').slice(0,90)).join('\n')+silenceLine+crossLine+'\n你始终知道这些真实间隔。未满一小时属于正常聊天间隔，不要主动说“怎么这么久没理我”；超过一小时才允许按人设自然在意，但也不要每句报时。对方直接询问时，无论间隔长短都必须按真实时间戳准确回答，误差只允许一两分钟。';}
function roleRecentChannelRounds(rows,channel,roundCount,maxRows){const src=(rows||[]).filter(x=>x&&x.channel===channel),starts=[];if(!src.length)return[];for(let i=0;i<src.length;i++)if(src[i].role==='user'&&(i===0||src[i-1].role!=='user'))starts.push(i);let start=starts.length?starts[Math.max(0,starts.length-Math.max(1,+roundCount||1))]:Math.max(0,src.length-Math.max(1,+maxRows||12)),picked=src.slice(start),cap=Math.max(2,+maxRows||12);if(picked.length<=cap)return picked;const firstUser=picked.find(x=>x.role==='user'),tail=picked.slice(-(cap-(firstUser?1:0)));return firstUser&&!tail.includes(firstUser)?[firstUser,...tail]:picked.slice(-cap);}
function roleReplyContinuityPin(c,now,opt){if(!c)return'';now=+now||Date.now();opt=opt||{};const synced=typeof roleCrossChannelOn==='function'?roleCrossChannelOn(c):typeof offlineWechatLiveOn!=='function'||offlineWechatLiveOn();let all=roleInteractionRows(c).filter(x=>x&&x.at<=now);if(!synced)all=all.filter(x=>opt.channel==='cohab'?x.channel==='cohab':x.channel!=='cohab');let rows=all.slice(-8);if(synced){const anchorChannel=opt.channel==='cohab'?'online':'cohab',anchor=roleRecentChannelRounds(all,anchorChannel,1,14),seen=new Set();rows=[...anchor,...rows].sort((a,b)=>a.at-b.at).filter(x=>{const key=[x.at,x.channel,x.role,x.text].join('|');if(seen.has(key))return false;seen.add(key);return true;});}if(!rows.length)return'';const timeOn=S.settings.timeAware!==false,me=S.me&&S.me.name||'用户',role=c.remark||c.name||'角色';return '\n【本轮发送前连续性核对（只供内部思考，绝不能照抄或汇报）】\n'+rows.map(x=>(timeOn?'['+fmtDT(x.at)+']':'')+'['+(x.channel==='cohab'?'共同生活':x.channel==='call'?'电话':'微信')+']['+(x.role==='user'?me:role)+'] '+x.text.slice(0,180)).join('\n')+'\n回复前只在心里核对：最近明确发生了什么、事情现在处于什么进度、你本人刚答应或说过什么。共同生活的最近完整一轮即使包含很多旁白或气泡，也必须从用户当时最先说/做的内容开始理解，不能只记住末尾几句角色台词。上面是双方原话，不等于每句话都是现实事实；假设、举例、引用、玩笑、询问和尚未实行的计划不能当成已经发生。没有更新的用户说明或真实功能结果时，不得无依据推翻、倒退或改写上一轮状态；确有新进展时可以自然改变，并承接变化。资料不足就自然询问，不能自行补出进展。只输出角色此刻自然会说的话，不要复述核对过程，也不要为了证明记得而机械总结前情。';}
