  report:{title:'报备',tone:'出门、回来、去做什么有没有说'},
  app:{title:'玩手机超时',tone:'游戏、刷视频、刷软件有没有失控'},
  task:{title:'任务没完成',tone:'答应做的事和任务有没有做到'},
