let stack=[{p:'home'}];
let wxTab='chats';
let _wxQuickOpen=false;
let _scrollBottomOnce={};
function go(p,params){stack.push(Object.assign({p},params));render();}
function back(){const leaving=cur();if(leaving&&leaving.p==='wxscan'&&window.wxScanStop)window.wxScanStop();if(stack.length>1){stack.pop();render();}}
function home(){if(window.wxScanStop)window.wxScanStop();window._wxReturnToDiscover=false;stack=[{p:'home'}];render();}
function cur(){return stack[stack.length-1];}
function renderPageKey(c){if(!c)return'';if(c.p==='chat')return'chat:'+c.id;if(c.p==='pfchat')return'pfchat:'+c.id;if(c.p==='pfgroup')return'pfgroup:'+c.gid;if(c.p==='group')return'group:'+c.id;if(c.p==='mgroom')return'mgroom:'+c.id;if(c.p==='hischat')return'hischat:'+c.id+':'+c.fid;if(c.p==='dydm')return'dydm:'+c.id;return c.p;}
function renderScrollTarget(c){if(!c)return null;if(c.p==='hischat'&&c.fid==='__me')return{id:'hisselflog',stick:true};const map={settings:['settingsscroll',0],couple:['couplescroll',0],wxmoment:['wxMomentScroll',0],wxalbum:['.wxalbum-page',0],wxfavorites:['.wxfav-page',0],spy:['spyAppScroll',0],x:['xscroll',0],dy:['dyfeed',0],wxnearby:['wxNearbyScroll',0],chat:['chatbg',1],pfchat:['pfchatbg',1],pfgroup:['pfgroupbg',1],group:['chatbg',1],mgroom:['mgrbg',1],alter:['alterbg',1],tale:['talebox',1],dread:['dreadbox',1],xdm:['xdmbox',1],dydm:['dydmbox',1],shopcs:['csbox',1],off:['offbg',1],rp:['rpbg',1],jail:['jailbox',1],gs:['gsbg',1],hischat:['hischatlog',1],phonesms:['smsbody',1],calllog:['cllog',0]};const x=map[c.p];return x?{id:x[0],stick:!!x[1]}:null;}
function nearBottom(el){return !el||Math.max(0,el.scrollHeight-el.scrollTop-el.clientHeight)<80;}
function chatPinBottom(cb){if(!cb)return;const pin=()=>{if(!cb.isConnected)return;cb.scrollTop=Math.max(0,cb.scrollHeight-cb.clientHeight);};pin();requestAnimationFrame(pin);}
function appendChatHTML(cb,html,opt){if(!cb||!html)return null;opt=opt||{};const stick=nearBottom(cb),typing=opt.replaceTyping?cb.querySelector('#typing'):null;let node=null;
  if(typing&&typing.isConnected){typing.insertAdjacentHTML('afterend',html);node=typing.nextElementSibling;typing.remove();}
  else{cb.insertAdjacentHTML('beforeend',html);node=cb.lastElementChild;}
  if(node&&node.classList&&node.classList.contains('msg')&&opt.animate!==false)node.classList.add('msg-enter');
  if(stick)chatPinBottom(cb);return node;}
function appendChatMessageHTML(id,c,m,opt){const cb=$('#chatbg');if(!cb||!m)return null;const prev=chatPrevVisibleBefore(id,m),html=chatBoundaryHTML(prev,m)+bubbleRow(c,m),node=appendChatHTML(cb,html,opt||{});refreshChatMood(id);return node;}
function chatMessageListHTML(id,c){const all=msgs(id).filter(m=>!m._call);all.forEach(m=>{if(!m.id)m.id=uid();});const renderLimit=CHAT_RENDER_LIMIT+(_chatRenderExtra[id]||0),skipped=Math.max(0,all.length-renderLimit),list=skipped?all.slice(skipped):all;let body=skipped?`<div class="tstamp"><span onclick="showOlderChat('${id}')" style="cursor:pointer">加载更早 ${Math.min(CHAT_RENDER_LIMIT,skipped)} 条 · 还剩 ${skipped} 条</span></div>`:'';let prevVisible=null;list.forEach(m=>{if(m._silent)return;body+=chatBoundaryHTML(prevVisible,m);body+=bubbleRow(c,m);prevVisible=m;});return body;}
function visibleRoleThought(c){return wechatNaturalOn()?String(c&&c.innerThought||''):String(c&&c.mood||'');}
function refreshChatMood(id){if(cur().p!=='chat'||cur().id!==id)return false;const c=getC(id),bar=$('#chatMoodBar'),label=$('#chatMoodText');if(!c||!bar||!label)return false;const natural=wechatNaturalOn(),thought=visibleRoleThought(c),visible=S.settings.showMoodTag!==false&&!!thought;bar.style.display=visible?'flex':'none';bar.setAttribute('onclick',(natural?'showInnerThought':'showMood')+"('"+id+"')");label.textContent=thought.slice(0,24)+(thought.length>24?'…':'');return true;}
function refreshChatMessages(id){if(cur().p!=='chat'||cur().id!==id)return false;const cb=$('#chatbg'),c=getC(id);if(!cb||!c)return false;const stick=nearBottom(cb),top=cb.scrollTop;cb.innerHTML=chatMessageListHTML(id,c);refreshChatMood(id);if(stick)chatPinBottom(cb);else cb.scrollTop=top;return true;}
function captureChatComposer(c){if(!c||c.p!=='chat')return null;const ta=$('#cinput');if(!ta)return null;let start=null,end=null;try{start=ta.selectionStart;end=ta.selectionEnd;}catch(_){}return{key:renderPageKey(c),value:ta.value||'',start,end,focused:document.activeElement===ta,height:ta.style.height||'',scrollTop:ta.scrollTop||0};}
function restoreChatComposer(c,st){if(!st||!c||st.key!==renderPageKey(c))return;const ta=$('#cinput');if(!ta)return;ta.value=st.value;ta.style.height=st.height||'auto';ta.scrollTop=st.scrollTop||0;if(typeof chatComposerStateSync==='function')chatComposerStateSync(ta);if(st.start!=null)try{ta.setSelectionRange(st.start,st.end==null?st.start:st.end);}catch(_){}if(st.focused)try{ta.focus({preventScroll:true});if(st.start!=null)ta.setSelectionRange(st.start,st.end==null?st.start:st.end);}catch(_){} }
function renderScrollStateKey(c,el){return String(el&&el.getAttribute&&el.getAttribute('data-render-scroll-key')||renderPageKey(c));}
function renderScrollElement(t){return !t?null:(String(t.id).charAt(0)==='.'?document.querySelector(t.id):document.getElementById(t.id));}
function captureRenderScroll(c){const t=renderScrollTarget(c);if(!t)return null;const el=renderScrollElement(t);if(!el)return{key:renderPageKey(c),id:t.id,had:false};const bottom=Math.max(0,el.scrollHeight-el.scrollTop-el.clientHeight);return{key:renderScrollStateKey(c,el),id:t.id,had:true,top:el.scrollTop,bottom,nearBottom:bottom<80};}
function restoreRenderScroll(c,st){const t=renderScrollTarget(c);if(!t)return;const el=renderScrollElement(t);if(!el)return;const key=renderScrollStateKey(c,el),force=_scrollBottomOnce&&_scrollBottomOnce[key];if(force){delete _scrollBottomOnce[key];requestAnimationFrame(()=>{el.scrollTop=el.scrollHeight;});el.scrollTop=el.scrollHeight;return;}const same=st&&st.had&&st.key===key&&st.id===t.id;if(t.stick){if(!same||st.nearBottom)el.scrollTop=el.scrollHeight;else el.scrollTop=st.top;}else if(same){el.scrollTop=st.top;requestAnimationFrame(()=>{if(el.isConnected)el.scrollTop=st.top;});}}
