async function cinemaExtractSubtitles(){if(sttRelayOn())return toast('内置识别不会上传原视频，请使用“压缩音频后提取”');const f=_cin.videoFile,s=cinemaSession();if(!f||!s){cinemaSetStatus('只能提取已导入的本地视频','error');return toast('一键提取只支持已导入的本地视频');}if(!cinemaSttConfigured())return cinemaExtractHelp();if(_cin.extracting)return toast('字幕正在提取，请稍候');const size=+f.size||0,tip=size?('视频约 '+Math.max(1,Math.round(size/1048576))+'MB。'):'';if(!await uiConfirm(tip+'将上传整段视频到你配置的语音转文字接口并可能产生费用，确定提取带时间轴字幕？'))return;_cin.extracting=true;const b=$('#cinExtractBtn');if(b){b.classList.add('on');b.disabled=true;const t=b.querySelector('span');if(t)t.textContent='提取中…';}cinemaSetStatus('正在提取整段视频字幕…','working');try{const cues=await sttTranscribeTimed(f,f.name||((s.title||'video')+'.'+((f.type||'').includes('webm')?'webm':'mp4')));if(!cues.length)throw new Error('接口没有返回分段时间戳；请换用支持 verbose_json/segments 的转写模型');const n=cinemaApplyCues(cues,'一键提取字幕','extract');cinemaSetStatus('已提取 '+n+' 句字幕 · 时间轴已对齐','ready');toast('已提取 '+n+' 句字幕，并与视频时间点对齐');}catch(e){cinemaSetStatus('字幕提取失败 · 可重试或导入 SRT / VTT','error');toast((e&&e.message)||'视频字幕提取失败');}finally{_cin.extracting=false;if(b&&b.isConnected){b.disabled=false;b.classList.remove('on');const t=b.querySelector('span');if(t)t.textContent='提取字幕';}}}
function cinemaLogHTML(s){const c=getC(s&&s.cid),items=(s&&s.items||[]).slice(-60);if(!items.length)return '<div class="cin-chat-empty"><b>同屏对话</b><span>开始播放后，直接和 '+cinemaRoleName(c)+' 聊这一幕。</span></div>';return items.map(m=>`<div class="cin-log ${m.who==='me'?'mine':'role'}"><span>${m.who==='me'?'我':cinemaRoleName(c)}</span><p>${esc(m.text).replace(/\n/g,'<br>')}</p><time>${s.kind==='video'?cinemaFmt(m.at||0):'第 '+((m.page||0)+1)+' 页'}</time></div>`).join('');}
function cinemaVisionIntervalLabel(){const set=cinemaInit().settings,n=set.visionInterval,labels={30:'30秒',60:'1分钟',120:'2分钟',150:'2分30秒',300:'5分钟',600:'10分钟'};if(!set.visionEnabled)return'画面关闭';return set.autoVision?('画面 '+(labels[n]||cinemaFmt(n))):'画面按需';}
function cinemaVoiceLangLabel(c){const x=cinemaInit(),v=x.settings.voiceLang,map={role:'跟随角色',zh:'中文',yue:'粤语',en:'英语',ja:'日语',ko:'韩语',fr:'法语',de:'德语',ru:'俄语'};return map[v]||map.role;}
function cinemaReplyCount(){return Math.max(1,Math.min(5,+cinemaInit().settings.replyCount||1));}
function cinemaRandomReplyCount(){const limit=cinemaReplyCount();return limit<=1?1:1+Math.floor(Math.random()*limit);}
function cinemaCompanionMode(){const v=cinemaInit().settings.companionMode;return v==='quiet'||v==='lively'?v:'soft';}
function cinemaCompanionLabel(){const v=cinemaCompanionMode();return v==='quiet'?'安静陪伴':v==='lively'?'活跃陪伴':'轻声陪伴';}
function cinemaAutoLimit(){return Math.max(0,Math.min(20,+cinemaInit().settings.autoLimit||0));}
function cinemaAutoGap(){const v=cinemaCompanionMode();return v==='lively'?115:v==='soft'?230:999999;}
function cinemaCanAutoSpeak(s){const set=cinemaInit().settings;if(!s||cinemaCompanionMode()==='quiet')return false;return (s.autoCount||0)<cinemaAutoLimit();}
function cinemaCommentDisplay(){return cinemaInit().settings.commentDisplay==='subtitle'?'subtitle':'barrage';}
function cinemaCaptionSpeed(){const v=cinemaInit().settings.captionSpeed;return v==='faster'||v==='slower'||v==='slowest'?v:'base';}
function cinemaCaptionSpeedLabel(){const speed=cinemaCaptionSpeed();return speed==='faster'?'更快':speed==='slower'?'标准':speed==='slowest'?'更慢':'快';}
function cinemaCaptionDuration(text,mode){const base=cinemaShotMs(text,mode),speed=cinemaCaptionSpeed(),factor=speed==='faster'?1:speed==='slower'?1.45:speed==='slowest'?1.75:1.2,min=speed==='faster'?3000:3600;return Math.max(min,Math.min(15800,base*factor));}
function cinemaStageTools(){const x=cinemaInit(),c=cinemaRole(),display=cinemaCommentDisplay(),subN=_cin.cues.filter(v=>v&&v.source!=='speech').length,visionOn=x.settings.visionEnabled&&(x.settings.autoVision||x.settings.visionOnAsk||x.settings.visionByRole),platform=!!_cin.provider,platformVision=platform&&privateNativeAppOn();return `<div class="cin-tool-shelf"><button id="cinExtractBtn" data-cin-action="extract">${svgIc('file',14)}<span>${subN?'字幕 '+subN:platform?'导入字幕':'提取字幕'}</span></button><button data-cin-action="frame" ${platform&&!platformVision?'disabled':''}>${svgIc('image',14)}<span>${platform?(platformVision?'系统取帧识别':'网页无法读取平台画面'):'识别此帧'}</span></button><button id="cinVisionBtn" class="${!platform&&visionOn?'on':''}" data-cin-action="vision" ${platform?'disabled':''}><span>${platform?'平台仅支持手动识别':cinemaVisionIntervalLabel()}</span></button><button id="cinVoiceBtn" class="${x.settings.voiceComment?'on':''}" data-cin-action="voice">${svgIc('volume',14)}<span>${x.settings.voiceComment?'语音 · '+cinemaVoiceLangLabel(c):'角色语音'}</span></button><button id="cinReplyBtn" data-cin-action="reply-count"><span>每次最多 ${cinemaReplyCount()}条</span></button><button id="cinAutoBtn" class="${cinemaCompanionMode()!=='quiet'?'on':''}" data-cin-action="auto"><span>${cinemaCompanionLabel()} · ${cinemaAutoLimit()}条/场</span></button><button id="cinDmBtn" class="on" data-cin-action="danmaku"><span>显示 · ${display==='barrage'?'弹幕':'底部字幕'} · ${cinemaCaptionSpeedLabel()}</span></button></div>`;}
function cinemaEventPoint(e){const p=e&&e.changedTouches&&e.changedTouches[0]||e&&e.touches&&e.touches[0]||e||{};return {x:+p.clientX||0,y:+p.clientY||0};}
function cinemaControlDown(e){const b=e&&e.target&&e.target.closest?e.target.closest('[data-cin-action]'):null,p=cinemaEventPoint(e);if(b)_cin.controlDown={el:b,x:p.x,y:p.y};}
function cinemaControlTap(e){const current=e&&e.currentTarget,b=current&&current.matches&&current.matches('[data-cin-action]')?current:e&&e.target&&e.target.closest?e.target.closest('[data-cin-action]'):null;if(!b||b.disabled)return;e.preventDefault();e.stopPropagation();b.classList.add('tap');setTimeout(()=>{if(b.isConnected)b.classList.remove('tap');},260);const a=b.dataset.cinAction;if(a==='play')cinemaTogglePlayback();else if(a==='media-hide')cinemaMediaToggle(false);else if(a==='fullscreen')cinemaToggleFullscreen();else if(a==='extract')cinemaSubtitleMenu();else if(a==='frame')cinemaAnalyzeFrame({currentTarget:b},false);else if(a==='vision')cinemaVisionMenu();else if(a==='voice')cinemaVoiceMenu();else if(a==='reply-count')cinemaReplyCountMenu();else if(a==='auto')cinemaCompanionMenu();else if(a==='danmaku')cinemaToggleDanmaku();else if(a==='back')cinemaVideoBack();else if(a==='rename')cinemaRename(b.dataset.session);else if(a==='end')cinemaEnd();else if(a==='top-close')cinemaTopToggle(false);else if(a==='top-open')cinemaTopToggle(true);else if(a==='chat-close')cinemaChatToggle(false);else if(a==='chat-open')cinemaChatToggle(true);else if(a==='mic')cinemaMicToggle(b.dataset.kind||'video');else if(a==='send')cinemaSend('video');else if(a==='book-voice')cinemaToggleBookVoice();else if(a==='book-send')cinemaSend('book');}
function cinemaControlPointerDown(e){const b=e.currentTarget,p=cinemaEventPoint(e);b._cinPress={x:p.x,y:p.y};}
function cinemaControlPointerUp(e){const b=e.currentTarget;if(!b||b.disabled)return;const p=cinemaEventPoint(e),start=b._cinPress;b._cinPress=null;b._cinPointerAt=Date.now();if(start&&Math.hypot(p.x-start.x,p.y-start.y)>12){e.preventDefault();e.stopPropagation();return;}cinemaControlTap(e);}
