function cinemaBindControls(root){if(!root)return;root.querySelectorAll('[data-cin-action]').forEach(b=>{if(b._cinActionBound)return;b._cinActionBound=true;b.addEventListener('pointerdown',cinemaControlPointerDown);b.addEventListener('pointerup',cinemaControlPointerUp);b.addEventListener('pointercancel',()=>{b._cinPress=null;b._cinPointerAt=Date.now();});b.addEventListener('click',cinemaControlClick);});root.querySelectorAll('[data-cin-resize]').forEach(g=>{if(g._cinResizeBound)return;g._cinResizeBound=true;g.addEventListener('pointerdown',e=>g.dataset.cinResize==='reader'?cinemaReaderResizeStart(e):cinemaComposerResizeStart(e));});}
function cinemaBindWatchControls(){const stage=$('#cinStage');cinemaBindControls(stage);const screen=stage&&stage.querySelector('.cin-screen');if(screen&&!screen._cinRevealBound){screen._cinRevealBound=true;screen.addEventListener('click',cinemaRevealControls);}}
function cinemaBindReaderControls(){cinemaBindControls($('.cin-reader'));}
function cinemaPlayerHTML(){if(_cin.provider==='bilibili'){const info=_cin.videoInfo||{},identity=info.idType==='episode'?'episodeId='+encodeURIComponent(info.id||_cin.externalId):info.idType==='season'?'seasonId='+encodeURIComponent(info.id||_cin.externalId):'bvid='+encodeURIComponent(info.bvid||_cin.externalId),q=['isOutside=true',identity,info.aid?'aid='+encodeURIComponent(info.aid):'',info.cid?'cid='+encodeURIComponent(info.cid):'','p=1','high_quality=1','danmaku=0','autoplay=0'].filter(Boolean).join('&');return'<div class="cin-platform-frame"><iframe id="cinBiliPlayer" class="cin-platform-player" src="https://player.bilibili.com/player.html?'+q+'" title="哔哩哔哩官方播放器" allow="autoplay; fullscreen; picture-in-picture; encrypted-media" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>';}return `<video id="cinVideo" src="${esc(_cin.videoUrl)}" playsinline webkit-playsinline disablepictureinpicture preload="metadata"></video>`;}
function renderCinemaWatch(){const s=cinemaSession(),c=s&&getC(s.cid);if(!s||!c||!_cin.videoUrl)return `<div class="cinema-home">${nav('放映室')}<div class="cin-empty" style="margin:auto;padding:30px">视频源已失效，请回到放映室重新选择视频。<button class="btn p" style="margin-top:16px" onclick="back()">返回放映室</button></div></div>`;
  return `<div class="cin-watch"><div id="cinStage" class="cin-stage cin-theater ${_cin.provider?'cin-platform-stage '+_cin.provider:''} ${_cin.chatOpen?'chat-open':''} ${_cin.mediaOpen===false?'media-hidden':''}" style="--cin-chat-h:${cinemaComposerHeight()}px"><div class="cin-screen">${cinemaPlayerHTML()}<div id="cinDanmaku" class="cin-danmaku"></div><div id="cinSub" class="cin-sub"></div><div id="cinVoiceSub" class="cin-voice-sub"><b></b><span></span></div>
      <div id="cinTopLayer" class="cin-overlay-top ${_cin.topOpen?'':'collapsed'}"><div class="cin-overlay-head"><button class="cin-edge-btn" data-cin-action="back" aria-label="返回">‹</button><button class="cin-watch-meta" data-cin-action="rename" data-session="${s.id}"><b id="cinWatchTitle">${esc(s.title)}</b><span>${cinemaRoleName(c)} 正在陪你看 · 点片名可修改</span></button><button class="cin-fullscreen-btn" data-cin-action="fullscreen" aria-label="切换系统全屏">⛶</button><button class="cin-collapse-btn" data-cin-action="top-close" aria-label="收起功能">⌃</button><button class="cin-end" data-cin-action="end">结束</button></div>${cinemaStageTools()}</div>
      <button id="cinTopReveal" class="cin-top-reveal ${_cin.topOpen?'hidden':''}" data-cin-action="top-open" aria-label="展开功能">•••</button>
      <div id="cinContextStatus" class="cin-status-chip" role="status" aria-live="polite">${_cin.cues.length?'字幕上下文已连接':'尚未理解画面 · 可提取字幕或识图'}</div>
      <div id="cinMediaControls" class="cin-media-controls ${_cin.mediaOpen===false?'hidden':''}" aria-label="影片播放控制"><button id="cinPlayBtn" data-cin-action="play" aria-label="播放">▶</button><input id="cinSeek" type="range" min="0" max="1000" value="0" aria-label="播放进度"><span id="cinTime">0:00 / 0:00</span><button class="cin-media-hide" data-cin-action="media-hide" aria-label="隐藏播放进度">⌄</button></div>
      <div id="cinChatDock" class="cin-chat-dock ${_cin.chatOpen?'open':''}"><button type="button" class="cin-chat-grip" data-cin-resize="video" aria-label="上下拖动调整聊天框高度"><span></span></button><button class="cin-chat-close" data-cin-action="chat-close" aria-label="收起输入">⌄</button><button id="cinVideoMic" class="cin-mic ${_cin.micKind==='video'?'recording':''}" data-cin-action="mic" data-kind="video" aria-label="${_cin.micKind==='video'?'持续话筒已开启，点一下关闭':'点一下开启持续话筒'}">${svgIc('mic',17)}</button><textarea id="cinInput" rows="3" maxlength="160" placeholder="和 ${cinemaRoleName(c)} 聊这一幕…"></textarea><button class="cin-send" data-cin-action="send">发送</button></div>
      <button id="cinChatReveal" class="cin-chat-reveal ${_cin.chatOpen?'hidden':''}" data-cin-action="chat-open">${svgIc('message',15,'#efe8ef')}<span>聊这一幕</span></button>
    </div></div></div>`;}
function cinemaCurrentTime(){const v=$('#cinVideo');if(v)return Math.max(0,Number(v.currentTime)||0);const s=cinemaSession();return Math.max(0,Number(s&&s.progress)||0);}
function cinemaDuration(){const v=$('#cinVideo');if(v&&Number.isFinite(v.duration))return Math.max(0,v.duration);const s=cinemaSession();return Math.max(0,Number(s&&s.duration)||Number(_cin.videoInfo&&_cin.videoInfo.duration)||0);}
function cinemaTogglePlayback(){const v=$('#cinVideo');if(v){if(v.paused){if(_cin.micKind==='video')_cin.micKeepVideoPlaying=true;v.play().catch(()=>cinemaVideoPlaybackError(v));}else{_cin.micKeepVideoPlaying=false;_cin.micVideoPlayToken=Number(_cin.micVideoPlayToken||0)+1;v.pause();}cinemaSyncMediaControls();return;}toast(_cin.provider==='bilibili'?'请使用B站播放器内的播放按钮':'官方播放器还在载入');}
function cinemaMediaToggle(open){_cin.mediaOpen=open!==false;const bar=$('#cinMediaControls'),stage=$('#cinStage');if(bar)bar.classList.toggle('hidden',!_cin.mediaOpen);if(stage)stage.classList.toggle('media-hidden',!_cin.mediaOpen);}
function cinemaSyncMediaControls(){const v=$('#cinVideo'),play=$('#cinPlayBtn'),seek=$('#cinSeek'),time=$('#cinTime');if(!v&&!_cin.provider)return;const duration=cinemaDuration(),current=cinemaCurrentTime(),paused=v?!!v.paused:!!_cin.externalPaused;if(play){play.textContent=paused?'▶':'❚❚';play.setAttribute('aria-label',paused?'播放':'暂停');play.disabled=_cin.provider==='bilibili';}if(seek&&!seek._dragging){seek.value=duration?String(Math.round(current/duration*1000)):'0';seek.disabled=_cin.provider==='bilibili'||!duration;}if(time)time.textContent=_cin.provider==='bilibili'?'使用播放器内控制':cinemaFmt(current)+' / '+cinemaFmt(duration);}
function cinemaVisionResetTimer(s,current){const set=cinemaInit().settings;if(!s)return 0;if(!set.visionEnabled||!set.autoVision){s.nextVisionAt=0;return 0;}const vi=Math.max(30,+set.visionInterval||150);s.nextVisionAt=Math.max(0,+current||0)+vi;save();return s.nextVisionAt;}
function cinemaExternalTick(){const s=cinemaSession();if(!s||!_cin.provider)return;const t=cinemaCurrentTime(),d=cinemaDuration();if(t>=0)s.progress=t;if(d)s.duration=d;s.updatedAt=Date.now();cinemaUpdateSubtitle();cinemaSyncMediaControls();if(Date.now()-_cin.lastSaveAt>5000)cinemaSaveProgress(false);}
async function cinemaAfterExternalRender(){const s=cinemaSession();if(!s)return;cinemaBindWatchControls();cinemaApplyComposerHeight(cinemaComposerHeight(),false);document.body.classList.add('cin-theater-open');const inp=$('#cinInput');if(inp)inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();cinemaSend('video');}});cinemaSyncMediaControls();setTimeout(()=>cinemaEnterImmersive(),60);_cin.externalReady=true;_cin.externalPaused=true;cinemaSetStatus('B站官方播放器已连接 · 请在画面内控制播放','ready');cinemaRestoreStoredSubtitles(s,_cin.token);}
function cinemaAfterVideoRender(){if(_cin.provider)return cinemaAfterExternalRender();const v=$('#cinVideo'),s=cinemaSession();if(!v||!s)return;cinemaBindWatchControls();cinemaApplyComposerHeight(cinemaComposerHeight(),false);document.body.classList.add('cin-theater-open');const sync=()=>cinemaSyncMediaControls(),ready=()=>{_cin.videoErrorShown=false;s.duration=Number.isFinite(v.duration)?v.duration:0;if(s.progress>0&&s.progress<Math.max(0,v.duration-2))try{v.currentTime=s.progress;}catch(_){}cinemaVisionResetTimer(s,Math.max(0,Number(v.currentTime)||Number(s.progress)||0));cinemaSaveProgress(true);sync();if(_cin.wantPlay){_cin.wantPlay=false;v.play().catch(()=>cinemaVideoPlaybackError(v));}};v.addEventListener('loadedmetadata',ready);if(v.readyState>=1)ready();v.addEventListener('play',sync);v.addEventListener('pause',()=>{sync();cinemaMicProtectVideo();});v.addEventListener('durationchange',sync);v.addEventListener('timeupdate',cinemaVideoTick);v.addEventListener('ended',()=>{cinemaSaveProgress(true);sync();});v.addEventListener('seeked',()=>{s.lastAuto=v.currentTime;cinemaVisionResetTimer(s,v.currentTime);cinemaAsrGuardPlayback(v);cinemaUpdateSubtitle();sync();});v.addEventListener('error',()=>cinemaVideoPlaybackError(v));const seek=$('#cinSeek');if(seek){seek.addEventListener('pointerdown',()=>seek._dragging=true);seek.addEventListener('input',()=>{const d=Number.isFinite(v.duration)?v.duration:0;if(d)v.currentTime=d*(+seek.value||0)/1000;sync();});seek.addEventListener('change',()=>{seek._dragging=false;cinemaAsrGuardPlayback(v);sync();});seek.addEventListener('pointerup',()=>{seek._dragging=false;sync();});}const inp=$('#cinInput');if(inp)inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();cinemaSend('video');}});cinemaUpdateSubtitle();sync();setTimeout(()=>cinemaEnterImmersive(),60);}
function cinemaVideoTick(){const v=$('#cinVideo'),s=cinemaSession();if(!v||!s)return;if(cinemaAsrGuardPlayback(v))return;s.progress=v.currentTime||0;s.duration=Number.isFinite(v.duration)?v.duration:s.duration;s.updatedAt=Date.now();cinemaUpdateSubtitle();cinemaSyncMediaControls();if(Date.now()-_cin.lastSaveAt>5000)cinemaSaveProgress(false);const cue=cinemaCueAt(v.currentTime||0),set=cinemaInit().settings,vi=Math.max(30,+set.visionInterval||150);let next=Number(s.nextVisionAt)||0;if(set.visionEnabled&&set.autoVision&&!next)next=cinemaVisionResetTimer(s,v.currentTime||0);if(set.visionEnabled&&set.autoVision&&!v.paused&&!_cin.visionBusy&&next>0&&v.currentTime>=next){s.nextVisionAt=(v.currentTime||0)+vi;save();cinemaAnalyzeFrame(null,true,{interval:true});}const cueKey=cue?(Math.round(cue.start*10)+'|'+cue.text):'';if(cue&&cueKey!==s.lastAutoCue&&cinemaCanAutoSpeak(s)&&!v.paused&&!_cin.busy&&(v.currentTime||0)>20&&(v.currentTime-(s.lastAuto||0)>cinemaAutoGap())){s.lastAuto=v.currentTime;s.lastAutoCue=cueKey;save();cinemaRoleReply('当前刚播放到的台词是：“'+cue.text+'”。只根据截至当前进度已经出现的内容和你的真实性格，判断这句是否真的触动你、让你想讨论或表达感受；绝对不能引用后面的台词或剧情。真有感触就说一句很短的自然反应；没有明显感触只输出 [保持安静]。',true,{allowSilence:true});}}
function cinemaSaveProgress(force){const s=cinemaSession();if(!s)return;_cin.lastSaveAt=Date.now();cinemaInit().progress[s.mediaKey]={kind:s.kind,title:s.title,progress:s.progress||0,duration:s.duration||0,page:s.page||0,updatedAt:Date.now()};save(force?0:500);}
function cinemaUpdateSubtitle(){const v=$('#cinVideo'),sub=$('#cinSub'),status=$('#cinContextStatus');if(!v&&!_cin.provider)return;const cue=cinemaCueAt(cinemaCurrentTime());if(sub){sub.textContent=cue&&cue.source!=='speech'?cue.text:'';sub.classList.toggle('show',!!(cue&&cue.source!=='speech'));}if(status&&!_cin.extracting){if(Date.now()<Number(_cin.statusLockUntil||0))return;status.classList.toggle('working',!!_cin.visionBusy);status.classList.remove('ready','error');status.textContent=_cin.visionBusy?'正在理解当前画面…':(_cin.cues.length||(cinemaSession()&&cinemaSession().sceneDesc))?'':_cin.provider?'官方播放器已连接 · 可导入字幕':'尚未理解画面 · 可提取字幕或识图';}}
function cinemaClearShots(){clearTimeout(_cin.shootTimer);clearTimeout(_cin.voiceSubTimer);_cin.shootTimer=null;_cin.voiceSubTimer=null;_cin.shootQueue=[];_cin.shootEpoch=(_cin.shootEpoch||0)+1;const end=_cin.shootResolve;_cin.shootResolve=null;if(end)try{end();}catch(_){}_cin.shootBusy=false;if(_cin.shootNode&&_cin.shootNode.remove)try{_cin.shootNode.remove();}catch(_){}_cin.shootNode=null;const dm=$('#cinDanmaku'),sub=$('#cinVoiceSub');if(dm)dm.innerHTML='';if(sub)sub.classList.remove('show','mine','role');}
function cinemaShotMs(text,mode){const lines=String(text||'').split(/\n+/),longest=Math.max(1,...lines.map(x=>[...x].length)),total=[...String(text||'')].length;if(mode==='subtitle')return Math.max(3000,Math.min(8000,1400+total*105));return Math.max(5500,Math.min(9000,3900+longest*70+Math.max(0,lines.length-1)*650));}
function cinemaShowShot(who,text){return new Promise(resolve=>{const mode=cinemaCommentDisplay(),ms=cinemaCaptionDuration(text,mode);let done=false;const finish=()=>{if(done)return;done=true;if(_cin.shootResolve===finish)_cin.shootResolve=null;clearTimeout(_cin.shootTimer);_cin.shootTimer=null;if(_cin.shootNode&&_cin.shootNode.remove)try{_cin.shootNode.remove();}catch(_){}_cin.shootNode=null;resolve();};_cin.shootResolve=finish;if(mode==='subtitle'){cinemaShowDialogueSubtitle(who,text,ms);_cin.shootTimer=setTimeout(finish,ms+80);return;}const box=$('#cinDanmaku');if(!box){finish();return;}box.innerHTML='';const d=document.createElement('div');d.className='cin-barrage '+(who==='me'?'mine':'role')+' glide';d.textContent=String(text||'').trim();d.style.top='28%';d.style.animationDuration=(ms/1000)+'s';d.addEventListener('animationend',finish,{once:true});box.appendChild(d);_cin.shootNode=d;_cin.lane++;_cin.shootTimer=setTimeout(finish,ms+400);});}
async function cinemaShootNext(){if(_cin.shootBusy)return;const item=_cin.shootQueue.shift();if(!item)return;_cin.shootBusy=true;const token=item.token,epoch=item.epoch;try{let visual=null,shown=false;const show=audioMs=>{if(shown||token!==_cin.token||epoch!==_cin.shootEpoch)return;shown=true;visual=cinemaShowShot(item.who,item.text,audioMs);};if(item.speakText&&item.speaker){await speakWait(item.speakText,item.speaker,{onAudioStart:show});if(!shown)show();}else show();if(visual)await visual;}catch(_){}finally{if(epoch===_cin.shootEpoch){_cin.shootBusy=false;if(item.who==='role')_cin.micIgnoreUntil=Date.now()+900;if(token===_cin.token&&_cin.shootQueue.length)cinemaShootNext();else if(!_cin.busy)cinemaMicResumeVideo();}}}
function cinemaShoot(who,text,opt){text=String(text||'').trim();if(!text)return;opt=opt||{};_cin.shootQueue.push({who,text,speakText:String(opt.speakText||'').trim(),speaker:opt.speaker||null,token:_cin.token,epoch:_cin.shootEpoch||0});cinemaShootNext();}
function cinemaAppendLog(item){const s=cinemaSession(),box=$('#cinLog');if(!s||!box)return;const empty=box.querySelector('.cin-chat-empty');if(empty)empty.remove();const c=getC(s.cid),d=document.createElement('div');d.className='cin-log '+(item.who==='me'?'mine':'role');d.innerHTML='<span>'+(item.who==='me'?'我':cinemaRoleName(c))+'</span><p>'+esc(item.text).replace(/\n/g,'<br>')+'</p><time>'+(s.kind==='video'?cinemaFmt(item.at||0):'第 '+((item.page||0)+1)+' 页')+'</time>';box.appendChild(d);box.scrollTop=box.scrollHeight;}
function cinemaMirrorToWechat(s,who,text){if(!s||!s.cid||!text)return;const c=getC(s.cid),at=s.kind==='video'?cinemaFmt(cinemaCurrentTime()||s.progress||0):'第 '+((s.page||0)+1)+' 页';cinemaWechatMessages(s).push({role:who==='me'?'user':'assistant',type:'sys',content:'🎬 放映室《'+s.title+'》 '+at+' · '+(who==='me'?S.me.name:(c&&c.name||'角色'))+'：'+String(text).replace(/\s+/g,' ').slice(0,240),time:Date.now(),id:uid(),_silent:true,_cinemaCtx:true,_cinemaSessionId:s.id});}
function cinemaAddItem(who,text,opt){const s=cinemaSession();if(!s||!text)return null;const item={who,text:String(text).slice(0,240),time:Date.now(),at:s.kind==='video'?cinemaCurrentTime():0,page:s.page||0};s.items=s.items||[];s.items.push(item);if(s.items.length>140)s.items=s.items.slice(-140);s.updatedAt=Date.now();cinemaMirrorToWechat(s,who,item.text);save();cinemaAppendLog(item);cinemaShoot(who,opt&&opt.shootText||item.text,opt);return item;}
function cinemaRoleContext(s){if(s.kind==='book'){const i=Math.max(0,Math.min(s.page||0,_cin.bookPages.length-1)),prev=i?_cin.bookPages[i-1].slice(-360):'';return '当前读到第'+(i+1)+'/'+_cin.bookPages.length+'页。\n'+(prev?'上一页结尾：'+prev+'\n':'')+'当前页正文：'+(_cin.bookPages[i]||'').slice(0,1800);}const t=cinemaCurrentTime(),subs=cinemaSubtitleContext(t),cue=cinemaCueAt(t),source=_cin.provider?cinemaPlatformName(_cin.provider)+'官方播放器。':'';return source+'当前播放时间 '+cinemaFmt(t)+' / '+cinemaFmt(s.duration||0)+'。\n'+(cue?'当前屏幕字幕：'+cue.text+'\n':'')+(subs?'截至此刻已经出现的字幕（绝对不要使用更晚内容）：\n'+subs:'')+(!subs?'目前没有可用字幕，只知道片名；不要假装知道具体剧情。':'')+(s.sceneDesc&&Math.abs(t-(s.sceneAt||0))<180?'\n当前画面理解：'+s.sceneDesc:'');}
function cinemaVoiceRule(c,count){const lang=cinemaVoiceLang(c),name={yue:'粤语',en:'英语',ja:'日语',ko:'韩语',fr:'法语',de:'德语',ru:'俄语'}[lang],n=Math.max(1,+count||1);if(!name)return'\n# 本场角色语音语言\n使用自然中文，每条单独一行。';const yue=lang==='yue',example=yue?'呢幕真係幾好睇。\n（这一幕真的挺好看。）':lang==='ja'?'このシーン、すごく好き。\n（我很喜欢这一幕。）':lang==='ko'?'이 장면 정말 좋아.\n（我很喜欢这一幕。）':lang==='fr'?"J’aime beaucoup cette scène.\n（我很喜欢这一幕。）":lang==='de'?'Diese Szene gefällt mir sehr.\n（我很喜欢这一幕。）':lang==='ru'?'Мне очень нравится эта сцена.\n（我很喜欢这一幕。）':'I like this scene.\n（我喜欢这一幕。）';return'\n# 本场角色语音语言\n每条先用'+name+'写真正说出口的一句，下一行用全角括号写准确的普通话中文翻译；共严格输出 '+n+' 组，每组两行，组与组之间换行。例如：\n'+example+'\n'+(yue?'粤语原文必须使用自然地道的粤语口语和粤语用字，不能改写成普通话句子；':'不要把中文夹进外语原文；')+'不要遗漏翻译。';}
function cinemaRoleSystem(c,s,count){const n=Math.max(1,+count||1),past=topSummaries(c.summaries||[],8).map(x=>'· '+summaryCleanText(c,x.text)).join('\n'),vision=cinemaInit().settings.visionByRole&&s.kind==='video'?'\n如果现有字幕确实不足、必须看当前画面才能回答，你可以只输出 [识别画面]；系统识别后会让你重新回答。不要随便调用。':'';return personaPin(c)+'\n角色核心设定：'+(c.persona||'按既有性格自然相处')+'\n说话习惯：'+traitDesc(c)+rolePriorityPrompt()+(past?'\n你们已有的长期记忆：\n'+past:'')+'\n\n# 放映室同屏陪伴\n你正和'+summaryUserLabel(c)+'在“放映室”一起'+(s.kind==='book'?'读':'看')+'《'+s.title+'》。只允许依据给你的【已看到/已读到】内容回应，严禁引用后面的剧情、常识里的结局或假装看到未提供的画面。像真人同屏时发弹幕一样自然回应：本次严格回复 '+n+' 条，每条都是独立短句，中文或粤语每条不超过28字，其他语言每条不超过12个词；严格按要求的条数输出，不合并成长段。保持角色自己的性格与称呼。只能输出要说的话；不要动作描写、第三人称叙述、括号舞台说明、心情标签、分析过程或“作为AI”。'+vision+cinemaVoiceRule(c,n);}
function cinemaCleanRoleText(raw){let t=cleanReply(raw).replace(/^[\s「『“"]+|[」』”"]+$/g,'').replace(/^\s*[\*（(【\[].{0,32}[\*）)】\]]\s*/,'').replace(/\n+/g,' ').trim();return Array.from(t).slice(0,90).join('');}
function cinemaOneSentence(text,limit){let s=String(text||'').replace(/\s+/g,' ').trim(),m=s.match(/^.*?(?:[。！？]|[.!?](?=\s|$))/);if(m)s=m[0];return s.slice(0,limit||80).trim();}
function cinemaParseRolePayloads(raw,c,count){const lang=cinemaVoiceLang(c),n=Math.max(1,Math.min(5,+count||1)),clean=cleanReply(raw),out=[];if(lang==='zh'){const parts=[];clean.split(/\n+/).forEach(line=>{const t=line.replace(/^[\s\-*\d.、]+/,'').replace(/^[「『“"]+|[」』”"]+$/g,'').trim();if(!t||/^\[(?:识别画面|查看画面)\]$/.test(t))return;const hits=t.match(/[^。！？.!?]+[。！？.!?]?/g)||[t];hits.forEach(v=>{v=cinemaOneSentence(v,64);if(v)parts.push(v);});});parts.slice(0,n).forEach(text=>out.push({spoken:text,translation:'',display:text,valid:true}));return out;}const lines=clean.split(/\n+/).map(x=>x.trim()).filter(x=>x&&!/^\[(?:识别画面|查看画面)\]$/.test(x)),code={yue:'粤',en:'英',ja:'日',ko:'韩'}[lang];for(let i=0;i<lines.length&&out.length<n;i++){if(/^[（(].+[）)]$/.test(lines[i]))continue;const spoken=cinemaOneSentence(lines[i].replace(/^[\s\-*\d.、]+/,'').replace(/^[「『“"]+|[」』”"]+$/g,'').trim(),96),next=lines[i+1],translation=cinemaOneSentence(next&&/^[（(].+[）)]$/.test(next)?next.replace(/^[（(]|[）)]$/g,'').trim():'',64);if(translation)i++;if(spoken)out.push({spoken,translation,display:spoken+(translation?'\n'+translation:''),valid:!!(translation&&hasForeign(spoken,code))});}return out;}
function cinemaParseRolePayload(raw,c){return cinemaParseRolePayloads(raw,c,1)[0]||{spoken:'',translation:'',display:'',valid:false};}
async function cinemaRoleReply(reason,automatic,opt){
  opt=opt||{};
  const s=cinemaSession(),c=s&&getC(s.cid);
  if(!s||!c||_cin.busy)return;
  _cin.busy=true;
  const token=_cin.token,send=$('.cin-send'),count=automatic?1:cinemaRandomReplyCount(),max=Math.min(620,140*count);
  if(send)send.disabled=true;
  try{
    const recent=(s.items||[]).slice(-(cinemaContextRounds()*2)).map(x=>(x.who==='me'?summaryUserLabel(c):c.name)+'：'+x.text).join('\n');
    const makePrompt=()=>cinemaRoleContext(s)+'\n\n最近同屏对话：\n'+(recent||'（还没有）')+'\n\n现在的要求：'+reason;
    const sys=cinemaRoleSystem(c,s,count)+(opt.allowSilence?'\n这是角色自行决定是否主动说话的时刻；如果按你的性格并没有明显感触，必须只输出 [保持安静]，不要硬凑反应。':'');
    let raw=await chatAPI([{role:'system',content:sys},{role:'user',content:makePrompt()}],{max,temp:.68});
    if(token!==_cin.token||cinemaSession()!==s)return;
    if(opt.allowSilence&&/^\s*\[(?:保持安静|不说话)\]\s*$/.test(cleanReply(raw)))return;
    if(/^\s*\[(?:识别画面|查看画面)\]\s*$/.test(cleanReply(raw))&&cinemaInit().settings.visionByRole){
      const ok=await cinemaAnalyzeFrame(null,true,{notice:true});
      if(ok)raw=await chatAPI([{role:'system',content:sys.replace(/\n如果现有字幕[\s\S]*?不要随便调用。/, '')},{role:'user',content:makePrompt()+'\n\n系统已经补充了当前画面理解，现在直接回应。'}],{max,temp:.65});
    }
    if(token!==_cin.token||cinemaSession()!==s)return;
    if(opt.allowSilence&&/^\s*\[(?:保持安静|不说话)\]\s*$/.test(cleanReply(raw)))return;
    let outs=cinemaParseRolePayloads(raw,c,count);
    if(cinemaVoiceLang(c)!=='zh'&&(outs.length<count||outs.some(x=>!x.valid))){
      raw=await chatAPI([{role:'system',content:sys},{role:'user',content:makePrompt()+'\n\n上一版语言格式或条数不合格，请严格按每条“目标语言原文一行，下一行（普通话中文翻译）”，共 '+count+' 组重写。'}],{max,temp:.5});
      if(token!==_cin.token||cinemaSession()!==s)return;
      if(opt.allowSilence&&/^\s*\[(?:保持安静|不说话)\]\s*$/.test(cleanReply(raw)))return;
      outs=cinemaParseRolePayloads(raw,c,count);
    }
    outs=outs.filter(x=>x.spoken).slice(0,count);
    const visionResponse=/^针对系统刚识别到的当前画面/.test(String(reason||''));
    if(automatic&&outs.length&&opt.countActive!==false&&!visionResponse){s.autoCount=(s.autoCount||0)+1;save();}
    const set=cinemaInit().settings,voiceOn=s.kind==='book'?set.bookVoice:set.voiceComment;
    outs.forEach(out=>cinemaAddItem('role',out.display||out.spoken,{shootText:out.display||out.spoken,speakText:voiceOn?out.spoken:'',speaker:voiceOn?c:null}));
  }catch(e){if(!automatic)toast((e&&e.message)||'角色暂时没有接上话');}
  finally{if(token===_cin.token)_cin.busy=false;if(send&&send.isConnected)send.disabled=false;if(!_cin.shootBusy&&!_cin.shootQueue.length)cinemaMicResumeVideo();}
}
function cinemaQuestionNeedsVision(text){return /[?？]|(?:谁|什么|怎么|怎样|为什么|哪里|哪儿|哪个|这是谁|这是|画面|屏幕|长什么|在干嘛|发生了什么|看见|看到)/.test(String(text||''));}
async function cinemaSend(kind){const id=kind==='book'?'cinBookInput':'cinInput',inp=$('#'+id),text=inp&&inp.value.trim(),s=cinemaSession(),token=_cin.token;if(!text||_cin.busy||!s)return;inp.value='';cinemaAddItem('me',text);if(kind==='video'&&cinemaInit().settings.visionOnAsk&&cinemaQuestionNeedsVision(text)&&cinemaVisionConfigured())await cinemaAnalyzeFrame(null,true,{silentReply:true});if(token!==_cin.token||cinemaSession()!==s)return;cinemaRoleReply('回应'+summaryUserLabel(cinemaRole())+'刚发的这句话。若对方问剧情，只依据当前上下文回答；不知道就自然承认此刻还看不出来。',false);}
function cinemaMicButton(kind){return $(kind==='book'?'#cinBookMic':'#cinVideoMic');}
function cinemaMicPaint(kind,state){const b=cinemaMicButton(kind);if(!b)return;b.classList.toggle('recording',state==='recording');b.classList.toggle('busy',state==='busy');b.disabled=state==='busy';b.setAttribute('aria-label',state==='recording'?'持续话筒已开启，点一下关闭':state==='busy'?'正在开启持续话筒':'点一下开启持续话筒');b.innerHTML=svgIc('mic',17);}
function cinemaMicProtectVideo(){const v=$('#cinVideo');if(_cin.micKind!=='video'||!_cin.micKeepVideoPlaying||!v||!v.isConnected||!v.paused||v.ended||_cin.asrGuardPaused||_cin.extracting||(typeof document!=='undefined'&&document.hidden))return false;const token=Number(_cin.micVideoPlayToken||0)+1;_cin.micVideoPlayToken=token;[0,120,360,760].forEach(delay=>setTimeout(()=>{if(token!==_cin.micVideoPlayToken||_cin.micKind!=='video'||!_cin.micKeepVideoPlaying||!v.isConnected||!v.paused||v.ended||_cin.asrGuardPaused||_cin.extracting||(typeof document!=='undefined'&&document.hidden))return;const p=v.play();if(p&&typeof p.catch==='function')p.catch(()=>{});},delay));return true;}
function cinemaMicResumeVideo(){const resume=!!_cin.micResumeVideo,v=$('#cinVideo');_cin.micResumeVideo=false;if(resume&&v&&v.isConnected){const p=v.play();if(p&&typeof p.catch==='function')p.catch(()=>{});}cinemaMicProtectVideo();}
function cinemaMicRestart(){if(!_cin.micKind||!_cin.micSR)return;try{_cin.micSR.start();cinemaMicProtectVideo();}catch(_){} }
function cinemaMicStop(notice){const kind=_cin.micKind,sr=_cin.micSR;_cin.micKind='';_cin.micBusy=false;_cin.micSR=null;_cin.micIgnoreUntil=0;_cin.micKeepVideoPlaying=false;_cin.micVideoPlayToken=Number(_cin.micVideoPlayToken||0)+1;if(sr)try{sr.onend=null;sr.onresult=null;sr.onerror=null;sr.stop();}catch(_){}if(kind)cinemaMicPaint(kind,'idle');cinemaMicResumeVideo();if(notice)toast('持续话筒已关闭');}
function cinemaMicHeard(kind,text){text=String(text||'').trim();if(!text||kind!==_cin.micKind||_cin.busy||_cin.shootBusy)return;const inp=$(kind==='book'?'#cinBookInput':'#cinInput');if(!inp)return;clearTimeout(_cin.voiceSubTimer);const sub=$('#cinVoiceSub');if(sub)sub.classList.remove('show','mine','role');inp.value=text;cinemaSend(kind);}
