async function musicSearchApple(q){const url='https://itunes.apple.com/search?term='+encodeURIComponent(q)+'&country=cn&media=music&entity=song&limit=24&lang=zh_cn',res=await fetchT(url,{method:'GET',headers:{Accept:'application/json'}},20000);if(!res.ok)throw new Error('HTTP '+res.status);const payload=await res.json(),rows=Array.isArray(payload&&payload.results)?payload.results:[];return rows.map(track=>({provider:'apple-preview',id:String(track&&track.trackId||''),title:String(track&&track.trackName||'').trim(),artist:String(track&&track.artistName||'').trim(),cover:String(track&&track.artworkUrl100||'').replace(/100x100bb/i,'300x300bb'),duration:Math.max(0,Math.round((+track.trackTimeMillis||0)/1000)),previewUrl:/^https:\/\//i.test(String(track&&track.previewUrl||''))?String(track.previewUrl):'',storeUrl:/^https:\/\//i.test(String(track&&track.trackViewUrl||''))?String(track.trackViewUrl):''})).filter(track=>track.id&&track.title&&track.previewUrl).slice(0,12);}
