function musicSearchPick(index,play){musicInit();const row=_musicSearchRows[Number(index)];if(!row||!row.id)return;let song=(S.music.songs||[]).find(s=>s.provider===row.provider&&String(s.providerId)===String(row.id));const url=row.provider==='apple-preview'?row.previewUrl:musicPublicStreamURL(row.id),prefix=row.provider==='apple-preview'?'ap_':'au_';if(!song){song={id:prefix+row.id,title:row.title||'未命名',artist:row.artist||'',lyrics:'',cover:row.cover||'',provider:row.provider,providerId:row.id,storeUrl:row.storeUrl||'',preview:row.provider==='apple-preview',src:{t:'url',url}};if((S.music.songs||[]).some(s=>s.id===song.id))song.id=prefix+row.id+'_'+uid();S.music.songs.unshift(song);save();}else{song.src={t:'url',url};song.storeUrl=row.storeUrl||song.storeUrl||'';song.preview=row.provider==='apple-preview';if(!song.cover&&row.cover)song.cover=row.cover;}if(play){closeModal();musicOpenPlayer(song.id,true);}else{save();musicSearchPaint();toast(row.provider==='apple-preview'?'已收藏官方试听，可以邀请角色一起听这一段':'已收藏，可以邀请角色一起听');}}
function musicToggleChat(){_mChatOpen=!_mChatOpen;const dock=document.getElementById('musicChatDock'),btn=document.getElementById('musicChatToggle'),input=document.getElementById('m_chat');if(dock)dock.classList.toggle('collapsed',!_mChatOpen);if(!_mChatOpen){if(input)input.blur();musicChatViewportBlur();}if(btn){btn.setAttribute('aria-expanded',String(_mChatOpen));btn.innerHTML=`<svg viewBox="0 0 24 24" width="15" height="15" aria-hidden="true"><path d="m7 ${_mChatOpen?'15':'9'} 5 ${_mChatOpen?'-5':'5'} 5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><span>${_mChatOpen?'收起聊天':'展开聊天'}</span>`;}}
function musicAdd(){musicInit();window._muBlob=null;window._muFileMeta=null;openModal(`<h3>添加歌曲</h3>
  <div class="field"><label>歌名</label><input id="mu_t" placeholder="歌名"></div>
  <div class="field"><label>歌手（选填）</label><input id="mu_a" placeholder="歌手"></div>
  <div class="field"><label>歌词（选填，带 [00:12.00] 时间轴会跟着高亮滚动）</label><textarea id="mu_l" rows="4" placeholder="把歌词粘进来…"></textarea></div>
  <div class="field"><label>音乐来源（二选一）</label>
    <div style="display:flex;gap:8px;margin-top:6px;align-items:center;flex-wrap:wrap"><button class="minibtn" onclick="mPickAudioFile()">选择音乐文件</button><button class="minibtn" onclick="mPickVideoFile()">选择录屏视频</button><span id="mu_file" style="font-size:12px;color:#888"></span></div>
    <div style="font-size:11px;color:#777;margin-top:4px">音乐支持 MP3/M4A 等音频；录屏请点单独的视频按钮。iPhone 可直接从“文件”App 选择。</div>
    <input id="mu_url" placeholder="或粘贴在线直链（.mp3 / .m4a）" style="margin-top:8px;width:100%;border:1px solid #38383a;border-radius:8px;padding:8px;background:#2c2c2e;color:#eee"></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="musicAddSave()">添加</button></div>`);}
function mPickSelected(f){window._muBlob=f;window._muFileMeta={blob:f,fileName:String(f.name||''),fileType:String(f.type||'application/octet-stream'),sourceVideoName:'',sourceVideoSize:0,mediaDuration:0};const e=$('#mu_file');if(e)e.textContent='已选：'+((f.name||'文件')+'').slice(0,22);const tt=$('#mu_t');if(tt&&!tt.value)tt.value=(f.name||'').replace(/\.[^.]+$/,'');}
