function mPickVideoFile(){pickMusicVideoFile(async f=>{const e=$('#mu_file'),tt=$('#mu_t');window._muBlob=null;window._muFileMeta=null;if(e)e.textContent='正在校验录屏声音 0%';if(tt&&!tt.value)tt.value=(f.name||'').replace(/\.[^.]+$/,'');try{const prepared=await musicPreparePickedFile(f,'video',p=>{if(e)e.textContent='正在校验录屏声音 '+p+'%';});window._muBlob=prepared.blob;window._muFileMeta=prepared;if(e)e.textContent='已验证：'+String(prepared.fileName||'录屏视频').slice(0,22);toast('录屏声音可播放，可以添加');}catch(err){if(e)e.textContent='录屏声音校验失败';toast((err&&err.message)||'这段录屏没有可播放的声音');}});}
