  Object.keys(APPDEFS).forEach(k=>{if(!seen.has(k)){clean[1].push(k);seen.add(k);}});
  Object.keys(HOME_SHORTCUTS).forEach(k=>{if(!seen.has(k)){clean[1].push(k);seen.add(k);}});
