let _privatePhoneAccount={loaded:false,loading:false,loggedIn:false,maskedPhone:'',userId:'',backup:null,error:''};
const PRIVATE_PHONE_AUTO_BACKUP_DELAY=30*60*1000,PRIVATE_PHONE_AUTO_BACKUP_RETRY=5*60*1000,PRIVATE_PHONE_RESTORE_ROLLBACK_KEY='__private_phone_restore_rollback';
let _privatePhoneCloudDirtyAt=0,_privatePhoneCloudTimer=null,_privatePhoneCloudBusy=false,_privatePhoneLastInteractionAt=Date.now();
