function foodReceive(mid){let found;for(const k in S.messages){const m=S.messages[k].find(x=>x.id===mid);if(m){found={m,k};break;}}
  if(!found||found.m.received)return;found.m.received=true;msgs(found.k).push({role:'user',type:'sys',content:'你签收了外卖：'+found.m.name,time:Date.now(),id:uid()});adjMood(found.k,6);save();render();toast('已签收 '+found.m.name);
  const c=getC(found.k);if(c&&!c.blocked)delayedAccountReply(found.k,'[系统：'+S.me.name+'刚刚签收了你点的外卖「'+found.m.name+'」。这是本轮新发生且必须先回应的事件，优先于此前未完话题。第一句话必须明确确认外卖已送到或提醒ta趁热吃，并自然提到餐品或吃饭；完成后才可以按人设承接旧话题。不能只继续旧话题，不能提系统。请用一至两句自然回应。]',1500);}
function foodReject(mid){let found;for(const k in S.messages){const m=S.messages[k].find(x=>x.id===mid);if(m){found={m,k};break;}}
  if(!found||found.m.received||found.m.declined)return;found.m.declined=true;msgs(found.k).push({role:'user',type:'sys',content:'你拒收了外卖：'+found.m.name,time:Date.now(),id:uid()});adjMood(found.k,-10);save();render();toast('已拒收');
  const c=getC(found.k);if(c&&!c.blocked)delayedAccountReply(found.k,'[系统：'+S.me.name+'拒收了你点的外卖「'+found.m.name+'」，回应一下。]',1500);}

/* ---------- 日历 ---------- */
const HOLIDAYS={'01-01':'元旦','02-14':'情人节','03-08':'女神节','05-01':'劳动节','05-20':'520','06-01':'儿童节','10-01':'国庆节','12-24':'平安夜','12-25':'圣诞节','12-31':'跨年'};
function todayStr(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function coupleDays(startDate,now){const m=(''+(startDate||'')).match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return 0;
  const d=new Date(now||Date.now()),start=Date.UTC(+m[1],+m[2]-1,+m[3]),today=Date.UTC(d.getFullYear(),d.getMonth(),d.getDate());
  return Math.max(1,Math.floor((today-start)/86400000)+1);}
function holidayOf(dateStr){const md=dateStr.slice(5);return HOLIDAYS[md]||'';}
/* ---------- 每日心情表 ---------- */
const MOOD_EMOJIS=['😊','🥰','😌','😐','😔','😣','😡','😭','😴','🤒'];
function moodToday(who){pruneDailyMood();const t=todayStr();return (S.mood||[]).find(m=>m.date===t&&m.who===who);}
function logMyMood(emoji){pruneDailyMood();const t=todayStr();S.mood=S.mood||[];let e=S.mood.find(m=>m.date===t&&m.who==='me');if(e){e.emoji=emoji;e.time=Date.now();}else S.mood.unshift({id:uid(),date:t,who:'me',emoji,note:'',time:Date.now()});if(S.mood.length>150)S.mood=S.mood.slice(0,150);save();render();toast('记下今天心情啦 · '+moodLabel(emoji));}
function myMoodNote(){pruneDailyMood();const t=todayStr();let e=(S.mood||[]).find(m=>m.date===t&&m.who==='me');const v=prompt('今天想记点啥心情？（他能看到）',e?e.note:'');if(v==null)return;S.mood=S.mood||[];if(e){e.note=v.trim();e.time=Date.now();}else S.mood.unshift({id:uid(),date:t,who:'me',emoji:'',note:v.trim(),time:Date.now()});save();render();}
async function moodDel(mid){if(!await uiConfirm('删掉这条心情记录？'))return;S.mood=(S.mood||[]).filter(m=>m.id!==mid);save();render();}
async function recordTaMood(cid){pruneDailyMood();const c=getC(cid);if(!c||c.blocked)return false;const t=todayStr();if((S.mood||[]).some(m=>m.date===t&&m.who===cid))return true;
  const mine=(S.mood||[]).find(m=>m.date===t&&m.who==='me');
  try{const moodList=MOODK.map(k=>k+'='+MOODS[k][0]).join('、');
    const sys=buildSystem(c)+'\n\n# 现在：在你手机「每日心情表」里记今天的一条\n关于'+S.me.name+'今天的状态、你俩今天的事、你的心情感受，记一句。'+(mine?'（ta今天自己记的心情是：'+moodLabel(mine.emoji)+' '+(mine.note||'')+'，你可以体贴地回应这个）':'')+'\n从这些心情里挑一个最贴切的（只用英文key）：'+moodList+'\n只输出一行，格式：心情key|一句不超过28字的心情记录。例如：love|今天她对我笑了，心都化了。别的都不要、别带方括号。';
    const r=await chatAPI([{role:'system',content:sys},{role:'user',content:'记今天'}],{max:80,aux:true});
    let line=cleanReply(r).replace(/\n/g,' ').trim();if(!line)return false;
    let mk='calm',note=line;const mm=line.match(/^\s*([a-z]+)\s*[|｜:：]\s*(.+)$/i);
    if(mm&&MOODS[mm[1].toLowerCase()]){mk=mm[1].toLowerCase();note=mm[2];}else{const em=(line.match(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2764}\u{2728}]/u)||[])[0];if(em){mk=moodKeyOf(em);note=line.replace(em,'');}}
    note=note.replace(/^[\s,，。、|｜:：]+/,'').slice(0,40)||line.slice(0,40);
    S.mood=S.mood||[];S.mood.unshift({id:uid(),date:t,who:cid,emoji:mk,note,time:Date.now()});if(S.mood.length>150)S.mood=S.mood.slice(0,150);save();if(cur().p==='calendar')render();return true;
  }catch(e){return false;}}
function moodSection(){pruneDailyMood();const my=moodToday('me');const recent=(S.mood||[]).slice(0,10);const sel=my?moodKeyOf(my.emoji):'';
  const picker=MOODK.map(k=>`<span onclick="logMyMood('${k}')" title="${MOODS[k][0]}" style="cursor:pointer;padding:5px;border-radius:11px;display:inline-flex;${sel===k?'background:rgba(255,126,179,.3)':''}">${moodIc(k,24,'#c25a86')}</span>`).join('');
  const rows=recent.length?recent.map(m=>{const isMe=m.who==='me';const who=isMe?S.me.name:(getC(m.who)?(getC(m.who).remark||getC(m.who).name):'ta');return `<div style="display:flex;align-items:center;gap:7px;font-size:13px;color:#8a5670;padding:6px 0;border-top:.5px solid rgba(184,92,129,.18)"><span style="color:#c08aa0;width:36px;flex-shrink:0">${m.date.slice(5)}</span><b style="color:${isMe?'#d6568f':'#6f97c9'};flex-shrink:0">${esc(who)}</b><span style="flex-shrink:0;display:inline-flex">${moodGlyph(m.emoji,18,isMe?'#d6568f':'#6f97c9')}</span><span style="flex:1;min-width:0">${esc(m.note||'')}</span><span onclick="moodDel('${m.id}')" style="color:#e08aa0;cursor:pointer;flex-shrink:0">✕</span></div>`;}).join(''):'<div style="color:#b07a90;font-size:12px;padding:6px 0">点上面的小脸记今天心情～ta每天也会记一条，你俩都看得到对方</div>';
  return `<div style="margin:10px 12px;padding:13px 14px;border-radius:16px;background:linear-gradient(135deg,#ffe3ee,#ffd6e6 70%,#ffe0ef);box-shadow:0 6px 18px rgba(232,150,181,.22)"><div style="font-weight:700;color:#c2407a;margin-bottom:8px">每日心情表</div>
    <div style="display:flex;align-items:center;flex-wrap:wrap;gap:2px;margin-bottom:4px">${picker}<span onclick="myMoodNote()" style="margin-left:auto;font-size:13px;color:#c2407a;font-weight:600;cursor:pointer">写两句</span></div>
    ${rows}</div>`;}
let _calMonth='',_calSelected='',_calClockDay='';
function calDateParts(s){const m=String(s||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?{y:+m[1],m:+m[2],d:+m[3]}:null;}
function calDateString(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function calEnsure(){const today=todayStr();if(!_calMonth||_calClockDay!==today){_calMonth=today.slice(0,7);_calSelected=today;_calClockDay=today;}if(!calDateParts(_calSelected))_calSelected=today;}
function calSelect(date){if(!calDateParts(date))return;_calSelected=date;_calMonth=date.slice(0,7);render();}
function calShift(step){calEnsure();const p=calDateParts(_calSelected),mp=calDateParts(_calMonth+'-01'),day=p?p.d:1,last=new Date(mp.y,mp.m+(+step||0),0),next=new Date(last.getFullYear(),last.getMonth(),Math.min(day,last.getDate()));_calSelected=calDateString(next);_calMonth=_calSelected.slice(0,7);render();}
function calToday(){_calClockDay='';calEnsure();render();}
function calLocate(){calEnsure();openModal(`<h3>定位日期</h3><div class="field"><label>选择日期</label><input id="cal_locate_date" type="date" value="${_calSelected}"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="calLocateGo()">定位</button></div>`);}
function calLocateGo(){const el=$('#cal_locate_date'),v=el&&el.value;if(!calDateParts(v)){toast('请选择日期');return;}closeModal();calSelect(v);}
function calWeekLabel(date){const p=calDateParts(date);return p?'星期'+'日一二三四五六'[new Date(p.y,p.m-1,p.d).getDay()]:'';}
function calUtcValue(s){const p=calDateParts(s);return p?Date.UTC(p.y,p.m-1,p.d):NaN;}
function calDayDiff(a,b){const av=calUtcValue(a),bv=calUtcValue(b);return Number.isFinite(av)&&Number.isFinite(bv)?Math.round((av-bv)/86400000):NaN;}
function calAddDays(s,n){const p=calDateParts(s);if(!p)return'';const d=new Date(Date.UTC(p.y,p.m-1,p.d+(+n||0)));return d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0');}
function periodStore(){if(!Array.isArray(S.periods))S.periods=[];return S.periods;}
function periodNormalize(p){if(!p||!calDateParts(p.startDate))return null;const hadEnd=Object.prototype.hasOwnProperty.call(p,'endDate'),end=calDateParts(p.endDate)?p.endDate:(hadEnd?'':p.startDate);if(end&&calDayDiff(end,p.startDate)<0)return null;return Object.assign(p,{endDate:end});}
function periodRecords(){return periodStore().map(periodNormalize).filter(Boolean).sort((a,b)=>a.startDate.localeCompare(b.startDate));}
function periodEffectiveEnd(p){if(p&&calDateParts(p.endDate))return p.endDate;const today=todayStr();return p&&calDayDiff(today,p.startDate)>=0?today:(p&&p.startDate||today);}
function periodForDate(date){return periodRecords().filter(p=>calDayDiff(date,p.startDate)>=0&&calDayDiff(periodEffectiveEnd(p),date)>=0);}
function periodEstimate(){const rows=periodRecords();if(!rows.length||!rows[rows.length-1].endDate)return null;let cycle=28;if(rows.length>1){const gaps=[];for(let i=Math.max(1,rows.length-4);i<rows.length;i++){const n=calDayDiff(rows[i].startDate,rows[i-1].startDate);if(n>=20&&n<=45)gaps.push(n);}if(gaps.length)cycle=Math.round(gaps.reduce((a,b)=>a+b,0)/gaps.length);}const last=rows[rows.length-1];return {date:calAddDays(last.startDate,cycle),cycle,last};}
function periodFactsText(){const rows=periodRecords();if(!rows.length)return'';const today=todayStr(),last=rows[rows.length-1],ongoing=!last.endDate&&calDayDiff(today,last.startDate)>=0,previous=rows.length>1?rows[rows.length-2]:null,est=periodEstimate();if(ongoing)return '本次经期于'+last.startDate+'开始，目前仍在进行、还没有记录结束日期；今天是第'+(calDayDiff(today,last.startDate)+1)+'天';if(!last.endDate)return '已记录经期将于'+last.startDate+'开始，目前没有结束日期';const duration=calDayDiff(last.endDate,last.startDate)+1,gap=previous&&previous.endDate?calDayDiff(last.startDate,previous.endDate)-1:null,current=calDayDiff(today,last.startDate)>=0&&calDayDiff(last.endDate,today)>=0;let t='最近一次：'+last.startDate+'开始，'+last.endDate+'结束，共'+duration+'天';if(Number.isFinite(gap))t+='；距离上一次结束间隔'+gap+'天';if(current)t+='；今天处于本次记录的第'+(calDayDiff(today,last.startDate)+1)+'天';if(est)t+='；按现有记录粗略估计下次约在'+est.date+'前后（只是估计，不是确定日期）';return t;}
function periodSummaryCard(){const rows=periodRecords(),est=periodEstimate();if(!rows.length)return `<section class="cal-agenda" style="background:linear-gradient(135deg,#fff2f6,#ffe6ef)"><div class="cal-agenda-title"><div><strong style="color:#b43d69">经期记录</strong><span>可以先记录开始日期，结束后再补准确日期</span></div><button onclick="addCalEvent('${todayStr()}','period')">记录开始</button></div><div class="cal-empty" style="color:#a77387">还没有经期记录</div></section>`;const last=rows[rows.length-1],ongoing=!last.endDate,days=calDayDiff(periodEffectiveEnd(last),last.startDate)+1,prev=rows.length>1?rows[rows.length-2]:null,gap=!ongoing&&prev&&prev.endDate?calDayDiff(last.startDate,prev.endDate)-1:null;return `<section class="cal-agenda" style="background:linear-gradient(135deg,#fff2f6,#ffe6ef);border-color:rgba(218,91,137,.16)"><div class="cal-agenda-title"><div><strong style="color:#b43d69">经期记录</strong><span>${last.startDate} ${ongoing?'开始 · 进行中第 '+days+' 天':'至 '+last.endDate+' · '+days+'天'}</span></div><button onclick="${ongoing?`periodEndModal('${last.id}')`:`addCalEvent('${todayStr()}','period')`}">${ongoing?'记录结束':'记录本次'}</button></div><div style="padding:0 4px 4px;color:#9c6077;font-size:12px;line-height:1.7">${ongoing?'角色已经知道本次开始；补上结束日期后也会知道实际持续天数。':(Number.isFinite(gap)?'距上一次结束 '+gap+' 天 · ':'')+(est?'预计下次约在 '+est.date+' 前后':'记录两次后可估算周期')}<br><span style="color:#b98799">预测只依据你的历史记录，用于生活提醒，不作医疗判断。</span></div></section>`;}
function calDelete(id){S.calendar=S.calendar.filter(x=>x.id!==id);save();render();}
function calDeletePeriod(id){askConfirm('删除这一整段经期记录？',()=>{S.periods=periodStore().filter(x=>x.id!==id);save();render()},{danger:true});}
function periodEndModal(id){const p=periodRecords().find(x=>x.id===id);if(!p||p.endDate)return;openModal(`<h3>记录经期结束</h3><div class="hint" style="margin-bottom:12px">开始日期：${esc(p.startDate)}。补上准确结束日期后，角色会知道本次已经结束和实际持续天数。</div><div class="field"><label>结束日期（含当天）</label><input id="period_end_date" type="date" value="${todayStr()}"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="periodEndSave('${p.id}')">保存结束日期</button></div>`);}
function periodEndSave(id){const p=periodRecords().find(x=>x.id===id),end=($('#period_end_date')||{}).value;if(!p||!calDateParts(end)||calDayDiff(end,p.startDate)<0){toast('结束日期不能早于开始日期');return;}p.endDate=end;p.endedAt=Date.now();save();closeModal();render();toast('经期结束日期已记录，角色也会知道');}
function calEventRow(e){const c=getC(e.contactId),period=e.type==='period',wedding=e.type==='wedding',del=period&&e._periodId?`calDeletePeriod('${e._periodId}')`:`calDelete('${e.id}')`,kind=wedding?'婚礼预约':period?'生理期':'日程',detail=wedding&&e.time?e.time+' · '+kind:kind;return `<div class="cal-event"><i style="background:${wedding?'#b89378':period?'#ff5b78':'#4b8cff'}"></i><div class="cal-event-main"><b>${esc(e.title)}</b><small>${period?(e._periodDay?'生理期 · 第'+e._periodDay+'天':'生理期'):esc(detail)}${c?' · '+esc(c.remark||c.name)+(wedding?'赴约':'提醒'):''}</small></div><button onclick="${del}" aria-label="删除日程">${svgIc('trash',17,'currentColor')}</button></div>`;}
function renderCalendar(){pruneDailyMood();calEnsure();const today=todayStr(),mp=calDateParts(_calMonth+'-01'),first=new Date(mp.y,mp.m-1,1),start=new Date(mp.y,mp.m-1,1-first.getDay()),monthLabel=mp.y+'年'+mp.m+'月',week=['日','一','二','三','四','五','六'],byDate={};(S.calendar||[]).forEach(e=>{if(e&&e.date)(byDate[e.date]||(byDate[e.date]=[])).push(e);});periodRecords().forEach(p=>{const days=calDayDiff(periodEffectiveEnd(p),p.startDate)+1;for(let i=0;i<days;i++){const date=calAddDays(p.startDate,i);(byDate[date]||(byDate[date]=[])).push({id:'period-day-'+p.id+'-'+i,_periodId:p.id,_periodDay:i+1,date,title:p.title||'生理期',type:'period',contactId:p.contactId||''});}});const cells=[];for(let i=0;i<42;i++){const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i),ds=calDateString(d),outside=d.getMonth()!==mp.m-1,events=byDate[ds]||[],hol=holidayOf(ds);cells.push(`<button class="cal-day${outside?' outside':''}${ds===today?' today':''}${ds===_calSelected?' selected':''}" onclick="calSelect('${ds}')"><span>${d.getDate()}</span>${hol?'<small>'+esc(hol.slice(0,4))+'</small>':''}${events.length?'<i class="cal-dot'+(events.some(x=>x.type==='period')?' period':'')+'"></i>':''}</button>`);}const selectedEvents=(byDate[_calSelected]||[]).slice().sort((a,b)=>String(a.title||'').localeCompare(String(b.title||''))),sp=calDateParts(_calSelected),selectedLabel=sp?(sp.m+'月'+sp.d+'日 · '+calWeekLabel(_calSelected)):'';
  return `<div class="nav cal-nav"><span class="l" onclick="back()">‹</span><span class="t">日历</span><span class="r" onclick="addCalEvent('${_calSelected}')">＋</span></div><div class="scroll cal-scroll"><section class="cal-card"><div class="cal-toolbar"><div><strong>${monthLabel}</strong><small>${selectedLabel}</small></div><div class="cal-tools"><button onclick="calLocate()">${svgIc('search',16,'currentColor')}<em>定位</em></button><button onclick="calToday()">今天</button></div></div><div class="cal-month-nav"><button onclick="calShift(-1)" aria-label="上个月">‹</button><div></div><button onclick="calShift(1)" aria-label="下个月">›</button></div><div class="cal-week">${week.map(x=>'<span>'+x+'</span>').join('')}</div><div class="cal-grid">${cells.join('')}</div></section>${periodSummaryCard()}<section class="cal-agenda"><div class="cal-agenda-title"><div><strong>${selectedLabel}</strong>${holidayOf(_calSelected)?'<span>'+esc(holidayOf(_calSelected))+'</span>':''}</div><button onclick="addCalEvent('${_calSelected}')">添加日程</button></div>${selectedEvents.length?selectedEvents.map(calEventRow).join(''):'<div class="cal-empty">这一天没有安排</div>'}</section>${moodSection()}<div style="height:20px"></div></div>`;}
function addCalEvent(date,presetType){openModal(`<h3>${presetType==='period'?'记录经期':'添加日程'}</h3>
  <div class="field"><label>日期</label><input id="ce_d" type="date" value="${calDateParts(date)?date:todayStr()}"></div>
  <div class="field"><label>事项</label><input id="ce_t" placeholder="${presetType==='period'?'生理期（可不填）':'去看医生 / 发工资…'}"></div>
  <div class="field"><label>类型</label><select id="ce_type" onchange="calEventTypeChanged()"><option value="event"${presetType==='period'?'':' selected'}>普通日程</option><option value="period"${presetType==='period'?' selected':''}>姨妈期</option><option value="wedding">预约婚礼</option></select></div>
  <div class="field" id="ce_end_wrap" style="display:${presetType==='period'?'block':'none'}"><label>结束日期（可稍后补）</label><input id="ce_end" type="date" value=""><div class="hint">只填开始日期即可先保存为“进行中”，角色会知道；结束后再补准确日期，角色也会知道实际持续天数。</div></div>
  <div class="field" id="ce_time_field" style="display:none"><label>准确时间</label><input id="ce_time" type="time" value="19:00" step="60"><div class="hint" style="margin-top:7px">保存后只记录约定，不会提前发卡；到了这个日期和时间，角色才会主动发来婚礼形式选择卡。</div></div>
  <div class="field"><label>谁提醒我</label><select id="ce_c"><option value="">不提醒</option>${S.contacts.filter(c=>!c.deleted).map(c=>`<option value="${c.id}">${esc(c.remark||c.name)}</option>`).join('')}</select></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="saveCalEvent()">保存</button></div>`);}
function calEventTypeChanged(){const typeEl=$('#ce_type'),wrap=$('#ce_end_wrap'),timeField=$('#ce_time_field'),title=$('#ce_t'),role=$('#ce_c'),coupleCid=S.couple&&S.couple.cid||'';if(!typeEl)return;const type=typeEl.value;if(wrap)wrap.style.display=type==='period'?'block':'none';if(timeField)timeField.style.display=type==='wedding'?'block':'none';if(title&&type==='wedding'&&!title.value.trim())title.value='我们的婚礼';if(role){if(type==='wedding'){role.value=coupleCid;role.disabled=true;if(!coupleCid)toast('请先在情侣空间绑定婚礼角色');}else role.disabled=false;}}
function saveCalEvent(){const d=$('#ce_d').value,t=$('#ce_t').value.trim(),type=$('#ce_type').value,cid=$('#ce_c').value,time=type==='wedding'?($('#ce_time')&&$('#ce_time').value||''):'';if(!d){toast('请选择日期');return;}if(type==='period'){const end=(($('#ce_end')||{}).value||'').trim();if(end&&(!calDateParts(end)||calDayDiff(end,d)<0)){toast('结束日期不能早于开始日期');return;}periodStore().push({id:uid(),startDate:d,endDate:end,title:t||'生理期',contactId:cid,createdAt:Date.now()});save();closeModal();render();toast(end?'经期开始和结束日期已记录，角色也会知道':'经期开始日期已记录，角色会知道本次正在进行');return;}if(!t){toast('填写事项');return;}if(type==='wedding'&&(!S.couple||!S.couple.cid||cid!==S.couple.cid)){toast('婚礼只能与情侣空间绑定的角色进行');return;}if(type==='wedding'&&!time){toast('预约婚礼需要准确时间');return;}const eventAt=type==='wedding'?new Date(d+'T'+time+':00').getTime():0;if(type==='wedding'&&!Number.isFinite(eventAt)){toast('婚礼日期或时间不正确');return;}
  const e={id:uid(),date:d,title:t,type,contactId:cid};if(type==='wedding'){e.time=time;e.eventAt=eventAt;e.weddingStyle='choice';}S.calendar.push(e);save();if(type==='wedding'&&typeof weddingScheduleCalendarEvent==='function')weddingScheduleCalendarEvent(e);closeModal();render();toast(type==='wedding'?'婚礼日期已约定；到时角色会主动发来邀请卡':'已添加 📅');}
