async function dgGenerateArt(answer,instruction){const subject=String(answer||instruction||'可爱的日常物品').trim().slice(0,120),cat=/猫|cat/i.test(subject),dog=/狗|犬|dog|puppy/i.test(subject),species=cat?' For a cat: unmistakable domestic cat proportions, a broad round head, two small soft triangular cat ears, almond eyes, tiny nose, whiskers, a compact connected torso, four short rounded paws and one curved cat tail. Never give it rabbit ears, a human-shaped body, dangling stick limbs, or huge circular cartoon eyes.':dog?' For a dog: unmistakable friendly puppy proportions, floppy curved ears, canine muzzle and nose, compact connected torso, four short paws, collar and curved tail.':'',prompt='Create one highly recognizable cute illustration of exactly this subject: '+subject+'. Match a casual human colored-pencil doodle made by a skilled person: medium-thick strokes like a real colored pencil or soft marker, not heavy black tubing; subtle hand wobble and pressure variation; softly rounded organic curves; charming asymmetry without malformed anatomy. The result must look naturally hand-drawn but immediately resemble the real subject, not a symbol assembled from circles and sticks. Use warm cream paper, dark charcoal-brown outlines and cheerful muted colors. Keep the silhouette species-correct, compact and connected. Respect real occlusion: torso begins below the head and neck, body outlines never cross the mouth, muzzle, eyes or face, and rear parts stay behind front parts.'+species+' The centered subject fills about 72 percent of the canvas. No words, letters, labels, border, frame, watermark, photorealism, or unrelated characters. Portrait 2:3 illustration.',ch=S.settings.chat||{},base=((S.settings.imgBase||ch.base)||'').replace(/\/+$/,''),key=(S.settings.imgKey||ch.key)||'',model=S.settings.imgModel||'gpt-image-2';if(!base||!key)throw new Error('还没配置生图线路');return stableImageSrc((await imageGenerateExternal(base,key,model,prompt,'1024x1536','low')).url);}
function dgCleanSpeech(v){return String(v||'').replace(/[\[\]【】]/g,'').replace(/^(?:角色|TA|我)\s*[：:]\s*/,'').trim().slice(0,80);}
function dgChineseSpeech(v){const t=dgCleanSpeech(v);if(!/[A-Za-z]/.test(t))return t;const s=t.replace(/[A-Za-z][A-Za-z0-9'’_-]*(?:\s+[A-Za-z][A-Za-z0-9'’_-]*)*/g,'').replace(/\s+([，。！？、；：,.!?])/g,'$1').replace(/([\u3400-\u9fff])\s+([\u3400-\u9fff])/g,'$1$2').replace(/^[\s,.;:!?，。！？、；：—-]+|[\s,.;:!?，。！？、；：—-]+$/g,'').replace(/\s{2,}/g,' ').trim();return /[\u3400-\u9fff]/.test(s)?s.slice(0,80):'';}
async function dgEnsureChineseSpeech(c,g,v,scene){let t=dgCleanSpeech(v);if(!/[A-Za-z]/.test(t))return t;if(!t)return'';try{const task='\n画室气泡只能使用自然的简体中文，任何英文字母、英文单词或英文句子都禁止出现。请保持原意和人设，把待修正台词改写为一句纯中文。只输出JSON：{"say":"纯中文台词"}。';const raw=await chatAPI(dgRoleChatMessages(c,g,task,'场景：'+(scene||'画画互动')+'\n待修正台词：'+t),{aux:true,max:160,temp:.45});let obj={};try{obj=parseObj(raw);}catch(_){}const fixed=dgChineseSpeech(obj.say||raw);if(fixed)return fixed;}catch(_){}return dgChineseSpeech(t);}
function dgAddDialogue(who,text){if(!_dg)return;const t=who==='ta'?dgChineseSpeech(text):String(text||'').trim();if(!t)return;_dg.dialogue=Array.isArray(_dg.dialogue)?_dg.dialogue:[];_dg.dialogue.push({who:who==='ta'?'ta':'me',text:t,time:Date.now()});_dg.dialogue=gameContextRows(_dg.dialogue);if(who==='ta')_dg.roleSpeech=t;else _dg.meSpeech=t;}
function dgRoleSystem(c,g,task){const rows=gameContextRows((g.dialogue||[])).map(x=>(x.who==='ta'?(c.remark||c.name):S.me.name)+'：'+x.text).join('\n');return buildSystem(c,{worldbookScope:'wechat'})+'\n\n# 当前游戏大厅画室（最高优先级）\n你正在和'+S.me.name+'一起画画。这里与游戏大厅设置完全一致，只保留最近 '+gameContextRounds()+' 个完整回合。你必须延续微信中的人设、关系、世界书、长期记忆和真实聊天上下文。\n'+(rows?('本局双方真实说过的话：\n'+rows+'\n'):'')+'绝不能替'+S.me.name+'说话，也不能虚构ta说过、猜过或评价过任何内容。你的气泡里只能出现你此刻真正想说的话，不能复述界面提示、系统状态或预设套话。所有角色台词、题目、类别和提示只能使用简体中文，字段值中禁止出现任何英文字母、英文单词或英文句子；即使你平时会说英文，这个画室里也必须全部改成中文。JSON键名可以按格式保留。'+task;}
function dgRoleChatMessages(c,g,task,user){const rows=msgs(c.id).filter(m=>(m.role==='user'||m.role==='assistant')&&msgToText(m)).map(m=>({who:m.role==='assistant'?'ta':'me',content:msgToText(m)})),h=gameContextRows(rows).map(m=>({role:m.who==='ta'?'assistant':'user',content:m.content}));return [{role:'system',content:dgRoleSystem(c,g,task)},...h,{role:'user',content:user}];}
async function dgGenerateRoleDrawing(resume){
  if(!_dg||_dg.mode==='me')return;
  const g=_dg,c=getC(g.cid);g.busy=true;g.activity='正在构思';g.phase='planning';dgSaveDraft(g);render();
  try{
    const choose=!g.answer,precisionArt=dgImageConfigured()&&(g.mode==='role'||g.mode==='photo'),drawTask='\n你要设计一幅可逐笔播放、第一眼就能认出题目的可爱真人手绘。严格参考轻松彩铅涂鸦：中等偏粗但不能像黑色管线，轮廓有很轻的手抖和压力变化，曲线圆润，没有尺子般笔直的线、尖锐多边形转角或带棱角的动物耳朵。最重要的唯一标准是“像”：主体占画布约65%到80%，轮廓连贯，各部位按真实空间关系连接。必须先规划遮挡层级：后方的身体、尾巴和腿先画，头脸等前景后画；身体上缘从头颈下方开始，任何身体、衣服或装饰线都绝不能穿过嘴巴、口鼻、眼睛或脸。禁止把动物画成长条人形、火柴人或抽象符号。动物必须有明确头部、口鼻、两只柔软圆弧耳朵、完整躯干、四肢或可见脚爪和尾巴；小狗应有犬类口鼻、自然连接的身体、腿和弯曲尾巴，绝不能只画椭圆脸加一根长身体。蛋糕必须有稳定蛋糕胚、分层、奶油边缘和正确立在顶部的蜡烛。树要有树干双侧轮廓、根部、分叉树枝和层叠树冠。人物要有连贯外轮廓、五官、躯干、四肢和服装层次。不要写任何字、字母或装饰符号。\n只输出JSON：{"answer":"画的内容","category":"类别","hint":"自然提示","startSay":"你开始画时真正会说的一句话","finishSay":"画完后真正会说的一句话","strokes":[{"part":"头部外轮廓等具体部位","color":"#29282b","width":15,"points":[[100,100],[120,120]]}]}。画布宽1000高1200，使用28到48笔；每笔只给决定形状的关键锚点，普通线条3到8个点，长外轮廓最多12个点，禁止为圆润效果重复堆叠相近坐标。本地画笔会根据锚点自动圆滑、补足采样并加入轻微真人手抖，所以必须把省下的内容用于保证部位齐全和比例正确。每一笔必须填写 part，先规划结构和前后层级，再用连续圆润的中粗笔画完成。主轮廓线宽12到18，内部细节7到11，禁止大量细碎纤细线条。生成前在内部逐项检查：主要部位是否齐全、是否相连、剪影是否可辨、有没有线条错误穿过脸部、耳朵是否柔软圆弧。两句台词必须符合你的人设，不能使用固定游戏套话。',quickTask='\n这局会使用精细生图，你只需快速决定主题和自然台词，不要规划坐标笔迹。只输出简短JSON：{"answer":"具体主题","category":"类别","hint":"自然提示","startSay":"开始画时真正会说的一句话","finishSay":"画完后真正会说的一句话"}。主题必须具体、第一眼可辨，台词符合你的人设，不能使用固定套话，不能替用户说话。',task=precisionArt?quickTask:drawTask;
    const usedTopics=dgUsedTopics(c),usedText=usedTopics.length?'\n这些题目以前已经画过，禁止再次使用，也不要使用它们的同义词、大小版本或只换修饰词的变体：'+usedTopics.join('、')+'。必须想一个明显不同的新主题。':'',request=g.mode==='photo'?'请直接在空白画布上，根据'+S.me.name+'的真实要求「'+g.instruction+'」完成一幅独立、完整、可爱的画，不要等待图片，也不需要猜答案。':(choose?'请你根据你和'+S.me.name+'真实相处时聊过、经历过或共同喜欢的日常，自主决定一个具体、可画、可猜的题目。不要从固定词库随机抽，也不要总画树。答案必须始终保密，绝不让'+S.me.name+'提前输入或看到题目。'+usedText:'由'+S.me.name+'自定义的内容：'+g.answer+'。按这个内容画，不要擅自换题。'),artPromise=precisionArt&&g.mode==='photo'?dgGenerateArt(g.answer,g.instruction).then(value=>({value}),error=>({error})):null;
    if(artPromise){g.activity='正在创作';dgSaveDraft(g);render();}const raw=await chatAPI(dgRoleChatMessages(c,g,task,request),{aux:true,max:precisionArt?700:DG_LINE_MAX,temp:.58});if(_dg!==g)return;let obj={};try{obj=parseObj(raw);}catch(_){}
    if(choose){let candidate=String(obj.answer||'').trim().slice(0,60);if(/[A-Za-z]/.test(candidate))candidate='';for(let attempt=0;attempt<2&&(!candidate||dgTopicRepeated(candidate,usedTopics));attempt++){const retryRequest=request+'\n你刚才想到的「'+(candidate||'空题目')+'」与历史题目重复、不是纯中文或不可用。彻底放弃它，换一个不同类别、不同主体的纯中文新题目；仍按原JSON格式完整输出。';const retryRaw=await chatAPI(dgRoleChatMessages(c,g,task,retryRequest),{aux:true,max:precisionArt?700:DG_LINE_MAX,temp:.72});if(_dg!==g)return;try{obj=parseObj(retryRaw);}catch(_){obj={};}candidate=String(obj.answer||'').trim().slice(0,60);if(/[A-Za-z]/.test(candidate))candidate='';}if(!candidate||dgTopicRepeated(candidate,usedTopics))throw new Error('这次想到的题目重复或不是纯中文，正在等一个全新的灵感');g.answer=candidate;dgRememberTopic(g.answer);}if(!g.answer)throw new Error('角色没有决定画什么');g.category=dgChineseSpeech(obj.category).slice(0,20);g.hint=dgChineseSpeech(obj.hint);const reference=!g.background?dgReferencePlan(g.answer):[],vectorPlan=reference.length?reference:dgNormalizePlan(obj,g.answer);g.generatedArt='';if(precisionArt){g.activity='正在创作';dgSaveDraft(g);render();try{if(artPromise){const artResult=await artPromise;if(artResult.error)throw artResult.error;g.generatedArt=artResult.value;}else g.generatedArt=await dgGenerateArt(g.answer,g.instruction);if(_dg!==g)return;g.plan=dgRevealPlan();}catch(_){if(_dg!==g)return;let fallback=vectorPlan;if(!fallback.length){const rawFallback=await chatAPI(dgRoleChatMessages(c,g,drawTask,request),{aux:true,max:DG_LINE_MAX,temp:.52});let fallbackObj={};try{fallbackObj=parseObj(rawFallback);}catch(_){}fallback=dgNormalizePlan(fallbackObj,g.answer);}g.plan=fallback;toast('精细生图暂时不可用，已改用普通画笔');}}else g.plan=vectorPlan;if(g.plan.length<5)throw new Error('角色没有生成可用画作');g.aiStrokeIndex=0;
    const start=await dgEnsureChineseSpeech(c,g,obj.startSay,'开始画画'),finish=await dgEnsureChineseSpeech(c,g,obj.finishSay,'完成画作');g.finishSpeech=finish;if(start)dgAddDialogue('ta',start);
  }
  catch(e){if(_dg!==g)return;g.busy=false;g.phase='planning';dgSaveDraft(g);render();toast((e&&e.message)||'画笔规划失败，请稍后再试');return;}
  if(_dg!==g)return;g.busy=false;g.activity='';g.phase='drawing';g.revision++;dgSaveDraft(g);render();setTimeout(dgAnimateNext,resume?300:520);}
function dgCanvas(){return document.getElementById('dgcanvas');}
function dgCtx(){const cv=dgCanvas();return cv&&cv.getContext('2d');}
function dgDrawImageFit(ctx,im,w,h){if(!ctx||!im)return;const iw=im.naturalWidth||w,ih=im.naturalHeight||h,z=Math.min(w/iw,h/ih),dw=iw*z,dh=ih*z;ctx.drawImage(im,(w-dw)/2,(h-dh)/2,dw,dh);}
function dgArtSurface(old,cv){if(old&&old.width===cv.width&&old.height===cv.height)return old;const x=document.createElement('canvas');x.width=cv.width;x.height=cv.height;return x;}
function dgPaintGeneratedArt(ctx,cv){if(!_dg||!_dgArtImage||!_dgArtImage.complete)return;const complete=_dg.phase==='done'||((_dg.plan||[]).length&&(_dg.aiStrokeIndex||0)>=_dg.plan.length);if(complete){dgDrawImageFit(ctx,_dgArtImage,cv.width,cv.height);return;}_dgArtLayer=dgArtSurface(_dgArtLayer,cv);_dgArtMask=dgArtSurface(_dgArtMask,cv);_dgArtComposite=dgArtSurface(_dgArtComposite,cv);const layer=_dgArtLayer.getContext('2d'),mask=_dgArtMask.getContext('2d'),mix=_dgArtComposite.getContext('2d');layer.clearRect(0,0,cv.width,cv.height);dgDrawImageFit(layer,_dgArtImage,cv.width,cv.height);mask.clearRect(0,0,cv.width,cv.height);(_dg.strokes||[]).filter(s=>s&&s.reveal).forEach(s=>dgStroke(mask,s));if(_dg._revealPartial)dgStroke(mask,_dg._revealPartial.stroke,_dg._revealPartial.upto);mix.globalCompositeOperation='source-over';mix.clearRect(0,0,cv.width,cv.height);mix.drawImage(_dgArtLayer,0,0);mix.globalCompositeOperation='destination-in';mix.drawImage(_dgArtMask,0,0);mix.globalCompositeOperation='source-over';ctx.drawImage(_dgArtComposite,0,0);}
function dgPaintBase(ctx,cv){ctx.globalCompositeOperation='source-over';ctx.fillStyle='#fbf7ef';ctx.fillRect(0,0,cv.width,cv.height);if(_dgBgImage&&_dgBgImage.complete)dgDrawImageFit(ctx,_dgBgImage,cv.width,cv.height);dgPaintGeneratedArt(ctx,cv);}
function dgStroke(ctx,s,upto){if(!ctx||!s||!s.points||s.points.length<2)return;ctx.globalCompositeOperation='source-over';ctx.strokeStyle=s.color||'#29282b';ctx.lineWidth=Math.max(2,+s.width||13);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(s.points[0][0],s.points[0][1]);const n=upto==null?s.points.length:Math.min(s.points.length,upto);for(let i=1;i<n;i++)ctx.lineTo(s.points[i][0],s.points[i][1]);ctx.stroke();}
function dgRedraw(){const cv=dgCanvas(),ctx=dgCtx();if(!cv||!ctx||!_dg)return;dgPaintBase(ctx,cv);(_dg.strokes||[]).filter(s=>!s.reveal).forEach(s=>dgStroke(ctx,s));}
function dgMount(){const cv=dgCanvas();if(!cv||!_dg)return;cv.width=1000;cv.height=1200;cv.oncontextmenu=e=>e.preventDefault();cv.onselectstart=e=>e.preventDefault();cv.ondragstart=e=>e.preventDefault();_dgBgImage=null;_dgArtImage=null;_dgArtLayer=_dgArtMask=_dgArtComposite=null;if(_dg.background){const im=new Image();_dgBgImage=im;im.onload=dgRedraw;im.src=_dg.background;}if(_dg.generatedArt){const im=new Image();_dgArtImage=im;im.onload=dgRedraw;im.src=_dg.generatedArt;}dgRedraw();if(_dg.mode!=='me'||_dg.phase!=='drawing')return;cv.onpointerdown=e=>{e.preventDefault();const r=cv.getBoundingClientRect(),p=[(e.clientX-r.left)/r.width*1000,(e.clientY-r.top)/r.height*1200];_dg._drawing={color:_dg.color||DG_COLORS[0],width:_dg.width||13,points:[p]};try{cv.setPointerCapture(e.pointerId);}catch(_){};};cv.onpointermove=e=>{const s=_dg&&_dg._drawing;if(!s)return;e.preventDefault();const r=cv.getBoundingClientRect(),p=[Math.max(0,Math.min(1000,(e.clientX-r.left)/r.width*1000)),Math.max(0,Math.min(1200,(e.clientY-r.top)/r.height*1200))],q=s.points[s.points.length-1];if(Math.hypot(p[0]-q[0],p[1]-q[1])<2.5)return;s.points.push(p);dgStroke(dgCtx(),{color:s.color,width:s.width,points:[q,p]});};const end=()=>{const s=_dg&&_dg._drawing;if(!s)return;_dg._drawing=null;if(s.points.length===1)s.points.push([s.points[0][0]+.5,s.points[0][1]+.5]);_dg.strokes.push(s);_dg.visionDesc='';_dg.revision++;dgSaveDraft(_dg);};cv.onpointerup=end;cv.onpointercancel=end;}
function dgBrushPlace(x,y,color,dipping){const brush=$('#dgAiBrush');if(!brush)return false;brush.style.left=Math.max(1,Math.min(99,x))+'%';brush.style.top=Math.max(1,Math.min(99,y))+'%';brush.style.setProperty('--brush-color',color||DG_COLORS[0]);brush.classList.toggle('dipping',!!dipping);return true;}
function dgBrushDip(color){color=dgPaletteColor(color);const shell=document.querySelector('.dg-canvas-shell'),i=DG_COLORS.indexOf(color),sw=document.querySelector('.dg-ai-swatch[data-i="'+i+'"]');document.querySelectorAll('.dg-ai-swatch').forEach(x=>x.classList.toggle('on',x===sw));if(!shell||!sw)return false;const a=shell.getBoundingClientRect(),b=sw.getBoundingClientRect();return dgBrushPlace((b.left+b.width/2-a.left)/a.width*100,(b.top+b.height/2-a.top)/a.height*100,color,true);}
function dgBrushFollow(point,color){if(!point)return;dgBrushPlace(point[0]/10,point[1]/12,color,false);}
function dgAnimateNext(){const g=_dg;if(!g||g.mode==='me'||g.phase!=='drawing')return;const idx=g.aiStrokeIndex||0;if(idx>=(g.plan||[]).length){g._revealPartial=null;dgRedraw();const brush=$('#dgAiBrush');if(brush)brush.classList.add('rest');if(g.finishSpeech){const said=g.finishSpeech;g.finishSpeech='';dgAddDialogue('ta',said);dgUpdateSpeech();}dgSaveDraft(g);return;}const s=g.plan[idx],ctx=dgCtx(),token=g._anim||0,pts=s.points||[],brushColor=dgPaletteColor(s.brushColor||s.color||DG_COLORS[0]);if(g._brushColor!==brushColor&&dgBrushDip(brushColor)){g._brushColor=brushColor;setTimeout(()=>{if(_dg===g&&g.phase==='drawing')dgAnimateNext();},460);return;}let len=0;for(let i=1;i<pts.length;i++)len+=Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]);const drawMs=s.reveal?Math.max(760,Math.min(1350,len*1.3)):Math.max(720,Math.min(3100,len*3)),started=(window.performance&&performance.now)?performance.now():Date.now();const tick=now=>{if(_dg!==g||g.phase!=='drawing'||token!==(g._anim||0))return;const elapsed=Math.max(0,(now||Date.now())-started),n=Math.min(pts.length,Math.max(2,Math.ceil(1+(pts.length-1)*elapsed/drawMs)));dgBrushFollow(pts[Math.max(0,n-1)],brushColor);if(s.reveal){g._revealPartial={stroke:s,upto:n};dgRedraw();}else{dgRedraw();dgStroke(ctx,s,n);}if(n<pts.length){g._animFrame=requestAnimationFrame(tick);return;}g._revealPartial=null;g.strokes.push(s);g.aiStrokeIndex=idx+1;g.revision++;dgSaveDraft(g);const pause=s.reveal?170:360+Math.min(320,Math.round(len/5));setTimeout(()=>{if(_dg===g)dgAnimateNext();},pause);};g._animFrame=requestAnimationFrame(tick);}
function dgUpdateSpeech(){if(!_dg)return;const a=$('#dgRoleSpeech'),b=$('#dgMeSpeech');if(a)a.textContent=_dg.roleSpeech||'';if(b)b.textContent=_dg.meSpeech||'';}
function dgSetColor(color,el){if(!_dg)return;_dg.color=color;document.querySelectorAll('.dg-color').forEach(x=>x.classList.toggle('on',x===el));}
function dgSetWidth(w,el){if(!_dg)return;_dg.width=+w;document.querySelectorAll('.dg-width').forEach(x=>x.classList.toggle('on',x===el));}
function dgUndo(){if(!_dg||_dg.mode!=='me'||_dg.phase!=='drawing'||!_dg.strokes.length)return;_dg.strokes.pop();_dg.visionDesc='';_dg.revision++;dgRedraw();dgSaveDraft(_dg);toast('已撤回上一笔');}
async function dgClearCanvas(){if(!_dg||_dg.busy)return;if(!(_dg.strokes.length||_dg.background)){toast('画布已经是空的');return;}if(!await uiConfirm('清空当前画布上的全部笔迹和底图？\n已保存到画作里的图片不会被删除。'))return;dgStopRuntime();_dg.strokes=[];_dg.background='';_dg.plan=[];_dg.aiStrokeIndex=0;_dg.visionDesc='';_dg.baseDescription='';_dg.revision++;_dgBgImage=null;dgSaveDraft(_dg);render();toast('画布已清空');}
function dgUploadBase(){if(!_dg||_dg.mode!=='me'||_dg.phase!=='drawing')return;pickFile('image/*',async f=>{try{let src=await compress(f,1000,.78);if(src.length>1500000)src=await compress(f,760,.68);if(!_dg)return;_dg.background=src;_dg.visionDesc='';_dg.revision++;dgSaveDraft(_dg);render();toast('图片已放到画布底层，可以接着画');}catch(_){toast('图片读取失败');}});}
function dgCanvasData(){const cv=dgCanvas();if(!cv)return'';try{return cv.toDataURL('image/jpeg',.82);}catch(_){return'';}}
function dgLoadSnapshotImage(src){return new Promise((resolve,reject)=>{if(!src)return resolve(null);const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('底图读取失败'));im.src=src;});}
async function dgSnapshotData(g){const cv=document.createElement('canvas');cv.width=1000;cv.height=1200;const ctx=cv.getContext('2d');ctx.fillStyle='#fbf7ef';ctx.fillRect(0,0,cv.width,cv.height);if(g.background){const im=await dgLoadSnapshotImage(g.background);dgDrawImageFit(ctx,im,cv.width,cv.height);}if(g.generatedArt){const im=await dgLoadSnapshotImage(g.generatedArt);dgDrawImageFit(ctx,im,cv.width,cv.height);}(g.strokes||[]).filter(s=>!s.reveal).forEach(s=>dgStroke(ctx,s));return cv.toDataURL('image/jpeg',.84);}
async function dgArchive(silent){const g=_dg;if(!g||!(g.strokes.length||g.background||g.generatedArt))return false;if(g.savedRevision===g.revision){if(!silent)toast('这版画作已经保存');return true;}try{const src=await dgSnapshotData(g);if(!src)throw new Error('画布生成失败');await primeImageForSave(src);if(_dg!==g)return false;const x=dgState(),c=getC(g.cid);x.gallery.unshift({id:uid(),cid:g.cid,who:g.mode==='me'?'me':'ta',answer:g.answer||'自由画',src,time:Date.now(),roleName:(c&&(c.remark||c.name))||'角色'});if(x.gallery.length>20)x.gallery=x.gallery.slice(0,20);g.savedRevision=g.revision;dgSaveDraft(g);const ok=await saveNowAsync();if(!ok)throw new Error('本机存储写入失败');if(!silent)toast('画作已完整保存到游戏大厅');return true;}catch(e){toast((e&&e.message)||'画作保存失败');return false;}}
function dgOpenGallery(){const list=dgState().gallery,beadHTML=typeof beadGalleryItemsHTML==='function'?beadGalleryItemsHTML():'',beadCount=typeof beadGalleryCount==='function'?beadGalleryCount():0,drawHTML=list.map(x=>`<article><img src="${x.src}" onclick="viewImg('${x.src}')"><div><b>${esc(x.answer||'未命名')}</b><small>${esc(x.who==='me'?'我画的':(x.roleName||'TA')+'画的')} · ${esc(ymd(x.time||Date.now()))}</small></div><button onclick="dgDeleteArtwork('${x.id}')">删除</button></article>`).join('');openModal(`<h3>我的画作</h3><div class="hint">你画我猜与像素拼拼乐的成品都集中在这里；当前共 ${list.length+beadCount} 幅。删除后无法恢复。</div><div class="dg-gallery">${beadHTML+drawHTML||'<div class="empty">还没有保存画作</div>'}</div><button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
async function dgDeleteArtwork(id){if(!await uiConfirm('删除这幅已经保存的画作？'))return;const x=dgState();x.gallery=x.gallery.filter(a=>a.id!==id);save();dgOpenGallery();}
function dgFinishDrawing(){if(!_dg||_dg.mode!=='me'||!['drawing','guessing'].includes(_dg.phase))return;clearInterval(_dg._tm);_dg._tm=null;if(!_dg.strokes.length&&!_dg.background){toast('先在画布上画一点东西');return;}_dg.phase='guessing';_dg.busy=true;_dg.activity='正在识图';dgSaveDraft(_dg);render();setTimeout(()=>dgAskRoleGuess(''),150);}
async function dgAskRoleGuess(hint){const g=_dg,c=g&&getC(g.cid);if(!g||!c||g.mode!=='me')return;g.busy=true;g.activity=g.visionDesc?'正在猜':'正在识图';g.phase='guessing';if(hint){dgAddDialogue('me',hint);g.guesses.push({who:'me',text:hint});}render();let visionFallback=false;if(!g.visionDesc){try{const data=await dgSnapshotData(g),raw=await visionAPI(data,'只客观描述这幅画里能看到的主体、结构、颜色和后来添加的笔迹，不要扮演任何角色，不要替任何人说话，不要给出预写台词。只输出JSON：{"description":"画面描述"}。');if(_dg!==g)return;let seen={};try{seen=parseObj(raw);}catch(_){}g.visionDesc=String(seen.description||raw||'').slice(0,500);}catch(_){if(_dg!==g)return;visionFallback=true;g.visionDesc='仅供你内部判断：这幅画的真实答案是「'+g.answer+'」。请自然地把它当成自己从画面和提示中猜到的结果，绝对不要向'+S.me.name+'提及答案由系统提供、视觉读取异常、降级或任何幕后过程。';}g.activity='正在猜';render();}
  try{const task='\n现在轮到你看画并亲自猜。只能依据画面描述、本局真实对话和'+S.me.name+'亲口给的提示判断。只输出JSON：{"guess":"你的一个具体答案","say":"你此刻真正会说的完整一句话"}。say 必须符合你的人设，可以把答案自然说进句子里，不能使用系统准备的固定话术，也不能谈论识图、系统或幕后过程。如果画面描述明确给出了真实答案，guess 和 say 都要自然说出这个答案。';const raw=await chatAPI(dgRoleChatMessages(c,g,task,'画面描述：'+g.visionDesc+'\n你此前猜过：'+g.guesses.filter(x=>x.who==='ta').map(x=>x.guess||x.text).join('；')+'\n请给出这一次的新猜测。'),{aux:true,max:260,temp:.62});if(_dg!==g)return;let obj={};try{obj=parseObj(raw);}catch(_){obj={say:cleanReply(raw)}}const modelGuess=String(obj.guess||'').replace(/[\[\]【】"“”]/g,'').trim().slice(0,30),guess=visionFallback?String(g.answer||'').trim().slice(0,30):modelGuess,spoken=await dgEnsureChineseSpeech(c,g,obj.say,'猜画回应'),chineseGuess=dgChineseSpeech(guess),say=visionFallback&&chineseGuess&&(!spoken||!spoken.includes(chineseGuess))?chineseGuess:spoken;if(guess)g.guesses.push({who:'ta',text:say||chineseGuess,guess});if(say)dgAddDialogue('ta',say);g.busy=false;if(guess&&dgCorrect(guess)){g.phase='done';dgRecordMemory(true);dgArchive(true);}}
  catch(_){if(_dg!==g)return;const guess=String(g.answer||'').trim();g.busy=false;if(guess){g.guesses.push({who:'ta',text:guess,guess});dgAddDialogue('ta',guess);g.phase='done';dgRecordMemory(true);dgArchive(true);}}
  if(_dg===g){dgSaveDraft(g);render();}}
function dgHintRole(){const el=$('#dg_hint_input');if(el)el.focus();}
function dgSendHint(){const g=_dg,el=$('#dg_hint_input'),v=String(el&&el.value||'').trim();if(!g||g.mode!=='me'||g.busy)return;if(!v){toast('先写下一点提示');return;}dgAskRoleGuess(v);}
async function dgSubmitGuess(){const g=_dg,c=g&&getC(g.cid);if(!g||!c||g.mode!=='role'||g.busy||g.phase!=='drawing')return;const el=$('#dg_role_input'),v=String(el&&el.value||'').trim();if(!v){toast('先输入你猜的答案');return;}dgAddDialogue('me',v);g.guesses.push({who:'me',text:v,guess:v});g.busy=true;g.activity='正在回应';render();const ok=dgCorrect(v);try{const task='\n'+S.me.name+'刚刚亲口提交了一个答案。你知道秘密题目是「'+g.answer+'」，ta这次'+(ok?'猜对了':'没有猜对')+'。只输出JSON：{"say":"你此刻真实自然的回应"}。回应必须符合人设和关系，不要使用固定的答对或答错台词，也不要替ta说话。';const raw=await chatAPI(dgRoleChatMessages(c,g,task,'这是'+S.me.name+'真实输入的答案：'+v),{aux:true,max:180,temp:.72});if(_dg!==g)return;let obj={};try{obj=parseObj(raw);}catch(_){}const say=await dgEnsureChineseSpeech(c,g,obj.say||raw,'回答猜测');if(say)dgAddDialogue('ta',say);g.busy=false;g.activity='';if(ok){clearInterval(g._tm);g._tm=null;g._anim=(g._anim||0)+1;g.phase='done';dgRecordMemory(true);dgArchive(true);}}
  catch(e){if(_dg!==g)return;g.busy=false;g.activity='';toast((e&&e.message)||'角色暂时没有回应');}if(_dg===g){dgSaveDraft(g);render();}}
async function dgRoleHint(){const g=_dg,c=g&&getC(g.cid);if(!g||!c||g.mode!=='role'||g.phase!=='drawing'||g.busy)return;g.busy=true;g.activity='正在回应';render();try{const task='\n'+S.me.name+'请你给一点提示。秘密题目是「'+g.answer+'」。请结合已经给过的提示，用你自己的说话方式透露一点点，但不要直接说出答案。只输出JSON：{"say":"你真正会给出的提示"}。';const raw=await chatAPI(dgRoleChatMessages(c,g,task,'请给我一点提示'),{aux:true,max:180,temp:.7});if(_dg!==g)return;let obj={};try{obj=parseObj(raw);}catch(_){}let say=await dgEnsureChineseSpeech(c,g,obj.say||raw,'给出提示');if(!say)say=dgChineseSpeech(g.hint);if(say)dgAddDialogue('ta',say);g.hintIndex=(g.hintIndex||0)+1;}catch(e){toast((e&&e.message)||'角色暂时没有回应');}if(_dg===g){g.busy=false;g.activity='';dgSaveDraft(g);render();}}
async function dgGuideRole(){const g=_dg,c=g&&getC(g.cid);if(!g||!c||g.mode!=='photo'||g.busy||g.phase!=='drawing')return;const el=$('#dg_role_input'),v=String(el&&el.value||'').trim();if(!v){toast('先写下要 TA 修改或添加什么');return;}dgStopRuntime();dgAddDialogue('me',v);g.guesses.push({who:'me',text:v,kind:'guide'});g.busy=true;g.activity='正在构思';render();try{const rect=g.backgroundRect||{x:0,y:0,w:1000,h:1200},task='\n'+S.me.name+'正在自由模式里直接指导你修改当前画布。你必须理解ta的自然语言，例如不满意、重画、换颜色、添加发型、衣服或具体物体。只输出JSON：{"action":"append或replace","answer":"修改后的画面标题","startSay":"你开始修改时真正会说的话","finishSay":"改完后真正会说的话","strokes":[...]}。如果只是添加新物体用 append；涉及重画、删除、结构调整或换色用 replace，并输出完整的新叠加笔迹。画布宽1000高1200，使用24到44笔；每笔只输出3到8个决定形状的关键锚点，长外轮廓最多12个点，禁止重复堆坐标，本地会自动圆滑、补点和加入轻微手抖。保持中等偏粗的彩铅手绘感，主轮廓12到18，内部细节7到11，圆润转角，禁止粗黑管线、尖角和大量细碎线条。先检查前后遮挡，身体和衣服线不能穿过脸、嘴或眼睛。若有底图，底图绝不能重画或清除：新增发型要依据识图 curves 和至少5个头顶 landmarks，用宽度18到30的同色重叠笔触铺成贴住头骨的大面积发片，发根沿原头顶，刘海落在脸部上缘，侧发接鬓角，不能画成悬空帽子、几根框线，不能重复五官或另画新人物；衣服必须从肩颈连接，袖子接双肩，用同色宽笔触铺出衣服面积并包住躯干。若无底图，就根据当前主题和修改要求完成一幅独立完整的画。不能替用户说话。';const current='当前主题：'+g.answer+'\n底图识图定位：'+(g.baseDescription||'无底图，请在空白画布独立作画')+'\n底图画布矩形：'+JSON.stringify(rect)+'\n此前要求：'+g.instruction+'\n'+S.me.name+'刚刚的真实修改要求：'+v;const raw=await chatAPI(dgRoleChatMessages(c,g,task,current),{aux:true,max:DG_LINE_MAX,temp:.55});if(_dg!==g)return;let obj={};try{obj=parseObj(raw);}catch(_){}const next=dgNormalizePlan(obj,String(obj.answer||g.answer));if(!next.length)throw new Error('没有生成可用笔迹');if(String(obj.action||'').toLowerCase()==='replace'){g.strokes=[];g.revision++;}g.plan=next;g.aiStrokeIndex=0;g.instruction=(g.instruction+'；'+v).slice(-800);g.finishSpeech=await dgEnsureChineseSpeech(c,g,obj.finishSay,'完成修改');const start=await dgEnsureChineseSpeech(c,g,obj.startSay,'开始修改');if(start)dgAddDialogue('ta',start);g.busy=false;g.activity='';g.phase='drawing';dgSaveDraft(g);render();setTimeout(dgAnimateNext,520);return;}catch(e){if(_dg!==g)return;g.busy=false;g.activity='';toast((e&&e.message)||'修改画面失败');}if(_dg===g){dgSaveDraft(g);render();}}
function dgRecordMemory(won){if(!_dg||_dg.memoryRecorded||(!(_dg.strokes||[]).length&&!_dg.background&&!_dg.generatedArt&&!(_dg.dialogue||[]).length))return;const c=getC(_dg.cid);if(!c)return;_dg.memoryRecorded=true;const gameName=_dg.mode==='photo'?'我说你画':'你画我猜';c.gamesPlayed=c.gamesPlayed||[];if(c.gamesPlayed.indexOf(gameName)<0)c.gamesPlayed.push(gameName);c.drawGuessMemory=Array.isArray(c.drawGuessMemory)?c.drawGuessMemory:[];const who=_dg.mode==='me'?S.me.name:(c.remark||c.name),summary=_dg.mode==='photo'?who+'根据「'+(_dg.answer||'自由主题')+'」完成了自由画':who+'画了「'+(_dg.answer||'一幅画')+'」，'+(_dg.mode==='me'?(won?'角色猜中了':'角色参与了猜画'):(won?S.me.name+'猜中了':S.me.name+'参与了画画'));c.drawGuessMemory.unshift({time:Date.now(),answer:_dg.answer,drawer:_dg.mode,won:!!won,summary});if(c.drawGuessMemory.length>12)c.drawGuessMemory=c.drawGuessMemory.slice(0,12);gameSetHandoff(c.id,gameName,(_dg.dialogue||[]).map(x=>({who:x.who,text:x.text})));save();}
function renderDrawGuess(){if(!_dg)return'';const c=getC(_dg.cid);if(!c)return'';const setup=_dg.phase==='setup',drawing=_dg.phase==='drawing',meDraw=_dg.mode==='me',photo=_dg.mode==='photo',done=_dg.phase==='done',titlePlaceholder=photo?'例如：画一只趴在窗边的小猫':'写下这局你想画的题目',busyText=_dg.activity||'正在处理';return `<div class="dg-app"><div class="dg-nav"><button type="button" onclick="dgExit()">退出</button><div><b>${photo?'我说你画':'你画我猜'}</b><span>${esc(dgPhaseText(_dg))}</span></div><button type="button" class="danger" onclick="dgEnd()">结束</button></div><div class="dg-stage">
  ${_dg.roleSpeech?`<div class="dg-person role"><div class="dg-speech" id="dgRoleSpeech">${esc(_dg.roleSpeech)}</div></div>`:''}
  ${photo&&!done||setup&&meDraw?`<label class="dg-title-edit"><span>${photo?'这局想让 TA 画什么':'这局题目'}</span><input id="dg_room_title" maxlength="80" value="${esc(_dg.answer||'')}" placeholder="${titlePlaceholder}" oninput="dgSetRoomTitle(this.value)"></label>`:`<div class="dg-secret"><span>${meDraw?'你的题目':setup?'TA 正在保密选题':'秘密题目'}</span><b>${meDraw||done?esc(_dg.answer||'自由画'):'••••'}</b></div>`}
  <div class="dg-canvas-shell ${meDraw&&drawing?'active':''}"><canvas id="dgcanvas" aria-label="${photo?'我说你画':'你画我猜'}画布"></canvas><span class="dg-paper-grain"></span>${!meDraw&&drawing?`<div class="dg-ai-palette" aria-label="TA 的调色盘">${DG_COLORS.map((x,i)=>`<i class="dg-ai-swatch" data-i="${i}" style="--c:${x}"></i>`).join('')}</div><span class="dg-ai-brush" id="dgAiBrush" aria-hidden="true"></span>`:''}${_dg.busy?'<div class="dg-busy"><i></i><span>'+busyText+'</span></div>':''}</div>
  ${_dg.meSpeech?`<div class="dg-person me"><div class="dg-speech" id="dgMeSpeech">${esc(_dg.meSpeech)}</div></div>`:''}</div>
  ${setup?`<div class="dg-setupbar"><button type="button" class="primary" onclick="dgStartPrepared()">${meDraw?'开始画':'让 TA 开始画'}</button></div>`:''}
  ${meDraw&&drawing?`<div class="dg-tools"><div class="dg-tools-head"><span>画笔颜色</span><button type="button" class="primary" onclick="dgFinishDrawing()">画好了</button></div><div class="dg-palette">${DG_COLORS.map(x=>`<button type="button" class="dg-color ${(_dg.color||DG_COLORS[0])===x?'on':''}" style="--c:${x}" onclick="dgSetColor('${x}',this)"></button>`).join('')}</div><div class="dg-tool-row"><button type="button" onclick="dgUploadBase()">相册底图</button><button type="button" onclick="dgUndo()">撤回一笔</button><button type="button" onclick="dgClearCanvas()">清空画布</button><button type="button" onclick="dgArchive(false)">保存</button><span class="dg-width" onclick="dgSetWidth(8,this)"><i style="width:5px;height:5px"></i></span><span class="dg-width ${(_dg.width||13)===13?'on':''}" onclick="dgSetWidth(13,this)"><i style="width:9px;height:9px"></i></span><span class="dg-width" onclick="dgSetWidth(20,this)"><i style="width:13px;height:13px"></i></span></div></div>`:''}
  ${!meDraw&&drawing?`<div class="dg-guessbar dg-rolebar"><input id="dg_role_input" maxlength="120" placeholder="${photo?'告诉 TA 要添加什么、换什么颜色或哪里要改':'输入你猜的答案'}" onkeydown="if(event.key==='Enter'){event.preventDefault();${photo?'dgGuideRole()':'dgSubmitGuess()'}}"><button type="button" onclick="dgArchive(false)" ${_dg.busy?'disabled':''}>保存</button>${photo?`<button type="button" class="primary" onclick="dgGuideRole()" ${_dg.busy?'disabled':''}>发送</button>`:`<button type="button" onclick="dgRoleHint()" ${_dg.busy?'disabled':''}>提示</button><button type="button" class="primary" onclick="dgSubmitGuess()" ${_dg.busy?'disabled':''}>提交答案</button>`}</div>`:''}
  ${_dg.phase==='planning'&&!_dg.busy?`<div class="dg-guessbar"><span>刚才没有生成可用笔迹</span><button type="button" class="primary" onclick="dgGenerateRoleDrawing(true)">重新尝试</button></div>`:''}
  ${meDraw&&_dg.phase==='guessing'?`<div class="dg-hintbar"><input id="dg_hint_input" maxlength="36" placeholder="在这里给 TA 一点提示" onkeydown="if(event.key==='Enter'){event.preventDefault();dgSendHint()}"><button type="button" onclick="dgSendHint()" ${_dg.busy?'disabled':''}>发送提示</button><button type="button" class="primary" onclick="dgAskRoleGuess('')" ${_dg.busy?'disabled':''}>再看一次</button></div>`:''}
  ${done?`<div class="dg-finish"><button type="button" onclick="dgArchive(false)">保存画作</button><button type="button" onclick="dgNewRound()">再来一轮</button><button type="button" class="primary" onclick="dgEnd()">结束并记住</button></div>`:''}</div>`;}
function dgNewRound(){if(!_dg)return;const cid=_dg.cid;dgRecordMemory(_dg.phase==='done');dgDropDraft(_dg);dgStopRuntime();_dg=null;stack=[{p:'home'},{p:'gameshub'}];render();dgOpenSetup(cid);}
function dgExit(){if(!_dg)return openGames();dgStopRuntime();_dg.busy=false;dgSaveDraft(_dg);_dg=null;stack=[{p:'home'},{p:'gameshub'}];render();toast('画布草稿已保留');}
async function dgEnd(){if(!_dg)return openGames();const name=_dg.mode==='photo'?'我说你画':'你画我猜';if(!await uiConfirm('结束这局'+name+'？\n当前画布会保存到画作，角色也会记得这一轮画了什么。'))return;const g=_dg;dgStopRuntime();dgRecordMemory(g.phase==='done');const hadArt=!!(g.strokes.length||g.background||g.generatedArt),saved=!hadArt||await dgArchive(true);if(hadArt&&!saved)return;dgDropDraft(g);_dg=null;stack=[{p:'home'},{p:'gameshub'}];render();toast('这局已经保存');}
/* ===== 单独游戏空间 ===== */
let _gs=null;
function gsDraftStore(){S.me=S.me||{};if(!S.me.gameDrafts||typeof S.me.gameDrafts!=='object'||Array.isArray(S.me.gameDrafts))S.me.gameDrafts={};return S.me.gameDrafts;}
function gsDraftKey(kind,cid){return String(kind||'game')+'|'+String(cid||'');}
function gsDraftList(){return Object.values(gsDraftStore()).filter(d=>d&&d.cid&&getC(d.cid)).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,12);}
function gsSaveDraft(g){if(!g||!g.cid)return false;const store=gsDraftStore(),key=gsDraftKey(g.kind,g.cid);store[key]={cid:g.cid,kind:g.kind,title:g.title,intro:g.intro,msgs:(g.msgs||[]).map(m=>({id:m.id||uid(),who:m.who,text:String(m.text||'')})),t:Math.max(0,+g.t||0),updatedAt:Date.now()};const keys=Object.keys(store);if(keys.length>12)keys.sort((a,b)=>(store[b].updatedAt||0)-(store[a].updatedAt||0)).slice(12).forEach(k=>delete store[k]);save();return true;}
function gsDropDraft(g){if(!g)return false;const store=gsDraftStore(),key=gsDraftKey(g.kind,g.cid);if(!store[key])return false;delete store[key];save();return true;}
function gsLoadDraft(kind,cid){const d=gsDraftStore()[gsDraftKey(kind,cid)];return d?{cid:d.cid,kind:d.kind,title:d.title||'游戏',intro:d.intro||'',msgs:(d.msgs||[]).map(m=>({id:m.id||uid(),who:m.who,text:String(m.text||'')})),t:Math.max(0,+d.t||30*60),busy:false,_tm:null}:null;}
function gsOpenDraft(d){if(!d)return false;if(_gs&&_gs._tm)clearInterval(_gs._tm);_gs={cid:d.cid,kind:d.kind,title:d.title||'游戏',intro:d.intro||'',msgs:(d.msgs||[]).map(m=>({id:m.id||uid(),who:m.who,text:String(m.text||'')})),t:Math.max(0,+d.t||30*60),busy:false,_tm:null};closeModal();go('gs');gsTimer();if(_gs.msgs.length)gsRender();else gsKick();return true;}
function gsResumeDraft(index){return gsOpenDraft(gsDraftList()[Math.max(0,+index||0)]);}
function openGameSpace(kind,cid,intro,title){const c=getC(cid);if(!c)return;
  if(_gs){clearInterval(_gs._tm);gsSaveDraft(_gs);}const old=gsLoadDraft(kind,cid);if(old)return gsOpenDraft(old);
  _gs={cid,kind,title:title||'游戏',intro,msgs:[],t:30*60,busy:false,_tm:null};
  gsSaveDraft(_gs);go('gs');gsTimer();gsKick();}
function gsSystem(){const c=getC(_gs.cid);
  return buildSystem(c,{worldbookScope:'games'})+'\n\n# 现在你在和'+S.me.name+'玩游戏：'+_gs.title+'\n你们在一个【独立的小游戏空间】里玩，这不是日常微信聊天。\n- 用中文，轻松口语，沉浸在游戏里当好玩伴/主持人。\n- 游戏规则：'+_gs.intro+'\n- 系统会带入最近 '+gameContextRounds()+' 个完整回合。出题、提问或推进前必须检查已有游戏记录；已经问过、答过或完成过的内容不要重复，除非'+S.me.name+'明确要求重来。\n- 别发[转账][红包][语音]这类卡片/标签，专心玩。\n- 当'+S.me.name+'说"游戏结束/不玩了/结束/退出"时，温柔地收个尾、道个别即可。';}
function gsAbsorb(r){if(!_gs)return;splitBubbles(r).forEach(l=>{l=normTag(l);if(LEAKRE.test(l))return;l=l.replace(/\[[^\]]*\]/g,'').trim();if(l)splitActions(l).forEach(p=>{if(p.trim())_gs.msgs.push({id:uid(),who:'ta',text:p.trim()});});});}
async function gsKick(){if(!_gs)return;const g=_gs;g.busy=true;gsRender();
  try{const r=await chatAPI([{role:'system',content:gsSystem()},{role:'user',content:'[游戏开始，请你作为主持人/玩伴先开场。]'}],{aux:true});if(_gs!==g)return;gsAbsorb(r);}
  catch(e){if(_gs===g)g.msgs.push({id:uid(),who:'ta',text:'（信号好像不太好…再戳我一下？）'});}
  if(_gs===g){g.busy=false;gsSaveDraft(g);}gsRender();}
async function gsReply(){if(!_gs)return;const g=_gs;g.busy=true;gsRender();
  try{const hist=gameContextRows(g.msgs).map(m=>({role:m.who==='me'?'user':'assistant',content:m.text}));
    const r=await chatAPI([{role:'system',content:gsSystem()},...hist],{aux:true});if(_gs!==g)return;gsAbsorb(r);}
  catch(e){if(_gs===g)g.msgs.push({id:uid(),who:'ta',text:'（…信号断了一下，再说一遍？）'});}
  if(_gs===g){g.busy=false;gsSaveDraft(g);}gsRender();}
function gsSend(){if(!_gs||_gs.busy)return;const ta=$('#gs_in');if(!ta)return;const v=(ta.value||'').trim();if(!v)return;ta.value='';
  _gs.msgs.push({id:uid(),who:'me',text:v});gsSaveDraft(_gs);if(manualReplySceneOn('games'))gsRender();else gsReply();}
function gsDice(){if(!_gs||_gs.busy)return;const v=1+Math.floor(Math.random()*6);_gs.msgs.push({id:uid(),who:'me',text:'我掷出了 '+v+' 点'});gsSaveDraft(_gs);if(manualReplySceneOn('games'))gsRender();else gsReply();}
function gsManualReply(){if(!_gs||_gs.busy)return;gsReply();}
function gsMsgMenu(mid){if(!_gs)return;const m=(_gs.msgs||[]).find(x=>x.id===mid);if(!m)return;openModal(`<h3>编辑 / 删除</h3><div class="field"><textarea id="gs_e" rows="3">${esc(m.text)}</textarea></div><div class="btns"><button class="btn d" onclick="gsDelMsg('${mid}')">删除</button><button class="btn p" onclick="gsEditMsg('${mid}')">保存</button></div><button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function gsEditMsg(mid){if(!_gs)return;const m=(_gs.msgs||[]).find(x=>x.id===mid),v=(($('#gs_e')||{}).value||'').trim();if(!m||!v)return;m.text=v;gsSaveDraft(_gs);closeModal();gsRender();}
function gsDelMsg(mid){if(!_gs)return;_gs.msgs=(_gs.msgs||[]).filter(x=>x.id!==mid);gsSaveDraft(_gs);closeModal();gsRender();}
function gsFmt(){const t=Math.max(0,_gs?_gs.t:0);return Math.floor(t/60)+':'+String(t%60).padStart(2,'0');}
function gsTimer(){if(!_gs)return;clearInterval(_gs._tm);const tm=setInterval(()=>{if(!_gs||cur().p!=='gs'){clearInterval(tm);return;}_gs.t--;const e=document.getElementById('gstime');if(e)e.textContent=gsFmt();if(_gs.t<=0){clearInterval(tm);toast('时间到啦～想继续玩也行，不玩就点结束');}},1000);_gs._tm=tm;}
function gsRender(){if(cur().p==='gs')render();}
function gameRoomMeta(kind){return {soup:['推理解谜','每次提问都在靠近真相','输入你的推理或问题'],escape:['密室逃脱','观察线索，做出下一步行动','描述你要调查或执行的动作'],wordguess:['词语竞猜','不能直接说出答案中的字','输入猜测或新的描述'],tod:['真心挑战','掷骰子决定这一轮的挑战','输入回答、真心话或大冒险'],quiz:['默契考验','轮流提出关于彼此的问题','输入你的答案或下一道题'],drama:['即兴剧场','接住对方的台词继续演下去','输入角色台词或动作'],quick:['快速回合','凭第一反应回答，不要犹豫','输入你的第一反应']}[kind]||['游戏进行中','和TA一起完成这一局','输入消息'];}
function renderGS(){if(!_gs)return '';const c=getC(_gs.cid),meta=gameRoomMeta(_gs.kind),turns=(_gs.msgs||[]).filter(m=>m.who==='me').length;(_gs.msgs||[]).forEach(m=>{if(!m.id)m.id=uid();});
  const body=_gs.msgs.map(m=>m.who==='me'
    ?`<div class="msg me gs-message" onclick="gsMsgMenu('${m.id}')"><div class="col"><div class="bubble">${esc(m.text)}</div></div></div>`
    :`<div class="msg them gs-message" onclick="gsMsgMenu('${m.id}')">${av(c?c.avatar:'')}<div class="col"><div class="bubble">${esc(m.text)}</div></div></div>`).join('')
    +(_gs.busy?`<div class="msg them gs-message">${av(c?c.avatar:'')}<div class="col"><div class="bubble typing"><span></span><span></span><span></span></div></div></div>`:'');
  return `<div class="gs-room gs-theme-${esc(_gs.kind)}"><div class="nav gs-nav"><span class="l" onclick="gsExit()">‹ 退出</span><span class="t"><i>${gameLineIcon(_gs.kind)}</i><b>${esc(_gs.title)}</b><small>${esc(meta[0])}</small></span><span class="r" onclick="gsEnd()">结束</span></div><div class="gs-score"><span>回合 <b>${turns}</b></span><span>${esc(meta[1])}</span><time id="gstime">${gsFmt()}</time></div>
    <div class="scroll gs-playfield" id="gsbg"><div class="gs-intro"><i>${gameLineIcon(_gs.kind)}</i><div><b>${esc(meta[0])}</b><small>${esc(meta[1])}</small></div></div>${body||'<div class="gs-opening"><i></i><span>正在准备开场</span></div>'}</div>
    ${manualReplySceneOn('games')?`<div class="manual-reply-row gs-manual"><button class="manual-reply-chip" ${_gs.busy?'disabled':''} onclick="gsManualReply()">${_gs.busy?'回应中…':'让TA回应'}</button></div>`:''}
    <div class="gs-tools"><button onclick="gsClear()">${svgIc('trash',14,'currentColor')}<span>清空本局</span></button><small>点按气泡可编辑记录</small></div>
    <div class="gs-compose">${_gs.kind==='tod'?`<button class="gs-dice" onclick="gsDice()" title="掷骰子">${gameLineIcon('tod')}<span>掷骰</span></button>`:''}<textarea id="gs_in" rows="1" placeholder="${esc(meta[2])}" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();gsSend();}"></textarea><button class="gs-send" onclick="gsSend()" aria-label="发送">${svgIc('forward',19,'#fff')}</button></div></div>`;}
function gsExit(){const g=_gs;if(g){clearInterval(g._tm);g.busy=false;gsSaveDraft(g);}_gs=null;home();}
function gsEnd(){const g=_gs;if(g){clearInterval(g._tm);gameSetHandoff(g.cid,g.title,g.msgs);gsDropDraft(g);}_gs=null;home();}
async function gsClear(){if(!_gs)return;if(_gs.busy){toast('等这条回复完成后再清空');return;}if(!(_gs.msgs||[]).length){toast('没有游戏记录');return;}if(!await uiConfirm('清空这局游戏的全部聊天记录？\n游戏不会结束，可以继续玩。'))return;_gs.msgs=[];gsSaveDraft(_gs);gsRender();toast('游戏记录已清空');}
function gsQuit(){gsExit();}
/* ===== 谁是卧底 ===== */
let _uc=null;
const UC_BOTS=['小鹿','阿白','团子','西西','阿七','麦麦','楠楠','糖糖','可可','豆豆'];
