const UC_WORDS={
 美食:[['可乐','雪碧'],['汉堡','三明治'],['包子','饺子'],['蛋糕','面包'],['咖啡','奶茶'],['西瓜','哈密瓜'],['薯条','薯片'],['火锅','麻辣烫'],['牛奶','酸奶'],['草莓','车厘子'],['拉面','米线'],['月饼','蛋黄酥'],['冰淇淋','棒冰'],['橙子','橘子'],['饺子','馄饨'],['豆浆','米汤']],
 日常:[['牙刷','牙膏'],['毛巾','浴巾'],['雨伞','雨衣'],['钢笔','铅笔'],['沙发','床'],['空调','风扇'],['镜子','窗户'],['枕头','抱枕'],['钱包','卡包'],['口红','唇膏'],['耳机','音响'],['手表','手环'],['眼镜','墨镜'],['充电器','充电宝'],['闹钟','手表'],['拖鞋','凉鞋']],
 动物:[['老虎','豹子'],['青蛙','蟾蜍'],['乌龟','甲鱼'],['兔子','仓鼠'],['蝴蝶','飞蛾'],['鲸鱼','海豚'],['企鹅','鸭子'],['马','驴'],['蜜蜂','蚂蚁'],['鹦鹉','八哥'],['金鱼','锦鲤'],['狼','哈士奇'],['熊猫','浣熊'],['蜗牛','蜘蛛']],
 地点:[['学校','幼儿园'],['医院','药店'],['电影院','剧院'],['超市','便利店'],['游泳池','澡堂'],['机场','火车站'],['公园','植物园'],['图书馆','书店'],['酒吧','咖啡厅'],['健身房','操场'],['酒店','民宿'],['银行','邮局']],
 职业:[['医生','护士'],['老师','教授'],['警察','保安'],['演员','主播'],['歌手','rapper'],['作家','记者'],['厨师','服务员'],['司机','快递员'],['程序员','设计师'],['律师','法官'],['理发师','化妆师']],
 抽象:[['梦想','理想'],['爱情','友情'],['回忆','想象'],['谎言','秘密'],['时间','年龄'],['影子','倒影'],['运气','缘分'],['寂寞','孤独'],['后悔','遗憾'],['希望','期待'],['自由','放纵'],['温柔','善良'],['勇气','冲动']]
};
function ucConfig(cid){closeModal();const cs=S.contacts.filter(c=>!c.deleted);
  openModal(`<h3>谁是卧底</h3>
   <div class="hint">勾选要拉进来一起玩的角色（可多选），人数不够用匿名AI玩家补。每人拿到一个词，卧底的词不一样。</div>
   <div class="field"><label>拉谁进来玩（可多选）</label><div class="section">${cs.length?cs.map(c=>`<label class="avline" style="font-weight:400">${esc(c.remark||c.name)}<span class="sw ${c.id===cid?'on':''}" data-uc="${c.id}" onclick="this.classList.toggle('on')"></span></label>`).join(''):'<div style="font-size:12px;color:#999;padding:8px">还没有角色，会全用匿名AI玩家</div>'}</div></div>
   <div class="field"><label>再加几个匿名AI玩家</label><select id="uc_bots"><option>0</option><option>1</option><option selected>2</option><option>3</option><option>4</option></select></div>
   <div class="field"><label>词库类别</label><select id="uc_cat"><option value="ai">AI随机出题（无限不重复）</option><option value="美食">美食</option><option value="日常">日常用品</option><option value="动物">动物</option><option value="地点">地点</option><option value="职业">人物职业</option><option value="抽象">抽象脑洞</option></select></div>
   <div class="field"><label>卧底人数</label><select id="uc_u"><option selected>1</option><option>2</option></select></div>
   <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="ucStart()">开始</button></div>`);}
async function ucStart(){const sel=[...document.querySelectorAll('[data-uc].on')].map(e=>e.getAttribute('data-uc'));
  const nbots=+($('#uc_bots')?$('#uc_bots').value:0)||0;let U=+($('#uc_u')?$('#uc_u').value:1)||1;
  const cat=$('#uc_cat')?$('#uc_cat').value:'ai';
  const chars=sel.map(id=>getC(id)).filter(Boolean);const total=1+chars.length+nbots;
  if(total<4){toast('至少要4个玩家(含你)，多拉角色或加几个AI玩家');return;}
  closeModal();U=Math.min(U,Math.max(1,Math.floor((total-1)/2)));
  const traits=[...UC_TRAITS].sort(()=>Math.random()-.5);
  const players=[{id:'me',name:S.me.name,isMe:true,avatar:S.me.avatar,bot:false,alive:true,role:'civ',word:'',desc:'',_said:false,vote:null}];
  chars.forEach(c=>players.push({id:'p_'+c.id,name:c.remark||c.name,avatar:c.avatar,isMe:false,bot:false,alive:true,role:'civ',word:'',desc:'',_said:false,vote:null}));
  let bi=0;for(let i=0;i<nbots;i++)players.push({id:'bot'+i,name:UC_BOTS[bi++%UC_BOTS.length],avatar:'',isMe:false,bot:true,trait:traits[i%traits.length],alive:true,role:'civ',word:'',desc:'',_said:false,vote:null});
  const N=players.length;
  const ridx=[...Array(N).keys()].sort(()=>Math.random()-.5).slice(0,U);ridx.forEach(i=>players[i].role='undercover');
  _uc={cid,players,N,U,phase:'loading',round:1,turn:0,order:[],civWord:'',ucWord:'',busy:true,lastOut:null,win:null,_botDescDone:false};
  go('uc');render();
  let pair=null;
  if(cat!=='ai'&&UC_WORDS[cat]){const list=UC_WORDS[cat];pair=list[Math.floor(Math.random()*list.length)];if(window._ucLast===pair.join()&&list.length>1){pair=list[(list.indexOf(pair)+1)%list.length];}window._ucLast=pair.join();if(Math.random()<.5)pair=[pair[1],pair[0]];}
  if(pair){_uc.civWord=pair[0];_uc.ucWord=pair[1];}
  else{try{const r=await chatAPI([{role:'system',content:'给一对"谁是卧底"游戏用的词：两个相近但不同的具体名词，能描述也容易混淆。只输出一行，格式：平民词:::卧底词。例如 可乐:::雪碧 或 老虎:::豹子'},{role:'user',content:'出一对词'}],{max:40,aux:true});
    const p=(r||'').split(/:::|：：：/).map(x=>x.trim()).filter(Boolean);_uc.civWord=p[0]||'苹果';_uc.ucWord=p[1]||'梨';}
  catch(e){_uc.civWord='苹果';_uc.ucWord='梨';}}
  if(!_uc)return;_uc.players.forEach(p=>p.word=p.role==='undercover'?_uc.ucWord:_uc.civWord);
  _uc.order=[...Array(N).keys()].sort(()=>Math.random()-.5);_uc.turn=0;_uc.phase='desc';_uc.busy=false;ucStep();}
function ucAlive(){return _uc.players.filter(p=>p.alive);}
function ucStep(){if(!_uc)return;
  // 先把所有 bot 的描述一次性批量生成（省调用）；真正的角色单独调
  const bots=_uc.players.filter(p=>p.alive&&p.bot&&!p._said);
  if(bots.length&&!_uc._botDescDone){_uc._botDescDone=true;_uc.busy=true;render();ucBotDescs(bots);return;}
  while(_uc.turn<_uc.order.length){const p=_uc.players[_uc.order[_uc.turn]];
    if(p&&p.alive&&!p._said){
      if(p.isMe){_uc.phase='desc';render();return;}
      if(p.bot){_uc.turn++;continue;}
      _uc.busy=true;render();ucAIDesc(p);return;}
    _uc.turn++;}
  ucVotePhase();}
function ucFallbackDesc(){return ['不太好说…','你们先猜猜','跟楼上差不多','嗯…挺常见的','有点难形容'][Math.floor(Math.random()*5)];}
async function ucBotDescs(bots){if(!_uc)return;
  const prev=ucAlive().filter(x=>x._said).map(x=>x.name+'：'+x.desc).join('\n')||'(还没人描述)';
  const lines=bots.map(b=>b.name+'（词：'+b.word+'，性格：'+(b.trait||'普通')+'）').join('\n');
  try{const r=await chatAPI([{role:'system',content:'你在主持"谁是卧底"，替下面几个电脑玩家各写一句对"自己词"的描述。规则：每句【不能出现该玩家自己的词或其中的字】，自然像真人；【每个人都要按自己的"性格"用不同的语气和风格说话，别写得千篇一律】；谁的词跟多数人明显不同(可能是卧底)就描述得更含糊别暴露。已有描述：\n'+prev+'\n这几个玩家、各自的词和性格：\n'+lines+'\n严格每行一个、按这个顺序，格式：玩家名:::描述（8到22字，体现各自性格）。只输出这些行，别的不要。'},{role:'user',content:'给出他们的描述'}],{max:400,aux:true});
    const map={};(r||'').split('\n').forEach(line=>{const m=line.split(/:::|：：：/);if(m.length>=2&&m[0].trim())map[m[0].trim()]=m[1].trim();});
    bots.forEach(b=>{b.desc=((map[b.name]||'').replace(/^["「『]+|["」』]+$/g,'').slice(0,40))||ucFallbackDesc();b._said=true;});}
  catch(e){bots.forEach(b=>{b.desc=ucFallbackDesc();b._said=true;});}
  if(!_uc)return;_uc.busy=false;ucStep();}
async function ucAIDesc(p){if(!_uc)return;const prev=ucAlive().filter(x=>x._said).map(x=>x.name+'：'+x.desc).join('\n')||'(你是第一个说的)';
  const cc=getC(p.id.slice(2));const base=cc?buildSystem(cc)+'\n\n':'';
  try{const r=await chatAPI([{role:'system',content:base+'你在玩"谁是卧底"，你拿到的词是「'+p.word+'」。用一句话描述这个词（可以带点你自己的说话风格），【绝不能说出这个词本身或它包含的字】，要自然、像真人。如果你发现自己的词好像和别人描述的对不上，你可能是少数派(卧底)，那就说得更模糊、更含糊地跟着大家，别暴露自己。本轮已有的描述：\n'+prev+'\n只输出你的一句话描述（8到22字，不要引号、不要带名字、不要解释）。'},{role:'user',content:'轮到你描述了'}],{max:60,aux:true});
    p.desc=(cleanReply(r)||'').replace(/^["「『]+|["」』]+$/g,'').replace(/\n/g,' ').slice(0,40)||'…(想不出词)';}
  catch(e){p.desc='…(没说话)';}
  p._said=true;_uc.turn++;_uc.busy=false;ucStep();}
function ucDesc(){if(!_uc)return;const ta=$('#uc_in');const v=(ta&&ta.value||'').trim();if(!v){toast('描述一下你的词吧～');return;}
  const me=_uc.players.find(p=>p.isMe);me.desc=v.slice(0,40);me._said=true;_uc.turn++;ucStep();}
async function ucVotePhase(){if(!_uc)return;_uc.phase='vote';_uc.busy=true;_uc.players.forEach(p=>p.vote=null);render();
  const alive=ucAlive();const summary=alive.map(p=>p.name+'：'+(p.desc||'(没说)')).join('\n');
  // 角色单独投（带各自人设）
  for(const p of alive){if(p.isMe||p.bot)continue;
    const others=alive.filter(x=>x.id!==p.id);const cc=getC(p.id.slice(2));const base=cc?buildSystem(cc)+'\n\n':'';
    try{const r=await chatAPI([{role:'system',content:base+'你在玩"谁是卧底"。你自己的词是「'+p.word+'」。下面是每个人的描述：\n'+summary+'\n请你【独立】判断：谁的描述放到你的词「'+p.word+'」上最不贴切、最不像在说你这个词，谁就最可能是卧底——按你自己的想法投，别管别人怎么想。从这些人里投一个（不能投自己）：'+others.map(x=>x.name).join('、')+'。只回答一个名字，不要解释。'},{role:'user',content:'你投谁？'}],{max:20,aux:true});
      const nm=(r||'').trim();let t=others.find(x=>nm.includes(x.name));if(!t)t=others[Math.floor(Math.random()*others.length)];p.vote=t?t.id:null;}
    catch(e){p.vote=others.length?others[Math.floor(Math.random()*others.length)].id:null;}}
  // bot 批量投（一次调用）
  const bots=alive.filter(p=>p.bot);
  if(bots.length){
    try{const r=await chatAPI([{role:'system',content:'你在主持"谁是卧底"投票。大家的描述：\n'+summary+'\n下面每个电脑玩家有【自己的词】和【性格】，请站在各自的角度【独立】判断：对该玩家来说，谁的描述跟「他自己的词」最不搭、最可疑，就投谁；多疑的更爱投人、迷糊的可能投错、阴阳怪气的可能乱投——按性格来。每个人的词不同，投票很可能【各不相同】，不要全投同一个人（除非极其明显）。不能投自己。玩家、词和性格：\n'+bots.map(b=>b.name+'（词：'+b.word+'，性格：'+(b.trait||'普通')+'）').join('\n')+'\n可投的人：'+alive.map(x=>x.name).join('、')+'。严格每行一个，格式：玩家名:::要投的人名。只输出这些行。'},{role:'user',content:'给出各自的投票'}],{max:200,aux:true});
      const map={};(r||'').split('\n').forEach(line=>{const m=line.split(/:::|：：：/);if(m.length>=2)map[m[0].trim()]=m[1].trim();});
      bots.forEach(b=>{const others=alive.filter(x=>x.id!==b.id);const nm=map[b.name]||'';let t=others.find(x=>nm.includes(x.name));if(!t)t=others[Math.floor(Math.random()*others.length)];b.vote=t?t.id:null;});}
    catch(e){bots.forEach(b=>{const others=alive.filter(x=>x.id!==b.id);b.vote=others.length?others[Math.floor(Math.random()*others.length)].id:null;});}}
  if(!_uc)return;_uc.busy=false;render();}
function ucVote(id){if(!_uc||_uc.busy)return;const me=_uc.players.find(p=>p.isMe);if(!me.alive){ucTally();return;}me.vote=id;ucTally();}
function ucTally(){if(!_uc)return;const alive=ucAlive();const tally={};
  alive.forEach(p=>{if(p.vote){tally[p.vote]=(tally[p.vote]||0)+1;}});
  let max=0,top=[];Object.keys(tally).forEach(id=>{if(tally[id]>max){max=tally[id];top=[id];}else if(tally[id]===max)top.push(id);});
  let outId,tie=false;
  if(!top.length)outId=alive[Math.floor(Math.random()*alive.length)].id;
  else if(top.length>1){tie=true;outId=top[Math.floor(Math.random()*top.length)];}
  else outId=top[0];
  const out=_uc.players.find(p=>p.id===outId);out.alive=false;
  const votes=alive.filter(p=>p.vote).map(p=>p.name+'→'+(_uc.players.find(x=>x.id===p.vote)||{}).name).join('，');
  _uc.lastOut={name:out.name,role:out.role,tie,votes,wasMe:out.isMe};
  const aliveU=_uc.players.filter(p=>p.alive&&p.role==='undercover').length;
  const aliveC=_uc.players.filter(p=>p.alive&&p.role==='civ').length;
  if(aliveU===0){_uc.phase='over';_uc.win='civ';}
  else if(aliveU>=aliveC){_uc.phase='over';_uc.win='under';}
  else _uc.phase='result';
  render();}
function ucNextRound(){if(!_uc)return;_uc.round++;_uc.players.forEach(p=>{p._said=false;p.desc='';p.vote=null;});
  _uc.order=_uc.players.map((p,i)=>i).filter(i=>_uc.players[i].alive).sort(()=>Math.random()-.5);
  _uc.turn=0;_uc.phase='desc';_uc.lastOut=null;_uc._botDescDone=false;render();ucStep();}
function ucMsgMenu(pid){if(!_uc)return;const p=(_uc.players||[]).find(x=>x.id===pid);if(!p||!p.desc)return;openModal(`<h3>编辑 / 删除</h3><div class="field"><textarea id="uc_e" rows="3">${esc(p.desc)}</textarea></div><div class="btns"><button class="btn d" onclick="ucDelMsg('${pid}')">删除</button><button class="btn p" onclick="ucEditMsg('${pid}')">保存</button></div><button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function ucEditMsg(pid){if(!_uc)return;const p=(_uc.players||[]).find(x=>x.id===pid),v=(($('#uc_e')||{}).value||'').trim();if(!p||!v)return;p.desc=v.slice(0,80);closeModal();render();}
function ucDelMsg(pid){if(!_uc)return;const p=(_uc.players||[]).find(x=>x.id===pid);if(!p)return;p.desc='';closeModal();render();}
function ucPill(p){const me=_uc.players.find(x=>x.isMe);const dead=!p.alive;
  return `<div class="uc-player${dead?' dead':''}" ${p.desc?`onclick="ucMsgMenu('${p.id}')"`:''}>${av(p.avatar,'sm')}<div><b>${esc(p.name)}${p.isMe?' <small>你</small>':''}</b>${p.desc?`<span>${esc(p.desc)}</span>`:'<span class="waiting">等待描述</span>'}</div>${dead?`<em>${p.role==='undercover'?'卧底':'平民'} · 已出局</em>`:'<i></i>'}</div>`;}
function renderUC(){if(!_uc)return '';const me=_uc.players.find(p=>p.isMe);
  let panel='';
  if(_uc.phase==='loading')panel='<div class="uc-status"><i></i><span>正在分配词卡</span></div>';
  else if(_uc.phase==='desc'){const cur_=_uc.players[_uc.order[_uc.turn]];
    if(cur_&&cur_.isMe&&cur_.alive&&!cur_._said&&!_uc.busy)panel=`<div class="uc-action"><b>轮到你描述</b><small>用一句话描述，但不要直接说出词卡</small><div><textarea id="uc_in" rows="1" placeholder="输入一句描述" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();ucDesc();}"></textarea><button onclick="ucDesc()">发送</button></div></div>`;
    else panel=`<div class="uc-status"><i></i><span>${esc((cur_&&cur_.name)||'玩家')}正在描述</span></div>`;}
  else if(_uc.phase==='vote'){
    if(_uc.busy)panel='<div class="uc-status"><i></i><span>其他玩家正在投票</span></div>';
    else if(me.alive)panel=`<div class="uc-vote"><b>选出你认为的卧底</b><div>${ucAlive().filter(p=>!p.isMe).map(p=>`<button onclick="ucVote('${p.id}')">${esc(p.name)}</button>`).join('')}</div></div>`;
    else panel=`<div class="uc-vote"><b>你已出局 · 旁观模式</b><div><button onclick="ucVote('')">查看投票结果</button></div></div>`;}
  else if(_uc.phase==='result'){const o=_uc.lastOut;
    panel=`<div class="uc-result">${o.tie?'<small>本轮平票 · 随机裁定</small>':''}<b>${esc(o.name)} 被票出局</b><strong>${o.role==='undercover'?'身份：卧底':'身份：平民'}</strong><p>${esc(o.votes||'')}</p><button onclick="ucNextRound()">进入下一轮</button></div>`;}
  else if(_uc.phase==='over'){const o=_uc.lastOut;const meUnder=me.role==='undercover';const win=_uc.win;
    const iWon=(win==='under')===meUnder;
    panel=`<div class="uc-result final"><small>GAME OVER</small><b>${win==='under'?'卧底阵营获胜':'平民阵营获胜'}</b><strong class="${iWon?'win':'lose'}">你是${meUnder?'卧底':'平民'} · ${iWon?'本局获胜':'本局落败'}</strong><p>平民词：${esc(_uc.civWord)}<br>卧底词：${esc(_uc.ucWord)}</p><div>${_uc.players.map(p=>esc(p.name)+' · '+(p.role==='undercover'?'卧底':'平民')).join('　')}</div><footer><button onclick="ucReplay()">再来一局</button><button onclick="ucQuit()">退出游戏</button></footer></div>`;}
  const show=!!_uc.showWord;
  const wordBox=`<button class="uc-word" onclick="ucToggleWord()"><small>你的词卡 · 点按${show?'隐藏':'查看'}</small><b class="${show?'show':''}">${show?esc(me.word||'…'):'••••'}</b><span>第 ${_uc.round} 轮 · 根据描述判断自己的阵营</span></button>`;
  return `<div class="uc-room"><div class="nav uc-nav"><span class="l" onclick="ucQuit()">‹ 退出</span><span class="t"><i>${gameLineIcon('undercover')}</i><b>谁是卧底</b><small>DEDUCTION ROOM</small></span><span class="r" onclick="ucQuit()">结束</span></div><div class="scroll uc-scroll">${wordBox}<div class="uc-list">${_uc.players.map(ucPill).join('')}</div><div class="uc-panel">${panel}</div><div style="height:20px"></div></div></div>`;}
function ucSetHandoff(){if(!_uc)return;const rows=(_uc.players||[]).filter(p=>p.desc).map(p=>({who:p.isMe?'me':'ta',name:p.name,text:p.desc}));if(_uc.lastOut)rows.push({who:'sys',text:_uc.lastOut.name+'被票出局'});gameSetHandoff(_uc.cid,'谁是卧底',rows);}
function ucReplay(){const lead=_uc.players.find(p=>!p.isMe&&p.id.indexOf('p_')===0);const cid=_uc.cid||(lead?lead.id.slice(2):(S.contacts.filter(c=>!c.deleted)[0]||{}).id);ucSetHandoff();_uc=null;if(cid)ucConfig(cid);else home();}
function ucToggleWord(){if(!_uc)return;_uc.showWord=!_uc.showWord;render();}
function ucQuit(){ucSetHandoff();_uc=null;home();}
/* ===== 通话记录（可删改）===== */
let _clTab='all',_clOpen={};
let _callReplay=null,_callReplayExporting=false,_callReplayOutput=null;
let _callReplayRevoiceBusy=false;
function callReplayAudioKey(m){const x=m&&String(m.callAudio||'').match(/^idb-audio:(.+)$/i);return x?x[1]:'';}
function callReplayClearAudio(m){if(!m)return;const k=callReplayAudioKey(m);if(k)imgDel('__audio_'+k);delete m.callAudio;delete m.callAudioTs;}
async function callReplayStoreAudio(m,ab,dur){if(!m||!ab||m._ck!=='video')return '';const du=audioBufToDataUrl(ab,'audio/mpeg');if(!du)return '';const k='call_'+String(m.id||uid()).replace(/[^a-zA-Z0-9_-]/g,'');try{await imgPut('__audio_'+k,du);m.callAudio='idb-audio:'+k;m.callAudioTs=Date.now();m.callAudioDur=Math.max(0,+dur||0);save();return m.callAudio;}catch(_){return '';}}
async function callReplayReplaceAudio(m,ab,dur){if(!m||!ab||m._ck!=='video')return '';const du=audioBufToDataUrl(ab,'audio/mpeg');if(!du)return '';const old={audio:m.callAudio||'',ts:m.callAudioTs,dur:m.callAudioDur,key:callReplayAudioKey(m)},k='call_'+String(m.id||uid()).replace(/[^a-zA-Z0-9_-]/g,'')+'_redo_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7);try{await imgPut('__audio_'+k,du);m.callAudio='idb-audio:'+k;m.callAudioTs=Date.now();m.callAudioDur=Math.max(0,+dur||0);save();if(old.key&&old.key!==k)await imgDel('__audio_'+old.key);return m.callAudio;}catch(_){if(old.audio)m.callAudio=old.audio;else delete m.callAudio;if(old.ts!==undefined)m.callAudioTs=old.ts;else delete m.callAudioTs;if(old.dur!==undefined)m.callAudioDur=old.dur;else delete m.callAudioDur;await imgDel('__audio_'+k);return '';}}
function callReplayCue(m,prev,c){if(m&&m._callVoiceCue)return m._callVoiceCue;const a=prev&&callIsActionLine(prev.content)?String(prev.content||''):'';if(/大笑|笑出声|放声笑/.test(a))return'大笑';if(/轻笑|低笑|笑了|笑一下|笑起来|勾起.{0,3}笑/.test(a))return'轻笑';if(/叹气|叹了/.test(a))return'叹气';if(/哭|抽泣|哽咽/.test(a))return'哭泣';if(/亲|吻|啵/.test(a))return'亲亲';return ttsRequestedCue(a)||ttsAutoCue(a+' '+String(m&&m.content||''),c)||'';}
function callReplayRows(id,cs){const c=getC(id);if(!c)return[];const raw=msgs(id).filter(m=>m&&m._call&&m._ck==='video'&&(m._cs||'')===cs&&!m._callTranslationOf),out=[];raw.forEach((m,i)=>{const text=String(m.content||'').trim(),legacyTrans=m.role==='assistant'&&/^[（(][^）)]*[）)]$/.test(text)&&hasCN(text);if(legacyTrans&&out.length&&out[out.length-1].role==='assistant'&&!out[out.length-1].action){if(!out[out.length-1].trans)out[out.length-1].trans=text;return;}const trans=String(m._callTrans||'').trim(),audio=m.role==='assistant'?m.callAudio:(m.type==='voice'?m.audio:'');out.push({id:m.id||uid(),role:m.role,text,trans,audio:audio||'',action:callIsActionLine(text),cue:callReplayCue(m,raw[i-1],c),interjection:m._callVoiceInterjection!==false,time:m.time||0});});return out.filter(x=>x.text||x.audio);}
function callReplayChecked(){return Array.from(document.querySelectorAll('.call-replay-pick:checked')).map(x=>x.value);}
function clReplayChoose(all){document.querySelectorAll('.call-replay-pick').forEach(x=>x.checked=!!all);}
function clReplayPicker(id,cs){const rows=callReplayRows(id,cs);if(!rows.length){toast('这通没有可回放的内容');return;}const sound=rows.filter(x=>x.audio).length,revoiceable=rows.filter(x=>x.role==='assistant'&&!x.action&&pickSpoken(x.text,ttsContentLang(getC(id)))).length;
  openModal(`<h3>视频通话回放</h3><div class="hint" style="line-height:1.7">选择想保留的时间点。🔊 表示保存了当时的真实声音；“仅字幕”不会自动生成语音。旧通话没有声音时，可选中TA说话的时间点重新生成后再导出。</div>
  <div style="display:flex;gap:8px;margin:9px 0"><button class="minibtn" onclick="clReplayChoose(true)">全选</button><button class="minibtn" onclick="clReplayChoose(false)">全不选</button><span style="margin-left:auto;color:${sound?'#6fd49a':'#fa7777'};font-size:12px;align-self:center">${sound?'已有 '+sound+' 个时间点保存声音':'旧记录没有保存声音'}</span></div>
  <div style="max-height:48vh;overflow:auto;border:1px solid #303036;border-radius:12px;padding:3px 10px">${rows.map((r,i)=>`<label style="display:flex;gap:9px;align-items:flex-start;padding:9px 0;border-bottom:.5px solid #29292d"><input class="call-replay-pick" type="checkbox" value="${esc(r.id)}" checked style="margin-top:4px"><span style="min-width:23px;color:${r.audio?'#70d99b':'#888'}">${r.audio?'🔊':'◻'}</span><span style="flex:1;font-size:13px;line-height:1.55;color:#ddd"><b style="color:${r.role==='user'?'#ffd6e8':'#9ec5fe'}">${r.role==='user'?'我':'TA'} · ${r.time?hm(r.time):('第'+(i+1)+'条')}</b><br>${esc(r.text)}${r.trans?'<br><span style="color:#999">'+esc(r.trans)+'</span>':''}${!r.audio?'<br><span style="color:#777">仅字幕</span>':''}</span></label>`).join('')}</div>
  ${revoiceable?`<button class="btn g" style="margin-top:10px;color:#ffb36b" onclick="clReplayRevoice('${id}','${cs}')">重新生成所选时间点的声音（成功会扣点）</button>`:''}<div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn g" onclick="clReplayStart('${id}','${cs}')">播放回放</button><button class="btn p" onclick="clReplayExport('${id}','${cs}')">生成有声视频</button></div>`);}
function callReplayPickRows(id,cs){const ids=callReplayChecked();if(!ids.length){toast('请至少选择一个时间点');return[];}const set=new Set(ids);return callReplayRows(id,cs).filter(x=>set.has(String(x.id)));}
async function clReplayRevoice(id,cs){if(_callReplayRevoiceBusy){toast('正在重新配音，请稍等');return;}const c=getC(id),rows=callReplayPickRows(id,cs);if(!c||!rows.length)return;if(!ttsApiOn(c)){toast('请先在AI账户或角色语音里开启语音');return;}const lang=ttsContentLang(c),targets=rows.filter(x=>x.role==='assistant'&&!x.action&&pickSpoken(x.text,lang));if(!targets.length){toast('请选择TA说话的时间点');return;}let points=0;targets.forEach(x=>{const t=ttsPerformanceText(pickSpoken(x.text,lang),c,ttsCfg(c),{cue:x.cue,interjection:x.interjection});points+=typeof aiTtsPointCost==='function'?aiTtsPointCost([...t].length):Math.max(1,Math.ceil([...t].length/50));});const note=ttsUseRelay(c)?'预计扣除约 '+points+' 点；每句成功才扣，失败不扣。':'使用这个角色选择的外置语音路线，不扣内置AI点数。';if(!await uiConfirm('将重新生成所选的 '+targets.length+' 个时间点声音。\n'+note+'\n已有声音仅在新声音成功保存后替换；失败会保留原声音。'))return;_callReplayRevoiceBusy=true;closeModal();audioUnlock();toast('正在按原台词和情绪重新生成声音…');let ok=0,fail=0;for(const row of targets){const m=msgs(id).find(x=>String(x.id)===String(row.id));if(!m)continue;let ab=null;try{const spoken=pickSpoken(m.content,lang);ab=await ttsArr(spoken,c,{cue:row.cue,interjection:row.interjection});const buf=await decodeBuf(ab);if(buf){const stored=await callReplayReplaceAudio(m,ab,buf.duration);if(stored){m._callVoiceCue=row.cue||'';m._callVoiceInterjection=row.interjection;ok++;}else{if(ab)await ttsRefundAudio(ab,'call-revoice-store-failed');fail++;}}else{if(ab)await ttsRefundAudio(ab,'call-revoice-decode-failed');fail++;}}catch(_){if(ab)await ttsRefundAudio(ab,'call-revoice-exception');fail++;}}_callReplayRevoiceBusy=false;save();if(typeof aiAccountRefresh==='function')setTimeout(()=>aiAccountRefresh(true,true),500);const ids=new Set(rows.map(x=>String(x.id))),fresh=callReplayRows(id,cs).filter(x=>ids.has(String(x.id)));toast(ok?'已重新生成 '+ok+' 个时间点'+(fail?'，'+fail+'个失败未替换':''):'重新生成失败，原声音已保留');if(ok)clReplayStartRows(id,cs,fresh);}
function callReplayPlayFull(buf){ensureAudio();return new Promise(res=>{if(!_audio||!buf){res();return;}try{if(_audio.state==='suspended'||_audio.state==='interrupted')_audio.resume();stopBufSource('replaced-by-call-replay');const src=_audio.createBufferSource(),gain=_audio.createGain();src.buffer=buf;gain.gain.value=volMul();src.connect(gain);gain.connect(_audio.destination);let done=false;const end=()=>{if(done)return;done=true;res();};src.onended=end;src.start();_curSrc=src;setTimeout(end,buf.duration*1000+1200);}catch(_){res();}});}
async function callReplayPlayRow(row){if(row.audio){try{const ab=await audioDataToBuf(row.audio),buf=await decodeBuf(ab);if(buf){await callReplayPlayFull(buf);return;}}catch(_){}}await sleep(Math.min(4200,Math.max(1000,(row.text||'').length*115)));}
function updateCallReplaySub(){const box=$('#callSub');if(!box||!_callReplay)return;const s=_callReplay.sub;box.innerHTML=s?`<div class="csline ${s.who==='me'?'me':''}">${esc(s.text).replace(/\n/g,'<br>')}</div>`:'';const st=$('#callStat'),row=_callReplay.rows[_callReplay.index],point=row&&row.time?hm(row.time):('第'+Math.min(_callReplay.index+1,_callReplay.rows.length)+'条');if(st)st.textContent=_callReplay.done?'回放结束':'时间点 '+point+' · '+Math.min(_callReplay.index+1,_callReplay.rows.length)+' / '+_callReplay.rows.length;}
function renderCallReplay(){const L=$('#callLayer'),r=_callReplay;if(!L||!r)return;const c=getC(r.id);if(!c){stopCallReplay();return;}L.style.left=L.style.top=L.style.right=L.style.bottom='';L.className='callscreen show video active';callApplyBackdrop(L,c);
  L.innerHTML=`<div onclick="stopCallReplay()" title="关闭回放" style="position:absolute;left:16px;top:50px;font-size:25px;cursor:pointer;z-index:3">‹</div><div style="position:absolute;right:16px;top:53px;padding:5px 10px;border-radius:14px;background:rgba(0,0,0,.42);font-size:12px">回放</div><div class="cav">${callAvatarHTML(c)}</div><div class="cname">${esc(c.remark||c.name)}</div><div class="cstat"><span id="callStat"></span></div><div class="callsub" id="callSub"></div><div class="callbtns"><div class="cbtncol"><div class="cbtn red" onclick="stopCallReplay()">${svgIc('hangup',24,'#fff')}</div>结束回放</div>${r.done?`<div class="cbtncol"><div class="cbtn gray" onclick="restartCallReplay()">↻</div>重新播放</div>`:''}</div>`;callWarmStoredImage(c.avatar);scheduleVisibleStoredImages(true);updateCallReplaySub();}
async function clReplayStart(id,cs){const rows=callReplayPickRows(id,cs);if(!rows.length)return;if(!rows.some(x=>x.audio)){toast('这段没有保存声音，不能有声回放');return;}closeModal();_callReplay={id,cs,rows,index:0,sub:null,done:false,token:uid()};const token=_callReplay.token;renderCall();for(let i=0;i<rows.length;i++){if(!_callReplay||_callReplay.token!==token)return;_callReplay.index=i;_callReplay.sub={who:rows[i].role==='user'?'me':'them',text:rows[i].text+(rows[i].trans?'\n'+rows[i].trans:'')};updateCallReplaySub();await callReplayPlayRow(rows[i]);await sleep(220);}if(_callReplay&&_callReplay.token===token){_callReplay.done=true;_callReplay.sub=null;renderCall();}}
function restartCallReplay(){if(!_callReplay)return;const r=_callReplay;_callReplay=null;clReplayStartRows(r.id,r.cs,r.rows);}
async function clReplayStartRows(id,cs,rows){_callReplay={id,cs,rows,index:0,sub:null,done:false,token:uid()};const token=_callReplay.token;renderCall();for(let i=0;i<rows.length;i++){if(!_callReplay||_callReplay.token!==token)return;_callReplay.index=i;_callReplay.sub={who:rows[i].role==='user'?'me':'them',text:rows[i].text+(rows[i].trans?'\n'+rows[i].trans:'')};updateCallReplaySub();await callReplayPlayRow(rows[i]);await sleep(220);}if(_callReplay&&_callReplay.token===token){_callReplay.done=true;_callReplay.sub=null;renderCall();}}
function stopCallReplay(){stopBufSource('call-replay-stopped');if(_curAudio)try{_curAudio.pause();}catch(_){}_callReplay=null;renderCall();}
async function callReplayCanvasImage(src){if(isStoredImgRef(src)){try{src=await imgGet(String(src).slice(4));}catch(_){src='';}}if(!src||!isImg(src))return null;return new Promise(res=>{const im=new Image();im.crossOrigin='anonymous';im.onload=()=>res(im);im.onerror=()=>res(null);im.src=src;});}
function callReplayCover(ctx,img,x,y,w,h){if(!img)return;const ir=img.width/img.height,rr=w/h;let sx=0,sy=0,sw=img.width,sh=img.height;if(ir>rr){sw=img.height*rr;sx=(img.width-sw)/2;}else{sh=img.width/rr;sy=(img.height-sh)/2;}ctx.drawImage(img,sx,sy,sw,sh,x,y,w,h);}
function callReplayRound(ctx,x,y,w,h,r){r=Math.min(r,w/2,h/2);ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);}
function callReplayWrap(ctx,text,max){const out=[];String(text||'').split('\n').forEach(part=>{let line='';Array.from(part).forEach(ch=>{const next=line+ch;if(line&&ctx.measureText(next).width>max){out.push(line);line=ch;}else line=next;});out.push(line);});return out.filter((x,i,a)=>x||a.length===1||i<a.length-1);}
function callReplayDraw(ctx,canvas,c,row,index,total,bg,avt){const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);const g=ctx.createRadialGradient(w*.5,h*.28,20,w*.5,h*.35,h*.8);g.addColorStop(0,'#293a49');g.addColorStop(1,'#090a10');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);if(bg){callReplayCover(ctx,bg,0,0,w,h);ctx.fillStyle='rgba(0,0,0,.46)';ctx.fillRect(0,0,w,h);}ctx.fillStyle='rgba(0,0,0,.42)';ctx.beginPath();callReplayRound(ctx,w-128,42,92,40,20);ctx.fill();ctx.fillStyle='#fff';ctx.font='22px system-ui';ctx.textAlign='center';ctx.fillText('回放',w-82,69);
  ctx.save();ctx.beginPath();callReplayRound(ctx,w-188,102,150,210,18);ctx.clip();if(avt)callReplayCover(ctx,avt,w-188,102,150,210);else{ctx.fillStyle='#444';ctx.fillRect(w-188,102,150,210);ctx.fillStyle='#fff';ctx.font='64px system-ui';ctx.fillText(isStoredImgRef(c.avatar)?'🙂':String(c.avatar||'🙂').slice(0,2),w-113,226);}ctx.restore();ctx.fillStyle='#fff';ctx.font='bold 38px system-ui';ctx.fillText(c.remark||c.name,w/2,110);ctx.fillStyle='#d3d3d8';ctx.font='23px system-ui';ctx.fillText('视频通话回放 · '+(row&&row.time?hm(row.time):((index+1)+' / '+total)),w/2,152);
  const main=(row&&row.text)||'',trans=(row&&row.trans)||'';ctx.font='31px system-ui';const lines=callReplayWrap(ctx,main,w-100),tl=trans?callReplayWrap(ctx,trans,w-120):[];const all=lines.concat(tl);let y=h-350-(all.length-1)*22;ctx.fillStyle=row&&row.role==='user'?'#ffd6e8':'#fff';lines.forEach(x=>{ctx.fillText(x,w/2,y);y+=46;});if(tl.length){ctx.fillStyle='#d1d1d6';ctx.font='25px system-ui';y+=5;tl.forEach(x=>{ctx.fillText(x,w/2,y);y+=38;});}ctx.fillStyle='#fa3b3b';ctx.beginPath();ctx.arc(w/2,h-100,50,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=7;ctx.beginPath();ctx.arc(w/2,h-100,20,.25,2.9);ctx.stroke();}
function callReplayMime(){const a=['video/mp4;codecs=h264,aac','video/mp4','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'];return a.find(x=>MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported(x))||'';}
function callReplayDeliver(blob,mime){if(_callReplayOutput&&_callReplayOutput.url)try{URL.revokeObjectURL(_callReplayOutput.url);}catch(_){}const ext=/mp4/i.test(mime)?'mp4':'webm',name='视频通话回放-'+Date.now()+'.'+ext,url=URL.createObjectURL(blob);let file=null;try{file=new File([blob],name,{type:mime||blob.type});}catch(_){}_callReplayOutput={blob,mime: mime||blob.type,ext,name,url,file};const canShare=!!(file&&navigator.share&&navigator.canShare&&navigator.canShare({files:[file]}));openModal(`<h3>有声回放已生成</h3><video src="${url}" controls playsinline style="width:100%;max-height:52vh;background:#000;border-radius:12px"></video><div class="hint" style="line-height:1.75;margin-top:9px">视频已经包含当时保存的声音。${ext==='mp4'?'iPhone 点下面按钮，在系统面板里选择“存储视频”，即可保存到相册。':'当前浏览器只能生成 WebM，可先下载到“文件”；如需直接进相册，建议换 Safari 再生成。'}</div><div class="btns"><button class="btn g" onclick="closeModal()">稍后处理</button><button class="btn p" onclick="${canShare?'callReplayShareLast()':'callReplayDownloadLast()'}">${canShare?'分享/存储视频':'下载视频'}</button></div>`);toast('有声视频已生成');}
async function callReplayShareLast(){const o=_callReplayOutput;if(!o||!o.file)return;if(!(navigator.share&&navigator.canShare&&navigator.canShare({files:[o.file]}))){callReplayDownloadLast();return;}try{await navigator.share({files:[o.file],title:'视频通话回放'});toast('请选择“存储视频”即可进相册');}catch(e){if(!e||e.name!=='AbortError')toast('系统分享没有打开，可点下载视频');}}
function callReplayDownloadLast(){const o=_callReplayOutput;if(!o)return;const a=document.createElement('a');a.href=o.url;a.download=o.name;document.body.appendChild(a);a.click();a.remove();toast('视频已开始下载');}
async function clReplayExport(id,cs){if(_callReplayExporting){toast('正在生成，请稍等');return;}const rows=callReplayPickRows(id,cs);if(!rows.length)return;if(rows.length>100){toast('一次最多选择100个时间点');return;}if(rows.length>50&&!await uiConfirm('这次选择了 '+rows.length+' 个时间点，生成时间会比较久。\n请保持小手机在前台，是否继续？'))return;if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){toast('当前浏览器暂不支持生成视频');return;}_callReplayExporting=true;closeModal();toast('正在生成有声视频，请不要切到后台');let ac=null,stream=null,timer=null;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('no-audio-context');ac=new AC();await ac.resume();const prepared=rows.map(row=>({row,dur:Math.min(4.2,Math.max(1,(row.text||'').length*.115))}));let firstAudio=null;for(let i=0;i<prepared.length&&!firstAudio;i++){if(!prepared[i].row.audio)continue;try{const ab=await audioDataToBuf(prepared[i].row.audio),buf=ab&&await ac.decodeAudioData(ab.slice(0));if(buf)firstAudio={i,buf};}catch(_){}}if(!firstAudio){toast('这些时间点没有可用声音，不能导出静音视频');return;}const c=getC(id),canvas=document.createElement('canvas');canvas.width=720;canvas.height=1280;const ctx=canvas.getContext('2d'),bg=await callReplayCanvasImage(S.me.callBg),avt=await callReplayCanvasImage(c.avatar);stream=canvas.captureStream(30);const dest=ac.createMediaStreamDestination();dest.stream.getAudioTracks().forEach(t=>stream.addTrack(t));const mime=callReplayMime(),opts={videoBitsPerSecond:rows.length>50?1800000:3500000,audioBitsPerSecond:128000};if(mime)opts.mimeType=mime;const rec=new MediaRecorder(stream,opts),chunks=[];rec.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data);};let active=0;callReplayDraw(ctx,canvas,c,prepared[0].row,0,prepared.length,bg,avt);timer=setInterval(()=>callReplayDraw(ctx,canvas,c,prepared[active].row,active,prepared.length,bg,avt),1000/24);const stopped=new Promise((res,rej)=>{rec.onstop=res;rec.onerror=e=>rej(e.error||e);});rec.start(500);for(let i=0;i<prepared.length;i++){active=i;callReplayDraw(ctx,canvas,c,prepared[i].row,i,prepared.length,bg,avt);let buf=firstAudio&&firstAudio.i===i?firstAudio.buf:null;if(!buf&&prepared[i].row.audio)try{const ab=await audioDataToBuf(prepared[i].row.audio);if(ab)buf=await ac.decodeAudioData(ab.slice(0));}catch(_){}const dur=buf?Math.max(.7,buf.duration):prepared[i].dur;if(buf){await new Promise(res=>{const src=ac.createBufferSource();src.buffer=buf;src.connect(dest);src.onended=res;src.start();setTimeout(res,dur*1000+700);});}else await sleep(dur*1000);buf=null;await sleep(220);}clearInterval(timer);timer=null;rec.stop();await stopped;const type=rec.mimeType||mime||'video/webm',blob=new Blob(chunks,{type});if(!blob.size)throw new Error('empty-video');await callReplayDeliver(blob,type);}catch(e){toast('生成失败：当前浏览器不支持这次导出');}finally{if(timer)clearInterval(timer);if(stream)stream.getTracks().forEach(t=>t.stop());if(ac)try{await ac.close();}catch(_){}_callReplayExporting=false;}}
function renderCallLog(id){const c=getC(id);if(!c)return '';
  let list=msgs(id).filter(m=>m._call);
  if(_clTab==='voice')list=list.filter(m=>(m._ck||'voice')==='voice');
  else if(_clTab==='video')list=list.filter(m=>m._ck==='video');
  // 按"每通通话"(session)分组
  const groups=[],map={};
  list.forEach(m=>{const k=m._cs||('_'+(m.time||0));if(!map[k]){map[k]={cs:m._cs||'',ck:m._ck,msgs:[]};groups.push(map[k]);}map[k].msgs.push(m);});
  const html=groups.map((g,gi)=>{const first=g.msgs[0],last=g.msgs[g.msgs.length-1],groupKey=id+'|'+(g.cs||('_'+(first.time||0)));
    const kind=g.ck==='video'?'📹 视频通话':'📞 语音通话';
    const dateStr=first.time?fmtDate(first.time):'';const st=first.time?hm(first.time):'';const et=last.time?hm(last.time):'';
    const inner=g.msgs.map(m=>{const who=m.role==='user'?S.me.name:(c.remark||c.name);const txt=m.type==='voice'?('🎙️ '+(m.content||'语音')):(m.content||'');
      return `<div style="padding:6px 0;border-top:.5px solid #242428"><div style="font-size:11px;color:#888;display:flex;justify-content:space-between"><span>${esc(who)}</span><span><span onclick="clEdit('${id}','${m.id}')" style="color:#54a0ff;cursor:pointer">✎改</span><span onclick="clDel('${id}','${m.id}')" style="color:#fa5151;cursor:pointer;margin-left:14px">✕删</span></span></div><div style="color:#ddd;white-space:pre-wrap;font-size:14px;margin-top:2px">${esc(txt)}</div></div>`;}).join('');
    return `<details data-cl-key="${esc(groupKey)}" ${_clOpen[groupKey]?'open':''} ontoggle="clToggle(this)" style="margin:10px;border:1px solid #2a2a2c;border-radius:14px;overflow:hidden;background:#141416">
      <summary style="list-style-position:inside;background:#1e1e22;padding:9px 12px;cursor:pointer"><div style="display:inline-flex;width:calc(100% - 22px);justify-content:space-between;align-items:flex-start;gap:8px;vertical-align:top"><div style="min-width:0"><div style="font-size:13px;color:#9ec5fe;font-weight:600">${kind} · 第${gi+1}通</div><div style="font-size:11px;color:#888;margin-top:2px">${dateStr}　开始 ${st} — 结束 ${et}</div><div style="font-size:10px;color:#777;margin-top:4px">内容默认折叠 · 点标题展开</div></div><div style="display:flex;gap:10px;align-items:center">${g.ck==='video'?`<span onclick="event.preventDefault();event.stopPropagation();clReplayPicker('${id}','${g.cs}')" style="color:#70d99b;font-size:12px;cursor:pointer;white-space:nowrap">回放/导出</span>`:''}<span onclick="event.preventDefault();event.stopPropagation();clDelSession('${id}','${g.cs}')" style="color:#fa5151;font-size:12px;cursor:pointer;white-space:nowrap">删这通</span></div></div></summary>
      <div style="padding:2px 12px 10px">${inner}</div></details>`;}).join('');
  const tab=(k,l)=>`<span onclick="_clTab='${k}';render()" style="padding:4px 14px;border-radius:14px;cursor:pointer;${_clTab===k?'background:#07c160;color:#fff':'color:#999'}">${l}</span>`;
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">通话记录</span><span class="r" onclick="clClear('${id}')" style="color:#fa5151;font-size:13px">清空</span></div>
   <div style="padding:8px;background:#1c1c1e;display:flex;gap:8px;justify-content:center;border-bottom:.5px solid #2a2a2c">${tab('all','全部')}${tab('voice','语音')}${tab('video','视频')}</div>
   <div style="padding:6px 10px;text-align:right;background:#111"><button class="minibtn" onclick="clClearOld('${id}')">删掉一天前的${_clTab==='voice'?'语音':_clTab==='video'?'视频':''}</button></div>
   <div class="scroll" id="cllog" style="background:#000">
   <div class="hint">每通电话单独一框，内容默认折叠，点标题展开。点「回放/导出」可按时间点选择内容；已有声音直接回放且不重复扣点。旧记录没有声音时，也可以选择TA说话的时间点重新生成。</div>
   ${html||'<div class="empty" style="padding:40px">还没有通话记录</div>'}<div style="height:20px"></div></div>`;}
function clEdit(id,mid){const m=msgs(id).find(x=>x.id===mid);if(!m)return;
  openModal(`<h3>编辑这句</h3><div class="field"><textarea id="cl_t" rows="3">${esc(m.content||'')}</textarea></div>
   <div class="hint">编辑后原声音与文字不再一致，因此会移除这一句的回放声音，避免声音和字幕对不上。</div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="clSaveEdit('${id}','${mid}')">保存</button></div>`);}
function clSaveEdit(id,mid){const m=msgs(id).find(x=>x.id===mid),v=$('#cl_t');if(m&&v&&m.content!==v.value){m.content=v.value;if(m._callTranslationOf){const p=msgs(id).find(x=>x.id===m._callTranslationOf);if(p)p._callTrans=v.value;}else callReplayClearAudio(m);}save();closeModal();clKeep(()=>{});}
function clToggle(el){const key=el&&el.dataset&&el.dataset.clKey;if(key)_clOpen[key]=!!el.open;}
function clKeep(fn){const e=$('#cllog');if(e)e.querySelectorAll('details[data-cl-key]').forEach(x=>clToggle(x));const top=e?e.scrollTop:0,bottom=e?Math.max(0,e.scrollHeight-e.scrollTop-e.clientHeight):0,atBottom=!!(e&&bottom<80);fn();render();const restore=()=>{const el=$('#cllog');if(!el)return;el.scrollTop=atBottom?Math.max(0,el.scrollHeight-el.clientHeight-bottom):Math.min(top,Math.max(0,el.scrollHeight-el.clientHeight));};restore();requestAnimationFrame(()=>{restore();requestAnimationFrame(restore);});}
function clDel(id,mid){const arr=msgs(id);const i=arr.findIndex(x=>x.id===mid);if(i<0)return;clKeep(()=>{callReplayClearAudio(arr[i]);if(arr[i]&&arr[i]._call&&arr[i].audio)clearVoiceAudio(arr[i]);arr.splice(i,1);save();});}
async function clDelSession(id,cs){if(!await uiConfirm('删除这一整通通话记录？'))return;clKeep(()=>{S.messages[mkey(id)]=msgs(id).filter(m=>{const del=m._call&&(m._cs||'')===cs;if(del){callReplayClearAudio(m);if(m.audio)clearVoiceAudio(m);}return !del;});save();});toast('已删这通');}
async function clClear(id){const sc=_clTab==='voice'?'语音':_clTab==='video'?'视频':'全部';if(!await uiConfirm('清空和ta的'+sc+'通话记录？\n（只删这一类的通话内容，不动文字聊天和记忆）'))return;
  S.messages[mkey(id)]=msgs(id).filter(m=>{if(!m._call)return true;const k=m._ck==='video'?'video':'voice',del=_clTab==='all'||k===_clTab;if(del){callReplayClearAudio(m);if(m.audio)clearVoiceAudio(m);}return !del;});save();render();toast(sc+'通话记录已清空');}
async function clClearOld(id){const sc=_clTab==='voice'?'语音':_clTab==='video'?'视频':'';const cut=Date.now()-86400000;
  if(!await uiConfirm('删掉一天前的'+sc+'通话记录？（只删这类、且超过24小时的）'))return;
  let n=0;S.messages[mkey(id)]=msgs(id).filter(m=>{if(!m._call)return true;if(m.time&&m.time>=cut)return true;if(_clTab!=='all'){const k=m._ck==='video'?'video':'voice';if(k!==_clTab)return true;}callReplayClearAudio(m);if(m.audio)clearVoiceAudio(m);n++;return false;});
  save();render();toast(n?'已删掉'+n+'条一天前的记录':'没有一天前的记录');}
