let _off=null;
function offData(id){S.offline=S.offline&&typeof S.offline==='object'&&!Array.isArray(S.offline)?S.offline:{};let o=S.offline[id];if(!o||typeof o!=='object'||Array.isArray(o))o=S.offline[id]={};o.loc=typeof o.loc==='string'?o.loc:'';o.when=typeof o.when==='string'?o.when:'';o.msgs=Array.isArray(o.msgs)?o.msgs:[];o.memory=Array.isArray(o.memory)?o.memory:[];o.history=Array.isArray(o.history)?o.history:[];o.started=!!o.started;o.daypart=typeof o.daypart==='string'?o.daypart:'';return o;}
function cohabRoot(){S.cohabitation=S.cohabitation&&typeof S.cohabitation==='object'&&!Array.isArray(S.cohabitation)?S.cohabitation:{};const r=S.cohabitation;r.homes=r.homes&&typeof r.homes==='object'&&!Array.isArray(r.homes)?r.homes:{};if(typeof r.enabled!=='boolean')r.enabled=false;if(typeof r.paused!=='boolean')r.paused=!r.enabled;return r;}
function cohabDefaultCid(){const r=cohabRoot(),valid=id=>id&&getC(id)&&!getC(id).deleted;if(valid(r.cid))return r.cid;const couple=S.couple&&valid(S.couple.cid)&&S.couple.cid,first=(S.contacts||[]).find(c=>c&&!c.deleted&&!c.blocked);r.cid=couple||first&&first.id||'';return r.cid;}
function cohabRepairRows(rows,kind,base){if(!Array.isArray(rows))return[];return rows.map((row,index)=>{if(typeof row==='string'||typeof row==='number')row={text:String(row)};if(!row||typeof row!=='object'||Array.isArray(row))return null;row.text=String(row.text==null?'':row.text).trim();if(!row.text)return null;if(!row.id)row.id=uid();if(!Number.isFinite(+row.time)||+row.time<=0)row.time=base+index;if(kind==='message'&&!['me','ta','旁白','日期'].includes(row.who))row.who=row.role==='user'?'me':row.role==='assistant'?'ta':'旁白';if(kind==='summary'){row.ts=Math.max(1,+row.ts||+row.time||base+index);row.imp=Math.max(1,Math.min(5,+row.imp||3));row.rounds=Math.max(1,+row.rounds||1);row.mode=row.mode==='split'?'split':'single';}return row;}).filter(Boolean);}
function cohabData(id){const r=cohabRoot();id=id||cohabDefaultCid();if(!id)return null;let d=r.homes[id];if(!d||typeof d!=='object'||Array.isArray(d))d=r.homes[id]={};const legacyBase=Math.max(1,+d.startedAt||+d.phaseAt||Date.now()-Math.max(1000,(Array.isArray(d.msgs)?d.msgs.length:0)+100));d.msgs=cohabRepairRows(d.msgs,'message',legacyBase);d.notices=cohabRepairRows(d.notices,'notice',legacyBase);d.summaries=cohabRepairRows(d.summaries,'summary',legacyBase);d.summarySeq=Math.max(0,+d.summarySeq||0);d.summaryRetryAt=Math.max(0,+d.summaryRetryAt||0);d.msgSeq=Math.max(0,+d.msgSeq||0);d.msgs.forEach((m,index)=>{if(!(+m.cohabSeq>0))m.cohabSeq=++d.msgSeq;else d.msgSeq=Math.max(d.msgSeq,+m.cohabSeq);if(!Number.isFinite(+m.time)||+m.time<=0)m.time=legacyBase+index;});d.phase=['home','work','returning','away','together-away'].includes(d.phase)?d.phase:'home';d.activity=cohabActivityClean(d.activity)||cohabPhaseDefaultActivity(d.phase);d.place=cohabPlaceClean(d.place)||(d.phase==='home'&&/^在/.test(d.activity)?cohabPlaceClean(d.activity):'');d.placeAt=Math.max(0,+d.placeAt||0);d.phaseAt=+d.phaseAt||Date.now();d.startedAt=+d.startedAt||Date.now();d.nextAt=+d.nextAt||0;d.nextPhase=['home','work','returning','away','together-away'].includes(d.nextPhase)?d.nextPhase:'';d.unreadReturn=!!d.unreadReturn;d.returnedAt=+d.returnedAt||0;d.phoneInspectDueAt=Math.max(0,+d.phoneInspectDueAt||0);if(d.phoneInspection&&Date.now()-(+d.phoneInspection.at||0)>120000)d.phoneInspection=null;if(d.pendingArrival&&typeof d.pendingArrival!=='object')d.pendingArrival=null;cohabSettings(d);return d;}
function cohabSettings(d){d=d&&typeof d==='object'?d:{};const x=d.settings&&typeof d.settings==='object'&&!Array.isArray(d.settings)?d.settings:d.settings={},apiRoutes=['follow','0','1','2','3'];x.contextLimit=Math.max(10,Math.min(80,Math.round(+x.contextLimit||+(S.settings&&S.settings.offHist)||30)));x.summaryRounds=x.summaryRounds===0?0:Math.max(1,Math.min(40,Math.round(+x.summaryRounds||6)));x.summaryMemoryLimit=Math.max(1,Math.min(20,Math.round(+x.summaryMemoryLimit||8)));x.summaryMode=['single','split'].includes(x.summaryMode)?x.summaryMode:(S.settings&&S.settings.offSummaryMode==='single'?'single':'split');x.replyModel=['role','main','aux'].includes(x.replyModel)?x.replyModel:(['role','main','aux'].includes(x.replyRoute)?x.replyRoute:'role');x.replyApiRoute=apiRoutes.includes(String(x.replyApiRoute))?String(x.replyApiRoute):'follow';x.summaryModel=['reply','main','aux'].includes(x.summaryModel)?x.summaryModel:(['reply','main','aux'].includes(x.summaryRoute)?x.summaryRoute:(S.settings&&S.settings.offSummaryModel==='aux'?'aux':'main'));x.summaryApiRoute=['reply',...apiRoutes].includes(String(x.summaryApiRoute))?String(x.summaryApiRoute):'reply';return x;}
function cohabContextLimit(d){return cohabSettings(d).contextLimit;}
function cohabSummaryRoundLimit(d){return cohabSettings(d).summaryRounds;}
function cohabSummaryMemoryLimit(d){return cohabSettings(d).summaryMemoryLimit;}
function cohabSummaryMode(d){return cohabSettings(d).summaryMode;}
function cohabModelLabel(model){return({role:'跟随角色模型',reply:'跟随对话模型',main:'主模型',aux:'副模型'})[model]||'跟随角色模型';}
function cohabApiRouteLabel(route){if(route==='reply')return'跟随对话路线';if(route==='follow')return'跟随微信路线';const i=parseInt(route,10);return Number.isInteger(i)&&CHAT_ROUTE_NAMES[i]?CHAT_ROUTE_NAMES[i]:'跟随微信路线';}
function cohabReplyAux(c,d){const model=cohabSettings(d).replyModel;return model==='aux'||model==='role'&&c.model==='aux';}
function cohabReplyRouteIndex(d){const route=cohabSettings(d).replyApiRoute;return route==='follow'?null:parseInt(route,10);}
function cohabSummaryAux(c,d){const model=cohabSettings(d).summaryModel;if(model==='reply')return cohabReplyAux(c,d);return model==='aux';}
function cohabSummaryRouteIndex(d){const x=cohabSettings(d),route=x.summaryApiRoute;if(route==='reply')return cohabReplyRouteIndex(d);return route==='follow'?null:parseInt(route,10);}
function cohabSettingsBrief(d){const x=cohabSettings(d);return x.contextLimit+'条 · '+(x.summaryRounds?x.summaryRounds+'轮总结':'总结关闭')+' · '+cohabModelLabel(x.replyModel)+' / '+cohabApiRouteLabel(x.replyApiRoute);}
function cohabSettingSet(id,key,value,el){const d=cohabData(id);if(!d)return;const x=cohabSettings(d);if(key==='contextLimit')x.contextLimit=Math.max(10,Math.min(80,Math.round(+value||30)));else if(key==='summaryRounds')x.summaryRounds=Math.max(0,Math.min(40,Math.round(+value||0)));else if(key==='summaryMemoryLimit')x.summaryMemoryLimit=Math.max(1,Math.min(20,Math.round(+value||8)));else if(key==='summaryMode'&&['single','split'].includes(value))x.summaryMode=value;else if(key==='replyModel'&&['role','main','aux'].includes(value))x.replyModel=value;else if(key==='replyApiRoute'&&['follow','0','1','2','3'].includes(String(value)))x.replyApiRoute=String(value);else if(key==='summaryModel'&&['reply','main','aux'].includes(value))x.summaryModel=value;else if(key==='summaryApiRoute'&&['reply','follow','0','1','2','3'].includes(String(value)))x.summaryApiRoute=String(value);else return;if(el&&/Limit|Rounds/.test(key))el.value=x[key];const brief=document.getElementById('cohab-settings-brief');if(brief)brief.textContent=cohabSettingsBrief(d);save();}
function cohabMemoryKey(x){return encodeURIComponent([x&&x.id||'',+((x&&x.ts)||0),String(x&&x.text||'').slice(0,80)].join('|'));}
function cohabMemoryEnsureIds(d){let changed=false;(d&&d.summaries||[]).forEach(x=>{if(x&&typeof x==='object'&&!x.id){x.id=uid();changed=true;}});return changed;}
function cohabMemoryFindIndex(d,key){key=String(key||'');return(d&&d.summaries||[]).findIndex(x=>String(x&&x.id||'')===key||cohabMemoryKey(x)===key);}
function cohabMemoryScrollTop(){const sheet=$('#modalSheet');return sheet?sheet.scrollTop:0;}
function cohabMemoryRestoreScroll(top){top=Math.max(0,+top||0);const restore=()=>{const sheet=$('#modalSheet');if(sheet)sheet.scrollTop=Math.min(top,Math.max(0,sheet.scrollHeight-sheet.clientHeight));};restore();requestAnimationFrame(()=>{restore();requestAnimationFrame(restore);});}
function cohabMemorySetImp(id,key,n){const d=cohabData(id),i=cohabMemoryFindIndex(d,key);if(!d||i<0)return;n=Math.max(1,Math.min(5,parseInt(n,10)||3));const top=cohabMemoryScrollTop();d.summaries[i].imp=n;save();cohabMemoryOpen(id,{scrollTop:top});toast('已设为 '+n+' 星');}
function cohabMemoryPrune(d,cap){cap=Math.max(1,+cap||60);const rows=d&&d.summaries||[];while(rows.length>cap){const i=rows.findIndex(x=>(+x.imp||3)<5);if(i<0)break;rows.splice(i,1);}return rows;}
async function cohabMemoryDelete(id,key){const d=cohabData(id);if(!d||cohabMemoryFindIndex(d,key)<0)return;const top=cohabMemoryScrollTop();if(!await uiConfirm('删除这条共同生活记忆？\n\n只删除这条总结，不会删除共同生活原聊天。'))return;const i=cohabMemoryFindIndex(d,key);if(i<0){toast('这条记忆已经不存在');return;}d.summaries.splice(i,1);save();cohabMemoryOpen(id,{scrollTop:top});toast('共同生活记忆已删除');}
async function cohabMemoryClear(id){const d=cohabData(id);if(!d||!d.summaries||!d.summaries.length)return;if(!await uiConfirm('清空全部共同生活记忆？\n\n只清空共同生活总结，不会删除原聊天、微信或单次线下约会。'))return;d.summaries=[];save();cohabMemoryOpen(id);toast('共同生活记忆已清空');}
function cohabMemoryOpen(id,opt){const d=cohabData(id),c=getC(id);if(!d||!c)return;if(cohabMemoryEnsureIds(d))save(0);const items=(d.summaries||[]).slice().sort((a,b)=>(+b.ts||0)-(+a.ts||0)),stars=(x,key)=>{const n=Math.max(1,Math.min(5,+x.imp||3));return `<div role="group" aria-label="共同生活记忆重要度" style="display:flex;gap:2px;margin:0 0 5px">${[1,2,3,4,5].map(v=>`<button type="button" aria-label="设为${v}星" title="设为${v}星" data-cid="${esc(id)}" data-mid="${esc(key)}" onclick="cohabMemorySetImp(this.dataset.cid,this.dataset.mid,${v})" style="padding:0 1px;border:0;background:transparent;color:${v<=n?'#f5b301':'#777'};font-size:16px;line-height:1;cursor:pointer">${v<=n?'★':'☆'}</button>`).join('')}</div>`;};openModal(`<h3>共同生活记忆</h3><div class="hint" style="line-height:1.75">这里只有共同生活自己的总结，不会复制到微信记忆列表，也不会写入原来的单次线下约会。开启线上/线下同步时，微信与共同生活里的${esc(c.remark||c.name)}只会按当前话题临时读取这里的相关记忆。点星星可设 1–5 星；高星记忆会优先参与回忆，5 星不会被容量清理。</div><div class="cohab-memory-list" data-cohab-memory-list>${items.length?items.map(x=>{const key=String(x.id);return `<article data-cohab-memory-id="${esc(key)}"><div style="display:flex;align-items:flex-start;gap:8px"><div style="flex:1;min-width:0">${stars(x,key)}<time>${esc(offDateTime(x.ts))} · ${Math.max(1,+x.rounds||1)}轮 · ${x.mode==='split'?'分段':'整段'}</time><p>${esc(x.text||'')}</p></div><button type="button" aria-label="删除共同生活记忆" data-cid="${esc(id)}" data-mid="${esc(key)}" onclick="cohabMemoryDelete(this.dataset.cid,this.dataset.mid)" style="width:34px;height:34px;flex:none;border-radius:10px;border:1px solid rgba(250,81,81,.28);background:rgba(250,81,81,.09);color:#ff7474;cursor:pointer;font-size:18px">×</button></div></article>`;}).join(''):'<div class="empty" style="padding:28px 8px">还没有生成共同生活记忆</div>'}</div><div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">关闭</button>${items.length?`<button class="btn d" data-cid="${esc(id)}" onclick="cohabMemoryClear(this.dataset.cid)">清空记忆</button>`:''}<button class="btn p" data-cid="${esc(id)}" onclick="closeModal();cohabSummarizeNow(this.dataset.cid)">立即总结</button></div>`);if(opt&&Number.isFinite(+opt.scrollTop))cohabMemoryRestoreScroll(opt.scrollTop);}
function cohabPushMessage(d,m){if(!d||!m)return m;d.msgSeq=Math.max(0,+d.msgSeq||0)+1;m.cohabSeq=d.msgSeq;if(!Number.isFinite(+m.time))m.time=Date.now();d.msgs.push(m);const root=S.cohabitation&&S.cohabitation.homes||{},id=Object.keys(root).find(k=>root[k]===d);if(id&&m.who!=='日期')roleServerPushTouchSoon(id,m.time);return m;}
function cohabPushNotice(d,text,opt){if(!d||!String(text||'').trim())return null;opt=opt||{};d.notices=Array.isArray(d.notices)?d.notices:[];const key=String(opt.key||''),old=key&&d.notices.find(x=>x&&x.key===key);if(old)return old;const item={id:uid(),kind:opt.kind||'system',key,time:Number.isFinite(+opt.time)?+opt.time:Date.now(),text:String(text).replace(/\s+/g,' ').trim().slice(0,260),tripId:String(opt.tripId||'')};d.notices.push(item);d.notices=d.notices.slice(-60);return item;}
function cohabTripRows(c){return(S.travel&&Array.isArray(S.travel.trips)?S.travel.trips:[]).filter(x=>x&&x.cohab&&x.cid===c.id).sort((a,b)=>(+a.departAt||+a.ts||0)-(+b.departAt||+b.ts||0));}
function cohabTripContext(c,d){if(!c)return'';const rows=cohabTripRows(c).slice(-8);if(!rows.length)return'';const now=Date.now(),lines=rows.map(tr=>{const when=fmtDT(+tr.departAt||+tr.ts||now),route=(tr.from||'共同住处')+'→'+(tr.to||'目的地'),flight=tr.no?('，航班 '+tr.no):'';if(tr.status==='upcoming')return '· 已订双人行程：'+route+'，'+when+'出发'+flight+'。还没有出发。';if(tr.status==='traveling')return '· 双人行程进行中：已于 '+when+' 从'+(tr.from||'共同住处')+'出发前往'+tr.to+flight+'。';if(tr.status==='done')return '· 已完成的双人旅行：'+when+'从'+(tr.from||'共同住处')+'出发，去过「'+tr.to+'」'+flight+'。';return '· 已取消的双人行程：'+route+'，原定 '+when+flight+'。';});return '\n\n# 共同生活双人行程（云程后台真实订单）\n'+lines.join('\n')+'\n这些订单没有发到微信，也不是角色气泡；但你本人知道订了什么、何时出发、去过哪里。未到出发时间绝不能说已经出发，到点后必须承认状态已经推进。';}
function cohabTripDateAt(dateRaw,timeRaw,now){now=+now||Date.now();const raw=String(dateRaw||'').trim(),tm=String(timeRaw||'').trim().match(/^([01]\d|2[0-3]):([0-5]\d)$/);if(!tm)return null;let y,m,d,explicitYear=false,hit=raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);if(hit){explicitYear=true;y=+hit[1];m=+hit[2];d=+hit[3];}else{hit=raw.match(/^(\d{1,2})\s*月\s*(\d{1,2})\s*日?$/);if(!hit)return null;const base=new Date(now);y=base.getFullYear();m=+hit[1];d=+hit[2];}const make=year=>new Date(year,m-1,d,+tm[1],+tm[2],0,0),valid=x=>x.getFullYear()===y&&x.getMonth()===m-1&&x.getDate()===d;let at=make(y);if(!valid(at))return null;if(!explicitYear&&at.getTime()<now-60000){y++;at=make(y);if(!valid(at))return null;}const value=at.getTime();if(value<now-60000||value>now+366*86400000)return null;return{date:y+'-'+tvP2(m)+'-'+tvP2(d),dep:tm[1]+':'+tm[2],departAt:value};}
function cohabTripPlan(c,to,dateRaw,timeRaw,now){to=String(to||'').replace(/[\[\]【】|｜]/g,'').trim().slice(0,40);if(!c||!to)return{error:'目的地不完整'};if(S.settings&&S.settings.timeAware===false)return{error:'时间感知已关闭，不能创建准点行程'};const from=meHomeCity()||charHomeCity(c)||'苏州';if(tvSameCity(from,to))return{error:'出发地和目的地相同'};const dt=cohabTripDateAt(dateRaw,timeRaw,now);if(!dt)return{error:'日期或出发时间无效'};const seed=(dt.date+'|'+dt.dep+'|'+from+'|'+to+'|'+c.id).split('').reduce((s,ch)=>s+ch.charCodeAt(0),0),intl=tvCity(from).i||tvCity(to).i,durationHours=intl?8+Math.abs(seed)%7:1+Math.abs(seed)%3,price=tvPrice(from,to,'economy')*2;return{from,to,date:dt.date,dep:dt.dep,departAt:dt.departAt,arriveAt:dt.departAt+durationHours*3600000,durationHours,no:tvFlightNo(seed),price};}
function cohabExtractTravelTags(text,c,opt){opt=opt||{};let out=String(text||''),plans=[],errors=[],matched=0,blocked=0,consume=(to,date,time)=>{matched++;if(!opt.allow){blocked++;return'';}const plan=cohabTripPlan(c,to,date,time,opt.now||Date.now());if(plan.error)errors.push(plan.error);else plans.push(plan);return'';};out=out.replace(/\[(?:共同生活|同居)(?:双人)?订票\s*[|｜:：]\s*([^\]|｜】]+)\s*[|｜]\s*([^\]|｜】]+)\s*[|｜]\s*([^\]】]+)[\]】]/g,(_,to,date,time)=>consume(to,date,time));out=out.replace(/\[(?:双人)?订票\s*[|｜:：]\s*([^\]|｜】]+)\s*[|｜]\s*([^\]|｜】]+)\s*[|｜]\s*([^\]】]+)[\]】]/g,(_,to,date,time)=>consume(to,date,time));out=out.replace(/\[(?:双人)?订票\s*[|｜:：]\s*([^\]|｜】]+)\s*[|｜]\s*([^\]】]+)[\]】]/g,()=>{matched++;if(opt.allow)errors.push('缺少准确出发时间');else blocked++;return'';});return{text:out.replace(/\n{3,}/g,'\n\n').trim(),plans,errors,matched,blocked};}
function cohabCommitTripPlans(c,plans){if(!c||!plans||!plans.length)return[];tvInit();const made=[];for(const plan of plans){const duplicate=S.travel.trips.find(x=>x&&x.cohab&&x.cid===c.id&&x.to===plan.to&&+x.departAt===+plan.departAt&&/^(?:upcoming|traveling)$/.test(x.status||''));if(duplicate)continue;const trip={id:uid(),cid:c.id,from:plan.from,to:plan.to,date:plan.date,ret:'',cls:'economy',pax:2,by:'ta',meet:true,flier:'both',payer:'ta',no:plan.no,dep:plan.dep,arr:hm(plan.arriveAt),price:plan.price,status:'upcoming',ts:Date.now(),cohab:true,departAt:plan.departAt,arriveAt:plan.arriveAt};if(c.wallet!=null)c.wallet=Math.max(0,(+c.wallet||0)-plan.price);S.travel.trips.push(trip);made.push(trip);}if(made.length)save();return made;}
function cohabTripBookedNotice(tr){return '已购买 '+tr.no+' '+tr.from+'→'+tr.to+' 双人机票 · '+fmtDT(tr.departAt)+' 出发';}
function cohabTravelAdvance(id,d,now){const root=S.cohabitation;if(!root||!root.enabled||root.paused||root.cid!==id)return false;d=d||cohabData(id);now=+now||Date.now();if(!d||!S.travel||!Array.isArray(S.travel.trips))return false;let changed=false;for(const tr of S.travel.trips){if(!tr||!tr.cohab||tr.cid!==id||!['upcoming','traveling'].includes(tr.status))continue;if(tr.status==='upcoming'&&+tr.departAt<=now){tr.status='traveling';tr.departedAt=+tr.departAt||now;d.phase='together-away';d.activity='搭乘 '+tr.no+' 前往'+tr.to;d.place=(tr.from?tr.from+'→':'')+tr.to+'途中';d.placeAt=tr.departedAt;d.phaseAt=tr.departedAt;d.stateSource='cohab-trip';d.nextAt=0;d.nextPhase='';cohabPushNotice(d,'已到出发时间 · 已搭乘 '+tr.no+' 从'+tr.from+'出发前往'+tr.to,{kind:'trip-departure',key:'trip-departure:'+tr.id,time:tr.departedAt,tripId:tr.id});changed=true;}if(tr.status==='traveling'&&+tr.arriveAt<=now){tr.status='done';tr.arrivedAt=+tr.arriveAt||now;d.phase='together-away';d.activity='在'+tr.to+'旅行';d.place=tr.to;d.placeAt=tr.arrivedAt;d.phaseAt=tr.arrivedAt;d.stateSource='cohab-trip';tvAddStamp(S.travel,tr.to,tr.cid,tr.date);cohabPushNotice(d,tr.no+' 已抵达 '+tr.to+' · 双人旅行开始',{kind:'trip-arrival',key:'trip-arrival:'+tr.id,time:tr.arrivedAt,tripId:tr.id});changed=true;}}return changed;}
const _cohabSummaryBusy=new Set();
function cohabSummaryRows(d){return(d&&d.msgs||[]).filter(m=>m&&+m.cohabSeq>(+d.summarySeq||0)&&m.who!=='日期'&&String(m.text||'').trim());}
function cohabSummaryCompletedRounds(rows){let waiting=false,n=0;(rows||[]).forEach(m=>{const mine=m.who==='me'||m.who==='旁白'&&m.source==='me',theirs=m.who==='ta'||m.who==='旁白'&&m.source!=='me';if(mine)waiting=true;else if(theirs&&waiting){n++;waiting=false;}});return n;}
function cohabSummaryTranscript(rows,c){const call=offSummaryUserCall(c);return(rows||[]).map(m=>{const who=m.who==='me'?call:m.who==='旁白'?'现场旁白（只供理解，不得照抄成记忆）':'我';return who+'：'+String(m.text||'').replace(/\s+/g,' ').trim();}).join('\n');}
function cohabSummaryValid(text){text=String(text||'');return Array.from(text).length>=40&&text.includes('我')&&!/[【】]/.test(text)&&!/旁白|剧本|动作描写|镜头/.test(text);}
function cohabSummaryItems(raw,mode){if(mode==='single'){const text=trimSentence(cleanReply(raw),420);return cohabSummaryValid(text)?[{text,imp:4}]:[];}let data=null,s=String(raw||'');try{const object=s.match(/\{[\s\S]*\}/),array=s.match(/\[[\s\S]*\]/);data=JSON.parse(object?object[0]:array?array[0]:'null');}catch(_){}const list=Array.isArray(data)?data:Array.isArray(data&&data.items)?data.items:[];return list.map(x=>({text:trimSentence(cleanReply(x&&x.text||''),260),imp:Math.max(1,Math.min(5,+x.imp||+x.importance||3))})).filter(x=>cohabSummaryValid(x.text)).slice(0,8);}
function cohabMemoryPrompt(d,query){const limit=cohabSummaryMemoryLimit(d),picked=offlinePickRelevant(d&&d.summaries||[],query,Math.min(3,limit),limit,x=>x&&x.text||'').sort((a,b)=>(+b.imp||3)-(+a.imp||3)||(+a.ts||0)-(+b.ts||0));return picked.length?'\n\n# 共同生活已经自动整理的旧记忆（角色第一人称，只是过去背景；星级越高越重要）\n'+picked.map(x=>'· '+Math.max(1,Math.min(5,+x.imp||3))+'星｜'+x.text).join('\n')+'\n这些是过去几轮的生活记忆，不是当前仍在发生的动作或台词；当前现场只接下面的新消息。':'';}
async function cohabSummarize(id,d,opt){d=d||cohabData(id);opt=opt||{};const c=getC(id),rows=cohabSummaryRows(d),roundLimit=cohabSummaryRoundLimit(d),rounds=cohabSummaryCompletedRounds(rows);if(!d||!c||!rows.length||_cohabSummaryBusy.has(id)||!opt.force&&(!roundLimit||Date.now()<d.summaryRetryAt||rounds<roundLimit))return 0;const targetSeq=Math.max(...rows.map(m=>+m.cohabSeq||0)),transcript=cohabSummaryTranscript(rows,c),rule=offSummaryPerspectiveRule(c),aux=cohabSummaryAux(c,d),routeIndex=cohabSummaryRouteIndex(d),mode=cohabSummaryMode(d),split=mode==='split',format=split?'按不同的重要事件拆成1到8条独立记忆；内容少时宁可只有1条，也不重复、不凑数。每条60到180个中文字。只输出JSON对象：{"items":[{"text":"第一人称记忆","importance":1到5}]}，不要Markdown或解释。':'写成一整段80到300个中文字，只输出正文，不要标题、列表、括号或格式说明。',messages=[{role:'system',content:'你就是「'+(c.remark||c.name)+'」本人。把下面共同生活的新内容整理成可长期记住的生活记忆。只记录真正新增的重要事实、双方说清楚的话、约定、情绪或关系变化；普通起身、走路、坐下、拿东西、环境和姿势等动作描写不要写进记忆。'+rule+format},{role:'user',content:transcript}];_cohabSummaryBusy.add(id);try{let raw=await chatAPI(messages,{aux,routeIndex,max:split?1500:620,temp:.2,complete:true,allowSessionModel:true}),items=cohabSummaryItems(raw,mode);if(!items.length){raw=await chatAPI([...messages,{role:'assistant',content:raw||''},{role:'user',content:split?'上一版JSON、视角或内容不合格。严格按指定JSON返回1到8条角色第一人称记忆；内容少就只写1条，删除第三人称旁白、普通动作流水账和原文没有的事。':'上一版视角或格式不合格。严格改成角色第一人称“我”的一整段生活记忆，删除第三人称旁白、普通动作流水账和原文没有的事。'}],{aux,routeIndex,max:split?1500:620,temp:.08,complete:true,allowSessionModel:true});items=cohabSummaryItems(raw,mode);}if(!items.length)throw new Error('共同生活总结格式不合格');const batchId=uid(),now=Date.now();items.forEach(x=>d.summaries.push({id:uid(),batchId,ts:now,fromSeq:+rows[0].cohabSeq||0,toSeq:targetSeq,rounds:Math.max(1,rounds),mode,text:x.text,imp:x.imp}));cohabMemoryPrune(d,60);d.summarySeq=targetSeq;d.summaryRetryAt=0;await saveNowAsync();return items.length;}catch(_){d.summaryRetryAt=Date.now()+5*60000;save();return 0;}finally{_cohabSummaryBusy.delete(id);}}
function cohabMaybeSummarize(id,d){return cohabSummarize(id,d,{force:false});}
async function cohabSummarizeNow(id){const d=cohabData(id);if(!d)return;if(_cohabSummaryBusy.has(id)){toast('共同生活正在总结，请稍等');return;}if(!cohabSummaryRows(d).length){toast('上次总结后还没有新的共同生活内容');return;}toast(cohabSummaryMode(d)==='split'?'正在拆分共同生活重点…':'正在整理共同生活整段记忆…');const n=await cohabSummarize(id,d,{force:true});if(n){toast('共同生活记忆已保存');cohabMemoryOpen(id);}else toast('总结暂时没有生成，原聊天没有丢失');}
function cohabSceneActive(){return !!(_off&&_off.mode==='cohab'&&typeof cur==='function'&&cur().p==='off');}
function offSceneData(id){return _off&&_off.mode==='cohab'?cohabData(id):offData(id);}
function cohabPhaseLabel(phase){return({home:'在家',work:'上班中',returning:'回家路上',away:'外出中','together-away':'一起外出'})[phase]||'在家';}
