function cohabApplyOnlineMessageTags(text,c,outcome){let out=String(text||''),delivered=0;out=out.replace(/\[(?:共同生活发消息|线下发消息)\s*[|｜:：]\s*([^\]|｜】]*)\s*[|｜]\s*([^\]】]+)[\]】]/g,(_,rawTarget,body)=>{const target=cohabResolveOnlineMessageTarget(rawTarget,c),ok=!!(target&&cohabDeliverOnlineMessage(c,target,body));if(ok)delivered++;roleInterceptDiagnosticAction(outcome,ok);return'';});return{text:out.replace(/\n{3,}/g,'\n\n').trim(),delivered};}
