function cohabApplyScheduleTags(text,c,opt){opt=opt||{};let out=String(text||''),changed=false,leaveChanged=false,scheduleChanged=false;if(!c)return{text:out,changed};const ensure=()=>{const old=c.sched||{};c.sched=Object.assign({on:true,work:'公司',home:'家',amS:'08:00',amE:'12:00',pmS:'14:00',pmE:'18:00',leaves:[]},old);if(!Array.isArray(c.sched.leaves))c.sched.leaves=[];return c.sched;};out=out.replace(/\[(?:共同生活|同居)请假\s*[|｜:：]\s*(\d{4}-\d{2}-\d{2})\s*[|｜]\s*(\d{4}-\d{2}-\d{2})(?:\s*[|｜]\s*([^\]】]*))?\s*[\]】]/g,(_,start,end,reason)=>{const days=scheduleLeaveDays(start,end);if(!days||days>366)return'';const sc=ensure(),item={id:uid(),start,end,reason:String(reason||'').trim().slice(0,40),source:opt.source||'role',createdAt:Date.now()},same=sc.leaves.find(x=>x&&x.start===start&&x.end===end);if(same)Object.assign(same,item,{id:same.id||item.id});else sc.leaves.push(item);sc.on=true;delete c._currentActivity;changed=leaveChanged=true;return'';});out=out.replace(/\[(?:共同生活|同居)(?:销假|取消请假)\s*[|｜:：]\s*(\d{4}-\d{2}-\d{2})\s*[|｜]\s*(\d{4}-\d{2}-\d{2})\s*[\]】]/g,(_,start,end)=>{if(!scheduleLeaveDays(start,end))return'';const sc=ensure(),before=sc.leaves.length;sc.leaves=sc.leaves.filter(x=>!x||x.end<start||x.start>end);if(sc.leaves.length!==before){delete c._currentActivity;changed=leaveChanged=true;}return'';});out=out.replace(/\[(?:共同生活|同居)作息\s*[|｜:：]\s*(\d{2}:\d{2})\s*[|｜]\s*(\d{2}:\d{2})\s*[|｜]\s*(\d{2}:\d{2})\s*[|｜]\s*(\d{2}:\d{2})\s*[\]】]/g,(_,amS,amE,pmS,pmE)=>{const v=[amS,amE,pmS,pmE].map(toMin);if(v.some((n,i)=>n<0||n>=24*60||!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test([amS,amE,pmS,pmE][i]))||!(v[0]<v[1]&&v[1]<=v[2]&&v[2]<v[3]))return'';const sc=ensure();Object.assign(sc,{on:true,amS,amE,pmS,pmE});delete c._currentActivity;changed=scheduleChanged=true;return'';});if(changed&&opt.persist!==false)save();return{text:out.replace(/\n{3,}/g,'\n\n').trim(),changed,leaveChanged,scheduleChanged};}
