function cohabSetPhase(id,phase,minutes,opt){const d=cohabData(id);if(!d)return;opt=opt||{};phase=['home','work','returning','away','together-away'].includes(phase)?phase:'home';const prev=d.phase,activity=cohabActivityClean(opt.activity),placeHint=opt.place||(((phase==='home'&&/^在/.test(activity))||phase==='together-away')?activity:''),place=cohabPlaceClean(placeHint);d.phase=phase;d.activity=activity||cohabPhaseDefaultActivity(phase);d.phaseAt=Date.now();d.nextAt=0;d.nextPhase='';d.stateSource=opt.source||'manual';if(d.stateSource==='owner-manual'){const c=getC(id),spec=c?activitySpec(c,new Date(d.phaseAt)):null;d.scheduleSlotKey=spec&&spec.key||d.scheduleSlotKey||'';}if(phase==='work'){d.nextAt=d.phaseAt+Math.max(15,+minutes||480)*60000;d.nextPhase='returning';}else if(phase==='returning'){d.nextAt=d.phaseAt+Math.max(5,+minutes||30)*60000;d.nextPhase='home';}else if(phase==='home'){if(place||prev!=='home'){d.place=place||'玄关';d.placeAt=d.phaseAt;d.placeSource=d.stateSource;}if(prev!=='home'&&prev!=='together-away'){d.returnedAt=d.phaseAt;d.unreadReturn=true;}}else if(phase==='together-away'){d.place=place;d.placeAt=d.phaseAt;d.placeSource=d.stateSource;}if(!opt.silent){const c=getC(id),name=c&&(c.remark||c.name)||'TA';toast(phase==='home'&&prev!=='home'&&prev!=='together-away'?name+'回来了':'状态已切换为“'+cohabStatusLabel(d)+'”');}save();if(typeof roleServerPushSyncSoon==='function')roleServerPushSyncSoon(id);if(cohabSceneActive())render();}
