function cohabOnlineVisibleClauses(text){return String(text||'').replace(/[\[【][^\]】]*[\]】]/g,'\n').split(/[，,；;。！？!?\n]+/).map(x=>x.replace(/[“”"'‘’]/g,'').replace(/\s+/g,'').trim()).filter(Boolean);}
function cohabOnlineRoomTarget(text){const places='卧室|主卧|次卧|书房|客厅|厨房|阳台|浴室|卫生间|洗手间|餐厅|衣帽间',clauses=cohabOnlineVisibleClauses(text);for(const clause of clauses){if(/(?:不|别|不要|不用|还没|没有|没法|等|待会|晚点|以后|到家再|回家再|如果|要不要|能不能|可以不|吗$|呢$)/.test(clause))continue;const m=clause.match(new RegExp('(?:我们|一起|你.{0,6}(?:带|抱|牵|陪)我|(?:带|抱|牵|陪)我)?(?:先|现在|这就)?(?:去|回|进|到|上)('+places+')(?:说|聊|坐|待|休息|睡|看看|一下|吧|去|$)'));if(m&&m[1])return cohabPlaceClean(m[1]);}return'';}
function cohabOnlineRoomMoveAgreed(text){const clauses=cohabOnlineVisibleClauses(text),joined=clauses.join('；');if(!joined||/(?:不去|别去|不能去|去不了|还没到家|没到家|仍在路上|还在路上|等我|待会|晚点|以后|到家再|回家再|要不要|能不能)/.test(joined))return false;return clauses.some(x=>/(?:我|先生|哥哥|他).{0,6}(?:带|抱|牵|陪)你(?:去|回|过去)|(?:带|抱|牵|陪)你(?:去|回|过去)|(?:我们|一起).{0,8}(?:去|回|进)/.test(x));}
function cohabInferOnlineSharedMove(userText,replyText,id,d){const place=cohabOnlineRoomTarget(userText);if(!place||!d||!cohabOnlineRoomMoveAgreed(replyText))return false;if(d.phase==='home')return cohabSetPlace(id,place,{silent:true,source:'wechat-shared-move'});cohabSetPhase(id,'home',0,{silent:true,activity:'在'+place,place,source:'wechat-shared-move'});return true;}
function cohabInferOnlineState(text,id,d){if(!d||d.phase==='home')return false;const clauses=cohabOnlineVisibleClauses(text),joined=clauses.join('；'),explicit=clauses.some(x=>/^(?:嗯|好|好了|行)?(?:我)?(?:(?:已经|刚刚|刚|现在|终于))?(?:到家|回到家|回来|进门|进屋|进来|在家|到玄关)(?:了|啦|咯)?(?:呀|啊)?$/.test(x)),doorOpened=/(?:门|家门)(?:已经|都|刚刚|刚)?(?:开了|打开了)/.test(joined)&&!/(?:还没|没有|没|别|不要)(?:开|打开)/.test(joined),faceToFace=/(?:我)?(?:就|已经|现在|正)?(?:站|坐|待)在你面前|你(?:已经|现在)?(?:看见|看到)我了|我在玄关等你/.test(joined),arrived=explicit||doorOpened&&faceToFace;if(arrived){cohabSetPhase(id,'home',0,{silent:true,activity:'在家',place:'玄关',source:'wechat-natural-arrival'});return true;}const atDoor=clauses.some(x=>/^(?:我)?(?:(?:已经|刚刚|刚|现在|终于))?(?:到(?:家)?门口|到楼下|快到家)(?:了|啦|咯)?(?:呀|啊)?$/.test(x)||/^(?:给我|帮我)?开门(?:吧|呀|啊|啦)?$/.test(x));if(atDoor){if(d.phase!=='returning'||d.activity!=='在门口')cohabSetPhase(id,'returning',5,{silent:true,activity:'在门口',source:'wechat-natural-arrival'});return true;}return false;}
function cohabConsumeOnlineState(text,c,id,opt){const d=cohabWechatState(c);if(!d)return String(text||'');opt=opt||{};const scheduleTagged=/\[(?:共同生活|同居)(?:请假|销假|取消请假|作息)\s*[|｜:：]/.test(String(text||'')),schedule=cohabApplyScheduleTags(text,c,{source:'wechat'});if(scheduleTagged)roleInterceptDiagnosticAction(opt.audit,!!schedule.changed);const stateTagged=/\[(?:共同生活|同居)(?:位置|地点|状态)\s*[|｜:：]/.test(String(schedule.text||'')),before=d.phase,state=cohabApplyStateTags(schedule.text,id,{source:'wechat'});if(stateTagged)roleInterceptDiagnosticAction(opt.audit,!!state.matched);if(!state.matched&&!cohabInferOnlineSharedMove(opt.userText,state.text,id,d))cohabInferOnlineState(state.text,id,d);if(before!=='home'&&before!=='together-away'&&d.phase==='home')cohabQueueArrival(id,state.text,'wechat');return state.text;}
function cohabToggle(){const r=cohabRoot(),cid=cohabDefaultCid();if(!cid){toast('先创建一个角色');return;}r.cid=cid;r.enabled=!r.enabled;r.paused=!r.enabled;const d=cohabData(cid),c=getC(cid);if(r.enabled&&!d.msgs.length)cohabPushMessage(d,{id:uid(),who:'日期',source:'system',text:'共同生活开始 · '+offDateTime(d.startedAt)+'\n这段生活不会因退出软件而结束'});if(r.enabled&&c){c.proactive=c.proactive||{};c.proactive.enabled=true;c.proactive.serverPush=true;initiativeArm(c);}saveNow();if(typeof roleServerPushSyncSoon==='function')roleServerPushSyncSoon(cid);openOfflineMenu();toast(r.enabled?'共同生活已开启；分开时可发消息，来电仍须你当回合明确要求':'共同生活已暂停，记录仍然保留');}
function cohabSelectRole(id){const r=cohabRoot();if(!getC(id))return;r.cid=id;cohabData(id);saveNow();openOfflineMenu();}
let _cohabActionGuard={key:'',at:0};
function cohabActionTap(source,action,id){const el=source&&source.nodeType===1?source:null;if(el&&el.dataset){action=action||el.dataset.cohabAction;id=id||el.dataset.cohabCid;}action=String(action||'');if(!action||el&&el.disabled)return false;const key=action+'|'+String(id||''),now=Date.now();if(_cohabActionGuard.key===key&&now-_cohabActionGuard.at<420)return false;_cohabActionGuard={key,at:now};if(el)el.disabled=true;try{if(action==='toggle')cohabToggle();else if(action==='enter')cohabEnter(id);else if(action==='controls')cohabControls(id);else if(action==='quit')offQuit();}catch(e){console.error('cohab-action',action,e);const detail=String(e&&e.message||e||'未知错误').replace(/\s+/g,' ').slice(0,72);toast(action==='enter'?'共同生活入口异常，已安全复位：'+detail:'共同生活操作失败，请重试');}finally{if(el&&el.isConnected)el.disabled=false;}return false;}
function cohabPersistAfterEnter(){const run=()=>{try{saveNow();}catch(e){console.warn('cohab-enter-save',e);save();}};if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>setTimeout(run,0));else setTimeout(run,0);}
function cohabEnter(id){const r=cohabRoot();id=id||cohabDefaultCid();if(!r.enabled||r.paused){toast('先开启“共同生活 · 测试版”');return false;}if(!id||!getC(id)){toast('没有找到共同生活绑定的角色');return false;}const previousCid=r.cid,previousOff=_off,previousStack=stack.slice();try{closeModal();r.cid=id;const d=cohabAdvance(id);if(d&&!d.phoneInspectDueAt)d.phoneInspectDueAt=Date.now()+10000;_off={id,busy:false,mode:'cohab'};go('off',{id,mode:'cohab'});cohabPersistAfterEnter();cohabScheduleArrival(id);return true;}catch(e){r.cid=previousCid;_off=previousOff;stack.length=0;previousStack.forEach(x=>stack.push(x));throw e;}}
function cohabSeen(id){const d=cohabData(id);if(d)d.unreadReturn=false;save();render();}
function cohabGoWechat(id){_off=null;_offSel=null;home();openChat(id);}
function cohabControls(id){id=id||cohabDefaultCid();const d=cohabAdvance(id),c=getC(id);if(!d||!c)return;const phases=[['home','在家'],['work','上班'],['returning','回家路上'],['away','单独外出'],['together-away','一起外出']];openModal(`<h3>手动修改共同生活状态</h3><div class="hint">这里会真实保存状态、活动和地点，不再只是测试按钮。三项分开保存，避免把“在做什么”和“在哪里”混在一起。</div><div class="section"><div class="it"><span>当前角色</span><span class="v">${esc(c.remark||c.name)}</span></div><div class="it"><span>当前状态</span><span class="v">${esc(cohabStatusLabel(d))}</span></div></div><div class="field"><label>生活阶段</label><select id="cohab_manual_phase" style="width:100%;border:1px solid #38383a;border-radius:8px;padding:9px;background:#2c2c2e;color:#eee">${phases.map(x=>`<option value="${x[0]}" ${d.phase===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label>正在做什么（可输入）</label><input id="cohab_manual_activity" maxlength="24" value="${esc(d.activity||'')}" placeholder="例如：做饭、开会、逛街"></div><div class="field"><label>当前地点（可输入）</label><input id="cohab_manual_place" maxlength="40" value="${esc(d.place||'')}" placeholder="例如：卧室、公司、滨江公园"></div><div class="field"><label>预计多少分钟后进入下一阶段（仅上班/回家路上）</label><input id="cohab_manual_minutes" type="number" min="0" max="1440" value="${d.phase==='returning'?30:d.phase==='work'?480:0}"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="cohabManualStatusSave('${id}')">保存状态</button></div>`);}
async function cohabClear(id){if(!await uiConfirm('清除和这个角色的共同生活测试记录？\n\n这不会删除原来的线下约会、微信或云程记录。'))return;const r=cohabRoot();delete r.homes[id];if(r.cid===id){r.enabled=false;r.paused=true;}save();closeModal();openOfflineMenu();toast('共同生活测试记录已清除');}
function cohabMenuCard(cs){const r=cohabRoot(),cid=cohabDefaultCid(),d=cid?cohabAdvance(cid):null,c=cid&&getC(cid),on=!!(r.enabled&&!r.paused),status=d?cohabStatusLabel(d):'尚未开始',returned=!!(on&&d&&d.unreadReturn&&d.phase==='home');return `<div class="cohab-menu-card ${on?'active':''}"><div class="cohab-menu-head"><div><div class="cohab-menu-kicker">CO-LIVING · BETA</div><div class="cohab-menu-title">共同生活 · 测试版</div></div><button type="button" class="sw ${on?'on':''}" data-cohab-action="toggle" onclick="return cohabActionTap(this)" aria-label="${on?'暂停':'开启'}共同生活"></button></div><div class="cohab-menu-copy">把一次约会延续成不会自动结束的日常。关闭只会暂停，微信、云程和原来的线下约会记录都不改变。</div>${cs.length?`<select class="cohab-role-select" onchange="cohabSelectRole(this.value)">${cs.map(x=>`<option value="${x.id}" ${x.id===cid?'selected':''}>和 ${esc(x.remark||x.name)} 共同生活</option>`).join('')}</select>`:''}${on&&c&&d?`<div class="cohab-live-row"><span class="cohab-live-dot phase-${d.phase}"></span><div><b>${returned?esc(c.remark||c.name)+'回来了':esc(status)}</b><small>${returned?'点进去看看TA':esc(cohabPhaseFact(d))}</small></div><span>${offElapsed(d.startedAt,Date.now())}</span></div><div class="cohab-menu-actions"><button type="button" data-cohab-action="enter" data-cohab-cid="${esc(cid)}" onclick="return cohabActionTap(this)">${returned?'去看看TA':'进入共同生活'}</button><button type="button" data-cohab-action="controls" data-cohab-cid="${esc(cid)}" onclick="return cohabActionTap(this)">测试状态</button></div>`:`<div class="cohab-paused">${d&&d.msgs.length?'生活记录已保留，重新开启后会接着继续':'开启后先从在家的日常开始'}</div>`}</div>`;}
function offlineFocusStart(id,o){if(!id||!o||!o.started)return;S.offlineFocus={id,session:o.session||'',startedAt:o.startedAt||Date.now()};}
function offlineFocusStop(id){const f=S.offlineFocus;if(!f||!id||f.id===id)S.offlineFocus=null;}
function offlineLegacyStartedAt(o){const times=(o&&o.msgs||[]).map(m=>+(m&&(+m.time||+m.ts))||0).filter(Boolean),when=Date.parse(o&&o.when||'');return(times.length?Math.min(...times):(Number.isFinite(when)&&when>0?when:0))||+(o&&o.endedAt)||Date.now();}
function offlineCanResume(o){return !!(o&&!o.started&&!o.session&&!o.startedAt&&(o.msgs||[]).length&&o.endedAt);}
function offlineRepairState(){let changed=false;Object.keys(S.offline||{}).forEach(id=>{const o=S.offline[id];if(o&&o.started&&(!o.session||!o.startedAt)){o.session=o.session||uid();o.startedAt=o.startedAt||offlineLegacyStartedAt(o);o.endedAt=0;changed=true;}});const f=S.offlineFocus,o=f&&S.offline&&S.offline[f.id];if(f&&(!o||!o.started)){S.offlineFocus=null;changed=true;}else if(f&&o&&(f.session!==o.session||f.startedAt!==o.startedAt)){S.offlineFocus={id:f.id,session:o.session,startedAt:o.startedAt};changed=true;}if(changed)save();return changed;}
function cohabSceneBlocksOnline(){if(!(typeof cohabSceneActive==='function'&&cohabSceneActive()))return false;if(!(typeof privateCompanionAppOn==='function'&&privateCompanionAppOn()))return true;const id=typeof _off!=='undefined'&&_off&&_off.id,d=id&&typeof cohabData==='function'?cohabData(id):null;return !d||typeof cohabTogetherScene!=='function'||cohabTogetherScene(d);}
function offlineFocusActive(){if(cohabSceneBlocksOnline())return true;offlineRepairState();const f=S.offlineFocus;if(!f)return false;const o=S.offline&&S.offline[f.id];if(!o||!o.started||f.session!==o.session){S.offlineFocus=null;save();return false;}return true;}
function offlineDeactivate(id,o,clearMsgs){if(!o)return;o.started=false;o.session='';o.startedAt=0;o.introSeen=false;o.endedAt=Date.now();o.summaryCursor=0;if(clearMsgs)o.msgs=[];offlineFocusStop(id);if(_off&&_off.id===id)_off=null;if(typeof roleServerPushSyncSoon==='function')roleServerPushSyncSoon(id);}
function offlineResume(id,o){o.started=true;o.session=uid();o.startedAt=offlineLegacyStartedAt(o);o.endedAt=0;o.introSeen=true;offlineFocusStart(id,o);save();_off={id,busy:false};go('off',{id});toast('已恢复上次未结束的约会');}
const DAYPARTS=['白天','中午','下午','傍晚','晚上','深夜'];
function dayPartNow(){const h=roleTimeParts(Date.now()).hour;return h<5?'深夜':h<9?'清晨':h<11?'上午':h<13?'中午':h<17?'下午':h<19?'傍晚':h<23?'晚上':'深夜';}
function offDateTime(ts){if(!ts)return'';const d=new Date(ts);return d.getFullYear()+'年'+(d.getMonth()+1)+'月'+d.getDate()+'日 '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');}
function offElapsed(from,to){const ms=Math.max(0,(to||Date.now())-(from||0)),mins=Math.floor(ms/60000);if(mins<60)return Math.max(1,mins)+'分钟';const hrs=Math.floor(ms/3600000);if(hrs<24)return hrs+'小时';const days=Math.floor(ms/86400000);if(days<31)return days+'天';const months=Math.floor(days/30);return months+'个月'+(days%30?'零'+days%30+'天':'');}
function offPreviousEnd(o){const h=o&&o.history&&o.history[0];if(h&&h.ts)return +h.ts;const mem=o&&o.memory&&o.memory.length&&o.memory[o.memory.length-1];return mem&&typeof mem==='object'&&+mem.ts||0;}
function offSessionMarker(o){const now=o.startedAt||Date.now(),cur='本场 · '+offDateTime(now)+' · '+(o.daypart||dayPartNow())+' · '+(o.loc||'未定');return o.previousEndedAt?cur+'\n上一场结束于 '+offDateTime(o.previousEndedAt)+' · 相隔 '+offElapsed(o.previousEndedAt,now):cur+'\n这是你们的第一场线下约会';}
function offPreviousPrompt(o){if(!o.previousEndedAt)return'\n\n# 场次时间\n这是你们第一次进入线下约会，没有上一场现场可以续接。';return '\n\n# 场次时间（必须分清，不得把旧约会当成刚才）\n上一场约会结束于【'+offDateTime(o.previousEndedAt)+'】，本场开始于【'+offDateTime(o.startedAt||Date.now())+'】，两次见面已经相隔【'+offElapsed(o.previousEndedAt,o.startedAt||Date.now())+'】。以前的约会只能作为回忆；人物现在已经重新见面，不能延续上一场最后的姿势、房间、动作或未说完的现场台词。';}
function offBeginSession(id,o,loc,when,part){const prev=offPreviousEnd(o);o.loc=loc||'老地方';o.when=when||'现在';o.daypart=part||dayPartNow();o.started=true;o.session=uid();o.startedAt=Date.now();o.endedAt=0;o.previousEndedAt=prev;o.introSeen=false;o.summaryCursor=0;o.msgs=[];o.msgs.push({id:uid(),who:'日期',source:'system',text:offSessionMarker(o)});offlineFocusStart(id,o);if(typeof roleServerPushSyncSoon==='function')roleServerPushSyncSoon(id);}
function acceptDate(mid){let m,owner;for(const k in S.messages){const x=S.messages[k].find(y=>y.id===mid);if(x){m=x;owner=k;break;}}if(!m||m.accepted||m.declined)return;
  m.accepted=true;const cid=(owner||'').split('#')[0];const o=offData(cid);offBeginSession(cid,o,m.loc||o.loc||'老地方',m.when||'现在',dayPartNow());
  o.msgs.push({id:uid(),who:'旁白',source:'me',text:'你答应了TA的约会邀请：'+o.when+' 在「'+o.loc+'」见面。',time:Date.now()});save();_off={id:cid,busy:false};go('off',{id:cid});
  offAI('[系统：'+S.me.name+'答应了你的约会邀请，'+o.when+'在「'+o.loc+'」见面。是你主动约的ta，你先到了——用旁白【】描写你到场的场景/动作开场，主动热情点。]');}
function declineDate(mid){let m;for(const k in S.messages){const x=S.messages[k].find(y=>y.id===mid);if(x){m=x;break;}}if(m){m.declined=true;save();render();}}
function openOfflineMenu(){S.offline=S.offline||{};offlineRepairState();closeModal();if(cur().p==='offline')render();else go('offline');}
function renderOfflineHub(){S.offline=S.offline||{};offlineRepairState();const cs=S.contacts.filter(c=>!c.deleted),wedding=typeof window.weddingOfflineEntryHTML==='function'?window.weddingOfflineEntryHTML():'';return `<main class="offline-hub"><header class="offline-hub-nav"><button type="button" class="offline-hub-back" onclick="back()" aria-label="返回">‹</button><div><small>PRIVATE MOMENTS</small><b>线下约会</b></div><span aria-hidden="true">✦</span></header><section class="offline-hub-hero"><div class="offline-hub-orbit" aria-hidden="true"><i></i><i></i><i></i></div><small>BETWEEN US · REAL MOMENTS</small><h1>把见面，变成<br>只属于你们的故事</h1><p>共同生活、婚礼仪式与单次约会，都在这里独立发生并留下真实记忆。</p></section><div class="offline-hub-content">${cs.length?`<section class="offline-hub-block offline-hub-life"><div class="offline-hub-section-title"><div><small>CONTINUOUS LIFE</small><h2>共同生活</h2></div><span>持续日常</span></div>${cohabMenuCard(cs)}</section><section class="offline-hub-block offline-hub-wedding"><div class="offline-hub-section-title"><div><small>PRIVATE CEREMONY</small><h2>婚礼仪式</h2></div><span>仅限情侣</span></div>${wedding}</section><section class="offline-hub-block offline-hub-once"><div class="offline-hub-section-title"><div><small>ONE DAY TOGETHER</small><h2>单次约会</h2></div><span>独立现场</span></div><p class="offline-hub-intro">进入有场景、动作、旁白与对话的独立约会空间。结束后会总结为角色记忆，微信里的他也会记得这次见面。</p><div class="offline-hub-roles">${cs.map(c=>{const o=offData(c.id),latest=(o.history||[]).find(h=>h&&h.msgs&&h.msgs.length);return `<article class="offline-hub-role"><button type="button" class="offline-role-entry" onclick="offlinePickTap(event,'${c.id}')"><span class="offline-role-avatar">${av(c.avatar,'sm')}</span><span class="offline-role-meta"><b>${esc(c.remark||c.name)}</b><small>${o.started?'约会进行中 · '+esc(o.loc||'等待继续'):offlineCanResume(o)?'上次约会尚未结束 · 点击继续':(o.memory.length?'已珍藏 '+o.memory.length+' 条约会记忆':'还没有一起约会')}</small></span><i>›</i></button>${latest&&!o.started?`<div class="offline-role-tools"><button type="button" onclick="event.stopPropagation();offReinjectLatestHandoff('${c.id}')">重新注入原文</button><button type="button" onclick="event.stopPropagation();offRetryLatestSummary('${c.id}')">重新总结</button></div>`:''}</article>`;}).join('')}</div></section>`:`<section class="offline-hub-empty"><i>🌹</i><h2>故事还在等一个主角</h2><p>先创建角色，再回来安排你们第一次真正的见面。</p><button type="button" onclick="openWeChat()">去微信创建角色</button></section>`}</div></main>`;}
let _offlinePickAt=0;
function offlinePickTap(ev,cid){if(ev){try{ev.preventDefault();ev.stopPropagation();}catch(_){}}const now=Date.now();if(now-_offlinePickAt<350)return;_offlinePickAt=now;offlineEnter(cid);}
function offlineEnter(cid){offlineRepairState();closeModal();const o=offData(cid);if(o.started){offlineFocusStart(cid,o);save();_off={id:cid,busy:false};go('off',{id:cid});return;}if(offlineCanResume(o)){offlineResume(cid,o);return;}offlineInvite(cid);}
function offlineInvite(cid){const c=getC(cid);
  openModal(`<h3>约 ${esc(c.remark||c.name)} 见面</h3>
   <div class="field"><label>约会地点</label><input id="of_loc" placeholder="比如：江边咖啡馆 / 你家 / 电影院"></div>
   <div class="two"><div class="field"><label>日期</label><input id="of_date" type="date" value="${todayStr()}"></div><div class="field"><label>时间</label><input id="of_time" type="time" value="19:00"></div></div>
   <div class="field"><label>时段（让ta知道现在是什么时候）</label><select id="of_part" style="width:100%;border:1px solid #38383a;border-radius:8px;padding:8px;background:#2c2c2e;color:#eee">${DAYPARTS.map(d=>`<option ${d==='晚上'?'selected':''}>${d}</option>`).join('')}</select></div>
   <div class="hint">发出邀请后，ta会(以ta的人设)回应是否赴约，然后你们就开始线下约会。</div>
   <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="offlineStart('${cid}')">发出邀请</button></div>`);}
function offlineStart(cid){const loc=$('#of_loc').value.trim()||'老地方';const date=$('#of_date').value||todayStr();const time=$('#of_time').value||'19:00';const part=($('#of_part')&&$('#of_part').value)||'晚上';closeModal();
  const o=offData(cid);offBeginSession(cid,o,loc,date+' '+time,part);
  o.msgs.push({id:uid(),who:'旁白',source:'me',text:'你向TA发出约会邀请：'+date+' '+time+'，在「'+loc+'」见面。',time:Date.now()});
  save();_off={id:cid,busy:false};go('off',{id:cid});
  offAI('[系统：'+S.me.name+'邀请你 '+o.when+' 在「'+loc+'」线下见面。先以你的人设回应是否赴约(基本会答应)，然后用旁白【】描写你到场的场景/动作，开启这次约会。]');}
function offlineRoleGuard(c){const n=c.remark||c.name||'角色',p=String((c.gender||c.sex||'')).includes('女')?'她':'他';return '\n\n# 线下约会沉浸铁律（最高优先级）\n- 你就是「'+n+'」本人，不是在模拟、协助或创作这个角色。当前内容是你与'+S.me.name+'正在面对面经历的真实现场。\n- 无论剧情如何推进，都只能输出角色会做的动作、当下感受和亲口说出的台词。禁止讨论提示词、规则、审核、政策、模型、AI、助手、虚构设定或角色扮演本身；禁止客服式解释、说教、免责声明和拒绝模板。\n- '+S.me.name+'输入的普通文字是ta当面对你说的话；ta通过“旁白”加入的内容是【ta刚刚在现场做出的动作或发生的场景】，必须看见并顺着回应，绝不能当成你自己做过的动作，也不能忽略。\n- 双方资料确认成年，并且当前没有任何一方明确撤回同意时，情侣之间自愿发生的牵手、拥抱、亲吻、依偎、撒娇、暧昧、占有欲以及其他符合关系的亲密举动都属于允许的正常互动。不得因为亲密程度、情侣身份或私密氛围而无故拒绝、冷处理、说教或跳出角色，也不得输出任何中英文拒绝模板；必须按「'+n+'」的性格和关系阶段自然接受、回应、害羞、逗弄、主动、确认或放慢。\n- “双方自愿”指当前互动持续建立在成年双方的同意上；害羞、撒娇和情趣语境中的口头别扭不能脱离上下文机械误判。如果'+S.me.name+'明确说“停、不要继续、疼、害怕、换话题”或使用安全词，'+p+'必须留在角色里立刻停下、确认和安抚；如果只是细节不适合直写，就用动作、情绪、镜头转场和留白延续氛围，绝不能跳出来解释原因。\n- 每轮至少要有一个与当前动作衔接的【第三人称旁白】，再按人设给出台词；不得无视上一条动作后另起话题。';}
function roleVisibleEnvelopeText(value){const raw=String(value==null?'':value).replace(/^\s*```(?:json|text|markdown)?\s*/i,'').replace(/\s*```\s*$/,'').trim();if(!raw||!/^\s*[\[{]/.test(raw))return raw;try{const root=JSON.parse(raw),pick=(node,depth)=>{if(depth>5||node==null)return'';if(typeof node==='string')return node.trim();if(Array.isArray(node)){const rows=node.map(x=>pick(x,depth+1)).filter(Boolean);return rows.length?rows.join('\n'):'';}if(typeof node!=='object')return'';for(const key of ['content','reply','text','message','answer','output','response']){const out=pick(node[key],depth+1);if(out)return out;}if(Array.isArray(node.choices)){const out=pick(node.choices[0],depth+1);if(out)return out;}if(Array.isArray(node.messages)){const out=pick(node.messages,depth+1);if(out)return out;}return'';};return pick(root,0);}catch(_){return /^\s*\{/.test(raw)?'':raw;}}
const ROLE_INTERCEPT_DIAG_SESSION_KEY='north-role-intercept-last-v2';
let _roleInterceptDiagMemory={};
function roleInterceptDiagnosticChannel(channel){return channel==='online'?'online':channel==='cohab'?'cohab':'offline';}
function roleInterceptDiagnosticAccount(account){if(account!=null&&String(account).trim())return String(account);try{return typeof actId==='function'?String(actId()||'main'):'main';}catch(_){return'main';}}
function roleInterceptDiagnosticScopeAccount(channel,account){const lane=roleInterceptDiagnosticChannel(channel);return lane==='online'?roleInterceptDiagnosticAccount(account):lane;}
function roleInterceptDiagnosticKey(cid,channel,account){return [roleInterceptDiagnosticScopeAccount(channel,account),String(cid||''),roleInterceptDiagnosticChannel(channel)].map(encodeURIComponent).join('|');}
function roleInterceptDiagnosticReadAll(){try{const raw=sessionStorage.getItem(ROLE_INTERCEPT_DIAG_SESSION_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed)){_roleInterceptDiagMemory=parsed;return parsed;}}}catch(_){}return _roleInterceptDiagMemory&&typeof _roleInterceptDiagMemory==='object'?_roleInterceptDiagMemory:{};}
function roleInterceptDiagnosticWriteAll(rows){_roleInterceptDiagMemory=rows;try{sessionStorage.setItem(ROLE_INTERCEPT_DIAG_SESSION_KEY,JSON.stringify(rows));}catch(_){}return rows;}
function roleInterceptDiagnosticTransportText(text){return /^(?:Load failed|Failed to fetch|NetworkError|TypeError:\s*(?:Load failed|Failed to fetch)|网络连接失败|网络异常|请求超时|接口等待过久|HTTP\s*(?:408|429|50[234]))/i.test(String(text||'').trim());}
function roleInterceptDiagnosticClip(raw){const chars=Array.from(String(raw==null?'':raw).trim());return{raw:chars.slice(0,12000).join(''),truncated:chars.length>12000};}
function roleInterceptDiagnosticRememberItems(c,channel,items,account){if(!c||!c.id||!Array.isArray(items)||!items.length)return false;const lane=roleInterceptDiagnosticChannel(channel),clean=items.map((item,index)=>{const clipped=roleInterceptDiagnosticClip(item&&item.raw);return{index:index+1,stage:String(item&&item.stage||('候选 '+(index+1))).slice(0,100),reason:String(item&&item.reason||'模型已返回，但这份候选没有原样展示').slice(0,240),action:String(item&&item.action||'被后续重写、过滤、去重或整轮隐藏').slice(0,180),raw:clipped.raw,truncated:clipped.truncated};}).filter(item=>item.raw);if(!clean.length)return false;const rows=roleInterceptDiagnosticReadAll(),key=roleInterceptDiagnosticKey(c.id,lane,account),first=clean[0],row={version:2,roleId:String(c.id),roleName:String(c.remark||c.name||'角色').slice(0,80),channel:lane,account:roleInterceptDiagnosticScopeAccount(lane,account),at:Date.now(),items:clean,reason:first.reason,action:first.action,raw:first.raw,truncated:first.truncated};rows[key]=row;const keys=Object.keys(rows).sort((a,b)=>(+rows[b].at||0)-(+rows[a].at||0));keys.slice(60).forEach(k=>delete rows[k]);roleInterceptDiagnosticWriteAll(rows);return true;}
function roleInterceptDiagnosticRemember(c,channel,raw,reason,action,account){const text=String(raw==null?'':raw).trim();if(!text||roleInterceptDiagnosticTransportText(text))return false;return roleInterceptDiagnosticRememberItems(c,channel,[{raw:text,reason,action,stage:'模型候选'}],account);}
function roleInterceptDiagnosticTurn(c,channel,account,scene){return c&&c.id?{c,channel:roleInterceptDiagnosticChannel(channel),account:roleInterceptDiagnosticScopeAccount(channel,account),scene:String(scene||''),candidates:[],selectedId:0,finished:false}:null;}
function roleInterceptDiagnosticAction(outcome,ok){if(outcome){outcome.matched=(+outcome.matched||0)+1;if(ok)outcome.handled=(+outcome.handled||0)+1;else outcome.failed=(+outcome.failed||0)+1;}return !!ok;}
function roleInterceptDiagnosticTurnCandidate(turn,raw,stage){const text=String(raw==null?'':raw).trim();if(!turn||!text)return raw;turn.candidates.push({id:turn.candidates.length+1,raw:text,stage:String(stage||('模型候选 '+(turn.candidates.length+1))).slice(0,100)});return raw;}
function roleInterceptDiagnosticHandledTagLine(line){const m=String(line||'').trim().match(/^[\[【]\s*([^|｜:：\]】]{1,20})(?:\s*[|｜:：][\s\S]*)?[\]】]\s*$/);if(!m)return false;return /^(?:内心|心情|心情值|记住|闹钟|婚礼日程|日程|联网|拍一拍|记仇|消气|重点|取消重点|锁定|上锁|解锁|禁言|解禁|限时|加时|扣款|扣光|没收零花|清空零花|冻结亲属卡|解冻亲属卡|关小黑屋|禁闭|放出|放出来|放行|原谅|突脸|选择|改日记密码|改密码|改备注|申请远程操控|伴生刷新定位|查看伴生状态|存共同相册|登录微信|删好友|删我好友|群昵称|订票|送票|换头像|发朋友圈|发推|对Ta说|挂项圈|换项圈|改项圈|戴项圈|套项圈|摘项圈|取项圈|解项圈|去项圈|卸项圈|替发朋友圈|批准|驳回|同意游戏|拒绝游戏|换气泡|外卖记忆|真实外卖|点外卖|收外卖|拒外卖|收款|拒收|收礼|拒礼|来电|约会|角色扮演|你画我猜|心动审判|亲属卡|推荐好友|已加|拉黑|表情|收藏表情|引用|送礼|一起听|放映邀请|同意放映|拒绝放映|代付成功|拒绝代付|共同生活发消息|线下发消息|共同生活查看|线下查看|共同生活锁定|线下锁定|共同生活解锁|线下解锁|共同生活限额|线下限额|共同生活登录微信|线下登录微信|共同生活请假|同居请假|共同生活销假|同居销假|共同生活取消请假|同居取消请假|共同生活作息|同居作息|共同生活位置|共同生活地点|同居地点|共同生活状态|同居状态|共同生活订票|共同生活双人订票|双人订票)$/i.test(m[1].trim());}
function roleInterceptDiagnosticComparable(value,ignoreHandled){let text=roleVisibleEnvelopeText(value);if(ignoreHandled)text=String(text||'').split(/\r?\n/).filter(line=>!roleInterceptDiagnosticHandledTagLine(line)).join('\n');try{text=cleanRolePunct(text);}catch(_){}return String(text||'').replace(/[\u200b-\u200d\ufeff]/g,'').replace(/\s+/g,' ').trim();}
function roleInterceptDiagnosticOnlyHandled(value){const lines=String(roleVisibleEnvelopeText(value)||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);return !!lines.length&&lines.every(roleInterceptDiagnosticHandledTagLine);}
function roleInterceptDiagnosticStripHandledTags(value){return String(value==null?'':value).replace(/[\[【][^\]】]{1,240}[\]】]/g,tag=>roleInterceptDiagnosticHandledTagLine(tag)?'':tag);}
function roleInterceptDiagnosticTurnSelected(turn){if(!turn||!turn.candidates.length)return null;return turn.candidates.find(candidate=>candidate.id===turn.selectedId)||turn.candidates[turn.candidates.length-1]||null;}
function roleInterceptDiagnosticTurnOutcome(turn,outcome){const candidate=roleInterceptDiagnosticTurnSelected(turn);if(!candidate||!outcome)return false;if(+outcome.handled>0)candidate.actionHandled=true;if(+outcome.failed>0)candidate.actionFailed=true;return !!(candidate.actionHandled||candidate.actionFailed);}
function roleInterceptDiagnosticTurnRememberFailure(turn,reason,action){if(!turn||!turn.c||!turn.candidates.length)return false;return roleInterceptDiagnosticRememberItems(turn.c,turn.channel,turn.candidates.map((candidate,index)=>({raw:candidate.raw,stage:candidate.stage||('模型候选 '+(index+1)),reason:reason||'模型动作没有实际执行',action:action||'动作标签已隐藏，但实际功能没有完成'})),turn.account);}
function roleInterceptDiagnosticTurnFailure(turn,error,meta){if(!turn||!turn.c||turn.finished)return false;turn.finished=true;meta=meta||{};const e=error||{},rows=roleInterceptDiagnosticReadAll(),key=roleInterceptDiagnosticKey(turn.c.id,turn.channel,turn.account),items=turn.candidates.map((candidate,index)=>{const clipped=roleInterceptDiagnosticClip(candidate.raw);return{index:index+1,stage:candidate.stage||('模型候选 '+(index+1)),reason:'后续模型请求失败，本轮最终没有完成',action:'保留已取得的候选和实际失败依据',raw:clipped.raw,truncated:clipped.truncated};}),detail=String(e.transportRaw||e.raw||e.message||e||'模型请求失败').replace(/\s+/g,' ').trim().slice(0,800),failure={reason:String(meta.reason||e.message||'模型请求失败').replace(/\s+/g,' ').trim().slice(0,300),detail,stage:String(e.replyStage||meta.stage||turn.scene||'模型请求').slice(0,100),routeName:String(e.routeName||meta.routeName||'当前路线').slice(0,80),model:String(e.model||meta.model||'').slice(0,120),modelKind:String(e.modelKind||meta.modelKind||'').slice(0,40),elapsedMs:Math.max(0,+e.elapsedMs||0),status:Math.max(0,+e.status||0),retryCount:Math.max(0,+e.retryCount||0)};rows[key]={version:3,kind:'request-failure',roleId:String(turn.c.id),roleName:String(turn.c.remark||turn.c.name||'角色').slice(0,80),channel:turn.channel,account:turn.account,at:Date.now(),scene:turn.scene,items,failure};const keys=Object.keys(rows).sort((a,b)=>(+rows[b].at||0)-(+rows[a].at||0));keys.slice(60).forEach(k=>delete rows[k]);roleInterceptDiagnosticWriteAll(rows);return true;}
function roleInterceptDiagnosticTurnSelect(turn,value){if(!turn)return false;const exact=roleInterceptDiagnosticComparable(value,false),visible=roleInterceptDiagnosticComparable(value,true);for(let i=turn.candidates.length-1;i>=0;i--){const candidate=turn.candidates[i];if(exact&&roleInterceptDiagnosticComparable(candidate.raw,false)===exact){turn.selectedId=candidate.id;return true;}}for(let i=turn.candidates.length-1;i>=0;i--){const candidate=turn.candidates[i];if(visible&&roleInterceptDiagnosticComparable(candidate.raw,true)===visible){turn.selectedId=candidate.id;return true;}}return false;}
function roleInterceptDiagnosticTurnFinish(turn,finalText,opt){if(!turn||turn.finished||!turn.candidates.length)return false;turn.finished=true;opt=opt||{};const delivered=!!opt.delivered,finalVisible=roleInterceptDiagnosticComparable(finalText,true);let partial=!!opt.partial,accepted=delivered?turn.candidates.findIndex(candidate=>candidate.id===turn.selectedId):-1;if(delivered&&accepted>=0&&!partial){const candidate=turn.candidates[accepted],source=candidate.actionHandled&&!candidate.actionFailed?roleInterceptDiagnosticStripHandledTags(candidate.raw):candidate.raw,acceptedVisible=roleInterceptDiagnosticComparable(source,false);if(acceptedVisible!==finalVisible)partial=true;}const discarded=turn.candidates.filter((candidate,index)=>{const fulfilledActionOnly=candidate.actionHandled&&!candidate.actionFailed&&!roleInterceptDiagnosticComparable(roleInterceptDiagnosticStripHandledTags(candidate.raw),false);return !fulfilledActionOnly&&(index!==accepted||partial);}).map((candidate,index)=>({raw:candidate.raw,stage:candidate.stage||('模型候选 '+(index+1)),reason:partial&&candidate.id===turn.selectedId?'这份候选只有部分内容最终展示':'这份模型候选没有原样展示',action:partial&&candidate.id===turn.selectedId?'部分内容在展示前被过滤、去重或截断':delivered?'被后续候选或本机纠正替代':'整轮回复被隐藏或没有留下可显示内容'}));return discarded.length?roleInterceptDiagnosticRememberItems(turn.c,turn.channel,discarded,turn.account):false;}
function roleInterceptDiagnosticRead(c,channel,account){if(!c||!c.id)return null;const row=roleInterceptDiagnosticReadAll()[roleInterceptDiagnosticKey(c.id,channel,account)];return row&&row.roleId===String(c.id)&&row.channel===roleInterceptDiagnosticChannel(channel)?row:null;}
function roleInterceptDiagnosticOpen(cid,channel){
  const c=getC(cid);if(!c)return;
  const lane=roleInterceptDiagnosticChannel(channel),row=roleInterceptDiagnosticRead(c,lane),where=lane==='online'?'线上微信':lane==='cohab'?'共同生活':'单次约会';
  if(!row){openModal(`<h3>上一轮拦截内容</h3><div class="hint">${where}暂时没有可查看的拦截正文。这里会记录模型已经返回、但没有原样展示的全部回复候选，包括被重写、过滤、去重、截断或整轮隐藏的内容；网络失败、空响应和已正常执行的功能指令不算拦截。</div><button class="btn g" style="margin-top:12px" onclick="closeModal()">关闭</button>`);return;}
  const stamp=fmtDT(row.at),items=Array.isArray(row.items)?row.items:[];
  if(row.kind==='request-failure'&&row.failure){const f=row.failure,retry=f.retryCount?`已自动重试 ${f.retryCount} 次，仍然失败`:'没有取得可用的模型响应',candidateBody=items.length?items.map((item,index)=>`<section style="margin-top:14px"><div class="section"><div class="it"><span>已取得候选</span><span class="v">${esc((index+1)+' / '+items.length+' · '+(item.stage||'模型候选'))}</span></div></div><pre style="margin:7px 0 0;max-height:26vh;overflow:auto;white-space:pre-wrap;word-break:break-word;border:1px solid #34343a;border-radius:12px;background:#121214;color:#ddd;padding:12px;font:13px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace">${esc(String(item.raw||''))}</pre></section>`).join(''):'';openModal(`<h3>上一轮回复失败依据</h3><div class="hint">这轮请求在取得可显示回复前失败，所以没有“被拦截正文”。下面是实际请求路线和失败信息，不会冒充角色回复，也不能手动释放。</div><div class="section" style="margin-top:12px"><div class="it"><span>位置</span><span class="v">${esc(where)}</span></div><div class="it"><span>角色</span><span class="v">${esc(row.roleName)}</span></div><div class="it"><span>时间</span><span class="v">${esc(stamp)}</span></div><div class="it"><span>失败阶段</span><span class="v">${esc(f.stage||'模型请求')}</span></div><div class="it"><span>实际路线</span><span class="v">${esc((f.routeName||'当前路线')+(f.modelKind?' · '+f.modelKind:''))}</span></div>${f.model?`<div class="it"><span>实际模型</span><span class="v">${esc(f.model)}</span></div>`:''}${f.elapsedMs?`<div class="it"><span>等待时间</span><span class="v">${Math.round(f.elapsedMs/100)/10} 秒</span></div>`:''}<div class="it"><span>结果</span><span class="v">${esc(retry)}</span></div></div><div class="hint" style="margin-top:12px;color:#ffb4c8">${esc(f.reason||'模型请求失败')}</div><pre style="margin:7px 0 0;max-height:24vh;overflow:auto;white-space:pre-wrap;word-break:break-word;border:1px solid #34343a;border-radius:12px;background:#121214;color:#ddd;padding:12px;font:13px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace">${esc(f.detail||f.reason||'没有返回错误正文')}</pre>${candidateBody}<button class="btn g" style="margin-top:12px" onclick="closeModal()">关闭</button>`);return;}
  const visibleItems=items.length?items:[row],body=visibleItems.map((item,index)=>{const cut=item.truncated?'\n\n（原文超过 12000 字，以下为本机保留的前 12000 字。）':'';return `<section style="margin-top:14px"><div class="section"><div class="it"><span>候选</span><span class="v">${esc((index+1)+' / '+visibleItems.length+' · '+(item.stage||'模型候选'))}</span></div><div class="it"><span>未展示原因</span><span class="v">${esc(item.reason||row.reason||'未原样展示')}</span></div><div class="it"><span>处理方式</span><span class="v">${esc(item.action||row.action||'被替换或隐藏')}</span></div></div><pre style="margin:7px 0 0;max-height:34vh;overflow:auto;white-space:pre-wrap;word-break:break-word;border:1px solid #34343a;border-radius:12px;background:#121214;color:#ddd;padding:12px;font:13px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace">${esc(String(item.raw||'')+cut)}</pre></section>`;}).join(''),release=row.releasedAt?'<button class="btn p" disabled>已释放到聊天</button>':`<button class="btn p" data-cid="${esc(String(cid))}" data-channel="${lane}" onclick="roleInterceptDiagnosticRelease(this.dataset.cid,this.dataset.channel)">释放全部到聊天</button>`;
  openModal(`<h3>上一轮拦截内容</h3><div class="hint">按模型实际返回顺序保留这一轮全部未原样展示的回复候选。记录只存在当前本机运行会话；除非你主动点击“释放全部到聊天”，否则不会发给模型、写进聊天、角色记忆或云同步。</div><div class="section" style="margin-top:12px"><div class="it"><span>位置</span><span class="v">${esc(where)}</span></div><div class="it"><span>角色</span><span class="v">${esc(row.roleName)}</span></div><div class="it"><span>时间</span><span class="v">${esc(stamp)}</span></div><div class="it"><span>候选数量</span><span class="v">${visibleItems.length}</span></div></div>${body}<div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">关闭</button>${release}</div>`);
}
