async function roleInterceptDiagnosticRelease(cid,channel){
  const c=getC(cid);if(!c)return false;
  const lane=roleInterceptDiagnosticChannel(channel),account=lane==='online'?roleInterceptDiagnosticAccount():undefined,row=roleInterceptDiagnosticRead(c,lane,account);
  if(!row)return toast('这轮拦截记录已经不存在'),false;
  if(row.kind==='request-failure')return toast('这轮只有接口失败依据，没有可释放的角色正文'),false;
  if(row.releasedAt)return toast('这轮内容已经释放过了'),false;
  const items=(Array.isArray(row.items)?row.items:[row]).map(item=>({item,text:roleInterceptDiagnosticReleaseText(item)})).filter(x=>x.text);
  if(!items.length)return toast('这轮没有可释放的正文'),false;
  const releaseKey=roleInterceptDiagnosticKey(c.id,lane,account);if(_roleInterceptReleaseBusy.has(releaseKey))return false;
  const agreed=await uiConfirm('把这一轮全部 '+items.length+' 份模型候选原样释放到'+(lane==='online'?'微信':lane==='cohab'?'共同生活':'单次约会')+'聊天？\n\n这些内容可能互相重复、前后矛盾、跳出角色或带有未执行的功能标签；释放只会把原文作为角色消息写入聊天，不会重新执行任何标签。');
  if(!agreed)return false;
  _roleInterceptReleaseBusy.add(releaseKey);
  let list=null,beforeLength=0,beforeSeq=0,push=null;
  try{
    const latest=roleInterceptDiagnosticRead(c,lane,account);if(!latest||latest.at!==row.at)throw new Error('确认期间出现了新的拦截记录，请重新查看');if(latest.releasedAt)throw new Error('这轮内容已经释放过了');
    if(lane==='online'){list=msgsForAccount(c.id,latest.account);push=m=>list.push(m);}
    else if(lane==='cohab'){const d=S.cohabitation&&S.cohabitation.homes&&S.cohabitation.homes[c.id];if(!d||!Array.isArray(d.msgs))throw new Error('原共同生活聊天已经不存在');list=d.msgs;beforeSeq=Math.max(0,+d.msgSeq||0);push=m=>{d.msgSeq=Math.max(0,+d.msgSeq||0)+1;m.cohabSeq=d.msgSeq;list.push(m);};}
    else{const o=S.offline&&S.offline[c.id];if(!o||!Array.isArray(o.msgs))throw new Error('原单次约会聊天已经不存在');list=o.msgs;push=m=>list.push(m);}
    beforeLength=list.length;const base=Date.now();items.forEach((x,index)=>{const common={id:uid(),time:base+index,_interceptReleased:true,_interceptAt:+latest.at||0,_interceptStage:String(x.item&&x.item.stage||'模型候选')};push(lane==='online'?Object.assign(common,{role:'assistant',type:'text',content:x.text}):Object.assign(common,{who:'ta',text:x.text}));});
    if(await saveNowAsync()===false)throw new Error('聊天保存失败，已撤回本次释放');
    const rows=roleInterceptDiagnosticReadAll(),stored=rows[releaseKey];if(stored&&stored.at===latest.at){stored.releasedAt=Date.now();stored.releasedCount=items.length;roleInterceptDiagnosticWriteAll(rows);}
    closeModal();if(lane==='online')openChat(c.id);else if(typeof offRender==='function')offRender();else render();toast('已释放 '+items.length+' 份拦截候选');return true;
  }catch(e){if(list&&list.length>beforeLength)list.splice(beforeLength);if(lane==='cohab'){const d=S.cohabitation&&S.cohabitation.homes&&S.cohabitation.homes[c.id];if(d)d.msgSeq=beforeSeq;}try{save(0);}catch(_){}toast(String(e&&e.message||e||'释放失败'));return false;}
  finally{_roleInterceptReleaseBusy.delete(releaseKey);}
}
