  medical:[[7.4,'住处附近','出门'],[8.2,'医院门诊楼','上班'],[11.8,'医院食堂','午餐'],[14.7,'工作地点','值班'],[18.2,'地铁站','下班'],[20.5,'住处附近','回家']],
