const renderCompanionPageCore=renderCompanionPage;
renderCompanionPage=function(c,SEC,HD){const html=renderCompanionPageCore(c,SEC,HD),st=companionState(),battery=st.battery,health=st.health,w=st.automationWindows,batteryText=battery?Math.round(battery.level*100)+'%':'待 iPhone 同步',batterySub=battery?(battery.state+(battery.lowPower?' · 低电量模式':'')+(battery.ts?' · '+fmtDT(battery.ts):'')):'伴生 App 前台运行时自动更新',stepText=health&&health.steps!==null?Math.round(health.steps):'--',healthText=companionHealthSummary(health),healthSub=health&&health.ts?'最近更新 '+fmtDT(health.ts):'需先在 iPhone 伴生 App 打开健康摘要开关',auto=st.automations||{},autoRows=[['morningSleep','每日睡眠记录必查','时段 '+companionAutomationRangeText(w.sleepStart,w.sleepEnd)+'；说“早安”可当天立即查看且不重复','health',true],['eveningScreen','每日总时长与全部 App 记录必查','时段 '+companionAutomationRangeText(w.usageStart,w.usageEnd)+'；总时长和每个 App 每天完整查看一次','screenTime',true],['absenceBattery','失联时查看 iPhone 电量与位置','3小时未回才检查；查完必须发消息或来电','battery'],['criticalBattery','电量 5% 及以下提醒充电','仅在未充电且快照新鲜时触发；同一轮只提醒一次','battery'],['emotionCare','难过时参考最新心率','只作关心线索，不判断撒谎、哭泣或疾病','health']];const wellness=`<div id="cou_companion_wellness" ${SEC}>${HD('heart','电量与 Apple Watch 健康','#7dd3fc')}<div style="padding:11px 12px;display:grid;grid-template-columns:1fr 1fr;gap:8px"><div style="background:rgba(125,211,252,.08);border:1px solid rgba(125,211,252,.16);border-radius:12px;padding:12px;text-align:center"><b style="display:block;font-size:22px;color:#bdeaff">${esc(batteryText)}</b><small style="color:#8799a5">iPhone 电量</small></div><div style="background:rgba(196,181,253,.08);border:1px solid rgba(196,181,253,.16);border-radius:12px;padding:12px;text-align:center"><b style="display:block;font-size:22px;color:#ddd6fe">${stepText}</b><small style="color:#958da9">今日步数</small></div></div><div class="it"><span style="color:#888">电量状态</span><span class="v">${esc(batterySub)}</span></div><div style="padding:11px 13px;border-top:1px solid rgba(255,255,255,.05);font-size:12px;line-height:1.7;color:#c9c4d2">${esc(healthText)}<small style="display:block;margin-top:4px;color:#777">${esc(healthSub)}</small></div><div style="padding:0 13px 12px;color:#777;font-size:11px;line-height:1.6">Apple Watch 数据通过 iPhone 健康 App 读取，不会重新配对手表。心境只来自用户主动记录，不做自动情绪识别，也不提供医疗诊断。</div></div>`;const windows=`<div style="padding:11px 12px;border-bottom:1px solid rgba(255,255,255,.05)"><b style="display:block;color:#eee;font-size:13px;margin-bottom:8px">自己设置每天可查看的时间</b><div style="display:grid;grid-template-columns:62px 1fr 18px 1fr;gap:7px;align-items:center;font-size:12px;color:#aaa;margin-bottom:8px"><span>睡眠</span><input id="comp_auto_sleep_start" aria-label="睡眠查看开始时间" type="time" value="${w.sleepStart}" style="min-width:0;background:#232127;color:#eee;border:1px solid #3b3740;border-radius:8px;padding:7px"><span>到</span><input id="comp_auto_sleep_end" aria-label="睡眠查看结束时间" type="time" value="${w.sleepEnd}" style="min-width:0;background:#232127;color:#eee;border:1px solid #3b3740;border-radius:8px;padding:7px"><span>App</span><input id="comp_auto_usage_start" aria-label="应用使用记录查看开始时间" type="time" value="${w.usageStart}" style="min-width:0;background:#232127;color:#eee;border:1px solid #3b3740;border-radius:8px;padding:7px"><span>到</span><input id="comp_auto_usage_end" aria-label="应用使用记录查看结束时间" type="time" value="${w.usageEnd}" style="min-width:0;background:#232127;color:#eee;border:1px solid #3b3740;border-radius:8px;padding:7px"></div><button class="minibtn" style="width:100%;background:#8d5272;color:#fff" onclick="companionSaveAutomationWindows()">保存每日必查时段</button></div>`;const automation=`<div id="cou_companion_automations" ${SEC}>${HD('spark','角色主动查看规则','#f7b3d2')}${windows}${autoRows.map(x=>{const allowed=st.roleAccess&&companionAutomationPermissions(x[0]).every(permission=>st.permissions[permission]);return `<div class="it" style="align-items:flex-start;opacity:${allowed?1:.48}"><span><b style="display:block;font-size:13px;color:#eee">${x[1]}</b><small style="display:block;margin-top:3px;color:#777;line-height:1.45">${x[2]}</small></span>${x[4]?`<span style="font-size:10px;color:${allowed?'#72df9f':'#999'};border:1px solid ${allowed?'rgba(114,223,159,.45)':'#555'};border-radius:999px;padding:4px 7px;white-space:nowrap">${allowed?'每日必查':'等待授权'}</span>`:`<span class="sw ${allowed&&auto[x[0]]?'on':''}" onclick="companionToggleAutomation('${x[0]}')"></span>`}</div>`;}).join('')}<div style="padding:10px 13px 12px;color:#777;font-size:11px;line-height:1.65">睡眠与应用使用记录是每日必查项，在各自设置时段内有新鲜快照后当天只执行一次；它们不受通用主动消息时段和20分钟防刷屏限制。说“早安/早上好”会立即完成当天睡眠查看。心率、电量、位置仍可在授权后全天自主查看、不限次数。页面完全关闭时不能伪装成本机常驻监控。</div></div>`;return html.replace('<div id="cou_companion_apps"',wellness+automation+'<div id="cou_companion_apps"');};
const renderCompanionPageAutomationCore=renderCompanionPage;
renderCompanionPage=function(c,SEC,HD){const html=renderCompanionPageAutomationCore(c,SEC,HD),st=companionState(),allowed=st.roleAccess&&st.permissions.appControl,row=`<div class="it" style="align-items:flex-start;opacity:${allowed?1:.48}"><span><b style="display:block;font-size:13px;color:#eee">手动解锁立即告诉角色</b><small style="display:block;margin-top:3px;color:#777;line-height:1.45">必开规则；只接受真实执行成功记录，排除角色自己下达的解锁命令</small></span><span class="sw ${allowed?'on':''}" onclick="companionToggleAutomation('manualUnlockAlert')"></span></div>`;return html.replace('<div style="padding:10px 13px 12px;color:#777;font-size:11px;line-height:1.65">睡眠与应用使用记录',row+'<div style="padding:10px 13px 12px;color:#777;font-size:11px;line-height:1.65">睡眠与应用使用记录');};
