function roleFeatureSection(html,start,end){const a=html.indexOf(`<div class="wx-feature-title">${start}</div>`),b=end?html.indexOf(`<div class="wx-feature-title">${end}</div>`,a):-1;return a<0?'':html.slice(a,b<0?html.length:b);}
function renderRoleManagement(id,group){const c=getC(id);if(!c)return '';const active=['profile','chat','calls','social','privacy'].includes(group)?group:'profile';
  const all=renderRoleManagementAll(id),first=all.indexOf('<div class="wx-feature-title">基础资料与记忆</div>'),footer=all.indexOf('<div style="padding:0 12px 20px">',first),dataStart=all.indexOf('<div class="wx-feature-title">聊天数据与联系人</div>',first),prefix=all.slice(0,first),suffix=all.slice(footer),parts={profile:roleFeatureSection(all,'基础资料与记忆','聊天与通话'),chat:roleFeatureSection(all,'主动联系与通知','隐私授权与查岗'),calls:roleFeatureSection(all,'聊天与通话','主动联系与通知'),social:roleFeatureSection(all,'内容发布','聊天数据与联系人'),privacy:roleFeatureSection(all,'隐私授权与查岗','内容发布')+all.slice(dataStart,footer)},titles={profile:'资料与记忆',chat:'聊天与主动',calls:'通话记录',social:'朋友圈与 X',privacy:'隐私、查岗与数据'};
  if(active==='chat'){const own=ttsRoleRouteOwnIndex(c),routeLabel=own==null?'跟随当前路线':TTS_ROUTE_NAMES[own];parts.chat=`<div class="wx-feature-title">角色语音</div><div class="section" style="margin:0 12px 12px"><div class="it" onclick="editVoice('${id}')"><span>语音音色与路线<br><small style="color:#888">每个角色可独立选择官网语音路线；不设置时继续跟随当前全局路线</small></span><span class="v">${esc(routeLabel)} ›</span></div></div>`+parts.chat;}
  const wxStepsEntry=active==='chat'?`<div class="wx-feature-title">微信运动</div><div class="section role-wxsteps-entry" style="margin:0 12px 12px"><div class="it" onclick="go('wxsteps')">${wxStepsAppIcon()}<span>微信运动<br><small style="color:#888">查看步数并启用或停用微信运动</small></span><span class="v">${S.me.stepOn?'已启用':'未启用'} ›</span></div></div>`:'';
  if(wxStepsEntry)parts[active]+=wxStepsEntry;
  return prefix.replace('<span class="t">角色功能</span>',`<span class="t">${titles[active]}</span>`)+parts[active]+suffix;}
function cToggleModel(id){const c=getC(id);if(!c)return;c.model=(c.model==='aux')?'chat':'aux';save();render();
  if(c.model==='aux'&&!(S.settings.aux&&S.settings.aux.model))toast('副模型未配置',3000);
  else{_wechatActualModelRoute.set(String(c.id),c.model==='aux'?'aux':'main');toast(c.model==='aux'?'已切换副模型':'已切换主模型',3000);}}
function contactMemoryThreadKey(key,id){return key===id||key.indexOf(id+'#')===0;}
function clearContactPhoneMemory(c,id){if(!c||typeof phState!=='function')return;const p=phState(),nums=new Set(),roleNum=typeof phRoleNumber==='function'?phNorm(phRoleNumber(c)):'';
  if(roleNum)nums.add(roleNum);
  ['phoneSpoofHistory','phoneAliasCallHistory','phoneSpoofSmsHistory','phoneAliasHistory'].forEach(k=>(c[k]||[]).forEach(x=>{if(x&&x.num)nums.add(phNorm(x.num));if(x&&x.targetNum)nums.add(phNorm(x.targetNum));}));
  Object.keys(p.aliasThreads||{}).forEach(k=>{const t=p.aliasThreads[k]||{};if(t.cid===id||t.roleId===id||phNorm(t.targetNum||'')===roleNum){nums.add(phNorm(k));if(t.aliasNum)nums.add(phNorm(t.aliasNum));if(t.targetNum)nums.add(phNorm(t.targetNum));delete p.aliasThreads[k];}});
  const msgForRole=m=>m&&(m.aliasTo===id||m.aliasFrom===id||m.spoofTo===id||m.roleId===id||m.cid===id);
  Object.keys(p.sms||{}).forEach(k=>{const arr=p.sms[k]||[],num=typeof phSmsDisplayNum==='function'?phNorm(phSmsDisplayNum(k)):phNorm(k);if(nums.has(num)||arr.some(msgForRole)){delete p.sms[k];if(p.read)delete p.read[k];}});
  p.recents=(p.recents||[]).filter(x=>!nums.has(phNorm(x&&x.num||'')));
  (p.voicemail||[]).filter(x=>x&&(x.roleId===id||nums.has(phNorm(x.num||'')))).forEach(clearVoiceAudio);
  p.voicemail=(p.voicemail||[]).filter(x=>!(x&&(x.roleId===id||nums.has(phNorm(x.num||'')))));
  p.trash=(p.trash||[]).filter(x=>!nums.has(phNorm(x&&x.num||'')));
  if(p.simCall&&p.simCall.meta&&p.simCall.meta.roleId===id){try{if('speechSynthesis'in window)speechSynthesis.cancel();}catch(_){}p.simCall=null;}
  Object.keys(_phAliasFollowups||{}).forEach(k=>{if(k.indexOf(id+':')===0||k.indexOf('spoof:'+id+':')===0)delete _phAliasFollowups[k];});
  delete c.phoneSpoofHistory;delete c.phoneAliasCallHistory;delete c.phoneSpoofSmsHistory;delete c.phoneAliasHistory;
}
function clearContactRoleplayMemory(id){if(!S.roleplay)return;delete S.roleplay[id];Object.keys(S.roleplay).forEach(k=>{const d=S.roleplay[k];if(!d)return;if(Array.isArray(d.members))d.members=d.members.filter(x=>x&&x.id!==id);if(Array.isArray(d.msgs))d.msgs=d.msgs.filter(x=>!x||x.cid!==id);if(d.inviteMids)delete d.inviteMids[id];});}
function clearContactMemoryData(c,id){const now=Date.now();c._memoryResetAt=now;
  const aids=['main',...((S.me&&S.me.accounts)||[]).map(a=>a&&a.id).filter(Boolean)];[...new Set(aids)].forEach(aid=>{if(typeof replyTouch==='function')replyTouch(id,aid);});
  Object.keys(S.messages||{}).forEach(k=>{if(!contactMemoryThreadKey(k,id))return;(S.messages[k]||[]).forEach(clearVoiceAudio);delete S.messages[k];});
  c.memory=[];c.summaries=[];c.aiMemoryImports=[];c.grudges=[];c._lifeNotesClearedAt=now;
  ['summary','tasks','taskHist','_accountMemory','_accountSummaries','_accountSummaryState','_memoryMeta','_memoryConflicts','_memoryLastPick','_sumCount','_summaryCursorV2','_dialogueEmotion','_jailHandoff','gamesPlayed','drawGuessMemory','wxLoginHistory','remoteControlHistory','suspicion','_spyKnowledge','_phoneInspectionFacts','_loginCode','_lastCallEnded','_gotFromMe','_pushedToMe','_initiative','_initiativeLast','_distressCallAt','_affGain','_affAt','emotionTailUntil','emotionTailReason','_altReportAt','_altReportDeliveredAt','_altReportEvents','_altIntroDone','_recoveredAt','_deleteDur','_recoverCount','_friendReqRetry','_friendRejectHistory','_blockedPhone','_blockedAt','_readdedAt','_readdKnown','_blockDur','_friendMeta'].forEach(k=>delete c[k]);
  delete c._offlineHandoff;delete c._gameHandoff;
  c.mood='';c.moodVal=70;c.moodAt=now;c.coldUntil=0;c._esc={stage:0};
  if(S.offline&&S.offline[id])delete S.offline[id];if(S.offlineFocus&&(S.offlineFocus===id||S.offlineFocus.cid===id))S.offlineFocus=null;
  if(S.music&&S.music.chat)S.music.chat=S.music.chat.filter(m=>m.cid!==id);
  if(S.cinema){S.cinema.sessions=(S.cinema.sessions||[]).filter(x=>x&&x.cid!==id);if(S.cinema.selectedCid===id)S.cinema.selectedCid='';}
  if(S.cohabitation&&S.cohabitation.homes)delete S.cohabitation.homes[id];
  if(S.alter)Object.keys(S.alter).forEach(k=>{if(k.split('@').indexOf(id)>=0)delete S.alter[k];});
  if(S.alterMeta)Object.keys(S.alterMeta).forEach(k=>{if(k.split('@').indexOf(id)>=0)delete S.alterMeta[k];});
  clearContactRoleplayMemory(id);clearContactPhoneMemory(c,id);
  if(S.wxLogin&&S.wxLogin.by===id){S.wxLogin=null;if(typeof _wxLoginTimer!=='undefined'&&_wxLoginTimer){clearInterval(_wxLoginTimer);_wxLoginTimer=null;}}
  if(S.spy&&S.spy[id]){const sp=S.spy[id];S.spy[id]={granted:sp.granted,loc:sp.loc,time:sp.time,times:sp.times,pwd:sp.pwd,phone:sp.phone,memorySince:now};}
  if(S._spySeen)S._spySeen[id]=now;if(S._spyCount)delete S._spyCount[id];
  if(S.couple&&S.couple.cid===id&&S.couple.behavior){const enabled=S.couple.behavior.enabled!==false;S.couple.behavior={enabled,items:[],_lastHit:{}};}
  if(S.jail&&S.jail.cid===id)S.jail={active:false,releasedAt:now,clearedAt:now};
  if(S.friendRequests)S.friendRequests=S.friendRequests.filter(x=>x&&x.contactId!==id);
  if(S._proactiveDone)delete S._proactiveDone[id];if(S._proactiveCount)delete S._proactiveCount[id];
  if(S._humanMetrics)Object.keys(S._humanMetrics).forEach(k=>{if(k.endsWith('|'+id))delete S._humanMetrics[k];});
  if(S._personaOutput)Object.keys(S._personaOutput).forEach(k=>{if(Array.isArray(S._personaOutput[k]))S._personaOutput[k]=S._personaOutput[k].filter(x=>x&&x.cid!==id);});
  if(c.proactive&&c.proactive.serverPush)c._serverMemoryResetPending=now;
}
async function wipeContact(id){const c=getC(id);if(!c||!isMain())return;
  if(!await uiConfirm('彻底清空和「'+(c.remark||c.name)+'」的【全部】记忆？\n\n包括：主号/小号聊天、长期记忆、对话总结、小事簿读取、记仇与情绪旧账、任务、线下约会、角色扮演、一起听、放映室、电话短信与语音留言、ta手机隐藏内容、关系小账本及记忆缓存。\n\n保留：角色人设、头像、关系设定、语音、API和美化。清空后无法恢复（建议先在 设置里导出备份）。'))return;
  clearContactMemoryData(c,id);render();toast('正在清除本机大聊天库和后台旧上下文…');
  try{const localSaved=await persistWechatMessagesNow();if(!localSaved)throw new Error('本机存档没有确认写入');const serverSaved=await roleServerPushResetMemory(c,c._memoryResetAt);if(!serverSaved&&c.proactive&&c.proactive.serverPush)throw new Error('后台旧上下文暂未清除');render();toast('已彻底清空和「'+(c.remark||c.name)+'」的全部记忆');}catch(e){render();openModal('<h3>清空尚未全部完成</h3><div class="hint" style="line-height:1.8">本机当前页面里的记忆已经移除，但'+esc(String(e&&e.message||'持久存储暂时不可用'))+'。<br><br>请保持页面开启并重试；在全部写入成功前，不会把这次操作冒充成“彻底完成”。</div><div class="btns"><button class="btn g" onclick="closeModal()">关闭</button><button class="btn p" onclick="closeModal();wipeContact(\''+id+'\')">重新清空</button></div>');}}
function setRemark(id){const c=getC(id);openModal(`<h3>备注</h3><div class="field"><input id="rmk" value="${esc(c.remark)}" placeholder="给ta起个备注名"></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="getC('${id}').remark=$('#rmk').value.trim();save();closeModal();render()">保存</button></div>`);}
function roleRemarkApply(c,value){if(!c)return false;const nv=String(value||'').replace(/[\r\n\[\]【】]/g,'').trim().slice(0,16);if(!nv||nv===c.remark)return false;const generic=/^(?:老公|老婆|宝贝|宝宝|亲爱的|对象|男朋友|女朋友|先生|太太|爱人|honey|baby|darling)$/i,duplicate=(S.contacts||[]).some(x=>x&&!x.deleted&&x.id!==c.id&&String(x.remark||'').trim().toLowerCase()===nv.toLowerCase());if(duplicate||generic.test(nv)&&(c._remarkHistory||[]).includes(nv))return false;c.remark=nv;c._remarkAt=Date.now();c._remarkHistory=[nv].concat(c._remarkHistory||[]).filter((x,i,a)=>x&&a.indexOf(x)===i).slice(0,8);return true;}
function affectionPanel(id){const c=getC(id);if(!c)return;const v=affNow(c);openModal(`<h3>关系状态</h3>
  <div class="hint">这里不会在聊天里显示，只影响ta对你的熟悉、关心和分寸。</div>
  <div style="margin:12px 0 8px;height:8px;border-radius:8px;background:#2c2c2e;overflow:hidden"><i id="af_bar" style="display:block;height:100%;width:${v}%;background:linear-gradient(90deg,#8aa4ff,#ff8fab)"></i></div>
  <div class="field"><label>进度 <b id="af_v" style="color:#ff8fab">${v}</b><small style="color:#888">/100 · ${affStage(v)}</small></label><input id="af_r" type="range" min="1" max="100" step="1" value="${v}" oninput="var n=+this.value;$('#af_v').textContent=n;$('#af_bar').style.width=n+'%'" style="width:100%"></div>
  <div class="it"><span>固定关系进度<br><small style="color:#888">固定后不会自动变化</small></span><span class="sw ${c.affectionLocked?'on':''}" id="af_lock" onclick="this.classList.toggle('on')"></span></div>
  <div class="it"><span>关闭布置任务<br><small style="color:#888">关闭后ta不会生成每日任务</small></span><span class="sw ${c.taskOff?'on':''}" id="af_taskoff" onclick="this.classList.toggle('on')"></span></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="saveAffectionPanel('${id}')">保存</button></div>`);}
function saveAffectionPanel(id){const c=getC(id);if(!c)return;c.affection=Math.max(1,Math.min(100,+($('#af_r')&&$('#af_r').value)||affNow(c)));c.affectionLocked=!!($('#af_lock')&&$('#af_lock').classList.contains('on'));c.taskOff=!!($('#af_taskoff')&&$('#af_taskoff').classList.contains('on'));save();closeModal();render();toast('已保存');}
function schedSet(id){const c=getC(id);const sc=c.sched||{on:false,work:'',home:'家',amS:'08:00',amE:'12:00',pmS:'14:00',pmE:'18:00',leaves:[]},today=scheduleDateKey(),leaves=scheduleLeaves(c).filter(x=>x.end>=today).slice(0,20),leaveHTML=leaves.length?leaves.map(x=>`<div class="it"><span>${esc(scheduleLeaveLabel(x))}<br><small style="color:#888">${esc(x.start+(x.end!==x.start?' 至 '+x.end:'')+(x.reason?' · '+x.reason:''))}</small></span><button class="minibtn" onclick="schedCancelLeave('${id}','${x.start}','${x.end}')">取消请假</button></div>`).join(''):'<div class="hint">目前没有已生效或即将生效的请假。</div>';
  openModal(`<h3>${esc(c.remark||c.name)} 的作息</h3>
   <div class="hint">设好后，查ta手机/聊天里ta的位置会跟着时间走。角色也能在共同生活或同步微信里自主请假、销假和调整上下班时间；角色改动会真实保存到这里。</div>
   <div class="it"><span>启用作息</span><span class="sw ${sc.on?'on':''}" id="sc_on" onclick="this.classList.toggle('on')"></span></div>
   <div class="field"><label>工作地点</label><input id="sc_work" value="${esc(sc.work||'')}" placeholder="医院 / 公司 / 工作室…"></div>
   <div class="field"><label>家 / 住处</label><input id="sc_home" value="${esc(sc.home||'家')}"></div>
   <div class="two"><div class="field"><label>上午上班</label><input type="time" id="sc_amS" value="${sc.amS||'08:00'}"></div><div class="field"><label>上午下班</label><input type="time" id="sc_amE" value="${sc.amE||'12:00'}"></div></div>
   <div class="two"><div class="field"><label>下午上班</label><input type="time" id="sc_pmS" value="${sc.pmS||'14:00'}"></div><div class="field"><label>下午下班</label><input type="time" id="sc_pmE" value="${sc.pmE||'18:00'}"></div></div>
   <div class="hint">周一至周五按这套时间工作；「上午下班」到「下午上班」之间是午休，「下午下班」后自由活动并回家。周六、周日默认休息。请假只覆盖登记的日期，到期后自动恢复这套工作日作息。</div>
   <h4 style="margin:16px 0 8px">请假安排</h4>${leaveHTML}
   <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="saveSched('${id}')">保存</button></div>`);}
async function schedCancelLeave(id,start,end){const c=getC(id);if(!c||!await uiConfirm('取消 '+start+(end!==start?' 至 '+end:'')+' 的请假吗？'))return;const sc=c.sched||{};sc.leaves=Array.isArray(sc.leaves)?sc.leaves.filter(x=>!x||x.end<start||x.start>end):[];delete c._currentActivity;save();schedSet(id);render();toast('已取消请假');}
function saveSched(id){const c=getC(id),old=c.sched||{};c.sched=Object.assign({},old,{on:$('#sc_on').classList.contains('on'),work:$('#sc_work').value.trim()||'公司',home:$('#sc_home').value.trim()||'家',amS:$('#sc_amS').value||'08:00',amE:$('#sc_amE').value||'12:00',pmS:$('#sc_pmS').value||'14:00',pmE:$('#sc_pmE').value||'18:00',leaves:Array.isArray(old.leaves)?old.leaves:[]});delete c._currentActivity;const d=cohabData(id);if(d){delete d.scheduleSlotKey;if(d.stateSource==='owner-manual')d.stateSource='schedule-auto';cohabAdvance(id);}save();closeModal();render();toast('作息已保存，当前生活状态已按新时间同步🕐');}
