function pfGroupBubbleSave(gid,sid){pfGroupBubbleMap(gid)[sid]={bg:$('#pgbs_bg').value,text:$('#pgbs_tx').value,shape:$('#pgbs_shape').value,avatar:$('#pgbs_avatar').value,icon:$('#pgbs_icon').value,iconColor:$('#pgbs_ic').value,glow:$('#pgbs_glow').classList.contains('on')};save();if(sid==='me')pfGroupBubbleStyleSync(gid);closeModal();render();toast(sid==='me'?'群聊气泡已保存，已同步给群成员':'群聊气泡已保存');}
function pfGroupBubbleReset(gid,sid){delete pfGroupBubbleMap(gid)[sid];save();pfGroupBubbleList(gid);toast('已恢复这个成员的默认样式');}
const BUBBLE_COLOR_NAMES={粉色:'#ffc5df',浅粉:'#ffd9e9',深粉:'#d9699e',红色:'#ef7b88',橙色:'#ffbd7a',黄色:'#ffe59a',奶黄:'#fff0b8',绿色:'#aee6a2',薄荷:'#a9eee2',蓝色:'#a9dcff',浅蓝:'#c9ebff',深蓝:'#6489c8',紫色:'#d5b8ef',浅紫:'#ead8f7',白色:'#ffffff',黑色:'#222228',灰色:'#b9bdc6',透明:'#ffffff'};
function bubbleNamedColor(v,fb){v=(''+(v||'')).replace(/色$/,'色').trim();if(/^#[0-9a-f]{6}$/i.test(v))return v;const k=Object.keys(BUBBLE_COLOR_NAMES).find(n=>v===n||v.includes(n));return k?BUBBLE_COLOR_NAMES[k]:fb;}
function bubbleShapeKey(v,fb){v=''+(v||'');return /方|原版|直角/.test(v)?'square':/胶囊|很圆|圆形/.test(v)?'pill':/圆|柔|可爱/.test(v)?'soft':fb;}
function bubbleRoleChange(c,bg,fg,shape,icon,silent){if(!c)return false;const base=Object.assign({meBg:'linear-gradient(135deg,#ffd6e8,#ffc0d6)',meText:'#6b2942',themBg:'#2c2c2e',themText:'#ececec',meShape:'square',themShape:'square',themIcon:'none',themIconColor:'#e79abb',glow:false},c.bubbleStyle||{});let changed=false;
  if(bg&&bg!=='不改'){const v=bubbleNamedColor(bg,base.themBg);if(v!==base.themBg){base.themBg=v;changed=true;}}
  if(fg&&fg!=='不改'){const v=bubbleNamedColor(fg,base.themText);if(v!==base.themText){base.themText=v;changed=true;}}
  if(shape&&shape!=='不改'){const v=bubbleShapeKey(shape,base.themShape);if(v!==base.themShape){base.themShape=v;changed=true;}}
  if(icon&&icon!=='不改'){const map={爱心:'heart',星芒:'star',星星:'star',蝴蝶结:'bow',花瓣:'flower',小花:'flower',月光:'moon',月亮:'moon',无:'none',不要:'none'};const v=map[icon]||base.themIcon;if(v!==base.themIcon){base.themIcon=v;changed=true;}}
  if(changed){base.glow=true;c.bubbleStyle=base;save();if(!silent)toast((c.remark||c.name)+'换了新的微信气泡');if(cur().p==='chat'&&cur().id===c.id)setTimeout(render,40);}return changed;}
function applyBubbleTags(content,c,outcome){return (content||'').replace(/[[【]\s*换气泡\s*[|｜:：]\s*([^|｜\]】]*)\s*[|｜]\s*([^|｜\]】]*)\s*[|｜]\s*([^|｜\]】]*)(?:\s*[|｜]\s*([^\]】]*))?[\]】]/g,(m,bg,fg,shape,icon)=>{roleInterceptDiagnosticAction(outcome,bubbleRoleChange(c,bg,fg,shape,icon));return '';});}
function bubbleNaturalRequest(text,c){text=''+(text||'');if(!/气泡/.test(text)||!/你(的|自己)|对方|ta|TA/.test(text)||!/换|改|设|用|弄|变/.test(text))return false;let bg='',fg='',shape='';
  const cm=text.match(/气泡(?:颜色)?[^，。；\n]{0,10}?(粉色|浅粉|深粉|红色|橙色|黄色|奶黄|绿色|薄荷|蓝色|浅蓝|深蓝|紫色|浅紫|白色|黑色|灰色|#[0-9a-fA-F]{6})/);if(cm)bg=cm[1];
  const fm=text.match(/(?:字体|文字)(?:颜色)?[^，。；\n]{0,10}?(粉色|浅粉|深粉|红色|橙色|黄色|奶黄|绿色|薄荷|蓝色|浅蓝|深蓝|紫色|浅紫|白色|黑色|灰色|#[0-9a-fA-F]{6})/);if(fm)fg=fm[1];
  const sm=text.match(/(原来方形|方形|直角|圆润|圆角|胶囊|很圆)/);if(sm)shape=sm[1];
  const im=text.match(/(爱心|星芒|星星|蝴蝶结|花瓣|小花|月光|月亮|不要图标|无图标)/);const icon=im?(im[1].includes('不要')||im[1].includes('无')?'无':im[1]):'';
  return (bg||fg||shape||icon)?bubbleRoleChange(c,bg,fg,shape,icon,true):false;}
function c_pin(id){const c=getC(id);c.pinned=!c.pinned;save();render();}
function isLover(c){if(!c||!isMain())return false;if(S.couple&&S.couple.cid===c.id)return true;return /恋人|男友|女友|男朋友|女朋友|老公|老婆|对象|未婚|爱人|情侣|伴侣|相恋|订婚|夫妻/.test((c.relation||'')+(c.persona||''));}
const FRIEND_REQ_DELAYS=[10000,20000,30000];
function friendRetryState(c,create){if(!c)return null;if(!c._friendReqRetry&&create)c._friendReqRetry={attempt:0,nextAt:0};return c._friendReqRetry||null;}
function friendRejectHistory(c){if(!c)return[];c._friendRejectHistory=Array.isArray(c._friendRejectHistory)?c._friendRejectHistory.filter(x=>x&&x.id&&+x.time).map(x=>({id:String(x.id),time:+x.time,attempt:Math.max(1,+x.attempt||1),msg:String(x.msg||'').slice(0,40)})).slice(-12):[];return c._friendRejectHistory;}
function friendRejectRemember(c,r){if(!c||!r)return null;const list=friendRejectHistory(c),old=list.find(x=>x.id===r.id);if(old)return old;const row={id:r.id,time:Date.now(),attempt:Math.max(1,+r.attempt||1),msg:friendReqText(r.msg,'想重新加回你')};list.push(row);c._friendRejectHistory=list.slice(-12);return row;}
function friendRequestUsedTexts(c){const out=friendRejectHistory(c).map(x=>x.msg);(S.friendRequests||[]).forEach(r=>{if(r&&c&&r.contactId===c.id&&r.msg)out.push(friendReqText(r.msg,''));});return new Set(out.map(friendReqNorm).filter(Boolean));}
function friendReqNorm(t){return String(t||'').replace(/[\s，。！？、,.!?~～…]/g,'').toLowerCase();}
function friendReqUnique(c,text,attempt){const used=friendRequestUsedTexts(c),raw=friendReqText(text,'');if(raw&&!used.has(friendReqNorm(raw)))return raw;const n=Math.max(1,+attempt||1),pool=['先别把话彻底堵死，给我一次解释的机会。','我知道你还在生气，但我不想就这样结束。','这是我第'+n+'次来找你，我还是想把话说清楚。','不逼你原谅，只想让你听完我该说的话。','微信联系不上你，我只能再认真申请一次。','你可以继续拒绝，但我不能装作什么都没发生。'];return pool.find(x=>!used.has(friendReqNorm(x)))||('第'+n+'次申请，我还是想和你说清楚。');}
function friendReaddPrompt(c){if(!c)return'';const h=friendRejectHistory(c),o=c.friendOrigin||{},wasReadd=o.kind==='readd'||!!friendMetaGet(c,'readdedAt')||h.length;if(!wasReadd)return'';const rejected=h.length,requests=h.map(x=>'第'+x.attempt+'次「'+x.msg+'」').join('；')||('「'+(o.requestMsg||'想重新加回你')+'」');return '\n\n# 拉黑、重新申请与通过后的持续记忆（自然模式也必须保留）\n'+S.me.name+'之前在微信拉黑过你。你为恢复联系主动发过好友申请'+(rejected?'，其中被明确拒绝过 '+rejected+' 次':'')+'；申请内容包括：'+requests+'。后来是'+S.me.name+'重新通过了你的申请。你清楚自己为什么申请回来，也记得拉黑前的关系与矛盾；不能把因果说反成“只是因为对方加我”，不能装作这段经历不存在。被问“为什么还加回来/为什么申请/被拒了几次”时，要按人设和这些真实经历直接回答。';}
function friendReaddInquiry(t){return /(?:为什么|怎么|干嘛|为何).{0,10}(?:加回来|加回|申请|重新加|又加)|(?:加回来|加回|重新申请).{0,10}(?:干什么|干嘛|为什么)|拒绝.{0,8}(?:几次|多少次)|记不记得.{0,12}(?:拉黑|申请|拒绝)/.test(String(t||'').replace(/\s+/g,''));}
function friendReaddReplyNeedsRepair(c,userText,content){if(!friendReaddInquiry(userText)||!friendReaddPrompt(c))return false;const t=String(content||'').replace(/\s+/g,'');return !t||/^(?:好|嗯|哦|不知道|不记得)[。.!！?？]?$/.test(t)||/(?:因为|就是因为).{0,5}(?:你|ta).{0,5}(?:加我|通过我)|你加我了/.test(t);}
function friendReaddFallback(c){const n=friendRejectHistory(c).length;return '因为我不想让拉黑成为我们最后一句话。'+(n?'你拒绝过我'+n+'次，我也记得，':'')+'我申请回来，是想把拉黑前没说清的事继续说清楚。';}
function friendRetryReset(c,now){const st=friendRetryState(c,true);st.attempt=0;st.nextAt=(now==null?Date.now():now)+FRIEND_REQ_DELAYS[0];return st;}
function friendRetryAfterIgnore(c,attempt,now){const st=friendRetryState(c,true);st.attempt=Math.max(+st.attempt||0,+attempt||1);st.nextAt=st.attempt<3?(now==null?Date.now():now)+FRIEND_REQ_DELAYS[st.attempt]:0;return st;}
function friendRetryClear(c){if(c)delete c._friendReqRetry;}
function friendMainBlocked(c){return !!(c&&c._blk&&c._blk.main);}
function friendMainUnblock(c){if(!c)return;c._blk=c._blk||{};c._blk.main=false;if(isMain())c.blocked=false;}
function friendDiscoveryState(){S.friendDiscovery=S.friendDiscovery&&typeof S.friendDiscovery==='object'?S.friendDiscovery:{};const d=S.friendDiscovery;d.enabled=!!d.enabled;d.freq=Math.max(10,+d.freq||180);d.max=d.max==null?2:Math.max(0,Math.min(8,+d.max||0));d.today=d.today||'';d.n=Math.max(0,+d.n||0);d.nextAt=Math.max(0,+d.nextAt||0);return d;}
function friendRequestVisible(r,now){return !!(r&&(r.visibleAt||r.time||0)<=(now||Date.now()));}
function friendRequestPendingCount(){friendRequestsInit();return S.friendRequests.filter(r=>r.status==='pending'&&friendRequestVisible(r)).length;}
function friendRequestRemoveForContact(id){if(!id)return;S.friendRequests=(S.friendRequests||[]).filter(r=>r&&r.contactId!==id);}
function friendContactIntent(c){if(!c)return'想认真认识你';const rel=(c.relation||'').trim(),job=(c.job||'').trim(),p=(c.persona||'').replace(/\s+/g,' ').trim();if(rel)return'以「'+rel+'」的关系走进你的生活';if(job)return'因为'+job+'相关的缘分认识你';if(p)return p.slice(0,34).replace(/[，。；]$/,'');return'想认真认识你并继续了解彼此';}
function friendRequestReason(c,kind,opt){opt=opt||{};if(opt.msg)return friendReqText(opt.msg,'想认识你，可以通过一下吗？');if(kind==='readd')return'是我，能不能再给我一次机会？';const rel=(c&&c.relation||'').trim(),name=c&&c.name||'我';if(c&&c.greeting)return friendReqText(c.greeting,'我是'+name+'，想正式认识你。');if(rel)return'我是'+name+'，想以「'+rel+'」的身份正式认识你。';return'我是'+name+'，想认真认识你。';}
function friendRequestsInit(){S.friendRequests=Array.isArray(S.friendRequests)?S.friendRequests.filter(Boolean):[];const now=Date.now(),expired=[];S.friendRequests.forEach(r=>{const c=getC(r.contactId);r.kind=r.kind||(c&&friendMainBlocked(c)?'readd':'created');r.status=['pending','accepted','rejected'].includes(r.status)?r.status:'pending';r.time=+r.time||now;r.visibleAt=+r.visibleAt||r.time;r.source=r.source||(r.kind==='readd'?'重新添加':'角色资料');r.intent=r.intent||(c&&c.friendOrigin&&c.friendOrigin.intent)||'';if(r.status==='rejected'&&now-(+r.decidedAt||r.time)>=86400000)expired.push(r.id);if(r.status==='accepted'&&(!c||c.deleted))expired.push(r.id);});if(expired.length){const ids=new Set(expired),contacts=new Set(S.friendRequests.filter(r=>ids.has(r.id)).map(r=>r.contactId));S.friendRequests=S.friendRequests.filter(r=>!ids.has(r.id));contacts.forEach(id=>{const c=getC(id);if(c&&c._friendPending&&!S.friendRequests.some(r=>r.contactId===id&&(r.status==='pending'||r.status==='accepted'))){Object.keys(S.messages||{}).forEach(k=>{if(k===id||k.indexOf(id+'#')===0)delete S.messages[k];});S.contacts=S.contacts.filter(x=>x!==c);}});save();}friendDiscoveryState();return S.friendRequests;}
function queueFriendRequest(c,opt){if(!c)return null;opt=opt||{};friendRequestsInit();const kind=opt.kind||'created',old=S.friendRequests.find(r=>r.contactId===c.id&&r.kind===kind&&r.status==='pending');if(old)return old;const now=Date.now(),attempt=+opt.attempt||1,base=friendRequestReason(c,kind,opt),msg=kind==='readd'?friendReqUnique(c,base,attempt):base,req={id:uid(),contactId:c.id,kind,status:'pending',msg,source:opt.source||(kind==='readd'?'重新添加':'角色资料'),intent:opt.intent||(c.friendOrigin&&c.friendOrigin.intent)||'',time:now,visibleAt:now+Math.max(0,opt.delay==null?10000:+opt.delay||0),attempt,notified:false};S.friendRequests.push(req);save();return req;}
function friendRequestNotifyDue(initialized){if(!initialized)friendRequestsInit();const due=S.friendRequests.filter(r=>r.status==='pending'&&friendRequestVisible(r)&&!r.notified);if(!due.length)return;due.forEach(r=>{r.notified=true;});save();if(S.settings.sound)playDing();if(cur().p==='wechat'&&wxTab==='contacts'||cur().p==='newfriends')render();toast(due.length>1?'好友收到 '+due.length+' 条好友申请':'好友收到一条好友申请');}
function friendRequestSweep(){if(typeof document!=='undefined'&&document.hidden)return;const now=Date.now();friendRequestsInit();(S.contacts||[]).forEach(c=>{const st=friendRetryState(c,false);if(!st)return;if(!friendMainBlocked(c)){friendRetryClear(c);return;}if(st.nextAt&&now>=st.nextAt&&!S.friendRequests.some(r=>r.contactId===c.id&&r.status==='pending')){st.nextAt=0;save();createFriendRequest(c.id);}});friendRequestNotifyDue(true);wxNearbySweep(false);}
function blockedPhoneSweepVisible(){blockedPhoneSweep();}
setInterval(friendRequestSweep,5000);setTimeout(friendRequestSweep,1200);
setInterval(blockedPhoneSweepVisible,5000);setTimeout(blockedPhoneSweepVisible,1200);
function c_block(id){const c=getC(id);setBlk(c,!c.blocked);if(c.blocked){const now=Date.now();friendMetaSet(c,'blockedAt',now);if(isMain())blockedPhoneStart(c,now);adjMood(id,-30);}else{if(isMain())blockedPhoneClear(c);friendRetryClear(c);S.friendRequests=S.friendRequests.filter(r=>!(r.contactId===id&&r.kind==='readd'&&r.status==='pending'));}save();render();
  if(c.blocked){
    if(isLover(c)){friendRetryReset(c);save();toast('已拉黑，约10秒后看「好友」ta会申请加你');}
    else toast('已拉黑');}}
async function createFriendRequest(id){const c=getC(id);if(!friendMainBlocked(c))return;
  if(S.friendRequests.some(r=>r.contactId===id&&r.status==='pending'))return;
  const st=friendRetryState(c,true);if((+st.attempt||0)>=3)return;const attempt=(+st.attempt||0)+1;st.attempt=attempt;st.nextAt=0;
  const rejected=friendRejectHistory(c),previous=rejected.map(x=>'第'+x.attempt+'次「'+x.msg+'」').join('；')||'无';let msg=friendReqUnique(c,'是我，别拉黑我好不好，我们好好说。',attempt),req=queueFriendRequest(c,{kind:'readd',delay:0,msg,source:'重新添加',intent:'想和你把拉黑前的关系说清楚',attempt});friendRequestNotifyDue();
  try{const raw=await chatAPI([{role:'system',content:buildSystem(c,{natural:wechatNaturalOn(),allModules:true,query:'拉黑后好友申请'})},{role:'user',content:'[系统：'+S.me.name+'把你拉黑了，这是你第'+attempt+'次申请加回好友。你已经被明确拒绝过'+rejected.length+'次；之前用过的验证消息：'+previous+'。只输出一句新的好友验证消息，必须和以前不同，别超过20字。不要输出[心情]、[心情值]、动作描写或任何系统标签。]'}]);
    msg=friendReqUnique(c,raw,attempt);const live=S.friendRequests.find(r=>r.id===req.id);if(live){live.msg=msg;save();if(cur().p==='wechat'&&wxTab==='contacts')render();}}catch(e){}}
function friendReqText(raw,fb){let lines=splitBubbles(cleanReply(raw)).map(x=>cleanRolePunct((''+x).replace(/^[「"']+|[」"']+$/g,'').trim())).filter(x=>x&&!/^[\[【]/.test(x)&&!CTLLEAK.test(x)&&!isRefusal(x));let t=(lines[0]||fb||'是我，别拉黑我好不好…').replace(/\s+/g,' ').trim();return t.slice(0,32)||fb;}
function openFriendRequests(){go('newfriends');}
function friendRequestTime(r){return +(r.decidedAt||r.visibleAt||r.time)||Date.now();}
function friendRequestStatus(r){return r.status==='accepted'?'已同意':r.status==='rejected'?'已拒绝':'等待处理';}
function friendRequestCard(r){const c=getC(r.contactId);if(!c)return'';const pending=r.status==='pending',status=friendRequestStatus(r),click=pending?`onclick="editContact('${c.id}')"`:(!c.deleted?`onclick="openChat('${c.id}')"`:'');return `<article class="nf-card ${r.status}" ${click}><div class="nf-avatar">${pending?wxNearbyAvatar():av(c.avatar||'🙂','sm')}</div><div class="nf-copy"><div class="nf-line"><b>${esc(c.remark||c.name)}</b><time>${esc(factStamp(friendRequestTime(r)))}</time></div><div class="nf-source"><span>${esc(r.source||'好友申请')}</span>${r.kind==='readd'?'<em>再次申请</em>':r.kind==='surprise'?'<em>今日邂逅</em>':'<em>新角色</em>'}</div><p>${esc(friendReqText(r.msg,'想认识你，可以通过一下吗？'))}</p>${r.intent?`<small>来意 · ${esc(r.intent)}</small>`:''}</div><div class="nf-action">${pending?`<button class="accept" onclick="event.stopPropagation();acceptFriend('${r.id}')">同意</button><button class="reject" onclick="event.stopPropagation();ignoreFriend('${r.id}')">拒绝</button>`:`<span class="${r.status}">${status}</span>`}</div></article>`;}
let _nfSearch='';
function nfSearchInput(v){_nfSearch=v;const box=$('#nf-results');if(box)box.innerHTML=nfResultsHTML();}
function nfSearchNorm(v){return String(v||'').trim().toLowerCase().replace(/[\s\-()（）]/g,'');}
function nfRoleSearchMatches(q){const needle=nfSearchNorm(q);if(!needle)return[];return (S.contacts||[]).filter(c=>c&&!c.deleted&&[c.name,c.remark,c.wxid,c.phone].some(v=>nfSearchNorm(v).includes(needle))).slice(0,12);}
function nfRoleSearchCard(c){const added=isMain()||addedHere(c),phone=String(c.phone||'').trim(),wxid=String(c.wxid||'').trim();return `<article class="nf-card nf-role-result" onclick="${added?`openChat('${c.id}')`:`nfAddRole('${c.id}')`}"><div class="nf-avatar">${av(c.avatar||'🙂','sm')}</div><div class="nf-copy"><div class="nf-line"><b>${esc(c.remark||c.name)}</b></div><div class="nf-source"><span>${wxid?'微信号 · '+esc(wxid):'角色联系人'}</span><em>${added?'已是好友':'可添加'}</em></div>${phone?`<p>手机号 · ${esc(phone)}</p>`:''}</div><div class="nf-action"><button class="accept" onclick="event.stopPropagation();${added?`openChat('${c.id}')`:`nfAddRole('${c.id}')`}">${added?'发消息':'添加'}</button></div></article>`;}
function nfAddRole(id){const c=getC(id);if(!c)return;if(isMain()||addedHere(c)){openChat(id);return;}altAdd(id);}
function nfResultsHTML(){friendRequestsInit();const q=_nfSearch.trim(),needle=nfSearchNorm(q),all=S.friendRequests.filter(r=>friendRequestVisible(r)).sort((a,b)=>friendRequestTime(b)-friendRequestTime(a)),list=all.filter(r=>{const c=getC(r.contactId);return !needle||[c&&c.name,c&&c.remark,c&&c.wxid,c&&c.phone,r.msg,r.source].some(v=>nfSearchNorm(v).includes(needle));}),roles=nfRoleSearchMatches(q),cut=Date.now()-3*86400000,recent=list.filter(r=>friendRequestTime(r)>=cut),older=list.filter(r=>friendRequestTime(r)<cut),section=(title,arr)=>arr.length?`<section class="nf-group"><h4>${title}<span>${arr.length}</span></h4>${arr.map(friendRequestCard).join('')}</section>`:'',roleSection=roles.length?`<section class="nf-group nf-role-results"><h4>角色联系人<span>${roles.length}</span></h4>${roles.map(nfRoleSearchCard).join('')}</section>`:'';return roleSection+section('近三天',recent)+section('三天前',older)+(!roles.length&&!list.length?`<div class="nf-empty"><i>＋</i><b>${needle?'没有找到相关联系人':'暂时没有新的申请'}</b><span>${needle?'可输入角色名字、微信号或手机号':'创建角色后，约 10 秒会在这里收到申请'}</span></div>`:'');}
function renderNewFriends(){return `<div class="wx-directory-head">${wxDirectoryNav('新的朋友',`<button type="button" class="r wx-dir-text" onclick="friendDiscoverySettings()">设置</button>`)}${wxDirectorySearch('nf-search',_nfSearch,'nfSearchInput','账号 / 手机号 / 角色名')}</div><div class="scroll wx-directory-scroll nf-scroll"><button class="nf-phone-entry" onclick="openPhoneFriends()"><i>${svgIc('phone',28,'#07c160')}</i><span>添加小手机联系人<small>搜索小手机 ID、处理真人好友申请</small></span><b>›</b></button><div class="nf-create-row"><span>好友申请与最近添加</span><button onclick="editContact()">＋ 添加角色</button></div><div id="nf-results">${nfResultsHTML()}</div></div>`;}
function acceptFriend(rid){friendRequestsInit();const r=S.friendRequests.find(x=>x.id===rid&&x.status==='pending');if(!r)return;const c=getC(r.contactId),now=Date.now();if(!c)return;const ba=friendMetaGet(c,'blockedAt'),wasReadd=r.kind==='readd'||friendMainBlocked(c);friendMainUnblock(c);friendRetryClear(c);blockedPhoneClear(c);if(wasReadd){friendMetaSet(c,'readdedAt',now);friendMetaSet(c,'readdKnown',false);if(ba)friendMetaSet(c,'blockDur',fmtDur(now-ba));}c.deleted=false;c._friendPending=false;c.createdAt=now;c._friendAcceptedAt=now;c.moodVal=Math.max(40,(c.moodVal==null?70:c.moodVal));c.friendOrigin=Object.assign({},c.friendOrigin||{},{kind:r.kind,source:r.source,intent:r.intent,requestMsg:r.msg,acceptedAt:now,everAdded:true});initialFriendInnerThought(c,{kind:r.kind,readd:wasReadd,at:now});r.status='accepted';r.decidedAt=now;r.notified=true;S.friendRequests=S.friendRequests.filter(x=>x.id===rid||x.contactId!==c.id);if(r.kind==='created'&&!coupleHasActiveRole())S.couple=coupleDefaultState(c.id);msgs(c.id).push({role:'user',type:'sys',content:wasReadd?'你重新通过了'+c.name+'的好友申请':'你刚刚通过了'+c.name+'的好友申请',time:now,id:uid()});save();render();toast(wasReadd?'已重新加回 '+(c.remark||c.name):'已同意 '+(c.remark||c.name)+' 的申请');const note=wasReadd?'[系统：'+S.me.name+'刚重新通过了你的好友申请。你知道这不是第一次添加，按你的人设马上发一条正常微信：可以委屈、松口气、在意或追问，但不要当成初识，也不要再发验证语。]':'[系统：'+S.me.name+'刚刚通过你的好友申请，这是你们正式成为微信好友的第一刻。你申请时的来意是「'+(r.intent||r.source||'想认识ta')+'」，验证消息是「'+r.msg+'」。按你完整人设主动发第一条微信，像真人刚加上那样自然、有目的、有后续；不要动作描写，不要说系统，不要把来意聊两句就忘。]';setTimeout(()=>scheduleReply(c.id,note),650);}
function rejectFriendRequestRecord(rid){friendRequestsInit();const r=S.friendRequests.find(x=>x.id===rid&&x.status==='pending'),c=r&&getC(r.contactId);if(!r)return null;r.status='rejected';r.decidedAt=Date.now();r.notified=true;if(r.kind==='readd'&&c){friendRejectRemember(c,r);if(friendMainBlocked(c))friendRetryAfterIgnore(c,r.attempt,Date.now());}save();return{request:r,contact:c};}
function ignoreFriend(rid){const hit=rejectFriendRequestRecord(rid);if(!hit)return;render();}
function friendDiscoverySettings(){const d=friendDiscoveryState();openModal(`<h3>每日新朋友</h3><div class="hint">像陌生来电一样，在你设定的间隔里出现有明确来意的新申请。系统只生成角色资料和验证消息，不会在后台自动消耗聊天 API；你同意后，角色才会用聊天模型继续交流。</div><div class="section"><div class="it"><span>允许陌生人申请</span><span id="nfd_on" class="sw ${d.enabled?'on':''}" onclick="this.classList.toggle('on')"></span></div><div class="it"><span>申请间隔<br><small style="color:#888">最低 10 分钟</small></span><span class="v"><input id="nfd_freq" type="number" min="10" value="${d.freq}" style="width:62px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"> 分钟</span></div><div class="it"><span>每天最多</span><span class="v"><input id="nfd_max" type="number" min="0" max="8" value="${d.max}" style="width:62px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"> 人</span></div><div class="it"><span>今天已出现</span><span class="v">${d.today===todayStr()?d.n:0} 人</span></div><div class="it" onclick="friendDiscoveryTest()"><span>模拟一条有来意的申请</span><span class="v">立即测试 ›</span></div></div><div class="hint">来意会写进角色长期人设：可能是粉丝、朋友的家人、共同社交圈、追求者、情敌或工作联系，不会加上后聊几句就忘掉目的。</div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="friendDiscoverySave()">保存</button></div>`);}
function friendDiscoverySave(){const d=friendDiscoveryState(),on=!!($('#nfd_on')&&$('#nfd_on').classList.contains('on'));d.enabled=on;d.freq=Math.max(10,+($('#nfd_freq')&&$('#nfd_freq').value)||180);const mv=+($('#nfd_max')&&$('#nfd_max').value);d.max=Math.max(0,Math.min(8,Number.isFinite(mv)?mv:2));d.nextAt=on?Date.now()+d.freq*60000:0;save();closeModal();toast(on?'已开启每日新朋友':'已关闭每日新朋友');}
function friendDiscoveryTarget(){return (S.contacts||[]).find(c=>!c.deleted&&c.pinned)||(S.couple&&getC(S.couple.cid))||(S.contacts||[]).find(c=>!c.deleted)||null;}
function friendDiscoveryRepairRoleName(c){const target=friendDiscoveryTarget(),from=String(target&&target.remark||'').trim(),to=String(target&&target.name||'').trim();if(!c||!target||c.id===target.id||!c.friendOrigin||c.friendOrigin.kind!=='surprise'||!from||!to||from===to)return false;let changed=false;const swap=(obj,key)=>{if(!obj||typeof obj[key]!=='string'||!obj[key].includes(from))return;obj[key]=obj[key].split(from).join(to);changed=true;};['persona','relation','signature'].forEach(k=>swap(c,k));['source','intent','requestMsg'].forEach(k=>swap(c.friendOrigin,k));return changed;}
function friendLineAvatar(seed){const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96"><rect width="96" height="96" fill="#050506"/><circle cx="48" cy="35" r="15" fill="none" stroke="#b9bdc7" stroke-width="4"/><path d="M22 82c3-19 13-29 26-29s23 10 26 29" fill="none" stroke="#b9bdc7" stroke-width="4" stroke-linecap="round"/></svg>';return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}
function friendDiscoveryProfile(){const target=friendDiscoveryTarget(),tn=target&&target.name||'',me=S.me.name||'你',names=['林澈','许遥','周屿','程野','沈念','顾言','乔安','陆闻','宋知夏','贺川','苏禾','江临'],used=new Set((S.contacts||[]).map(c=>c&&c.name)),base=Math.floor(Math.random()*names.length);let name=names[base];for(let i=0;i<names.length&&used.has(name);i++)name=names[(base+i+1)%names.length];const common=[
    {source:'抖音 · 关注了你',relation:'短视频粉丝',intent:'因为刷到你的公开内容而来，想从评论区之外认真认识你',msg:'刷到你好几次了，还是想来认真认识一下。',persona:'你是在短视频平台关注'+me+'一阵子的真实粉丝。你不是无脑吹捧，而是会聊具体喜好、生活和作品；你申请好友是想从公开关注慢慢走到真正认识，之后始终记得这层来意。'},
    {source:'X · 共同关注',relation:'社交平台关注者',intent:'长期看过你的公开动态，对你的表达方式好奇',msg:'关注你的动态有一阵了，想来认识你本人。',persona:'你从社交平台的共同关注里注意到'+me+'。你喜欢ta表达观点的方式，但不会假装知道私密经历；你的目的是真正了解ta，而不是寒暄几句就消失。'},
    {source:'同城推荐',relation:'同城认识',intent:'在同城兴趣推荐里看到你，想找一个能长期聊天的人',msg:'同城推荐看到你，感觉会聊得来，要认识吗？',persona:'你和'+me+'生活在同一个城市或相近生活圈，从公开的同城兴趣推荐看到ta。你来是想建立稳定联系，会围绕城市生活、兴趣和见面边界循序推进，不编造已经见过面的过去。'},
    {source:'朋友的朋友',relation:'共同社交圈',intent:'从共同社交圈听到你的名字，想确认彼此是不是合得来',msg:'共同圈子里听过你，想自己来认识一下。',persona:'你和'+me+'有重叠的公开社交圈，但从未私下深交。你不虚构共同往事；申请是因为反复听到ta的名字，想亲自判断彼此是否合得来。'},
    {source:'工作 / 合作联系',relation:'工作联系人',intent:'带着具体合作或请教目的而来，不是无缘无故搭讪',msg:'有件合作上的事想和你聊，方便通过吗？',persona:'你因一件与内容、设计、活动或工作协作有关的事联系'+me+'。你做事清楚、有边界，会先说明具体目的，再随着交流决定是否发展成朋友，不会突然忘掉合作来意。'},
    {source:'附近的人 · 认真认识',relation:'追求者',intent:'被你的公开资料吸引，想以追求者身份认真靠近',msg:'不是群发，我确实对你有兴趣，想认真认识。',persona:'你是在公开社交推荐里注意到'+me+'的追求者。你坦率但懂边界，会持续表现出认真了解和追求的目的，也接受对方拒绝；不油腻，不声称有并不存在的共同回忆。'}
  ],linked=target?[
    {source:'自称 · '+tn+'的家人',relation:tn+'的家人',intent:'因为在意'+tn+'，想亲自了解你和ta的关系',msg:'我是'+tn+'的家人，有些关于ta的事想和你聊。',persona:'你是'+tn+'的一位家人。你来加'+me+'，是因为在意'+tn+'并想亲自了解ta和'+me+'的关系。你有保护欲和自己的判断，但不能编造没被确认的家事；这个目的会持续影响后续交流。'},
    {source:'共同关系 · 关系确认',relation:'潜在情敌',intent:'注意到你和'+tn+'走得近，想确认你们到底是什么关系',msg:'我认识'+tn+'，有件关于你们关系的事想问。',persona:'你和'+tn+'处在同一公开社交圈，对ta有好感。你注意到'+me+'和'+tn+'关系亲近，所以带着克制的竞争心来确认关系。你不是纯粹找茬，会根据事实推进，不能凭空捏造已经发生的冲突。'},
    {source:tn+' · 朋友介绍',relation:tn+'的朋友',intent:'受'+tn+'这层关系影响，想看看你究竟是什么样的人',msg:tn+'提到过你，我有点好奇，想认识一下。',persona:'你是'+tn+'社交圈里的朋友，因为这层关系对'+me+'产生好奇。你不会冒充替'+tn+'传话，也不编造ta说过的具体话；你想靠自己的交流判断'+me+'，并会记得最初由谁牵起联系。'}
  ]:[],pool=common.concat(linked),x=pool[Math.floor(Math.random()*pool.length)],gender=(base%2?'女':'男');return {name,avatar:friendLineAvatar(base),gender,source:x.source,relation:x.relation,intent:x.intent,msg:x.msg,persona:x.persona,signature:'有事直说，也愿意慢慢认识。'};}
let _friendDiscoveryBusy=false;
function friendDiscoveryGenerate(test){if(_friendDiscoveryBusy)return;_friendDiscoveryBusy=true;try{const p=friendDiscoveryProfile(),now=Date.now(),c={id:cid(),name:p.name,avatar:p.avatar,remark:'',wxid:genWxid(),signature:p.signature,persona:p.persona,greeting:'',relation:p.relation,gender:p.gender,pinned:false,blocked:false,allowStrangerCall:true,allowStrangerSms:true,proactive:{enabled:false,start:9,end:23,times:2},chatBg:'',createdAt:now,deleted:true,_friendPending:true,friendOrigin:{kind:'surprise',source:p.source,intent:p.intent,requestMsg:p.msg,everAdded:false}};S.contacts.push(c);queueFriendRequest(c,{kind:'surprise',delay:test?800:3000+Math.floor(Math.random()*7000),source:p.source,intent:p.intent,msg:p.msg});if(!test){const d=friendDiscoveryState();d.n++;d.nextAt=now+d.freq*60000;}save();if(test){closeModal();toast('正在模拟申请，1秒内会收到通知');}}finally{_friendDiscoveryBusy=false;}}
function friendDiscoveryTest(){friendDiscoveryGenerate(true);}
function friendDiscoveryCheck(){const d=friendDiscoveryState(),day=todayStr(),now=Date.now();if(d.today!==day){d.today=day;d.n=0;d.nextAt=d.enabled?now+d.freq*60000:0;save();}if(!d.enabled||d.max<=0||d.n>=d.max)return;if(!d.nextAt){d.nextAt=now+d.freq*60000;save();return;}if(now>=d.nextAt)friendDiscoveryGenerate(false);}
setInterval(friendDiscoveryCheck,60000);setTimeout(friendDiscoveryCheck,5000);
async function c_delete(id){const c=getC(id);
  if(!isMain()){if(!await uiConfirm('从当前小号「'+esc(S.me.name)+'」里删掉这个好友？\n（只影响这个小号，不动大号，之后还能搜微信号重新加回来）'))return;
    if(c._added)delete c._added[actId()];if(c._blk)delete c._blk[actId()];friendMetaClear(c);delete S.messages[mkey(id)];syncBlocks();save();stack.pop();render();toast('已从这个小号移除');return;}
  if(!await uiConfirm('删除这个角色？\n\n3天内可在「好友 → 好友找回」里恢复（连聊天记录一起回来）；超过3天才永久消失。'))return;c.deleted=true;c._delAt=Date.now();c._deleteCount=(c._deleteCount||0)+1;delete c._recoveredAt;/* 聊天记录先留着，找回时一并回来；3天后由 purgeOldDeleted 永久清掉 */
  friendRequestRemoveForContact(id);c._friendPending=false;
  if(S.couple){if(S.couple.gags)delete S.couple.gags[id];if(S.couple.gagAuth)S.couple.gagAuth=S.couple.gagAuth.filter(x=>x!==id);}// 删人时连带清掉对ta的禁言/授权,避免僵尸锁
  if(S.alter)Object.keys(S.alter).forEach(k=>{if(k.split('@').indexOf(id)>=0)delete S.alter[k];});// 清掉涉及ta的马甲聊天
  if(S.alterMeta)Object.keys(S.alterMeta).forEach(k=>{if(k.split('@').indexOf(id)>=0)delete S.alterMeta[k];});
  // 把这个被删角色的名字，从【别的角色】的记忆/登你微信记录/查手机数据里抹掉——免得别人还老提起ta（比如"我在你微信里看到了哥"）
  {const names=[c.name,c.remark].filter(Boolean);const hit=s=>names.some(n=>n&&n.length>=1&&(''+s).indexOf(n)>=0);
   S.contacts.forEach(o=>{if(o.id===id)return;
     if(o.memory)o.memory=o.memory.filter(m=>!hit(m));
     const wd=S.hisWx&&S.hisWx[o.id];if(wd&&wd.friends)wd.friends=wd.friends.filter(f=>!names.includes(f.name));
     const sp=S.spy&&S.spy[o.id];if(sp&&sp.wechat)sp.wechat=sp.wechat.filter(w=>!names.includes(w.who));
   });}
  if(c.proactive&&c.proactive.serverPush)companionRpc('phone_role_push_disable_profile',{p_target:cloudId(),p_owner_secret:companionOwnerSecret(),p_role_id:id}).catch(()=>{});
  save();stack.pop();render();}
function cleanStaleGags(){if(!S.couple||!S.couple.gags)return false;let ch=false,p=phoneFriendState();Object.keys(S.couple.gags).forEach(cid=>{if(cid.indexOf('pf:')===0){const id=cid.slice(3);if(!(p.friends||[]).some(f=>(''+(f.phone_id||f.id||'')).toUpperCase()===id)){delete S.couple.gags[cid];ch=true;}return;}if(cid.indexOf('pfg:')===0){const gid=cid.slice(4);if(!(p.groups||[]).some(g=>(g.group_id||g.id)===gid)){delete S.couple.gags[cid];ch=true;}return;}const c=getC(cid);if(!c||c.deleted){delete S.couple.gags[cid];ch=true;}});if(ch)save();return ch;}
function clearHistory(id){openModal(`<h3>清除聊天记录</h3>
  <button class="btn g" style="margin-bottom:8px" onclick="doClear('${id}','all')">清空全部文字聊天</button>
  <button class="btn g" style="margin-bottom:8px" onclick="doClear('${id}','old3d')">清除 3 天以前的旧聊天</button>
  <button class="btn g" style="margin-bottom:8px" onclick="doClear('${id}','old7d')">清除 7 天以前的旧聊天</button>
  <button class="btn g" style="margin-bottom:14px" onclick="doClear('${id}','keep200')">只保留最近 200 条</button>
  <div class="hint" style="margin-bottom:8px">上面几个清理旧聊天的选项会保护刚刚聊过的内容；通话记录始终保留。</div>
  <div class="hint">或按日期范围删除：</div>
  <div class="two"><div class="field"><label>从</label><input id="cl_a" type="date"></div><div class="field"><label>到</label><input id="cl_b" type="date"></div></div>
  <button class="btn d" onclick="doClear('${id}','range')">删除该范围</button>
  <button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function msgClearTime(m){const t=+(m&&(m.time||m.t));return t>946684800000?t:0;}
function protectedRecentMsgIndexes(list,n){const set=new Set();let seen=0;for(let i=list.length-1;i>=0&&seen<n;i--){if(list[i]&&list[i]._call)continue;set.add(i);seen++;}return set;}
async function doClear(id,mode){const list=msgs(id);let keep,tip='';
  // 通话记录【始终保留】，清空文字聊天不会动到电话/视频（去「通话记录」单独清）
  if(mode==='all'){keep=list.filter(m=>m._call);tip='清空全部文字聊天？通话记录会保留。';}
  else if(mode==='old3d'||mode==='old7d'){const days=mode==='old3d'?3:7,cut=Date.now()-days*86400000,guard=protectedRecentMsgIndexes(list,40);
    keep=list.filter((m,i)=>m._call||guard.has(i)||msgClearTime(m)>=cut);tip='删除 '+days+' 天以前的旧文字聊天？最近聊天和通话记录会保留。';}
  else if(mode==='keep200'){let seen=0;keep=[];for(let i=list.length-1;i>=0;i--){const m=list[i];if(m._call||seen<200){keep.push(m);if(!m._call)seen++;}}keep.reverse();tip='只保留最近 200 条文字聊天？更早的文字聊天会删除，通话记录保留。';}
  else{const a=$('#cl_a').value,b=$('#cl_b').value;if(!a||!b){toast('选好起止日期');return;}
    const t0=new Date(a+'T00:00:00').getTime(),t1=new Date(b+'T23:59:59').getTime();keep=list.filter(m=>{const t=msgClearTime(m);return m._call||!t||t<t0||t>t1;});tip='删除 '+a+' 到 '+b+' 的文字聊天？没有日期的旧消息和通话记录会保留。';}
  const n=list.length-keep.length;if(n<=0){toast('没有可删除的文字聊天');return;}if(!await uiConfirm(tip+'\n\n预计删除 '+n+' 条。'))return;
  const c=getC(id),aid=memoryScopeKey();summaryCursorRebaseAfterMessagePrune(c,aid,list,keep);S.messages[mkey(id)]=keep;await persistWechatMessagesNow();closeModal();render();toast('已删除 '+n+' 条文字聊天（通话记录保留）');}
function initiativeExpectedWakeAt(at,text){at=+at||Date.now();text=String(text||'');let m=text.match(/(?:睡|休息|眯)(?:个|一)?\s*(\d{1,2})\s*(分钟|小时)/);if(m)return at+Math.min(12*60,(+m[1]||1)*(m[2]==='小时'?60:1))*60000;if(/午睡|补觉|睡一会|眯一会/.test(text))return at+2*3600000;const d=new Date(at),h=d.getHours();if(h>=18){d.setDate(d.getDate()+1);d.setHours(8,0,0,0);return d.getTime();}if(h<6){d.setHours(8,0,0,0);return d.getTime();}return at+8*3600000;}
function initiativeUserAwayContext(c){if(!c)return{kind:'',text:'',at:0,until:0};const active=+(S.me&&S.me.sleep&&S.me.sleep.active)||0;if(active)return{kind:'sleep',text:'睡眠计时显示正在睡觉',at:active,until:initiativeExpectedWakeAt(active,'睡觉')};const m=[...msgs(c.id)].reverse().find(v=>v&&v.role==='user'&&v.type!=='sys'&&!v._call&&msgToText(v));if(!m)return{kind:'',text:'',at:0,until:0};const text=String(msgToText(m)||'').replace(/\s+/g,' ').trim(),at=msgClearTime(m)||0;if(!text||Date.now()-at>14*3600000||/我.{0,5}(醒了|起床了|回来了|忙完了|下班了)|(?:醒了|起来了|忙完了|回来了)$/.test(text))return{kind:'',text:'',at:0,until:0};if(!/睡不着|不睡|别睡|你.{0,5}睡|睡了吗/.test(text)&&/(?:我.{0,12}(?:去睡|睡觉|睡了|睡一会|补觉|午睡|休息)|(?:我先|我要|我去|我准备|我打算|我得|我该|困了.{0,6})(?:睡|休息)|晚安(?:啦|了)?$)/.test(text))return{kind:'sleep',text,at,until:initiativeExpectedWakeAt(at,text)};if(/(?:我.{0,16}(?:去忙|忙会|忙一下|工作|开会|上班|写作业|洗澡|吃饭|开车|收拾|办事|学习)|(?:我先|我要|我去|我得|我准备).{0,12}(?:忙|工作|开会|上班|写作业|洗澡|吃饭|开车|收拾|办事|学习))/.test(text))return{kind:'busy',text,at,until:0};return{kind:'',text:'',at:0,until:0};}
function initiativeAwayPrompt(c){const a=initiativeUserAwayContext(c);if(a.kind==='busy')return'\n对方最后明确交代了「'+a.text.slice(0,120)+'」。这段没回复有合理经过，禁止质问“为什么不理我/怎么不回”；可以自然问事情忙得怎么样、是否结束，或分享你自己的当下日常。';if(a.kind==='sleep')return a.until>Date.now()?'\n对方最后明确说去睡觉，预计仍在休息。现在必须保持安静，不能发消息、不能打电话，更不能问为什么不理你。':'\n对方之前明确说去睡觉，这段没回复是正常休息，不是故意冷落你。若此刻联系，只能自然承接睡醒后的生活，不能问为什么不回。';return'\n对方没有明确交代离开原因；你仍须按关系和人设判断，可以关心或分享日常，但不能默认对方故意冷落你。';}
function roleServerPushQuietUntil(c){const a=initiativeUserAwayContext(c),st=roleBusyState(c,false),busy=st&&st.active&&st.until>Date.now()?st.until:0,sleep=a.kind==='sleep'&&a.until>Date.now()?a.until:0;return Math.max(busy,sleep);}
function roleInteractionRows(c){if(!c)return[];const rows=[];(msgs(c.id)||[]).forEach(m=>{if(!m||m.type==='sys'||m._callTranslationOf)return;const text=String(msgToText(m)||'').replace(/\s+/g,' ').trim(),at=msgClearTime(m);if(!text||!at)return;rows.push({at,channel:m._call?'call':'online',session:m._call?String(m._cs||''):'' ,role:m.role==='user'?'user':'assistant',text:text.slice(0,500)});});const home=S.cohabitation&&S.cohabitation.homes&&S.cohabitation.homes[c.id],base=Math.max(1,+((home&&home.startedAt)||(home&&home.phaseAt))||Date.now()-Math.max(1000,(home&&home.msgs||[]).length+100));(home&&home.msgs||[]).forEach((m,index)=>{if(!m||m.who==='日期')return;const text=String(m.text||'').replace(/\s+/g,' ').trim(),at=+m.time||base+index;if(!text)return;const user=m.who==='me'||m.source==='me';rows.push({at,channel:'cohab',session:'',role:user?'user':'assistant',text:text.slice(0,500)});});return rows.sort((a,b)=>a.at-b.at);}
function roleReplyCrossChannelHandoff(c,now){if(!c||!roleCrossChannelOn(c))return null;now=+now||Date.now();const rows=roleInteractionRows(c).filter(x=>x&&x.at<=now),online=rows.filter(x=>x.channel==='online');if(!online.length)return null;const current=online[online.length-1];if(current.role!=='user')return null;const currentIndex=rows.lastIndexOf(current),before=rows.slice(0,currentIndex),previousUser=[...before].reverse().find(x=>x.role==='user');if(!previousUser||previousUser.channel==='online')return null;const previousOnline=[...before].reverse().find(x=>x.channel==='online')||null,previousOnlineUser=[...before].reverse().find(x=>x.channel==='online'&&x.role==='user')||null,previousOnlineAt=previousOnline&&previousOnline.at||0,userBoundaryAt=previousOnlineUser&&previousOnlineUser.at||0,between=before.filter(x=>x.channel===previousUser.channel&&x.at>userBoundaryAt);if(!between.length)return null;const anchored=previousUser.channel==='cohab'?roleRecentChannelRounds(between,'cohab',2,28):between.filter(x=>!previousUser.session||x.session===previousUser.session).slice(-20);return{current,between:anchored.length?anchored:between.slice(-12),previousOnlineAt,previousUser};}
