  const mood=`<div class="moodbar chat-glass-mood" id="chatMoodBar" onclick="${thoughtOpen}('${id}')" style="display:${S.settings.showMoodTag!==false&&thought?'flex':'none'};align-items:center;gap:6px">${svgIc('thought',15,'currentColor')}<span id="chatMoodText" style="overflow:hidden;white-space:nowrap;text-overflow:ellipsis">${esc(thought.slice(0,24))}${thought.length>24?'…':''}</span></div>`;
