  const tc=taskC(),tt=tc&&tc.tasks&&tc.tasks.date===todayStr()?tc.tasks:null;if(tt)(tt.list||[]).forEach(x=>tasks.push((x.done?'已完成 ':'未完成 ')+(x.text||'任务')));
