    const r=await remoteControlExecute(a,c);remoteControlScene(r,remoteControlStageCaption(a,r),i,required.length,a);await remoteControlFocusViewedTarget(a);let entry=null;if(r.ok){entry={app:r.app,op:a.op,targetId:a.targetId||'',targetName:a.targetName||'',targetType:a.targetType||'',detail:r.detail,memory:r.memory,ts:Date.now()};ctl.actions.push(entry);save();}
    await sleep(320);const reaction=await remoteControlRoleReaction(c,a,r);if(entry){entry.roleLines=reaction.lines||[];entry.reactionDelete=!!reaction.deleteIntent;entry.reactionDeleteIndex=reaction.messageIndex;save();}await remoteControlShowRoleLines(reaction.lines);
    const reactionAction=remoteControlReactionDeleteAction(entry,reaction,c);if(reactionAction&&remoteControlActive()&&!ctl.cancelled){const visibleDelete=await remoteControlPrepareVisibleDelete(reactionAction);if(remoteControlActive()&&!ctl.cancelled){const dr=await remoteControlExecute(reactionAction,c);if(dr.ok){ctl.actions.push({app:dr.app,op:reactionAction.op,targetId:reactionAction.targetId||'',targetName:reactionAction.targetName||'',targetType:reactionAction.targetType||'',detail:dr.detail,memory:dr.memory,ts:Date.now()});save();if(visibleDelete)await remoteControlShowVisibleDeleteResult(reactionAction);}remoteControlScene(dr,'',i,required.length,visibleDelete?Object.assign({},reactionAction,{noNavigate:true}):reactionAction);}}
    if(a.targetType==='wechatList'){remoteControlProgress('正在选择要打开的微信聊天');const choices=await remoteControlWechatChoicePlan(c);remoteControlAppendChoices(required,i+1,choices);}
    else if(a.targetType==='xDmList'||a.targetType==='dyDmList'){remoteControlProgress('正在选择要打开的私信');const choices=await remoteControlDmChoicePlan(c,a.app);remoteControlAppendChoices(required,i+1,choices);}
    else if(a.fromWechatList)await remoteControlWechatExitToList();
