function wxLoginCompletionChannel(cid,opt){opt=opt&&typeof opt==='object'?opt:{};if(opt.channel==='cohab'||opt.channel==='online')return opt.channel;const c=getC(cid),latest=c&&typeof roleLatestUserChannel==='function'?roleLatestUserChannel(c,'online'):'online';return latest==='cohab'?'cohab':'online';}
