function summaryCursorRebaseAfterMessagePrune(c,aid,before,after){if(!c)return 0;before=Array.isArray(before)?before:[];after=Array.isArray(after)?after:[];aid=memoryScopeKey(aid);const st=summaryState(c,aid),done=summaryStateDone(c,aid,before),kept=new Set(after),next=before.slice(0,done).reduce((n,m)=>n+(kept.has(m)?1:0),0);summaryStateSave(c,aid,next,after);delete c._autoSummaryError;delete c._autoSummaryErrorAt;return next;}
function pruneSummaries(c,aid){aid=memoryScopeKey(aid);let arr=summaryList(c,aid);arr.forEach(x=>{if(x&&x.text)x.text=summaryRepairStoredText(c,x,aid);});for(let i=arr.length-1;i>=0;i--){for(let j=0;j<i;j++){if(summarySimilarity(arr[i]&&arr[i].text,arr[j]&&arr[j].text,aid)>=.72){arr[j].imp=Math.max(arr[j].imp||3,arr[i].imp||3);arr.splice(i,1);break;}}}if(S.settings.memAutoClean===false)return;const cap=(+S.settings.memCap)||100;
  while(arr.length>cap){let cand=-1,candImp=99;for(let i=0;i<arr.length;i++){const im=arr[i].imp||3;if(im>=5)continue;if(im<candImp){candImp=im;cand=i;}}if(cand<0)break;/* 剩下全是5星就不再删 */arr.splice(cand,1);}}
function summaryPerspectiveValid(c,text,aid){const t=summaryCleanText(c,text,aid),self=[c&&c.name,c&&c.remark].map(x=>String(x||'').trim()).filter(Boolean);if(!t||!t.includes('我')||/(?:^|[，。！？；\s])(对方|ta|TA)(?=[，。！？；\s]|$)/.test(t))return false;for(const name of self){if(name&&new RegExp('(?:^|[。！？；]\s*)'+wxEscRe(name)+'(?:说|想|觉得|看|问|让|把|在|正|又|没|没有|已经|后来)').test(t))return false;}return !/(?:^|[。！？；]\s*)(?:他|她)(?:说|想|觉得|看|问|让|把|在|正|又|没|没有|已经|后来)/.test(t);}
