  const prior=arr.slice(-8).map(x=>'· '+summaryCleanText(c,x.text,aid)).join('\n'),system=wechatSummarySystem(c,aid,prior),messages=[{role:'system',content:system},{role:'user',content:chunk}];
  busy.add(key);
