function incomingRingMusicModal(){musicInit();const songs=S.music.songs||[],selected=String(S.settings&&S.settings.incomingRingSongId||''),rows=songs.map(s=>`<button type="button" class="btn ${selected===s.id&&incomingRingKey()==='music'?'p':'g'}" style="margin-bottom:8px;text-align:left" data-song-id="${esc(String(s.id||''))}" onclick="incomingRingSongSelect(this.dataset.songId)">♫ ${esc(s.title||'未命名')}${s.artist?`<small style="display:block;margin-top:3px;opacity:.68">${esc(s.artist)}</small>`:''}</button>`).join('');openModal(`<h3>从音乐库选择来电铃声</h3><div class="hint" style="margin-bottom:10px">默认仍是本次提供的微信来电 MP3。选择音乐库歌曲后会循环播放；歌曲被删除或本地文件失效时自动回到默认 MP3。</div><button type="button" class="btn ${incomingRingKey()==='default'?'p':'g'}" style="margin-bottom:8px;text-align:left" onclick="incomingRingUseDefault()">♪ 使用默认微信来电 MP3</button>${rows||'<div class="hint">音乐库还是空的，请先到“音乐”里添加或收藏歌曲。</div>'}<div class="btns"><button class="btn g" onclick="closeModal()">取消</button>${songs.length?'':`<button class="btn p" onclick="closeModal();go('music')">去添加音乐</button>`}</div>`);}
function incomingRingUseDefault(){ringStop();S.settings.incomingRing='default';S.settings.incomingRingSongId='';save();closeModal();incomingRingPreview();render();toast('已恢复默认微信来电 MP3');return true;}
function incomingRingSongSelect(id){const song=(S.music&&S.music.songs||[]).find(x=>x.id===id);if(!song){toast('这首歌已不在音乐库');return false;}ringStop();S.settings.incomingRing='music';S.settings.incomingRingSongId=song.id;save();closeModal();incomingRingPreview();render();toast('已用「'+(song.title||'未命名')+'」作为微信来电铃声');return true;}
async function incomingRingMusicSource(){const song=incomingRingSong();if(!song)return null;if(song.src&&song.src.t==='url'&&song.src.url)return{url:song.src.url,owned:false};const blob=await mGet(song.id);if(!blob||song.fileSize&&Number(song.fileSize)!==Number(blob.size))return null;try{return{url:URL.createObjectURL(blob),owned:true};}catch(_){return null;}}
function ringAssetStart(a,onFail,url){if(!a)return false;try{a.pause();a.loop=true;a.volume=Math.max(0,Math.min(1,.42*volMul()));a.src=url||incomingRingUrl();a.currentTime=0;const p=a.play();if(p&&typeof p.catch==='function')p.catch(()=>{if(_ring===a&&onFail)onFail();});return true;}catch(_){return false;}}
function incomingRingAssetStart(url,preview){const primary=ringToneElement(),fallback=()=>{const shared=uiToneElement();if(!shared||shared===primary)return false;_ring=shared;return ringAssetStart(shared,()=>{if(_ring===shared)_ring=null;},url);};if(primary){_ring=primary;if(!ringAssetStart(primary,fallback,url)){_ring=null;if(!fallback())return false;}}else if(!fallback())return false;if(preview)_ringPreviewTimer=setTimeout(()=>ringStop(),4800);return true;}
async function incomingRingMusicStart(preview){const token=++_ringLoadToken,source=await incomingRingMusicSource();if(token!==_ringLoadToken){if(source&&source.owned)try{URL.revokeObjectURL(source.url);}catch(_){}return false;}if(!source){if(S.settings){S.settings.incomingRing='default';S.settings.incomingRingSongId='';save();}if(preview)toast('所选歌曲文件已失效，已恢复默认微信来电 MP3');return incomingRingAssetStart(incomingRingUrl(),preview);}if(source.owned)_ringOwnedUrl=source.url;return incomingRingAssetStart(source.url,preview);}
function ringStart(){ringStop();if(S.settings.sound){if(incomingRingKey()==='music')incomingRingMusicStart(false);else incomingRingAssetStart(incomingRingUrl(),false);}if(navigator.vibrate)navigator.vibrate([400,200,400,200,400]);}
function ringStop(){_ringLoadToken++;if(_ringPreviewTimer){clearTimeout(_ringPreviewTimer);_ringPreviewTimer=null;}if(_ring){if(typeof _ring==='number')clearInterval(_ring);else try{_ring.pause();_ring.loop=false;_ring.currentTime=0;}catch(_){}_ring=null;}if(_ringOwnedUrl){try{URL.revokeObjectURL(_ringOwnedUrl);}catch(_){}_ringOwnedUrl='';}if(navigator.vibrate)navigator.vibrate(0);}
