/* =================== 天气 =================== */
const WCODE={0:'晴',1:'晴',2:'多云',3:'阴',45:'雾',48:'雾',51:'小雨',53:'小雨',55:'雨',61:'小雨',63:'中雨',65:'大雨',71:'小雪',73:'雪',75:'大雪',80:'阵雨',81:'阵雨',82:'大阵雨',95:'雷雨',96:'雷雨'};
async function _weatherCoords(la,lo,placeName,manual){
  try{const w=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+la+'&longitude='+lo+'&current=temperature_2m,weather_code,precipitation').then(r=>r.json());
    let place=placeName||'';
    if(!place){try{const g=await fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+la+'&longitude='+lo+'&localityLanguage=zh').then(r=>r.json());
      const parts=[g.principalSubdivision||g.city,g.locality,(g.localityInfo&&g.localityInfo.administrative&&g.localityInfo.administrative.slice(-1)[0]&&g.localityInfo.administrative.slice(-1)[0].name)];
      place=parts.filter((x,i,a)=>x&&a.indexOf(x)===i).join('·');}catch(e){}}
    const code=w.current.weather_code,desc=WCODE[code]||'未知';
    S.weather={place,temp:Math.round(w.current.temperature_2m),desc,rain:(w.current.precipitation>0||[51,53,55,61,63,65,80,81,82,95,96].indexOf(code)>=0),time:Date.now()};
    save();if(manual)toast(''+place+' '+desc+' '+S.weather.temp+'°C');if(cur().p==='settings'||cur().p==='home')render();return true;
  }catch(e){if(manual)toast('天气获取失败');return false;}}
async function weatherByCity(){const q=prompt('定位用不了？直接输你的城市（如 苏州、北京、Shanghai）：',(S.weather&&S.weather.place)||'');if(q==null)return;const city=q.trim();if(!city)return;toast('查询中…');
  try{const g=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(city)+'&count=1&language=zh&format=json').then(r=>r.json());
    if(!g||!g.results||!g.results.length){toast('没找到这个城市，换个写法再试');return;}
    const r0=g.results[0];const nm=[r0.admin1,r0.name].filter((x,i,a)=>x&&a.indexOf(x)===i).join('·')||city;
    await _weatherCoords(r0.latitude,r0.longitude,nm,true);
  }catch(e){toast('查询失败，检查网络');}}
function fetchWeather(manual){if(!navigator.geolocation){if(manual)weatherByCity();return;}
  navigator.geolocation.getCurrentPosition(p=>{_weatherCoords(p.coords.latitude,p.coords.longitude,'',manual);},()=>{if(manual)weatherByCity();},{timeout:8000,maximumAge:600000});}

/* =================== 联网搜索 =================== */
function webSearchFailed(text){return /^（(?:联网|搜索)(?:失败|未启用)|^（没搜到/.test((''+(text||'')).trim());}
function localPersonalStateQuery(text){const t=(''+(text||'')).replace(/\s+/g,' ').trim();if(!t)return false;const internetExplicit=/(?:上网|联网|互联网|网页|网络)(?:查|搜)|(?:查|搜).{0,5}(?:互联网|网页|网络)/.test(t),personalState=/(?:你|你的|你自己|刚才|刚刚|有没有人|是不是有人).{0,18}(?:微信|消息|聊天|好友|手机|通讯录|短信|电话|谁找你|谁加你)|(?:微信|消息|聊天|好友|手机|通讯录|短信|电话).{0,18}(?:有人|谁|发来|找你|加你|刚才|刚刚)/.test(t);return personalState&&!internetExplicit;}
function autoWebQuery(text,c){if(!(S.settings.web&&S.settings.web.enabled))return'';const t=(''+(text||'')).replace(/\s+/g,' ').trim();if(!t)return'';const explicit=/帮我查|查一下|搜一下|搜索一下|上网查|联网查|查查|能不能查/.test(t),weather=/天气|气温|温度|多少度|下雨|降雨|空气质量|紫外线|台风/.test(t),liveTopic=/新闻|热搜|价格|汇率|股价|币价|比分|赛况|航班|列车|开售|上映|票房|营业时间|政策|规定|排行榜|榜单/.test(t),latestTopic=/(最新|实时|目前|刚刚).{0,12}(消息|进展|情况|版本|数据|排名|发布|比赛|结果)|(消息|进展|版本|数据|排名|比赛|结果).{0,12}(最新|实时|目前)/.test(t);if(localPersonalStateQuery(t))return'';if(!explicit&&!weather&&!liveTopic&&!latestTopic)return'';let q=t.replace(/^(?:你能不能|能不能|可以|麻烦)?(?:帮我)?(?:联网|上网)?(?:查一下|查查|搜一下|搜索一下)[，,:：\s]*/,'').slice(0,150);if(weather){let city='';if(/我这边|我这里|我的城市|当地/.test(t))city=typeof meHomeCity==='function'?meHomeCity():'';else city=typeof charHomeCity==='function'?charHomeCity(c):'';if(city&&!q.includes(city))q=city+' '+q;q+=' 当前天气 实时温度 降水';}return q.trim().slice(0,180);}
async function webSearch(q){const ws=S.settings.search||{};
  if(ws.mode==='model'){const a=S.settings.chat;const base=(ws.base||a.base||'').replace(/\/+$/,'');const key=ws.key||a.key;const model=ws.model||a.model;
    try{const r=await fetchT(base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model,max_tokens:700,messages:[{role:'system',content:'你是联网搜索助手。请就用户的问题给出尽量最新、真实的信息；如果你具备联网/检索能力就联网查证。无法真实检索时必须明确说无法联网，不得凭记忆伪装实时结果。'},{role:'user',content:'联网搜索并简要回答：'+q}]})});
      const d=await r.json().catch(()=>null);if(!r.ok)return '（搜索失败 '+r.status+'：检查设置里的联网模型）';
      return ((d&&d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)||'').slice(0,1800)||'（没搜到内容）';}catch(e){return '（搜索失败，检查联网模型设置）';}}
  const base=(ws.base||'https://s.jina.ai').replace(/\/+$/,'');
  try{const h={'Accept':'text/plain','X-Respond-With':'no-content'};if(ws.key)h['Authorization']='Bearer '+ws.key;
    const r=await fetchT(base+'/'+encodeURIComponent(q),{headers:h});const t=await r.text();
    if(!r.ok)return '（联网失败 '+r.status+'：可能要去"设置→联网搜索"填上 jina 密钥，或改用「用模型」）';
    return (t||'').slice(0,1800);}catch(e){return '（联网失败，检查网络，或在"设置→联网搜索"换方式）';}}
/* =================== 浏览器 =================== */
let _brBusy=false,_brBusyMode='';
function renderBrowser(){const b=S.browser||{};
  const webOn=!!(S.settings.web&&S.settings.web.enabled),items=b.items||[],history=(b.history||[]).slice(0,6),src=b.lastSearchMode==='web'?'已连接实时网络':b.lastSearchMode==='webmodel'?'联网模型结果':b.lastSearchMode==='fallback'?'网络不可用，已切换智能回答':b.lastSearchMode==='model'?'智能回答 · 内容可能不是最新':'';
  const search=`<div class="br-search"><span>${svgIc('search',19,'#8a8d94')}</span><input id="br_q" value="${esc(b.q||'')}" placeholder="搜索你感兴趣的内容" onkeydown="if(event.key==='Enter')browserSearch()"><button onclick="browserSearch()" ${_brBusy?'disabled':''}>${_brBusy?'搜索中':'百度一下'}</button></div>`;
  const homeView=`<div class="br-home"><div class="br-logo">百<span>度</span></div>${search}<div class="br-shortcuts"><button onclick="browserSearch('今日热点')">${svgIc('star',21,'#ff5a54')}<span>热榜</span></button><button onclick="browserSearch('今日新闻')">${svgIc('notebook',21,'#3478f6')}<span>资讯</span></button><button onclick="browserSearch('热门图片')">${svgIc('image',21,'#8f63e9')}<span>图片</span></button><button onclick="browserSearch('生活实用技巧')">${svgIc('book',21,'#f4a51c')}<span>知道</span></button></div><section class="br-hot"><div class="br-section-title"><b>百度热搜</b><small>实时热点</small></div>${['今日有哪些值得关注的消息','近期热门影视作品','本地周末好去处','夏日生活实用指南','大家都在听的新歌'].map((x,i)=>`<button onclick="browserSearch('${x}')"><i>${i+1}</i><span>${x}</span><em>${i<2?'热':''}</em></button>`).join('')}</section>${history.length?`<section class="br-recent"><div class="br-section-title"><b>最近搜索</b><button onclick="brHistory()">全部记录</button></div><div>${history.map((x,i)=>`<button onclick="brRe(${i})">${svgIc('clock',13,'#9699a0')} ${esc(x.q)}</button>`).join('')}</div></section>`:''}<div class="br-network">${webOn?'联网搜索已开启':'当前使用智能回答，可在设置中开启联网搜索'}</div></div>`;
  const busyView=`<div class="br-results"><div class="br-result-search">${search}</div><div class="br-loading"><i></i><i></i><i></i><span>${_brBusyMode==='model'?'正在整理答案':'正在检索相关内容'}</span></div></div>`;
  const resultView=`<div class="br-results"><div class="br-result-search">${search}</div><div class="br-result-meta"><span>搜索结果 · ${items.length}</span><small>${src}</small></div>${items.map((it,i)=>`<article class="br-result" onclick="brView(${i})"><div class="br-site"><span>B</span><div>百度智能搜索<small>baidu.com</small></div></div><h3>${esc(it.title)}</h3><p>${esc((it.snippet||'').slice(0,220))}${(it.snippet||'').length>220?'…':''}</p><div class="br-actions"><button onclick="event.stopPropagation();brView(${i})">查看详情</button><button onclick="event.stopPropagation();brFwd(${i})">转发给角色</button></div></article>`).join('')}<div class="br-end">没有更多结果了</div></div>`;
  return `<div class="nav br-nav"><span class="l" onclick="home()">‹</span><span class="t">百度</span><span class="r" onclick="brHistory()">${svgIc('clock',19,'currentColor')}</span></div><div class="scroll br-page">${_brBusy?busyView:(items.length?resultView:homeView)}</div>`;}
async function browserModelSearch(q){return await chatAPI([{role:'system',content:'你是浏览器里的普通回答模型。当前没有可用的真实联网结果，只能依据已有知识回答，可能不是最新信息。整理成3到5条简短结果，每行一条，严格格式：标题:::一两句话摘要。不要声称刚刚搜索、查到实时网页或看到最新资料。'},{role:'user',content:q}],{max:700,aux:true});}
async function browserSearch(qArg){if(_brBusy)return;const q=(qArg||($('#br_q')?$('#br_q').value:'')||'').trim();if(!q){toast('搜点啥呢');return;}
  S.browser=S.browser||{};S.browser.q=q;S.browser.history=S.browser.history||[];S.browser.history.unshift({q,time:Date.now()});S.browser.history=S.browser.history.slice(0,40);
  const webOn=!!(S.settings.web&&S.settings.web.enabled),webMode=((S.settings.search||{}).mode||'jina')==='model'?'webmodel':'web';_brBusy=true;_brBusyMode=webOn?webMode:'model';save();render();
  try{let r='',mode='model';if(webOn){const raw=await webSearch(q);if(webSearchFailed(raw)){mode='fallback';toast('⚠️ 联网失败，已改用普通模型');r=await browserModelSearch(q);}else{mode=webMode;toast(mode==='web'?'🌐 已获取 Jina 真实联网结果':'🌐 已获得联网模型回答');r=await chatAPI([{role:'system',content:'你是浏览器搜索结果整理器。根据下面联网搜到的资料，整理成3到5条搜索结果，要准确、基于资料、不要编造。每行一条，严格格式：标题:::一两句话摘要。只输出这些行。'},{role:'user',content:'搜索词：'+q+'\n\n联网资料：\n'+(raw||'').slice(0,1500)}],{max:700,aux:true});}}else{r=await browserModelSearch(q);}
    const items=looseLines(r).map(p=>({title:clean(p[0]),snippet:(p[1]||p[0]||'').trim()})).filter(x=>x.title);
    S.browser.items=items.length?items:[{title:q,snippet:mode==='web'?'没有整理出相关联网结果':'模型没有生成可用回答'}];S.browser.lastSearchMode=mode;
  }catch(e){S.browser.items=[{title:q,snippet:'搜索失败了，检查下网络再试一次'}];S.browser.lastSearchMode=webOn?'fallback':'model';}
  _brBusy=false;_brBusyMode='';save();render();}
function brView(i){const it=(S.browser.items||[])[i];if(!it)return;
  openModal(`<h3 style="color:#7db3ff">${esc(it.title)}</h3><div style="max-height:55vh;overflow:auto;color:#ddd;line-height:1.8;white-space:pre-wrap;font-size:14px">${esc(it.snippet)}</div><div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">关闭</button><button class="btn p" onclick="closeModal();brFwd(${i})">转发给角色</button></div>`);}
function brFwd(i){const it=(S.browser.items||[])[i];if(!it)return;const cs=S.contacts.filter(c=>!c.deleted&&(isMain()||addedHere(c)));if(!cs.length){toast('先加个角色');return;}
  window._brF=it;openModal(`<h3>转发给</h3>${cs.map(c=>`<div class="section"><div class="it" onclick="doBrFwd('${c.id}')">${esc(c.remark||c.name)}<span class="v">›</span></div></div>`).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function doBrFwd(cid){const it=window._brF;if(!it)return;pushMsg(cid,{role:'user',type:'weblink',title:it.title,snippet:it.snippet,q:(S.browser&&S.browser.q)||'',id:uid()});closeModal();toast('已转发给角色');scheduleReply(cid);}
function brHistory(){const h=(S.browser&&S.browser.history)||[];
  openModal(`<h3>搜索记录</h3>${h.length?h.map((x,i)=>`<div class="it"><span onclick="brRe(${i})" style="flex:1;color:#ccc;cursor:pointer;display:flex;align-items:center;gap:8px">${svgIc('search',15,'#888')}${esc(x.q)}</span><small style="color:#777">${fmtDate(x.time)}</small></div>`).join(''):'<div class="empty">还没搜过</div>'}<div class="btns" style="margin-top:8px"><button class="btn d" onclick="brClearHist()">清空记录</button><button class="btn g" onclick="closeModal()">关闭</button></div>`);}
async function brClearHist(){if(!await uiConfirm('清空全部浏览/搜索记录？\n（搜索框、搜索结果、历史记录都会清掉）'))return;S.browser={q:'',items:[],history:[]};save();closeModal();if(cur().p==='browser'||cur().p==='spy')render();toast('已清空');}
function brRe(i){const x=(S.browser&&S.browser.history||[])[i];if(!x)return;closeModal();browserSearch(x.q);}
function viewWeblink(mid){let m;for(const k in S.messages){const x=S.messages[k].find(y=>y.id===mid);if(x){m=x;break;}}if(!m)return;
  openModal(`<h3 style="color:#7db3ff">${esc(m.title)}</h3><div style="max-height:55vh;overflow:auto;color:#ddd;line-height:1.8;white-space:pre-wrap;font-size:14px">${esc(m.snippet||'')}</div><button class="btn g" style="margin-top:12px" onclick="closeModal()">关闭</button>`);}

/* =================== 闹钟 =================== */
let _nativeAlarmAuthorized=false,_nativeAlarmSyncBusy=false,_nativeAlarmSyncAgain=false;
function alarmCompanionFallback(c,label){const who=c&&String(c.remark||c.name||'').trim(),thing=String(label||'闹钟').trim()||'闹钟';return '到时间了。你定的“'+thing+'”，现在去做，做完回来告诉我。'+(who?'我等你。':'');}
async function alarmPrepareCompanionText(alarm){const c=alarm&&getC(alarm.contactId);if(!c||!(S.settings&&S.settings.chat&&S.settings.chat.key))return;try{const recent=(msgs(c.id)||[]).slice(-6).map(m=>(m.role==='user'?S.me.name:(c.remark||c.name))+'：'+msgToText(m)).join('\n').slice(-800),prompt='你给'+S.me.name+'设置的闹钟现在到点，备注是“'+String(alarm.label||'闹钟').slice(0,60)+'”。请按你自己的性格发一条自然的短消息提醒ta现在去做这件事，可以关心、催促、撒娇或严厉，但不能说自己是系统或闹钟程序，也不要输出任何方括号标签。只输出要发给ta的一至两句正文。'+(recent?'\n最近聊天仅供保持语气：\n'+recent:'');let text=String(await chatAPI([{role:'system',content:buildSystem(c)+'\n\n现在只写闹钟到点时的一条短提醒，不执行任何标签。'},{role:'user',content:prompt}],{max:120,temp:.82,aux:true})||'').replace(/\[(?:心情|记住|闹钟|来电|联网)[^\]]*\]/g,'').trim();text=cleanRolePunct(text).slice(0,160);if(!text)return;const live=(S.alarms||[]).find(a=>a.id===alarm.id);if(!live)return;live.companionText=text;save();nativeAlarmSync(false);}catch(_){}}
function nativeAlarmRows(){return(S.alarms||[]).map(a=>{const c=getC(a.contactId);return{id:String(a.id||''),time:String(a.time||''),label:String(a.label||'闹钟'),companionText:String(a.companionText||alarmCompanionFallback(c,a.label)),contactId:String(a.contactId||''),roleName:c?String(c.remark||c.name||'角色'):'角色',enabled:a.enabled!==false,repeat:a.repeat==='daily'?'daily':'once'};});}
function alarmApplyFiredEvents(rows){if(!Array.isArray(rows)||!rows.length)return 0;S._alarmEventSeen=S._alarmEventSeen||{};let added=0;for(const event of rows){const alarmId=String(event&&event.alarmId||''),firedAt=Math.max(0,+String(event&&event.firedAt||0)||Date.now()),key=alarmId+'|'+new Date(firedAt).toDateString();if(!alarmId||S._alarmEventSeen[key])continue;const alarm=(S.alarms||[]).find(a=>String(a.id)===alarmId),cid=String(event.roleId||alarm&&alarm.contactId||''),c=getC(cid);if(!c)continue;const content=String(event.message||alarm&&alarm.companionText||alarmCompanionFallback(c,event.label||alarm&&alarm.label)).trim();if(!content)continue;msgs(cid).push({role:'assistant',type:'text',content,time:firedAt,id:'alarm_'+alarmId+'_'+firedAt,_alarm:true});S._alarmEventSeen[key]=firedAt;added++;}const keys=Object.keys(S._alarmEventSeen);if(keys.length>80)keys.sort((a,b)=>S._alarmEventSeen[b]-S._alarmEventSeen[a]).slice(80).forEach(k=>delete S._alarmEventSeen[k]);if(added){save();if(cur().p==='chat')refreshChatMessages(cur().id);else render();}return added;}
async function nativeAlarmSync(showError){if(!window.__SMALL_PHONE_PRIVATE__||!window.SmallPhoneNative||typeof window.SmallPhoneNative.request!=='function')return false;if(_nativeAlarmSyncBusy){_nativeAlarmSyncAgain=true;return false;}_nativeAlarmSyncBusy=true;try{const result=await window.SmallPhoneNative.request('alarm.sync',{alarms:nativeAlarmRows()});_nativeAlarmAuthorized=!!(result&&result.supported&&result.authorized);alarmApplyFiredEvents(result&&result.firedEvents);const fired=new Set(result&&Array.isArray(result.firedIds)?result.firedIds:[]);if(fired.size){S.alarms=(S.alarms||[]).filter(a=>!fired.has(a.id));save();if(document.querySelector('.modal'))alarmManager();}if(showError&&result&&result.supported&&!result.authorized)toast('请允许小手机使用系统闹钟');return _nativeAlarmAuthorized;}catch(e){_nativeAlarmAuthorized=false;if(showError)toast('系统闹钟同步失败，请重新添加或检查权限');return false;}finally{_nativeAlarmSyncBusy=false;if(_nativeAlarmSyncAgain){_nativeAlarmSyncAgain=false;setTimeout(()=>nativeAlarmSync(false),100);}}}
function alarmIdentity(contactId,time,label,repeat){const m=String(time||'').trim().match(/^(\d{1,2}):(\d{2})$/),clock=m?String(Math.max(0,Math.min(23,+m[1]))).padStart(2,'0')+':'+String(Math.max(0,Math.min(59,+m[2]))).padStart(2,'0'):String(time||'').trim(),note=String(label||'起床').trim().replace(/\s+/g,' '),cycle=repeat==='daily'?'daily':'once';return [String(contactId||''),clock,note,cycle].join('\u0001');}
function alarmPendingDuplicate(contactId,time,label,repeat){const key=alarmIdentity(contactId,time,label,repeat);return(S.alarms||[]).find(a=>a&&a.enabled!==false&&alarmIdentity(a.contactId,a.time,a.label,a.repeat)===key)||null;}
function addAlarm(contactId,time,label,repeat){const normalized=alarmIdentity(contactId,time,label,repeat).split('\u0001'),clock=normalized[1],note=normalized[2],cycle=normalized[3],existing=alarmPendingDuplicate(contactId,clock,note,cycle);if(existing){nativeAlarmSync(false);toast('这个闹钟已经定好了 '+clock+' '+note);return existing;}const c=getC(contactId),text=alarmCompanionFallback(c,note),alarm={id:uid(),time:clock,label:note,companionText:text,contactId,enabled:true,repeat:cycle};S.alarms.push(alarm);save();nativeAlarmSync(true);setTimeout(()=>alarmPrepareCompanionText(alarm),120);toast('已定闹钟 '+clock+' '+note);return alarm;}
function alarmToggle(id){const alarm=S.alarms.find(a=>a.id===id);if(!alarm)return;alarm.enabled=!alarm.enabled;save();nativeAlarmSync(alarm.enabled);alarmManager();}
function alarmDelete(id){S.alarms=S.alarms.filter(a=>a.id!==id);save();nativeAlarmSync(false);alarmManager();}
function alarmManager(){openModal(`<h3>闹钟</h3>
  <div class="hint">私人版会同步为 iPhone 系统闹钟，即使小手机退到后台也能持续响；网页版保留原来的前台角色来电。也能在聊天里口头让 ta 定。</div>
  <div class="two"><div class="field"><label>时间</label><input id="al_t" type="time"></div>
  <div class="field"><label>谁来叫你</label><select id="al_c">${S.contacts.filter(c=>!c.deleted).map(c=>`<option value="${c.id}">${esc(c.remark||c.name)}</option>`).join('')}</select></div></div>
  <div class="two"><div class="field"><label>备注</label><input id="al_l" placeholder="起床啦"></div>
  <div class="field"><label>重复</label><select id="al_r"><option value="once">仅一次</option><option value="daily">每天</option></select></div></div>
  <button class="btn p" style="margin-bottom:12px" onclick="(function(){var t=$('#al_t').value;if(!t){toast('选个时间');return;}addAlarm($('#al_c').value,t,$('#al_l').value.trim(),$('#al_r').value);alarmManager();})()">添加</button>
  ${S.alarms.length?S.alarms.map(a=>{const c=getC(a.contactId);return `<div class="bill" style="border-radius:8px;margin-bottom:6px"><div><b style="font-size:18px">${a.time}</b> ${esc(a.label)} <span class="tag">${a.repeat==='daily'?'每天':'仅一次'}</span><small>${c?esc(c.remark||c.name):'?'} 提醒</small></div><div><span class="sw ${a.enabled?'on':''}" onclick="alarmToggle('${a.id}')"></span> <span onclick="alarmDelete('${a.id}')" style="color:#fa5151;cursor:pointer;margin-left:10px">✕</span></div></div>`;}).join(''):'<div class="empty">还没有闹钟</div>'}
  <button class="btn g" style="margin-top:10px" onclick="closeModal()">关闭</button>`);}
let _alarmFired={};
function checkAlarms(){if(!isMain()||_nativeAlarmAuthorized)return;const now=new Date();const hhmm=now.getHours().toString().padStart(2,'0')+':'+now.getMinutes().toString().padStart(2,'0');const tag=now.toDateString()+hhmm;
  for(const a of [...S.alarms]){if(!a.enabled||a.time!==hhmm||_alarmFired[a.id]===tag||_call)continue;const c=getC(a.contactId);if(!c)continue;const content=String(a.companionText||alarmCompanionFallback(c,a.label));msgs(c.id).push({role:'assistant',type:'text',content,time:Date.now(),id:'alarm_'+a.id+'_'+Date.now(),_alarm:true});notifyIncoming(c,msgs(c.id)[msgs(c.id).length-1]);incomingCall(a.contactId,'voice');_alarmFired[a.id]=tag;if(a.repeat!=='daily')S.alarms=S.alarms.filter(z=>z.id!==a.id);save();break;}}
setInterval(checkAlarms,15000);
window.addEventListener('small-phone-native-ready',()=>setTimeout(()=>{privateNativeStatusBarThemeSync(true);nativeAlarmSync(false);},200));
window.addEventListener('pageshow',()=>setTimeout(()=>nativeAlarmSync(false),800));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(()=>nativeAlarmSync(false),500);});
setTimeout(()=>nativeAlarmSync(false),3500);
