function rolePhoneInspectionAllFactsText(c){const st=companionRoleDataState();if(!st)return'';const h=st.health||{},apps=Array.isArray(st.apps)?st.apps:[],facts=[];if(st.battery)facts.push('电量 '+Math.round(st.battery.level*100)+'%'+(st.battery.state?'，'+st.battery.state:'')+(st.battery.lowPower?'，已开低电量模式':''));if(st.screenTimeAvailable){facts.push('屏幕总使用 '+companionDuration(st.screenTimeSec||0));const used=apps.filter(x=>(+x.usedSec||0)>0).sort((a,b)=>(+b.usedSec||0)-(+a.usedSec||0)).slice(0,8);if(used.length)facts.push('逐 App 使用：'+used.map(x=>x.name+' '+companionDuration(x.usedSec||0)).join('、'));}if(h.steps!==null&&h.steps!==undefined)facts.push('步数 '+Math.round(h.steps)+' 步');if(h.sleepSeconds!==null&&h.sleepSeconds!==undefined)facts.push('睡眠 '+companionDuration(h.sleepSeconds));if(h.heartRateBpm!==null&&h.heartRateBpm!==undefined)facts.push('心率 '+Math.round(h.heartRateBpm)+' 次/分');if(h.electrocardiogramAt)facts.push('心电 '+companionElectrocardiogramLabel(h.electrocardiogramClassification));if(h.hrvMs!==null&&h.hrvMs!==undefined)facts.push('HRV '+Math.round(h.hrvMs)+' 毫秒');if(st.location)facts.push('位置 '+(st.location.place||'已取得实时坐标'));return facts.join('\n');}
