function aiMemoryMoveOpen(cid){const cs=(S.contacts||[]).filter(c=>c&&!c.deleted);if(!cs.length){toast('先在微信里创建一个角色');return;}const selected=getC(cid)?cid:cs[0].id;openModal(`<h3>AI 记忆搬家</h3><div class="hint" style="line-height:1.75">选择记忆属于哪个角色，再上传从其他 AI 导出的文件。导入只会追加；不会覆盖现有聊天、人设和记忆。</div><div class="field"><label>搬给哪个角色</label><select id="aim_cid">${cs.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.remark||c.name)}</option>`).join('')}</select></div><div class="field"><label>记忆文件</label><input id="aim_file" type="file" accept=".json,.docx,.doc,.txt,.md,.csv,.html,.htm,.rtf,application/json,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain"></div><div class="hint">支持现成记忆、总结和聊天资料。不会上传到服务器，也不会调用付费模型；文件只在当前设备解析。</div><div id="aim_status" style="min-height:18px;margin-top:8px;color:#9aa;font-size:12px"></div><div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" id="aim_go" onclick="aiMemoryMoveAnalyze()">读取并预览</button></div>`);}
async function aiMemoryMoveAnalyze(){const file=((($('#aim_file')||{}).files)||[])[0],cid=String((($('#aim_cid')||{}).value)||'');if(!file){toast('先选择一个记忆文件');return;}if(!getC(cid)){toast('目标角色不存在');return;}const btn=$('#aim_go'),status=$('#aim_status');if(btn){btn.disabled=true;btn.textContent='正在读取…';}if(status)status.textContent='大文件需要一点时间，请保持页面开启';try{await new Promise(r=>setTimeout(r,20));const parsed=await aiMemoryReadFile(file),chunks=aiMemorySplitParts(parsed.parts);if(!chunks.length)throw new Error('没有从文件里找到可导入的文字记忆');_aiMemoryMovePreview={cid,name:file.name||'外部AI记忆',size:+file.size||0,format:parsed.format,charCount:chunks.reduce((n,x)=>n+x.length,0),chunks};aiMemoryMovePreview();}catch(e){if(status){status.style.color='#ff8b9d';status.textContent=(e&&e.message)||'文件读取失败';}if(btn){btn.disabled=false;btn.textContent='读取并预览';}}}
function aiMemoryMovePreview(){const p=_aiMemoryMovePreview,c=p&&getC(p.cid);if(!p||!c)return aiMemoryMoveOpen();const samples=p.chunks.slice(0,4).map(x=>`<div style="padding:8px 10px;margin-top:6px;border-radius:8px;background:#24242a;color:#d8d8dc;font-size:12px;line-height:1.55;white-space:pre-wrap">${esc(x.slice(0,260))}${x.length>260?'…':''}</div>`).join('');openModal(`<h3>导入预览</h3><div class="hint" style="line-height:1.8"><b>目标角色：</b>${esc(c.remark||c.name)}<br><b>文件：</b>${esc(p.name)}（${esc(p.format)} · ${fmtSize(p.size)}）<br><b>识别内容：</b>${northLocaleNumber(p.charCount)} 字 · ${northLocaleNumber(p.chunks.length)} 个可检索片段</div><div style="margin-top:10px"><b style="font-size:13px;color:#b9caff">内容示例</b>${samples}</div><div class="hint" style="margin-top:10px;color:#d5ad7a">确认后会作为“外部AI记忆”追加。以后聊天只提取与当前话题相关的少量片段，不会一次塞入整份文件。</div><div class="btns" style="margin-top:12px"><button class="btn g" onclick="aiMemoryMoveOpen('${c.id}')">重新选择</button><button class="btn p" id="aim_commit" onclick="aiMemoryMoveCommit()">确认导入全部</button></div>`);}
async function aiMemoryMoveCommit(){const p=_aiMemoryMovePreview,c=p&&getC(p.cid);if(!p||!c)return;const btn=$('#aim_commit');if(btn){btn.disabled=true;btn.textContent='正在保存…';}const docs=aiMemoryDocs(c),doc={id:uid(),name:String(p.name||'外部AI记忆').slice(0,180),format:p.format||'',size:p.size||0,charCount:p.charCount||0,importedAt:Date.now(),chunks:p.chunks.slice()},at=docs.length;docs.push(doc);try{if(!await saveNowAsync())throw new Error('浏览器没有足够存储空间');_aiMemoryMovePreview=null;closeModal();toast('已给 '+(c.remark||c.name)+' 导入 '+doc.chunks.length+' 条外部记忆');}catch(e){docs.splice(at,1);if(btn){btn.disabled=false;btn.textContent='确认导入全部';}toast('导入保存失败：'+((e&&e.message)||'请检查手机剩余空间'));}}
function aiMemoryMoveManage(){const rows=[];(S.contacts||[]).filter(c=>c&&!c.deleted).forEach(c=>aiMemoryDocs(c).forEach(d=>rows.push({c,d})));openModal(`<h3>已导入的 AI 记忆</h3><div class="hint">按文件管理。删除这里只会移除对应的外部记忆，不影响角色原有聊天和小手机自动记忆。</div>${rows.length?rows.sort((a,b)=>(b.d.importedAt||0)-(a.d.importedAt||0)).map(x=>`<div class="bill" style="border-radius:9px;margin-top:8px"><div style="min-width:0;flex:1"><b>${esc(x.d.name||'外部AI记忆')}</b><small style="display:block;color:#888;margin-top:4px">${esc(x.c.remark||x.c.name)} · ${northLocaleNumber((x.d.chunks||[]).length)}片段 · ${fmtSize(+x.d.size||0)}</small></div><button type="button" aria-label="删除导入记忆" onclick="aiMemoryMoveDelete('${x.c.id}','${x.d.id}')" style="width:36px;height:36px;border-radius:10px;border:1px solid rgba(250,81,81,.28);background:rgba(250,81,81,.09);color:#ff7474;cursor:pointer;font-size:18px">✕</button></div>`).join(''):'<div class="empty" style="padding:22px 0">还没有导入过外部 AI 记忆</div>'}<div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">关闭</button><button class="btn p" onclick="aiMemoryMoveOpen()">继续导入</button></div>`);}
async function aiMemoryMoveDelete(cid,did){const c=getC(cid),docs=c&&aiMemoryDocs(c),doc=docs&&docs.find(x=>x.id===did);if(!doc)return;if(!await uiConfirm('删除「'+(doc.name||'这份文件')+'」导入的全部外部记忆？\n\n角色原有聊天和小手机自动记忆不会被删除。',{danger:true}))return;c.aiMemoryImports=docs.filter(x=>x.id!==did);if(!await saveNowAsync()){c.aiMemoryImports=docs;toast('删除后保存失败，请稍后重试');return;}aiMemoryMoveManage();toast('这份外部记忆已删除');}
let _recoveryCandidate=null;
