function privateMirrorConflictModal(candidate,first){_privateMirrorCandidate=candidate;const m=candidate.meta;openModal(`<h3>私人版本发现更新</h3><div class="hint" style="line-height:1.8">${first?'这是首次绑定，':'网页本机也有尚未合并的改动，'}系统没有静默覆盖任何一端。<br><br>私人版本：<b>r${m.revision}</b> · ${esc(fmtDT(m.capturedAt||m.updatedAt))}<br>默认建议保留私人版本；应用前会保存当前网页快照，可随时撤回。</div><div class="btns"><button class="btn p" onclick="privateMirrorUsePrivate()">保留私人版本</button><button class="btn g" onclick="closeModal();toast('网页本机改动已暂留，且不会上传覆盖私人版本')">暂留网页本机</button></div><button class="btn g" style="margin-top:8px" onclick="privateMirrorRestoreRollback()">撤回上次镜像</button><div class="hint" style="margin-top:8px">聊天、角色、记忆、朋友圈、钱包和常规设置会同步；放映室原生大视频、系统相册原文件等大型媒体不属于网页镜像范围。</div>`);}
async function privatePrimaryMirrorCheck(opt){if(privateNativeAppOn()||_privateMirrorBusy||!cloudUrl()||!cloudKey())return null;opt=opt||{};_privateMirrorBusy=true;try{const row=await cloudFetchRow(),meta=row&&privateMirrorMeta(row.data,row);if(!meta)return null;const applied=Math.max(0,+((S.settings||{}).privateMirrorAppliedRevision)||0),key=meta.revision+':'+meta.updatedAt;if(meta.revision<=applied)return {current:true,meta};if(privateMirrorLocalDirty(meta)){if(_privateMirrorSeen!==key||opt.manual){_privateMirrorSeen=key;privateMirrorConflictModal({data:row.data,row,meta},!applied);}return {conflict:true,meta};}const appliedMeta=await privateMirrorApplyRemote(row.data,row,false);if(!opt.silent)toast('网页已自动同步私人版本 r'+appliedMeta.revision);return {applied:true,meta:appliedMeta};}finally{_privateMirrorBusy=false;}}
function privatePrimaryMirrorWake(){if(privateNativeAppOn()||_privateMirrorTimer)return;_privateMirrorTimer=setTimeout(()=>{_privateMirrorTimer=0;privatePrimaryMirrorCheck({silent:true}).catch(()=>{});},1200);}
async function privateMirrorPublishNow(){if(!privateNativeAppOn()){toast('请在私人 App 里执行这一步');return;}if(!cloudUrl()||!cloudKey()){toast('云连接尚未配置，请先保存云地址和 Key');return;}toast('正在把私人 App 当前数据发布到网页版…');try{if(!await saveNowAsync())throw new Error('私人 App 当前数据尚未保存完成');const snapshot=await fullBackupState();snapshot._persistedAt=Math.max(+snapshot._persistedAt||0,Date.now());const result=await privatePrimaryMirrorUpload(snapshot,{allowLegacy:true});if(!result||result.uploaded!==true)throw new Error('网页版镜像没有写入');S.settings.cloudAuto=true;await saveNowAsync();toast('✅ 已发布到网页版 · 私人版本 r'+result.revision);cloudSyncModal();}catch(e){toast('发布失败：'+String(e&&e.message||e));}}
async function cloudApplyLegacyRow(data,row,targetId){if(!data||!data.settings)throw new Error('云端数据格式不对');await privateMirrorSaveRollback('manual-web-cloud-restore');const keep={cloudUrl:cloudUrl(),cloudKey:cloudKey(),cloudId:targetId||cloudId(),cloudAuto:!!(S.settings&&S.settings.cloudAuto)},next=mergeStateData(data,{keepPhoneFriend:true});next.settings=next.settings||{};Object.assign(next.settings,keep,{cloudLast:Date.now()});S=next;normalizeLoadedState();phoneFriendState();if(!await saveNowAsync())throw new Error('网页云备份写入本机失败');return row&&row.updated_at||'';}
async function privateMirrorPullNow(){if(privateNativeAppOn()){toast('私人 App 不会从网页版反向恢复；请使用手机号私人备份');return;}if(!cloudUrl()||!cloudKey()){toast('云连接尚未配置，请先保存云地址和 Key');return;}toast('正在读取云端版本…');try{const row=await cloudFetchRow(),meta=row&&privateMirrorMeta(row.data,row);if(!row)throw new Error('云端还没有找到备份');if(meta){const applied=await privateMirrorApplyRemote(row.data,row,true);S.settings.cloudAuto=true;await saveNowAsync();closeModal();render();toast('✅ 网页已读取私人版本 r'+applied.revision);}else{await cloudApplyLegacyRow(row.data,row,cloudId());closeModal();render();toast('✅ 网页已读取原有云备份；读取前快照可撤回');}}catch(e){toast('读取失败：'+String(e&&e.message||e));}}
async function cloudBackup(opt){const U=cloudUrl(),K=cloudKey();if(!U||!K)throw new Error('还没填云地址/Key，先在云同步里填一下');opt=opt||{};const snapshot=await fullBackupState();if(privateNativeAppOn()){const result=await privatePrimaryMirrorUpload(snapshot,{allowLegacy:!!opt.allowLegacy});return result.bytes||JSON.stringify(snapshot).length;}const current=await cloudFetchRow();if(current&&privateMirrorMeta(current.data,current))throw new Error('当前云ID由私人版本主设备管理；网页仅作镜像，不能反向覆盖私人数据');const id=cloudId(),data=JSON.stringify(snapshot);/* 旧云ID手动备份兼容 */
  const r=await fetch(U+'/rest/v1/backups',{method:'POST',headers:{'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({id,data,ver:APP_VER,updated_at:new Date().toISOString()})});
  if(!r.ok){let t='';try{t=await r.text();}catch(_){}throw new Error('HTTP '+r.status+(t?(' '+t.slice(0,120)):''));}
  S.settings.cloudLast=Date.now();save();return data.length;}
async function cloudRestore(idOverride){if(privateNativeAppOn())throw new Error('私人 App 禁止读取网页快照；请使用手机号私人备份恢复');const targetId=idOverride||cloudId(),row=await cloudFetchRow(targetId);if(!row)throw new Error('云端没找到这个云ID的备份');const d=row.data;if(!d||!d.settings)throw new Error('云端数据格式不对');const meta=privateMirrorMeta(d,row);if(meta){await privateMirrorApplyRemote(d,row,true,targetId);return row.updated_at;}return cloudApplyLegacyRow(d,row,targetId);}
function cloudSyncModal(){const id=cloudId();const last=S.settings.cloudLast?(fmtDur(Date.now()-S.settings.cloudLast)+'前'):'从未',mirror=String((S.settings&&S.settings.privateMirrorSource)||'')==='private-ios',native=privateNativeAppOn(),revision=native?Math.max(0,+((S.settings||{}).privateMirrorRevision)||0):Math.max(0,+((S.settings||{}).privateMirrorAppliedRevision)||0),mode=native?'私人 App 主设备':'网页版云同步';
  const hasKeys=!!(cloudUrl()&&cloudKey());
  openModal(`<h3>☁️ ${native?'同步到网页版':'读取云端版本'}</h3><div style="margin:-2px 0 10px;padding:8px 10px;border:1px solid ${native?'rgba(86,201,142,.35)':'rgba(136,155,255,.35)'};border-radius:10px;background:${native?'rgba(43,124,82,.14)':'rgba(83,94,155,.14)'};color:#ddd;font-size:12px"><b>当前运行：${mode}</b><br><small style="color:#92929a">${native?'可发布给网页版；手机号备份在账号卡片里':'可立即备份当前网页版；若该云ID由私人 App 管理会安全拒绝覆盖'}</small></div><div class="hint">${native?'这里以私人 App 为准，一键发布后网页版才能读取。恢复私人 App 时只使用手机号私人备份，不会再误恢复网页旧数据。':'可手动备份当前网页版，也可读取私人 App 发布的镜像或原有网页云备份。应用前会自动保留当前网页快照。'}</div>
    <div class="field" style="background:rgba(120,120,165,.1);border-radius:10px;padding:10px"><label>云连接${hasKeys?' <span style="color:#20b26c;font-size:12px">✓ 已连接</span>':' <span style="color:#f0913b;font-size:12px">← 首次需要配置</span>'}</label>
      <input id="cl_url" value="${esc((S.settings.cloudUrl)||'')}" placeholder="云地址 https://xxxx.supabase.co" style="margin-bottom:6px">
      <input id="cl_key" value="${esc((S.settings.cloudKey)||'')}" placeholder="云Key sb_publishable_...">
      <button class="minibtn" style="margin-top:8px;background:#7c5cff;color:#fff" onclick="cloudSaveKeys()">保存云地址+Key</button>
      <div style="font-size:11px;color:#888;margin-top:6px">连接标识已自动管理，不需要再判断或修改云 ID。</div></div>
    <div style="font-size:12px;color:#888;padding:0 2px 10px">${revision?'当前私人修订：r'+revision+' · ':''}上次同步：${last}${mirror?' · 私人版本为主':''}</div>
    ${native?`<button class="btn p" style="width:100%;font-size:15px" onclick="privateMirrorPublishNow()">一键同步到网页版</button><button class="btn g" style="width:100%;margin-top:8px" onclick="privatePhoneCloudRestoreOpen()">恢复私人 App 数据</button>`:`<button class="btn p" style="width:100%;font-size:15px" onclick="cloudDoBackup()">立即备份当前网页版</button><button class="btn g" style="width:100%;margin-top:8px" onclick="privateMirrorPullNow()">一键读取云端版本</button><button class="btn g" style="width:100%;margin-top:8px" onclick="privateMirrorRestoreRollback()">撤回到读取前的网页数据</button>`}
    <details style="margin-top:10px"><summary style="color:#777;font-size:12px;cursor:pointer">高级连接信息</summary><div class="field"><label>自动管理的连接标识</label><div style="display:flex;gap:6px"><input id="cl_id" value="${esc(id)}" readonly style="flex:1;font-size:12px"><button class="minibtn" onclick="cloudCopyId()">复制</button></div></div>${native?'<div class="hint">私人 App 只允许恢复手机号私人备份，不提供网页旧快照恢复入口。</div>':'<button class="btn g" style="width:100%" onclick="cloudUseOtherId()">输入旧云ID兼容恢复</button>'}</details>
    <div class="it cloud-sync-auto-row" style="margin-top:8px;display:flex;align-items:center;gap:12px;overflow:hidden"><span style="flex:1;min-width:0;overflow-wrap:anywhere;line-height:1.45">${native?'自动发布私人版本':'自动读取私人版本'}<br><small style="color:#888">${native?'本机保存后防抖上传；网页版不会反向覆盖私人 App':'启动/回前台时只读取更新修订；冲突时保留回滚快照'}</small></span><span class="sw ${S.settings.cloudAuto?'on':''}" style="margin-left:auto;flex:0 0 44px" onclick="S.settings.cloudAuto=!S.settings.cloudAuto;save();this.classList.toggle('on');toast(S.settings.cloudAuto?'已开启安全同步':'已关闭安全同步')"></span></div>
    <div class="hint" style="color:#888;margin-top:6px">聊天、角色、记忆、朋友圈、钱包和常规设置会同步；原生大视频和系统媒体原文件不在网页镜像范围内。</div>
    <button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function cloudCopyId(){const id=cloudId(),el=$('#cl_id');copyTextCompat(id,el).then(ok=>toast(ok?'已复制云ID':'请长按输入框手动复制云ID'));}
function cloudSaveKeys(){S.settings=S.settings||{};S.settings.cloudUrl=((($('#cl_url')||{}).value)||'').trim();S.settings.cloudKey=((($('#cl_key')||{}).value)||'').trim();save();toast(cloudUrl()&&cloudKey()?'✅ 云配置已保存':'已保存(还差地址或Key)');cloudSyncModal();}
async function cloudDoBackup(){toast('同步中…☁️');try{let n;try{n=await cloudBackup();}catch(e){if(privateNativeAppOn()&&/旧格式备份/.test(e&&e.message||'')&&await uiConfirm('云端已有旧格式网页备份。确认以当前私人版本建立主设备镜像吗？\n\n旧云端内容不会在未确认时被覆盖。'))n=await cloudBackup({allowLegacy:true});else throw e;}toast('✅ 已同步到云（'+Math.round(n/1024)+'KB）');cloudSyncModal();}catch(e){toast('同步失败：'+e.message);}}
async function cloudDoRestore(){if(privateNativeAppOn()){privatePhoneCloudRestoreOpen();return;}return privateMirrorPullNow();}
function cloudUseOtherId(){openModal(`<h3>🔁 用旧云ID恢复</h3><div class="hint">在旧设备的「云同步」里点复制云ID，粘贴到这里，把数据拉到这台设备。恢复后这台也会用这个云ID，之后两台就同步了。</div><div class="field"><input id="cl_other" placeholder="粘贴旧设备的云ID"></div><div class="btns"><button class="btn g" onclick="cloudSyncModal()">返回</button><button class="btn p" onclick="cloudRestoreOther()">恢复到这台</button></div>`);}
async function cloudRestoreOther(){const oid=(($('#cl_other')||{}).value||'').trim();if(!oid){toast('先粘贴云ID');return;}if(!await uiConfirm('用这个云ID的备份覆盖本机数据？'))return;toast('恢复中…');try{await cloudRestore(oid);/* cloudRestore 已把 S 换成云端的(含它自己的cloudId)，两台从此同步 */render();closeModal();toast('✅ 已恢复到这台');}catch(e){toast('恢复失败：'+e.message);}}
let _cloudAutoT=0;async function cloudAutoTick(){if(!(S.settings&&S.settings.cloudAuto)||document.hidden)return;const now=Date.now();if(now-_cloudAutoT<600000||now-_privatePhoneLastInteractionAt<90000)return;_cloudAutoT=now;if(privateNativeAppOn()){privatePhoneCloudWake();return;}try{const mirrored=await privatePrimaryMirrorCheck({silent:true});if(mirrored)return;}catch(_){}const current=await cloudFetchRow().catch(()=>null);if(current)return;cloudBackup().catch(()=>{});}
setInterval(cloudAutoTick,600000);setTimeout(cloudAutoTick,8000);window.addEventListener('pageshow',privatePrimaryMirrorWake);window.addEventListener('focus',privatePrimaryMirrorWake);document.addEventListener('visibilitychange',()=>{if(!document.hidden)privatePrimaryMirrorWake();});
