  const logicalBytes=_coreLogicalBytes||bytes,overflow=!!_coreOverflowMode,native=(_nativeStorageEstimate&&_nativeStorageEstimate.loaded)?_nativeStorageEstimate:null,nativeTotal=+(native&&native.totalBytes)||0,nativeFree=+(native&&native.availableBytes)||0,nativeUsed=Math.max(0,nativeTotal-nativeFree),nativePct=nativeTotal?Math.min(100,Math.round(nativeUsed/nativeTotal*100)):0;
